namespace ImGui {
inline void InspecthorCopyableTextContext(const char* value) {
    if (!value) value = "";
    ImVec2 itemMin = GetItemRectMin();
    ImVec2 itemMax = GetItemRectMax();
    const size_t valueHash = std::hash<std::string_view>{}(std::string_view(value));
    char popupId[128] = {};
    snprintf(popupId, sizeof(popupId), "Copy value##copy_%08X_%08X_%08X_%08X_%zX",
        static_cast<unsigned int>(itemMin.x * 10.0f),
        static_cast<unsigned int>(itemMin.y * 10.0f),
        static_cast<unsigned int>(itemMax.x * 10.0f),
        static_cast<unsigned int>(itemMax.y * 10.0f),
        valueHash);
    if (IsItemHovered() && IsMouseReleased(ImGuiMouseButton_Right)) OpenPopup(popupId);
    if (BeginPopup(popupId)) {
        if (MenuItem("Copy value")) SetClipboardText(value);
        EndPopup();
    }
}

inline void InspecthorCopyableTextUnformatted(const char* text, const char* textEnd = nullptr) {
    TextUnformatted(text, textEnd);
    std::string value;
    if (text) value = textEnd ? std::string(text, textEnd) : std::string(text);
    InspecthorCopyableTextContext(value.c_str());
}

inline void InspecthorCopyableText(const char* fmt, ...) {
    char buffer[4096] = {};
    va_list args;
    va_start(args, fmt);
    vsnprintf(buffer, sizeof(buffer), fmt ? fmt : "", args);
    va_end(args);
    TextUnformatted(buffer);
    InspecthorCopyableTextContext(buffer);
}

inline void InspecthorCopyableTextWrapped(const char* fmt, ...) {
    char buffer[4096] = {};
    va_list args;
    va_start(args, fmt);
    vsnprintf(buffer, sizeof(buffer), fmt ? fmt : "", args);
    va_end(args);
    PushTextWrapPos(0.0f);
    TextUnformatted(buffer);
    PopTextWrapPos();
    InspecthorCopyableTextContext(buffer);
}
} // namespace ImGui

#define TextUnformatted InspecthorCopyableTextUnformatted
#define Text InspecthorCopyableText
#define TextWrapped InspecthorCopyableTextWrapped

