static bool OpenFileDialog(HWND owner, wchar_t* outPath, DWORD maxPathLen, const wchar_t* filter) {
    OPENFILENAMEW ofn;
    ZeroMemory(&ofn, sizeof(ofn));
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = owner;
    ofn.lpstrFile = outPath;
    ofn.lpstrFile[0] = L'\0';
    ofn.nMaxFile = maxPathLen;
    ofn.lpstrFilter = filter;
    ofn.nFilterIndex = 1;
    ofn.lpstrFileTitle = NULL;
    ofn.nMaxFileTitle = 0;
    ofn.lpstrInitialDir = NULL;
    ofn.Flags = OFN_PATHMUSTEXIST | OFN_FILEMUSTEXIST | OFN_NOCHANGEDIR;

    return GetOpenFileNameW(&ofn) == TRUE;
}

static bool SaveFileDialog(
    HWND owner,
    wchar_t* outPath,
    DWORD maxPathLen,
    const wchar_t* filter,
    const wchar_t* defaultExtension,
    const wchar_t* suggestedName
) {
    OPENFILENAMEW ofn;
    ZeroMemory(&ofn, sizeof(ofn));
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = owner;
    ofn.lpstrFile = outPath;
    wcsncpy_s(outPath, maxPathLen, suggestedName ? suggestedName : L"inspecthor_dump.bin", _TRUNCATE);
    ofn.nMaxFile = maxPathLen;
    ofn.lpstrFilter = filter;
    ofn.nFilterIndex = 1;
    ofn.lpstrDefExt = defaultExtension;
    ofn.Flags = OFN_PATHMUSTEXIST | OFN_OVERWRITEPROMPT | OFN_NOCHANGEDIR;

    return GetSaveFileNameW(&ofn) == TRUE;
}

static void VerticalSplitter(const char* id, float& heightValue, float minHeight, float maxHeight, bool isBottomResizer = false) {
    ImVec2 pos = ImGui::GetCursorScreenPos();
    float width = ImGui::GetContentRegionAvail().x;
    float thickness = 4.0f;

    ImGui::PushID(id);
    ImGui::InvisibleButton("##splitter", ImVec2(width, thickness));
    bool hovered = ImGui::IsItemHovered();
    bool held = ImGui::IsItemActive();

    ImVec4 color = ImGui::GetStyleColorVec4(held ? ImGuiCol_SeparatorActive : (hovered ? ImGuiCol_SeparatorHovered : ImGuiCol_Separator));
    ImGui::GetWindowDrawList()->AddRectFilled(pos, ImVec2(pos.x + width, pos.y + thickness), ImGui::ColorConvertFloat4ToU32(color));

    if (hovered || held) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeNS);
    }

    if (held) {
        float dy = ImGui::GetIO().MouseDelta.y;
        if (dy != 0.0f) {
            if (isBottomResizer) {
                heightValue -= dy;
            } else {
                heightValue += dy;
            }
            if (heightValue < minHeight) heightValue = minHeight;
            if (heightValue > maxHeight) heightValue = maxHeight;
        }
    }

    ImGui::PopID();
}

static void HorizontalSplitter(const char* id, float& widthValue, float minWidth, float maxWidth) {
    ImVec2 pos = ImGui::GetCursorScreenPos();
    float height = ImGui::GetContentRegionAvail().y;
    float thickness = 4.0f;

    ImGui::PushID(id);
    ImGui::InvisibleButton("##splitter", ImVec2(thickness, height));
    bool hovered = ImGui::IsItemHovered();
    bool held = ImGui::IsItemActive();

    ImVec4 color = ImGui::GetStyleColorVec4(held ? ImGuiCol_SeparatorActive : (hovered ? ImGuiCol_SeparatorHovered : ImGuiCol_Separator));
    ImGui::GetWindowDrawList()->AddRectFilled(pos, ImVec2(pos.x + thickness, pos.y + height), ImGui::ColorConvertFloat4ToU32(color));

    if (hovered || held) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW);
    }

    if (held) {
        float dx = ImGui::GetIO().MouseDelta.x;
        if (dx != 0.0f) {
            widthValue += dx;
            if (widthValue < minWidth) widthValue = minWidth;
            if (widthValue > maxWidth) widthValue = maxWidth;
        }
    }

    ImGui::PopID();
}

// String conversion helpers
static std::string WStringToString(const std::wstring& wstr) {
    if (wstr.empty()) return "";
    int size_needed = WideCharToMultiByte(CP_UTF8, 0, &wstr[0], (int)wstr.size(), nullptr, 0, nullptr, nullptr);
    std::string strTo(size_needed, 0);
    WideCharToMultiByte(CP_UTF8, 0, &wstr[0], (int)wstr.size(), &strTo[0], size_needed, nullptr, nullptr);
    return strTo;
}

static std::wstring StringToWString(const std::string& str) {
    if (str.empty()) return L"";
    int size_needed = MultiByteToWideChar(CP_UTF8, 0, &str[0], (int)str.size(), nullptr, 0);
    std::wstring wstrTo(size_needed, 0);
    MultiByteToWideChar(CP_UTF8, 0, &str[0], (int)str.size(), &wstrTo[0], size_needed);
    return wstrTo;
}

static std::string WidePathToUtf8(const std::wstring& path) {
    if (path.empty()) return "";
    int sizeNeeded = WideCharToMultiByte(CP_UTF8, 0, path.c_str(), -1, nullptr, 0, nullptr, nullptr);
    if (sizeNeeded <= 1) return "";
    std::string result(sizeNeeded - 1, '\0');
    WideCharToMultiByte(CP_UTF8, 0, path.c_str(), -1, result.data(), sizeNeeded, nullptr, nullptr);
    return result;
}

static bool FileExists(const std::wstring& path) {
    DWORD attrs = GetFileAttributesW(path.c_str());
    return attrs != INVALID_FILE_ATTRIBUTES && (attrs & FILE_ATTRIBUTE_DIRECTORY) == 0;
}

static std::vector<uint8_t> LoadEmbeddedResourceBytes(WORD resourceId) {
    HMODULE module = GetModuleHandleW(nullptr);
    HRSRC resource = FindResourceW(module, MAKEINTRESOURCEW(resourceId), MAKEINTRESOURCEW(10));
    if (!resource) return {};

    DWORD size = SizeofResource(module, resource);
    if (size == 0) return {};

    HGLOBAL loaded = LoadResource(module, resource);
    if (!loaded) return {};

    const void* data = LockResource(loaded);
    if (!data) return {};

    const auto* bytes = static_cast<const uint8_t*>(data);
    return std::vector<uint8_t>(bytes, bytes + size);
}

static std::string LoadEmbeddedResourceText(WORD resourceId) {
    std::vector<uint8_t> bytes = LoadEmbeddedResourceBytes(resourceId);
    if (bytes.empty()) return "";
    return std::string(reinterpret_cast<const char*>(bytes.data()), bytes.size());
}

static std::wstring GetExecutableDirectory() {
    wchar_t exePath[MAX_PATH] = {};
    DWORD len = GetModuleFileNameW(nullptr, exePath, MAX_PATH);
    if (len == 0 || len >= MAX_PATH) {
        return L".";
    }
    std::wstring path(exePath, len);
    size_t slash = path.find_last_of(L"\\/");
    return slash == std::wstring::npos ? L"." : path.substr(0, slash);
}

static std::wstring ResolveUiFontPath() {
    const wchar_t* fontName = L"JetBrainsMono-Light.ttf";
    std::vector<std::wstring> candidates;

    std::wstring exeDir = GetExecutableDirectory();
    candidates.push_back(exeDir + L"\\" + fontName);
    candidates.push_back(exeDir + L"\\Release\\" + fontName);

    wchar_t cwd[MAX_PATH] = {};
    if (GetCurrentDirectoryW(MAX_PATH, cwd) > 0) {
        std::wstring currentDir(cwd);
        candidates.push_back(currentDir + L"\\" + fontName);
        candidates.push_back(currentDir + L"\\Release\\" + fontName);
    }

    for (const auto& candidate : candidates) {
        if (FileExists(candidate)) {
            return candidate;
        }
    }
    return L"";
}

