void AddLog(const std::string& msg) {
    std::lock_guard<std::mutex> lock(g_LogsMutex);
    time_t now = time(nullptr);
    struct tm tstruct;
    localtime_s(&tstruct, &now);
    char timeStr[32];
    sprintf_s(timeStr, "[%02d:%02d:%02d]", tstruct.tm_hour, tstruct.tm_min, tstruct.tm_sec);
    g_Logs.push_back(std::string(timeStr) + " " + msg);
    if (g_Logs.size() > 100) {
        g_Logs.erase(g_Logs.begin());
    }
}

static void AddConsoleOutput(const std::string& msg) {
    std::lock_guard<std::mutex> lock(g_ConsoleMutex);
    g_ConsoleOutput.push_back(msg);
    if (g_ConsoleOutput.size() > 500) {
        g_ConsoleOutput.erase(g_ConsoleOutput.begin());
    }
}

static void AddTargetLifecycleOutput(DWORD pid, const std::string& reason) {
    if (pid == 0) {
        AddConsoleOutput("[lifecycle] Target process " + reason + ".");
        return;
    }
    AddConsoleOutput("[lifecycle] Target PID " + std::to_string(pid) + " " + reason + ".");
}

