static std::string UrlEncodeQuery(const std::string& value) {
    static const char hex[] = "0123456789ABCDEF";
    std::string encoded;
    for (unsigned char c : value) {
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.') {
            encoded += static_cast<char>(c);
        } else if (c == ' ') {
            encoded += '+';
        } else {
            encoded += '%';
            encoded += hex[(c >> 4) & 0x0F];
            encoded += hex[c & 0x0F];
        }
    }
    return encoded;
}

static void SearchApiInGoogle(const std::string& apiName) {
    if (apiName.empty() || apiName == "-") return;
    std::string url = "https://www.google.com/search?q=" + UrlEncodeQuery("Windows API " + apiName);
    HINSTANCE result = ShellExecuteW(nullptr, L"open", StringToWString(url).c_str(), nullptr, nullptr, SW_SHOWNORMAL);
    if (reinterpret_cast<INT_PTR>(result) <= 32) {
        AddLog("[error] could not open Google search for API: " + apiName);
    }
}

static void LookupNetworkIndicatorInVirusTotal(const std::string& type, const std::string& value) {
    if (value.empty() || value == "-") return;
    const char* route = type == "IP Address" ? "ip-address" : "domain";
    std::string url = "https://www.virustotal.com/gui/" + std::string(route) + "/" + UrlEncodeQuery(value);
    HINSTANCE result = ShellExecuteW(nullptr, L"open", StringToWString(url).c_str(), nullptr, nullptr, SW_SHOWNORMAL);
    if (reinterpret_cast<INT_PTR>(result) <= 32) AddLog("[error] could not open VirusTotal lookup for " + value + ".");
}

