static void DrawLogQueuePanel(float height) {
    ImGui::Text("Log Queue");
    ImGui::Spacing();
    ImGui::BeginChild("LogQueueChild", ImVec2(0.0f, height), true);
    {
        std::vector<std::string> logsSnapshot;
        {
            std::lock_guard<std::mutex> lock(g_LogsMutex);
            logsSnapshot = g_Logs;
        }

        for (size_t i = 0; i < logsSnapshot.size(); ++i) {
            const auto& logMsg = logsSnapshot[i];
            ImGui::PushID((int)i);
            bool selected = (g_SelectedLogIndex == (int)i);

            if (logMsg.find("[info]") != std::string::npos || logMsg.find("Captured") != std::string::npos) {
                ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.58f, 0.64f, 0.72f, 1.0f));
            } else if (logMsg.find("[warn]") != std::string::npos) {
                ImGui::PushStyleColor(ImGuiCol_Text, kUiGold);
            } else if (logMsg.find("[error]") != std::string::npos) {
                ImGui::PushStyleColor(ImGuiCol_Text, kUiRed);
            } else {
                ImGui::PushStyleColor(ImGuiCol_Text, kUiText);
            }
            if (ImGui::Selectable(logMsg.c_str(), selected, ImGuiSelectableFlags_AllowDoubleClick)) {
                g_SelectedLogIndex = (int)i;
            }
            ImGui::PopStyleColor();

            if (ImGui::BeginPopupContextItem("LogQueueContext")) {
                g_SelectedLogIndex = (int)i;
                if (ImGui::MenuItem("Copy Log Entry")) CopyToClipboard(logMsg);
                if (ImGui::MenuItem("Copy All")) CopyToClipboard(BuildLogQueueText(logsSnapshot));
                ImGui::EndPopup();
            }
            ImGui::PopID();
        }

        if (ImGui::BeginPopupContextWindow("LogQueuePanelContext", ImGuiPopupFlags_MouseButtonRight | ImGuiPopupFlags_NoOpenOverItems)) {
            if (ImGui::MenuItem("Copy All")) CopyToClipboard(BuildLogQueueText(logsSnapshot));
            ImGui::EndPopup();
        }
        
        // Auto scroll
        if (ImGui::GetScrollY() >= ImGui::GetScrollMaxY() - 25.0f) {
            ImGui::SetScrollHereY(1.0f);
        }
    }
    ImGui::EndChild();
}

