static const char* GetRegName(int reg, bool is64, bool is32) {
    static const char* regs64[] = { "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15" };
    static const char* regs32[] = { "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi" };
    if (is64) return regs64[reg & 15];
    return regs32[reg & 7];
}

static std::string NarrowString(const std::wstring& ws) {
    std::string s;
    s.reserve(ws.length());
    for (wchar_t wc : ws) {
        s.push_back(static_cast<char>(wc));
    }
    return s;
}

static std::string ReadStringFromProcess(HANDLE hProcess, uint64_t address) {
    if (address < 0x10000) return "";
    
    std::vector<char> buf(128);
    SIZE_T read = 0;
    if (!ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(address), buf.data(), buf.size(), &read) || read == 0) {
        return "";
    }
    
    bool isAscii = true;
    int asciiLen = 0;
    for (size_t i = 0; i < read; ++i) {
        if (buf[i] == '\0') {
            asciiLen = (int)i;
            break;
        }
        if (buf[i] < 32 || buf[i] > 126) {
            if (buf[i] != '\r' && buf[i] != '\n' && buf[i] != '\t') {
                isAscii = false;
                break;
            }
        }
    }
    
    if (isAscii && asciiLen > 0) {
        return std::string(buf.data(), asciiLen);
    }
    
    bool isUnicode = true;
    int uniLen = 0;
    const wchar_t* wbuf = reinterpret_cast<const wchar_t*>(buf.data());
    int wread = (int)(read / 2);
    for (int i = 0; i < wread; ++i) {
        if (wbuf[i] == L'\0') {
            uniLen = i;
            break;
        }
        if (wbuf[i] < 32 || wbuf[i] > 126) {
            if (wbuf[i] != L'\r' && wbuf[i] != L'\n' && wbuf[i] != L'\t') {
                isUnicode = false;
                break;
            }
        }
    }
    
    if (isUnicode && uniLen > 0) {
        std::wstring ws(wbuf, uniLen);
        return NarrowString(ws);
    }
    
    return "";
}

static std::string ResolveAddressToApiName(uint64_t address) {
    if (address < 0x10000) return "";
    
    HMODULE hMod = NULL;
    BOOL success = GetModuleHandleExW(
        GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(address),
        &hMod
    );
    
    if (success && hMod != NULL) {
        wchar_t path[MAX_PATH];
        if (GetModuleFileNameW(hMod, path, MAX_PATH)) {
            std::wstring wpath(path);
            size_t lastSlash = wpath.find_last_of(L"\\/");
            std::wstring dllName = (lastSlash != std::wstring::npos) ? wpath.substr(lastSlash + 1) : wpath;
            
            uint8_t* base = reinterpret_cast<uint8_t*>(hMod);
            IMAGE_DOS_HEADER* dos = reinterpret_cast<IMAGE_DOS_HEADER*>(base);
            if (dos->e_magic == IMAGE_DOS_SIGNATURE) {
                IMAGE_NT_HEADERS* nt = reinterpret_cast<IMAGE_NT_HEADERS*>(base + dos->e_lfanew);
                if (nt->Signature == IMAGE_NT_SIGNATURE) {
                    IMAGE_DATA_DIRECTORY* dir = &nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];
                    if (dir->Size > 0) {
                        IMAGE_EXPORT_DIRECTORY* exports = reinterpret_cast<IMAGE_EXPORT_DIRECTORY*>(base + dir->VirtualAddress);
                        uint32_t* functions = reinterpret_cast<uint32_t*>(base + exports->AddressOfFunctions);
                        uint32_t* names = reinterpret_cast<uint32_t*>(base + exports->AddressOfNames);
                        uint16_t* ordinals = reinterpret_cast<uint16_t*>(base + exports->AddressOfNameOrdinals);
                        
                        for (uint32_t i = 0; i < exports->NumberOfNames; ++i) {
                            uint32_t nameRva = names[i];
                            uint16_t ordinal = ordinals[i];
                            uint32_t funcRva = functions[ordinal];
                            uint8_t* funcAddr = base + funcRva;
                            
                            if (reinterpret_cast<uint64_t>(funcAddr) == address) {
                                std::string name = reinterpret_cast<const char*>(base + nameRva);
                                std::wstring wDllName = dllName;
                                std::string narrowDll = NarrowString(wDllName);
                                return narrowDll + "!" + name;
                            }
                        }
                    }
                }
            }
            
            std::wstring wDllName = dllName;
            std::string narrowDll = NarrowString(wDllName);
            char offsetStr[64];
            sprintf_s(offsetStr, "+0x%llX", address - reinterpret_cast<uint64_t>(hMod));
            return narrowDll + offsetStr;
        }
    }
    
    return "";
}

static std::string ResolveAddressToNearestApiName(uint64_t address) {
    if (address < 0x10000) return "";
    
    {
        std::lock_guard<std::mutex> lock(g_SymbolCacheMutex);
        auto it = g_CallerSymbolCache.find(address);
        if (it != g_CallerSymbolCache.end()) {
            return it->second;
        }
    }
    
    std::string result = "";
    
    HMODULE hMod = NULL;
    BOOL success = GetModuleHandleExW(
        GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(address),
        &hMod
    );
    
    if (success && hMod != NULL) {
        wchar_t path[MAX_PATH];
        if (GetModuleFileNameW(hMod, path, MAX_PATH)) {
            std::wstring wpath(path);
            size_t lastSlash = wpath.find_last_of(L"\\/");
            std::wstring dllName = (lastSlash != std::wstring::npos) ? wpath.substr(lastSlash + 1) : wpath;
            std::string narrowDll = NarrowString(dllName);
            
            uint8_t* base = reinterpret_cast<uint8_t*>(hMod);
            IMAGE_DOS_HEADER* dos = reinterpret_cast<IMAGE_DOS_HEADER*>(base);
            if (dos->e_magic == IMAGE_DOS_SIGNATURE) {
                IMAGE_NT_HEADERS* nt = reinterpret_cast<IMAGE_NT_HEADERS*>(base + dos->e_lfanew);
                if (nt->Signature == IMAGE_NT_SIGNATURE) {
                    IMAGE_DATA_DIRECTORY* dir = &nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];
                    if (dir->Size > 0) {
                        IMAGE_EXPORT_DIRECTORY* exports = reinterpret_cast<IMAGE_EXPORT_DIRECTORY*>(base + dir->VirtualAddress);
                        uint32_t* functions = reinterpret_cast<uint32_t*>(base + exports->AddressOfFunctions);
                        uint32_t* names = reinterpret_cast<uint32_t*>(base + exports->AddressOfNames);
                        uint16_t* ordinals = reinterpret_cast<uint16_t*>(base + exports->AddressOfNameOrdinals);
                        
                        std::string bestName;
                        uint64_t bestDiff = (uint64_t)-1;
                        
                        for (uint32_t i = 0; i < exports->NumberOfNames; ++i) {
                            uint32_t nameRva = names[i];
                            uint16_t ordinal = ordinals[i];
                            uint32_t funcRva = functions[ordinal];
                            uint64_t funcAddr = reinterpret_cast<uint64_t>(base + funcRva);
                            
                            if (address >= funcAddr) {
                                uint64_t diff = address - funcAddr;
                                if (diff < bestDiff) {
                                    bestDiff = diff;
                                    bestName = reinterpret_cast<const char*>(base + nameRva);
                                }
                            }
                        }
                        
                        if (!bestName.empty() && bestDiff < 0x20000) {
                            char offsetStr[64];
                            if (bestDiff > 0) {
                                sprintf_s(offsetStr, "+0x%llX", bestDiff);
                                result = narrowDll + "!" + bestName + offsetStr;
                            } else {
                                result = narrowDll + "!" + bestName;
                            }
                        }
                    }
                }
            }
            
            if (result.empty()) {
                char offsetStr[64];
                sprintf_s(offsetStr, "+0x%llX", address - reinterpret_cast<uint64_t>(hMod));
                result = narrowDll + offsetStr;
            }
        }
    }
    
    if (!result.empty()) {
        std::lock_guard<std::mutex> lock(g_SymbolCacheMutex);
        g_CallerSymbolCache[address] = result;
    }
    
    return result;
}

static std::string ResolveImmediate(HANDLE hProcess, uint64_t imm, bool is64, std::string& comment) {
    if (imm < 0x10000) return "";
    
    std::string resolved = ResolveAddressToApiName(imm);
    if (!resolved.empty()) {
        return resolved;
    }
    std::string str = ReadStringFromProcess(hProcess, imm);
    if (!str.empty()) {
        return "\"" + str + "\"";
    }
    
    // Check if imm points to a pointer that points to an API or a string
    uint64_t ptrVal = 0;
    SIZE_T read = 0;
    if (is64) {
        if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(imm), &ptrVal, 8, &read) && read == 8 && ptrVal >= 0x10000) {
            std::string res = ResolveAddressToApiName(ptrVal);
            if (!res.empty()) return "-> " + res;
            std::string s = ReadStringFromProcess(hProcess, ptrVal);
            if (!s.empty()) return "-> \"" + s + "\"";
        }
    } else {
        uint32_t val32 = 0;
        if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(imm), &val32, 4, &read) && read == 4 && val32 >= 0x10000) {
            std::string res = ResolveAddressToApiName(val32);
            if (!res.empty()) return "-> " + res;
            std::string s = ReadStringFromProcess(hProcess, val32);
            if (!s.empty()) return "-> \"" + s + "\"";
        }
    }
    return "";
}

static std::string FormatModRM(const uint8_t* code, int len, bool is64, uint64_t currentAddr, HANDLE hProcess, std::string& comment) {
    if (len < 2) return "";
    uint8_t modrm = code[1];
    uint8_t mod = (modrm >> 6) & 3;
    uint8_t reg = (modrm >> 3) & 7;
    uint8_t rm = modrm & 7;
    
    const char* regName = GetRegName(reg, is64, !is64);
    
    std::string rmStr;
    if (mod == 3) {
        rmStr = GetRegName(rm, is64, !is64);
    } else {
        std::ostringstream oss;
        oss << (is64 ? "qword ptr [" : "dword ptr [");
        if (rm == 4) {
            if (len >= 3) {
                uint8_t sib = code[2];
                uint8_t scale = (sib >> 6) & 3;
                uint8_t index = (sib >> 3) & 7;
                uint8_t base = sib & 7;
                
                bool hasBase = true;
                if (base == 5 && mod == 0) {
                    hasBase = false;
                }
                
                if (hasBase) {
                    oss << GetRegName(base, is64, !is64);
                }
                
                if (index != 4) {
                    if (hasBase) oss << " + ";
                    oss << GetRegName(index, is64, !is64);
                    if (scale > 0) oss << "*" << (1 << scale);
                }
                
                int dispOffset = 3;
                if (base == 5 && mod == 0) {
                    int32_t disp = *reinterpret_cast<const int32_t*>(code + dispOffset);
                    oss << "0x" << std::hex << disp;
                } else if (mod == 1) {
                    int8_t disp = *reinterpret_cast<const int8_t*>(code + dispOffset);
                    if (disp != 0) {
                        oss << (disp > 0 ? " + 0x" : " - 0x") << std::hex << std::abs(disp);
                    }
                } else if (mod == 2) {
                    int32_t disp = *reinterpret_cast<const int32_t*>(code + dispOffset);
                    if (disp != 0) {
                        oss << (disp > 0 ? " + 0x" : " - 0x") << std::hex << std::abs(disp);
                    }
                }
            }
        } else {
            if (mod == 0) {
                if (rm == 5) {
                    if (is64) {
                        int32_t disp = *reinterpret_cast<const int32_t*>(code + 2);
                        uint64_t targetAddr = currentAddr + len + disp;
                        oss << "rip";
                        if (disp != 0) {
                            oss << (disp > 0 ? " + 0x" : " - 0x") << std::hex << std::abs(disp);
                        }
                        
                        std::string addrName = ResolveAddressToApiName(targetAddr);
                        uint64_t derefVal = 0;
                        SIZE_T read = 0;
                        bool readOk = ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(targetAddr), &derefVal, 8, &read) && (read == 8);
                        
                        std::string derefName;
                        std::string derefStr;
                        if (readOk && derefVal >= 0x10000) {
                            derefName = ResolveAddressToApiName(derefVal);
                            if (derefName.empty()) {
                                derefStr = ReadStringFromProcess(hProcess, derefVal);
                            }
                        }
                        
                        std::ostringstream ann;
                        if (!addrName.empty()) {
                            ann << addrName;
                            if (readOk && derefVal >= 0x10000) {
                                if (!derefName.empty()) {
                                    ann << " -> " << derefName;
                                } else if (!derefStr.empty()) {
                                    ann << " -> \"" << derefStr << "\"";
                                }
                            }
                        } else {
                            if (!derefName.empty()) {
                                ann << "-> " << derefName;
                            } else if (!derefStr.empty()) {
                                ann << "-> \"" << derefStr << "\"";
                            } else {
                                std::string directStr = ReadStringFromProcess(hProcess, targetAddr);
                                if (!directStr.empty()) {
                                    ann << "\"" << directStr << "\"";
                                }
                            }
                        }
                        
                        std::string annStr = ann.str();
                        if (!annStr.empty()) {
                            comment = "; " + annStr;
                        }
                    } else {
                        uint32_t disp = *reinterpret_cast<const uint32_t*>(code + 2);
                        oss << "0x" << std::hex << disp;
                        
                        std::string addrName = ResolveAddressToApiName(disp);
                        uint32_t derefVal = 0;
                        SIZE_T read = 0;
                        bool readOk = ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>((uint64_t)disp), &derefVal, 4, &read) && (read == 4);
                        
                        std::string derefName;
                        std::string derefStr;
                        if (readOk && derefVal >= 0x10000) {
                            derefName = ResolveAddressToApiName(derefVal);
                            if (derefName.empty()) {
                                derefStr = ReadStringFromProcess(hProcess, derefVal);
                            }
                        }
                        
                        std::ostringstream ann;
                        if (!addrName.empty()) {
                            ann << addrName;
                            if (readOk && derefVal >= 0x10000) {
                                if (!derefName.empty()) {
                                    ann << " -> " << derefName;
                                } else if (!derefStr.empty()) {
                                    ann << " -> \"" << derefStr << "\"";
                                }
                            }
                        } else {
                            if (!derefName.empty()) {
                                ann << "-> " << derefName;
                            } else if (!derefStr.empty()) {
                                ann << "-> \"" << derefStr << "\"";
                            } else {
                                std::string directStr = ReadStringFromProcess(hProcess, disp);
                                if (!directStr.empty()) {
                                    ann << "\"" << directStr << "\"";
                                }
                            }
                        }
                        
                        std::string annStr = ann.str();
                        if (!annStr.empty()) {
                            comment = "; " + annStr;
                        }
                    }
                } else {
                    oss << GetRegName(rm, is64, !is64);
                }
            } else if (mod == 1) {
                int8_t disp = *reinterpret_cast<const int8_t*>(code + 2);
                oss << GetRegName(rm, is64, !is64);
                if (disp != 0) {
                    oss << (disp > 0 ? " + 0x" : " - 0x") << std::hex << std::abs(disp);
                }
            } else if (mod == 2) {
                int32_t disp = *reinterpret_cast<const int32_t*>(code + 2);
                oss << GetRegName(rm, is64, !is64);
                if (disp != 0) {
                    oss << (disp > 0 ? " + 0x" : " - 0x") << std::hex << std::abs(disp);
                }
            }
        }
        oss << "]";
        rmStr = oss.str();
    }
    
    uint8_t opcode = code[0];
    if (opcode == 0xFF || opcode == 0x8F || opcode == 0xF6 || opcode == 0xF7 || opcode == 0xC6 || opcode == 0xC7 || (opcode >= 0xD0 && opcode <= 0xD3) || opcode == 0x80 || opcode == 0x81 || opcode == 0x83) {
        return rmStr;
    }
    
    if (opcode == 0x8D) {
        return std::string(regName) + ", " + rmStr;
    }
    if (opcode == 0x8B || opcode == 0x8A || opcode == 0x03 || opcode == 0x0B || opcode == 0x23 || opcode == 0x2B || opcode == 0x33 || opcode == 0x3B) {
        return std::string(regName) + ", " + rmStr;
    }
    return rmStr + ", " + regName;
}

static uint64_t FollowJumps(HANDLE hProcess, uint64_t address) {
    uint8_t code[6];
    SIZE_T read = 0;
    if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(address), code, sizeof(code), &read) && read >= 2) {
        if (code[0] == 0xE9 && read >= 5) {
            int32_t offset = *reinterpret_cast<const int32_t*>(code + 1);
            return FollowJumps(hProcess, address + 5 + offset);
        }
        if (code[0] == 0xEB) {
            int8_t offset = *reinterpret_cast<const int8_t*>(code + 1);
            return FollowJumps(hProcess, address + 2 + offset);
        }
        if (code[0] == 0xFF && code[1] == 0x25 && read >= 6) {
            uint64_t ptrAddr = 0;
            if (!g_Target.is32Bit) {
                int32_t offset = *reinterpret_cast<const int32_t*>(code + 2);
                ptrAddr = address + 6 + offset;
            } else {
                ptrAddr = *reinterpret_cast<const uint32_t*>(code + 2);
            }
            uint64_t targetVal = 0;
            if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(ptrAddr), &targetVal, g_Target.is32Bit ? 4 : 8, &read)) {
                return targetVal;
            }
        }
    }
    return address;
}

static std::string DecodeInstructionText(uint64_t currentAddr, const uint8_t* code, int len, bool is64, HANDLE hProcess, std::string& comment) {
    if (len <= 0) return "db 0x00";
    
    uint8_t opcode = code[0];
    
    int opcodeIdx = 0;
    bool isRex = false;
    uint8_t rex = 0;
    while (opcodeIdx < len) {
        uint8_t b = code[opcodeIdx];
        if (b == 0x66 || b == 0x67 || b == 0x2E || b == 0x3E || b == 0x26 || b == 0x64 || b == 0x65 || b == 0x36 || b == 0xF0 || b == 0xF2 || b == 0xF3) {
            opcodeIdx++;
        } else if (is64 && (b & 0xF0) == 0x40) {
            isRex = true;
            rex = b;
            opcodeIdx++;
        } else {
            break;
        }
    }
    
    if (opcodeIdx >= len) return "db 0x" + StaticHex(code[0]);
    
    opcode = code[opcodeIdx];
    
    if (opcode == 0x90) return "nop";
    if (opcode == 0xCC) return "int3";
    if (opcode == 0xC3) return "ret";
    if (opcode == 0xC2) {
        uint16_t imm = *reinterpret_cast<const uint16_t*>(code + opcodeIdx + 1);
        std::ostringstream oss;
        oss << "ret 0x" << std::hex << imm;
        return oss.str();
    }
    
    if (opcode >= 0x50 && opcode <= 0x57) {
        int reg = opcode - 0x50;
        return "push " + std::string(GetRegName(reg, is64, !is64));
    }
    if (opcode >= 0x58 && opcode <= 0x5F) {
        int reg = opcode - 0x58;
        return "pop " + std::string(GetRegName(reg, is64, !is64));
    }
    
    if (opcode >= 0x70 && opcode <= 0x7F) {
        static const char* jccNames[] = { "jo", "jno", "jb", "jae", "je", "jne", "jbe", "ja", "js", "jns", "jp", "jnp", "jl", "jge", "jle", "jg" };
        const char* name = jccNames[opcode - 0x70];
        int8_t offset = *reinterpret_cast<const int8_t*>(code + opcodeIdx + 1);
        uint64_t target = currentAddr + len + offset;
        std::ostringstream oss;
        oss << name << " 0x" << std::hex << target;
        return oss.str();
    }
    
    if (opcode == 0x0F) {
        if (opcodeIdx + 1 < len) {
            uint8_t nextOp = code[opcodeIdx + 1];
            if (nextOp >= 0x80 && nextOp <= 0x8F) {
                static const char* jccNames[] = { "jo", "jno", "jb", "jae", "je", "jne", "jbe", "ja", "js", "jns", "jp", "jnp", "jl", "jge", "jle", "jg" };
                const char* name = jccNames[nextOp - 0x80];
                int32_t offset = *reinterpret_cast<const int32_t*>(code + opcodeIdx + 2);
                uint64_t target = currentAddr + len + offset;
                std::ostringstream oss;
                oss << name << " 0x" << std::hex << target;
                return oss.str();
            }
        }
    }
    
    if (opcode == 0xE8 || opcode == 0xE9) {
        const char* name = (opcode == 0xE8) ? "call" : "jmp";
        int32_t offset = *reinterpret_cast<const int32_t*>(code + opcodeIdx + 1);
        uint64_t target = currentAddr + len + offset;
        
        uint64_t resolvedTarget = FollowJumps(hProcess, target);
        std::string resolved = ResolveAddressToApiName(resolvedTarget);
        if (!resolved.empty()) {
            comment = "; " + resolved;
            if (opcode == 0xE8) {
                size_t lastBang = resolved.find('!');
                std::string shortName = (lastBang != std::string::npos) ? resolved.substr(lastBang + 1) : resolved;
                return "call " + shortName;
            }
        }
        std::ostringstream oss;
        oss << name << " 0x" << std::hex << target;
        return oss.str();
    }
    
    if (opcode == 0xEB) {
        int8_t offset = *reinterpret_cast<const int8_t*>(code + opcodeIdx + 1);
        uint64_t target = currentAddr + len + offset;
        std::ostringstream oss;
        oss << "jmp 0x" << std::hex << target;
        return oss.str();
    }
    
    if (opcode == 0x6A || opcode == 0x68) {
        uint64_t imm = 0;
        if (opcode == 0x6A) {
            imm = code[opcodeIdx + 1];
        } else {
            imm = *reinterpret_cast<const uint32_t*>(code + opcodeIdx + 1);
        }
        
        std::string resolved = ResolveImmediate(hProcess, imm, is64, comment);
        if (!resolved.empty()) {
            comment = "; " + resolved;
        }
        
        std::ostringstream oss;
        oss << "push 0x" << std::hex << imm;
        return oss.str();
    }
    
    if (opcode == 0x80 || opcode == 0x81 || opcode == 0x83) {
        uint8_t modrm = code[opcodeIdx + 1];
        uint8_t reg = (modrm >> 3) & 7;
        static const char* opNames[] = { "add", "or", "adc", "sbb", "and", "sub", "xor", "cmp" };
        const char* opName = opNames[reg];
        
        int immSize = (opcode == 0x81) ? 4 : 1;
        int immOffset = len - immSize;
        uint64_t imm = 0;
        if (immSize == 1) {
            imm = code[immOffset];
        } else {
            imm = *reinterpret_cast<const uint32_t*>(code + immOffset);
        }
        
        std::string rmComment;
        std::string rmStr = FormatModRM(code + opcodeIdx, len - opcodeIdx, is64, currentAddr + opcodeIdx, hProcess, rmComment);
        if (!rmComment.empty()) comment = rmComment;
        
        std::string immComment = ResolveImmediate(hProcess, imm, is64, comment);
        if (!immComment.empty()) {
            if (!comment.empty()) comment += " | ";
            comment += "Value: " + immComment;
        }
        
        std::ostringstream oss;
        oss << opName << " " << rmStr << ", 0x" << std::hex << imm;
        return oss.str();
    }
    
    if (opcode == 0xF6 || opcode == 0xF7) {
        uint8_t modrm = code[opcodeIdx + 1];
        uint8_t reg = (modrm >> 3) & 7;
        if (reg == 0) {
            int immSize = (opcode == 0xF6) ? 1 : 4;
            int immOffset = len - immSize;
            uint64_t imm = 0;
            if (immSize == 1) {
                imm = code[immOffset];
            } else {
                imm = *reinterpret_cast<const uint32_t*>(code + immOffset);
            }
            std::string rmComment;
            std::string rmStr = FormatModRM(code + opcodeIdx, len - opcodeIdx, is64, currentAddr + opcodeIdx, hProcess, rmComment);
            if (!rmComment.empty()) comment = rmComment;
            
            std::string immComment = ResolveImmediate(hProcess, imm, is64, comment);
            if (!immComment.empty()) {
                if (!comment.empty()) comment += " | ";
                comment += "Value: " + immComment;
            }
            
            std::ostringstream oss;
            oss << "test " << rmStr << ", 0x" << std::hex << imm;
            return oss.str();
        }
    }
    
    if (opcode == 0xC6 || opcode == 0xC7) {
        int immOffset = len - (opcode == 0xC6 ? 1 : 4);
        uint64_t imm = 0;
        if (opcode == 0xC6) {
            imm = code[immOffset];
        } else {
            imm = *reinterpret_cast<const uint32_t*>(code + immOffset);
        }
        std::string rmComment;
        std::string rmStr = FormatModRM(code + opcodeIdx, len - opcodeIdx, is64, currentAddr + opcodeIdx, hProcess, rmComment);
        if (!rmComment.empty()) comment = rmComment;
        
        std::string immComment = ResolveImmediate(hProcess, imm, is64, comment);
        if (!immComment.empty()) {
            if (!comment.empty()) comment += " | ";
            comment += "Value: " + immComment;
        }
        
        std::ostringstream oss;
        oss << "mov " << rmStr << ", 0x" << std::hex << imm;
        return oss.str();
    }
    
    if (opcode >= 0xB0 && opcode <= 0xBF) {
        int reg = (opcode & 7);
        bool isReg64 = is64 && (opcode >= 0xB8) && (rex & 0x08);
        uint64_t imm = 0;
        if (opcode >= 0xB8) {
            if (isReg64) {
                imm = *reinterpret_cast<const uint64_t*>(code + opcodeIdx + 1);
            } else {
                imm = *reinterpret_cast<const uint32_t*>(code + opcodeIdx + 1);
            }
        } else {
            imm = code[opcodeIdx + 1];
        }
        
        std::string resolved = ResolveImmediate(hProcess, imm, is64, comment);
        if (!resolved.empty()) {
            comment = "; " + resolved;
        }
        
        std::ostringstream oss;
        oss << "mov " << GetRegName(reg, isReg64, !isReg64) << ", 0x" << std::hex << imm;
        return oss.str();
    }
    
    if (opcode == 0xFF) {
        if (opcodeIdx + 1 < len) {
            uint8_t modrm = code[opcodeIdx + 1];
            uint8_t reg = (modrm >> 3) & 7;
            if (reg == 2 || reg == 4) {
                const char* name = (reg == 2) ? "call" : "jmp";
                std::string rmComment;
                std::string rmStr = FormatModRM(code + opcodeIdx, len - opcodeIdx, is64, currentAddr + opcodeIdx, hProcess, rmComment);
                if (!rmComment.empty()) {
                    comment = rmComment;
                }
                
                uint8_t mod = (modrm >> 6) & 3;
                uint8_t rm = modrm & 7;
                if (is64 && mod == 0 && rm == 5) {
                    int32_t disp = *reinterpret_cast<const int32_t*>(code + opcodeIdx + 2);
                    uint64_t ptrAddr = currentAddr + len + disp;
                    uint64_t targetVal = 0;
                    SIZE_T r = 0;
                    if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(ptrAddr), &targetVal, sizeof(targetVal), &r) && r == sizeof(targetVal)) {
                        std::string resolved = ResolveAddressToApiName(targetVal);
                        if (!resolved.empty()) {
                            comment = "; " + resolved;
                            size_t lastBang = resolved.find('!');
                            std::string shortName = (lastBang != std::string::npos) ? resolved.substr(lastBang + 1) : resolved;
                            return std::string(name) + " qword ptr [" + shortName + "]";
                        }
                    }
                } else if (!is64 && mod == 0 && rm == 5) {
                    uint32_t ptrAddr = *reinterpret_cast<const uint32_t*>(code + opcodeIdx + 2);
                    uint32_t targetVal = 0;
                    SIZE_T r = 0;
                    if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>((uintptr_t)ptrAddr), &targetVal, sizeof(targetVal), &r) && r == sizeof(targetVal)) {
                        std::string resolved = ResolveAddressToApiName(targetVal);
                        if (!resolved.empty()) {
                            comment = "; " + resolved;
                            size_t lastBang = resolved.find('!');
                            std::string shortName = (lastBang != std::string::npos) ? resolved.substr(lastBang + 1) : resolved;
                            return std::string(name) + " dword ptr [" + shortName + "]";
                        }
                    }
                }
                
                return std::string(name) + " " + rmStr;
            } else if (reg == 6) {
                std::string rmComment;
                std::string rmStr = FormatModRM(code + opcodeIdx, len - opcodeIdx, is64, currentAddr + opcodeIdx, hProcess, rmComment);
                if (!rmComment.empty()) comment = rmComment;
                
                uint8_t mod = (modrm >> 6) & 3;
                uint8_t rm = modrm & 7;
                if (is64 && mod == 0 && rm == 5) {
                    int32_t disp = *reinterpret_cast<const int32_t*>(code + opcodeIdx + 2);
                    uint64_t ptrAddr = currentAddr + len + disp;
                    uint64_t targetVal = 0;
                    SIZE_T r = 0;
                    if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(ptrAddr), &targetVal, sizeof(targetVal), &r) && r == sizeof(targetVal)) {
                        std::string resolved = ResolveAddressToApiName(targetVal);
                        if (!resolved.empty()) {
                            comment = "; " + resolved;
                        } else {
                            std::string str = ReadStringFromProcess(hProcess, targetVal);
                            if (!str.empty()) {
                                comment = "; \"" + str + "\"";
                            }
                        }
                    }
                } else if (!is64 && mod == 0 && rm == 5) {
                    uint32_t ptrAddr = *reinterpret_cast<const uint32_t*>(code + opcodeIdx + 2);
                    uint32_t targetVal = 0;
                    SIZE_T r = 0;
                    if (ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>((uintptr_t)ptrAddr), &targetVal, sizeof(targetVal), &r) && r == sizeof(targetVal)) {
                        std::string resolved = ResolveAddressToApiName(targetVal);
                        if (!resolved.empty()) {
                            comment = "; " + resolved;
                        } else {
                            std::string str = ReadStringFromProcess(hProcess, targetVal);
                            if (!str.empty()) {
                                comment = "; \"" + str + "\"";
                            }
                        }
                    }
                }
                
                return "push " + rmStr;
            }
        }
    }
    
    const char* instrName = "db";
    switch (opcode) {
        case 0x88: case 0x89: case 0x8A: case 0x8B:
            instrName = "mov"; break;
        case 0x8D:
            instrName = "lea"; break;
        case 0x01: case 0x03:
            instrName = "add"; break;
        case 0x29: case 0x2B:
            instrName = "sub"; break;
        case 0x31: case 0x33:
            instrName = "xor"; break;
        case 0x39: case 0x3B:
            instrName = "cmp"; break;
        case 0x85:
            instrName = "test"; break;
        default:
            break;
    }
    
    if (std::string(instrName) != "db") {
        std::string rmComment;
        std::string operands = FormatModRM(code + opcodeIdx, len - opcodeIdx, is64, currentAddr + opcodeIdx, hProcess, rmComment);
        if (!rmComment.empty()) {
            comment = rmComment;
        }
        return std::string(instrName) + " " + operands;
    }
    
    std::ostringstream fallback;
    fallback << "db ";
    for (int i = opcodeIdx; i < len; ++i) {
        fallback << "0x" << std::hex << (int)code[i];
        if (i + 1 < len) fallback << ", ";
    }
    return fallback.str();
}

static int GetInstructionLength(const uint8_t* code, int maxLen, bool is32Bit) {
    if (maxLen <= 0) return 0;
    int idx = 0;
    bool hasRex = false;
    uint8_t rex = 0;

    while (idx < maxLen) {
        uint8_t b = code[idx];
        if (b == 0x66 || b == 0x67 || b == 0x2E || b == 0x3E || b == 0x26 || b == 0x64 || b == 0x65 || b == 0x36 || b == 0xF0 || b == 0xF2 || b == 0xF3) {
            idx++;
        } else if (!is32Bit && (b & 0xF0) == 0x40) {
            hasRex = true;
            rex = b;
            idx++;
        } else {
            break;
        }
    }

    if (idx >= maxLen) return idx;

    uint8_t opcode = code[idx++];
    
    bool isTwoByte = false;
    if (opcode == 0x0F) {
        if (idx >= maxLen) return idx;
        opcode = code[idx++];
        isTwoByte = true;
    }

    bool hasModRM = false;
    int immSize = 0;

    if (isTwoByte) {
        if (opcode >= 0x80 && opcode <= 0x8F) {
            immSize = 4;
        } else if (opcode == 0xB6 || opcode == 0xB7 || opcode == 0xBE || opcode == 0xBF) {
            hasModRM = true;
        } else {
            hasModRM = true;
        }
    } else {
        switch (opcode) {
            case 0x80: case 0x81: case 0x83:
            case 0xC0: case 0xC1:
                hasModRM = true;
                immSize = (opcode == 0x81) ? 4 : 1;
                break;
            case 0xC6: case 0xC7:
                hasModRM = true;
                immSize = (opcode == 0xC6) ? 1 : 4;
                break;
            case 0xF6: case 0xF7:
                hasModRM = true;
                if (idx < maxLen) {
                    uint8_t modrm = code[idx];
                    uint8_t reg = (modrm >> 3) & 7;
                    if (reg == 0) {
                        immSize = (opcode == 0xF6) ? 1 : 4;
                    }
                }
                break;
            case 0x88: case 0x89: case 0x8A: case 0x8B:
            case 0x8D:
            case 0x01: case 0x03: case 0x09: case 0x0B: case 0x21: case 0x23: case 0x29: case 0x2B: case 0x31: case 0x33: case 0x39: case 0x3B:
            case 0x85:
            case 0x8F:
            case 0xD0: case 0xD1: case 0xD2: case 0xD3:
            case 0xFE: case 0xFF:
                hasModRM = true;
                break;
            case 0x6A:
                immSize = 1;
                break;
            case 0x68:
                immSize = 4;
                break;
            case 0xE8: case 0xE9:
                immSize = 4;
                break;
            case 0xEB:
                immSize = 1;
                break;
            case 0x70: case 0x71: case 0x72: case 0x73: case 0x74: case 0x75: case 0x76: case 0x77:
            case 0x78: case 0x79: case 0x7A: case 0x7B: case 0x7C: case 0x7D: case 0x7E: case 0x7F:
                immSize = 1;
                break;
            case 0xB0: case 0xB1: case 0xB2: case 0xB3: case 0xB4: case 0xB5: case 0xB6: case 0xB7:
                immSize = 1;
                break;
            case 0xB8: case 0xB9: case 0xBA: case 0xBB: case 0xBC: case 0xBD: case 0xBE: case 0xBF:
                immSize = (hasRex && (rex & 0x08)) ? 8 : 4;
                break;
            default:
                break;
        }
    }

    if (hasModRM) {
        if (idx >= maxLen) return idx;
        uint8_t modrm = code[idx++];
        uint8_t mod = (modrm >> 6) & 3;
        uint8_t rm = modrm & 7;

        if (mod != 3) {
            if (rm == 4) {
                if (idx >= maxLen) return idx;
                uint8_t sib = code[idx++];
                uint8_t base = sib & 7;
                if (base == 5 && mod == 0) {
                    idx += 4;
                }
            }
            
            if (mod == 0) {
                if (rm == 5) {
                    idx += 4;
                }
            } else if (mod == 1) {
                idx += 1;
            } else if (mod == 2) {
                idx += 4;
            }
        }
    }

    idx += immSize;
    return (idx > maxLen) ? maxLen : idx;
}

static uint64_t FindFunctionStart(HANDLE hProcess, uint64_t address, bool is32Bit) {
    if (address == 0) return 0;
    
    uint64_t scanStart = (address > 256) ? (address - 256) : 0;
    std::vector<uint8_t> buffer(address - scanStart);
    SIZE_T bytesRead = 0;
    if (!ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(scanStart), buffer.data(), buffer.size(), &bytesRead) || bytesRead == 0) {
        return address;
    }

    for (int i = (int)bytesRead - 3; i >= 0; --i) {
        if (buffer[i] == 0x55) {
            if (is32Bit) {
                if (i + 2 < (int)bytesRead && buffer[i+1] == 0x8B && buffer[i+2] == 0xEC) {
                    return scanStart + i;
                }
            } else {
                if (i + 3 < (int)bytesRead && buffer[i+1] == 0x48 && buffer[i+2] == 0x89 && buffer[i+3] == 0xE5) {
                    return scanStart + i;
                }
            }
            if (i > 0 && (buffer[i-1] == 0xC3 || buffer[i-1] == 0xCC || buffer[i-1] == 0x90)) {
                return scanStart + i;
            }
        }
        
        if (i > 0 && (buffer[i-1] == 0xC3 || buffer[i-1] == 0xCC || buffer[i-1] == 0x90)) {
            if (is32Bit && buffer[i] == 0x83 && buffer[i+1] == 0xEC) {
                return scanStart + i;
            }
            if (!is32Bit && buffer[i] == 0x48 && buffer[i+1] == 0x83 && buffer[i+2] == 0xEC) {
                return scanStart + i;
            }
        }
        
        if (buffer[i] == 0xC3) {
            int nextStart = i + 1;
            while (nextStart < (int)bytesRead && (buffer[nextStart] == 0xCC || buffer[nextStart] == 0x90)) {
                nextStart++;
            }
            if (nextStart < (int)bytesRead && nextStart <= (int)bytesRead - 2) {
                return scanStart + nextStart;
            }
        }
    }
    
    return address;
}

static void CacheDisassemblyForAddress(uint64_t address) {
    if (address == 0) return;
    if (!g_Target.active || g_Target.pid == 0) return;
    
    {
        std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
        for (const auto& kv : g_DisasmCache) {
            const auto& entry = kv.second;
            if (address >= entry.funcStart && address < entry.funcStart + entry.size) {
                return;
            }
        }
    }
    
    HANDLE hProcess = OpenProcess(PROCESS_VM_READ, FALSE, g_Target.pid);
    if (!hProcess) return;
    
    uint64_t funcStart = FindFunctionStart(hProcess, address, g_Target.is32Bit);
    
    {
        std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
        if (g_DisasmCache.find(funcStart) != g_DisasmCache.end()) {
            CloseHandle(hProcess);
            return;
        }
    }
    
    std::vector<uint8_t> buffer(512);
    SIZE_T bytesRead = 0;
    if (!ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(funcStart), buffer.data(), buffer.size(), &bytesRead) || bytesRead == 0) {
        CloseHandle(hProcess);
        return;
    }
    
    CachedDisassembly cached;
    cached.funcStart = funcStart;
    
    uint64_t currentAddr = funcStart;
    int offset = 0;
    int maxDisasm = 384;
    bool is64 = !g_Target.is32Bit;
    
    while (offset < maxDisasm && offset < (int)bytesRead) {
        int len = GetInstructionLength(buffer.data() + offset, (int)bytesRead - offset, !is64);
        if (len <= 0) len = 1;
        
        DisasmLine line;
        line.address = currentAddr;
        
        std::ostringstream bytesOss;
        for (int i = 0; i < len; ++i) {
            bytesOss << std::hex << std::setw(2) << std::setfill('0') << (int)buffer[offset + i] << " ";
        }
        line.bytes = bytesOss.str();
        
        line.instruction = DecodeInstructionText(currentAddr, buffer.data() + offset, len, is64, hProcess, line.comment);
        
        cached.lines.push_back(line);
        
        uint8_t opcode = buffer[offset];
        if (opcode == 0xC3 || opcode == 0xC2) {
            bool hasPadding = true;
            int paddingStart = offset + len;
            if (paddingStart < (int)bytesRead) {
                for (int j = paddingStart; j < paddingStart + 4 && j < (int)bytesRead; ++j) {
                    if (buffer[j] != 0xCC && buffer[j] != 0x90) {
                        hasPadding = false;
                    }
                }
            } else {
                hasPadding = false;
            }
            if (hasPadding) {
                offset += len;
                break;
            }
        }
        
        currentAddr += len;
        offset += len;
    }
    
    cached.size = (offset > 0) ? offset : 1;
    CloseHandle(hProcess);
    
    {
        std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
        g_DisasmCache[funcStart] = std::move(cached);
    }
}

static std::string FormatTelemetryEventInline(const TelemetryEvent& ev) {
    std::ostringstream oss;
    oss << ev.apiName << "(";
    for (size_t i = 0; i < ev.parameters.size(); ++i) {
        const auto& param = ev.parameters[i];
        oss << param.name << "=";
        std::string dec = DecodeParameterValue(ev.apiName, param);
        if (dec.empty()) {
            if (!param.decoded.empty()) {
                dec = param.decoded;
            } else {
                dec = "0x" + StaticHex(param.value);
            }
        }
        // Truncate dec if it is too long (e.g. max 40 chars)
        if (dec.length() > 40) {
            dec = dec.substr(0, 37) + "...";
        }
        oss << dec;
        if (i + 1 < ev.parameters.size()) {
            oss << ", ";
        }
    }
    oss << ") -> 0x" << std::hex << ev.returnValue;
    return oss.str();
}

// Call Graph Node Structure
struct CallGraphNode {
    std::string name;
    uint64_t address = 0;
    bool isApi = false;
    std::unordered_map<std::string, CallGraphNode> children;
};



static uint64_t ResolveFunctionStart(uint64_t address) {
    if (address == 0) return 0;
    
    {
        std::lock_guard<std::mutex> lock(g_ResolvedFuncStartsMutex);
        auto it = g_ResolvedFuncStarts.find(address);
        if (it != g_ResolvedFuncStarts.end()) {
            return it->second;
        }
    }

    {
        std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
        for (const auto& kv : g_DisasmCache) {
            const auto& entry = kv.second;
            if (address >= entry.funcStart && address < entry.funcStart + entry.size) {
                std::lock_guard<std::mutex> lock2(g_ResolvedFuncStartsMutex);
                g_ResolvedFuncStarts[address] = entry.funcStart;
                return entry.funcStart;
            }
        }
    }

    uint64_t resolved = address;
    if (g_Target.active && g_Target.pid != 0) {
        HANDLE hProcess = OpenProcess(PROCESS_VM_READ, FALSE, g_Target.pid);
        if (hProcess) {
            resolved = FindFunctionStart(hProcess, address, g_Target.is32Bit);
            CloseHandle(hProcess);
        }
    }

    {
        std::lock_guard<std::mutex> lock(g_ResolvedFuncStartsMutex);
        g_ResolvedFuncStarts[address] = resolved;
    }
    return resolved;
}

static void JumpToFunctionAddress(uint64_t address) {
    if (address == 0) return;
    
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    std::vector<FunctionCallerSummary> callers = BuildFunctionCallerSummaries(eventsSnapshot, modules);

    for (size_t i = 0; i < callers.size(); ++i) {
        if (callers[i].address == address) {
            g_DisasmScrollToAddress = address;
            break;
        }
    }
}

static CallGraphNode BuildCallGraph(
    const FunctionCallerSummary& caller,
    const std::vector<TelemetryEvent>& events,
    const std::vector<ObservedModule>& modules
) {
    CallGraphNode root;
    root.name = caller.functionName;
    root.address = caller.address;
    root.isApi = false;

    for (int idx : caller.eventIndices) {
        if (idx < 0 || idx >= (int)events.size()) continue;
        const auto& ev = events[idx];

        std::vector<CallGraphNode> path;
        int k = -1;
        for (size_t i = 0; i < ev.callStack.size(); ++i) {
            if (ResolveFunctionStart(ev.callStack[i]) == caller.address) {
                k = (int)i;
                break;
            }
        }

        if (k >= 0) {
            for (int j = k - 1; j >= 0; --j) {
                uint64_t addr = ResolveFunctionStart(ev.callStack[j]);
                CallGraphNode node;
                node.address = addr;
                node.isApi = false;
                node.name = FormatFunctionName(addr, "", modules);
                path.push_back(node);
            }
        }

        CallGraphNode apiNode;
        apiNode.name = ev.apiName;
        apiNode.address = 0;
        apiNode.isApi = true;
        path.push_back(apiNode);

        CallGraphNode* current = &root;
        for (const auto& node : path) {
            auto& child = current->children[node.name];
            if (child.name.empty()) {
                child = node;
            }
            current = &child;
        }
    }
    return root;
}

static int g_CallGraphExpandCollapseState = 0; // 0 = normal, 1 = expand all, 2 = collapse all

static void RenderCallGraphNode(const CallGraphNode& node, const std::vector<ObservedModule>& modules) {
    ImGui::PushID(node.name.c_str());
    
    ImGuiTreeNodeFlags flags = ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_OpenOnDoubleClick | ImGuiTreeNodeFlags_DefaultOpen;
    if (node.children.empty()) {
        flags |= ImGuiTreeNodeFlags_Leaf | ImGuiTreeNodeFlags_NoTreePushOnOpen;
    }

    if (g_CallGraphExpandCollapseState == 1) {
        ImGui::SetNextItemOpen(true);
    } else if (g_CallGraphExpandCollapseState == 2) {
        ImGui::SetNextItemOpen(false);
    }

    bool isOpen = ImGui::TreeNodeEx(node.name.c_str(), flags);

    if (ImGui::IsItemHovered()) {
        if (ImGui::IsMouseDoubleClicked(0) && !node.isApi && node.address != 0) {
            JumpToFunctionAddress(node.address);
        }
        if (ImGui::BeginPopupContextItem("CallGraphNodeContext")) {
            if (ImGui::MenuItem("Copy Name")) CopyToClipboard(node.name);
            if (!node.isApi && node.address != 0) {
                if (ImGui::MenuItem("Jump to Disassembly")) {
                    JumpToFunctionAddress(node.address);
                }
            }
            ImGui::EndPopup();
        }
    }

    if (isOpen && !node.children.empty()) {
        std::vector<std::string> keys;
        for (const auto& kv : node.children) {
            keys.push_back(kv.first);
        }
        std::sort(keys.begin(), keys.end());

        for (const auto& key : keys) {
            RenderCallGraphNode(node.children.at(key), modules);
        }
        ImGui::TreePop();
    }
    ImGui::PopID();
}

static void DrawCallGraphTab(
    const FunctionCallerSummary& caller,
    const std::vector<TelemetryEvent>& events,
    const std::vector<ObservedModule>& modules
) {
    ImGui::Spacing();
    
    if (ImGui::Button("Expand All")) {
        g_CallGraphExpandCollapseState = 1;
    }
    ImGui::SameLine();
    if (ImGui::Button("Collapse All")) {
        g_CallGraphExpandCollapseState = 2;
    }
    
    ImGui::Spacing();
    ImGui::Separator();
    ImGui::Spacing();

    ImGui::BeginChild("CallGraphTreeArea", ImVec2(0.0f, 0.0f), false);
    
    CallGraphNode graphRoot = BuildCallGraph(caller, events, modules);
    RenderCallGraphNode(graphRoot, modules);
    
    ImGui::EndChild();

    g_CallGraphExpandCollapseState = 0;
}

static bool GetCachedDisassemblyForFunction(uint64_t address, CachedDisassembly& cached) {
    std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
    for (const auto& kv : g_DisasmCache) {
        const auto& entry = kv.second;
        if (address >= entry.funcStart && address < entry.funcStart + entry.size) {
            cached = entry;
            return true;
        }
    }
    return false;
}

static void DrawBasicBlocksTab(const FunctionCallerSummary& caller) {
    CachedDisassembly cached;
    if (!GetCachedDisassemblyForFunction(caller.address, cached)) {
        if (g_Target.active && g_Target.pid != 0) {
            CacheDisassemblyForAddress(caller.address);
            GetCachedDisassemblyForFunction(caller.address, cached);
        }
    }
    if (cached.lines.empty()) {
        ImGui::TextColored(kUiTextMuted, "No cached disassembly for this function yet.");
        return;
    }

    struct BasicBlockRow {
        uint64_t start = 0;
        uint64_t end = 0;
        int instructions = 0;
        int calls = 0;
        int branches = 0;
        bool returns = false;
    };

    std::vector<BasicBlockRow> blocks;
    BasicBlockRow current;
    current.start = cached.lines.front().address;

    for (const auto& line : cached.lines) {
        std::string instr = ToLowerCopy(line.instruction);
        bool isCall = instr.rfind("call", 0) == 0;
        bool isBranch = instr.rfind("j", 0) == 0;
        bool isRet = instr.rfind("ret", 0) == 0;

        if (current.instructions == 0) {
            current.start = line.address;
        }
        current.end = line.address;
        current.instructions++;
        if (isCall) current.calls++;
        if (isBranch) current.branches++;
        if (isRet) current.returns = true;

        if (isBranch || isRet) {
            blocks.push_back(current);
            current = {};
        }
    }
    if (current.instructions > 0) {
        blocks.push_back(current);
    }

    ImGui::Text("Recovered %d basic block(s) from cached instructions.", (int)blocks.size());
    ImGui::Spacing();
    if (ImGui::BeginTable("BasicBlocksTable", 6, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
        ImGui::TableSetupColumn("Block", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Start", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("End", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Instructions", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Calls", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Control Flow", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();

        for (size_t i = 0; i < blocks.size(); ++i) {
            const auto& block = blocks[i];
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            std::ostringstream name;
            name << "block_" << std::uppercase << std::hex << (block.start - cached.funcStart);
            if (ImGui::Selectable(name.str().c_str(), false, ImGuiSelectableFlags_SpanAllColumns)) {
                g_DisasmScrollToAddress = block.start;
            }
            ImGui::TableSetColumnIndex(1);
            ImGui::Text("%s", StaticHex(block.start).c_str());
            ImGui::TableSetColumnIndex(2);
            ImGui::Text("%s", StaticHex(block.end).c_str());
            ImGui::TableSetColumnIndex(3);
            ImGui::Text("%d", block.instructions);
            ImGui::TableSetColumnIndex(4);
            ImGui::Text("%d", block.calls);
            ImGui::TableSetColumnIndex(5);
            if (block.returns) {
                ImGui::TextColored(kUiPurple, "returns");
            } else if (block.branches > 0) {
                ImGui::TextColored(kUiGold, "%d branch instruction(s)", block.branches);
            } else {
                ImGui::TextColored(kUiTextMuted, "falls through");
            }
        }
        ImGui::EndTable();
    }
}

static std::string BuildPseudocodeText(
    const FunctionCallerSummary& caller,
    const std::vector<TelemetryEvent>& events
) {
    std::ostringstream oss;
    oss << "function " << caller.functionName << "()\n{\n";
    oss << "    // Observed from runtime API telemetry.\n";
    for (int idx : caller.eventIndices) {
        if (idx < 0 || idx >= (int)events.size()) continue;
        const auto& ev = events[idx];
        std::string target = EventTargetObject(ev);
        std::string category = EventCategoryLabel(ev);
        oss << "    // " << category;
        if (!target.empty()) oss << ": " << target;
        oss << "\n";
        oss << "    " << FormatTelemetryEventInline(ev) << ";\n";
    }
    oss << "}\n";
    return oss.str();
}

static void DrawPseudocodeTab(
    const FunctionCallerSummary& caller,
    const std::vector<TelemetryEvent>& events
) {
    std::string pseudo = BuildPseudocodeText(caller, events);
    if (ImGui::Button("Copy Pseudocode")) {
        CopyToClipboard(pseudo);
    }
    ImGui::Spacing();
    ImGui::BeginChild("PseudocodeText", ImVec2(0.0f, 0.0f), true);
    ImGui::TextUnformatted(pseudo.c_str());
    ImGui::EndChild();
}

static void DrawCrossReferencesTab(
    const FunctionCallerSummary& caller,
    const std::vector<TelemetryEvent>& events,
    const std::vector<ObservedModule>& modules
) {
    if (ImGui::BeginTabBar("XrefInnerTabs")) {
        if (ImGui::BeginTabItem("API References")) {
            for (const auto& api : caller.apis) {
                ImGui::BulletText("%s", api.c_str());
            }
            ImGui::EndTabItem();
        }
        if (ImGui::BeginTabItem("Object References")) {
            if (caller.targets.empty()) {
                ImGui::TextColored(kUiTextMuted, "No decoded target/object references.");
            }
            for (const auto& target : caller.targets) {
                ImGui::BulletText("%s", target.c_str());
            }
            ImGui::EndTabItem();
        }
        if (ImGui::BeginTabItem("Observed By")) {
            for (int idx : caller.eventIndices) {
                if (idx < 0 || idx >= (int)events.size()) continue;
                const auto& ev = events[idx];
                ImGui::PushID(idx);
                std::string label = FormatTimestamp(ev.timestamp) + "  " + ev.apiName + "  call site " + FormatModuleOffset(ev.callerModule, ev.callerAddress, modules);
                if (ImGui::Selectable(label.c_str(), g_SelectedEventIndex == idx)) {
                    g_SelectedEventIndex = idx;
                    g_DisasmScrollToAddress = ev.callerAddress;
                }
                ImGui::PopID();
            }
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
}

static json CallGraphToJson(const CallGraphNode& node) {
    json item;
    item["name"] = node.name;
    item["address"] = node.address;
    item["type"] = node.isApi ? "api" : "function";
    item["children"] = json::array();
    std::vector<std::string> keys;
    for (const auto& kv : node.children) {
        keys.push_back(kv.first);
    }
    std::sort(keys.begin(), keys.end());
    for (const auto& key : keys) {
        item["children"].push_back(CallGraphToJson(node.children.at(key)));
    }
    return item;
}

static void AppendCallGraphMarkdown(const CallGraphNode& node, std::ostringstream& oss, int depth = 0) {
    for (int i = 0; i < depth; ++i) {
        oss << "  ";
    }
    oss << "- " << node.name << "\n";

    std::vector<std::string> keys;
    for (const auto& kv : node.children) {
        keys.push_back(kv.first);
    }
    std::sort(keys.begin(), keys.end());
    for (const auto& key : keys) {
        AppendCallGraphMarkdown(node.children.at(key), oss, depth + 1);
    }
}

static std::string EscapeHtml(const std::string& value) {
    std::string escaped;
    for (char c : value) {
        switch (c) {
            case '&': escaped += "&amp;"; break;
            case '<': escaped += "&lt;"; break;
            case '>': escaped += "&gt;"; break;
            case '"': escaped += "&quot;"; break;
            default: escaped += c; break;
        }
    }
    return escaped;
}

static bool WriteTextFileUtf8(const std::string& path, const std::string& text) {
    std::ofstream out(path, std::ios::binary);
    if (!out.is_open()) {
        return false;
    }
    out << text;
    return true;
}

static void DrawDisassemblyTab(const FunctionCallerSummary& caller) {
    CachedDisassembly cached;
    bool found = false;
    
    {
        std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
        for (const auto& kv : g_DisasmCache) {
            const auto& entry = kv.second;
            if (caller.address >= entry.funcStart && caller.address < entry.funcStart + entry.size) {
                cached = entry;
                found = true;
                break;
            }
        }
    }
    
    if (!found) {
        if (g_Target.active && g_Target.pid != 0) {
            CacheDisassemblyForAddress(caller.address);
            
            std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
            for (const auto& kv : g_DisasmCache) {
                const auto& entry = kv.second;
                if (caller.address >= entry.funcStart && caller.address < entry.funcStart + entry.size) {
                    cached = entry;
                    found = true;
                    break;
                }
            }
        }
    }
    
    if (!found) {
        ImGui::TextColored(kUiRed, "Target process is not running.");
        ImGui::Text("Cannot disassemble live memory (not cached during run).");
        return;
    }
    
    ImGui::Text("Disassembly of %s at 0x%llX (Size: %d bytes)", caller.functionName.c_str(), cached.funcStart, cached.size);
    ImGui::Spacing();
    
    struct TelemetryAddrInfo {
        const TelemetryEvent* preferredEvent = nullptr;
        int count = 0;
    };
    std::unordered_map<uint64_t, TelemetryAddrInfo> addrToEvent;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        const TelemetryEvent* selectedEv = (g_SelectedEventIndex >= 0 && g_SelectedEventIndex < (int)g_Events.size()) 
                                           ? &g_Events[g_SelectedEventIndex] : nullptr;
        for (const auto& ev : g_Events) {
            if (ev.callerAddress == 0) continue;
            auto& info = addrToEvent[ev.callerAddress];
            info.count++;
            if (selectedEv && ev.callerAddress == selectedEv->callerAddress) {
                info.preferredEvent = selectedEv;
            } else if (info.preferredEvent != selectedEv) {
                info.preferredEvent = &ev; // last one wins
            }
        }
    }
    
    if (ImGui::BeginTable("DisassemblyTable", 4, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_ScrollX | ImGuiTableFlags_Resizable, ImVec2(0.0f, ImGui::GetContentRegionAvail().y - 10.0f))) {
        ImGui::TableSetupColumn("Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Bytes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Instruction", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Comment", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableHeadersRow();
        
        for (size_t lineIdx = 0; lineIdx < cached.lines.size(); ++lineIdx) {
            const auto& line = cached.lines[lineIdx];
            ImGui::TableNextRow();
            
            bool isCallerLine = (line.address == caller.address);
            bool isCallSiteLine = false;
            if (lineIdx + 1 < cached.lines.size() && cached.lines[lineIdx + 1].address == caller.address) {
                isCallSiteLine = true;
            } else if (lineIdx + 1 == cached.lines.size()) {
                int numBytes = 0;
                std::istringstream iss(line.bytes);
                std::string byteStr;
                while (iss >> byteStr) {
                    numBytes++;
                }
                if (line.address + numBytes == caller.address) {
                    isCallSiteLine = true;
                }
            }
            
            bool highlightLine = isCallerLine || isCallSiteLine;
            
            // Auto scroll to target address
            if (g_DisasmScrollToAddress != 0 && (line.address == g_DisasmScrollToAddress || (isCallSiteLine && cached.lines[lineIdx + 1].address == g_DisasmScrollToAddress))) {
                ImGui::SetScrollHereY(0.5f);
                g_DisasmScrollToAddress = 0; // Reset scroll target once done
            }
            
            if (highlightLine) {
                ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg0, ImGui::GetColorU32(ImVec4(0.2f, 0.4f, 0.6f, 0.3f)));
            }
            
            ImGui::TableSetColumnIndex(0);
            char addrStr[64];
            sprintf_s(addrStr, "0x%llX", line.address);
            if (isCallSiteLine) {
                ImGui::TextColored(kUiGreen, "%s  *", addrStr);
            } else if (isCallerLine) {
                ImGui::TextColored(kUiGreen, "%s", addrStr);
            } else {
                ImGui::TextColored(kUiGold, "%s", addrStr);
            }
            
            ImGui::TableSetColumnIndex(1);
            ImGui::TextColored(kUiTextMuted, "%s", line.bytes.c_str());
            
            ImGui::TableSetColumnIndex(2);
            if (highlightLine) {
                ImGui::TextColored(kUiGreen, "%s", line.instruction.c_str());
            } else {
                ImGui::Text("%s", line.instruction.c_str());
            }
            
            // Align telemetry comments to the call instruction (which precedes the return address)
            uint64_t targetLookupAddr = 0;
            if (lineIdx + 1 < cached.lines.size()) {
                targetLookupAddr = cached.lines[lineIdx + 1].address;
            } else {
                int numBytes = 0;
                std::istringstream iss(line.bytes);
                std::string byteStr;
                while (iss >> byteStr) {
                    numBytes++;
                }
                targetLookupAddr = line.address + numBytes;
            }
            
            std::string telemetryComment;
            auto it = addrToEvent.find(targetLookupAddr);
            if (it != addrToEvent.end() && it->second.preferredEvent) {
                const auto& ev = *(it->second.preferredEvent);
                std::string evtStr = FormatTelemetryEventInline(ev);
                if (it->second.count > 1) {
                    telemetryComment = "[Calls: " + std::to_string(it->second.count) + "] " + evtStr;
                } else {
                    telemetryComment = evtStr;
                }
            }
            
            ImGui::TableSetColumnIndex(3);
            if (!telemetryComment.empty()) {
                ImGui::TextColored(kUiGreen, "%s", telemetryComment.c_str());
                if (ImGui::IsItemHovered()) {
                    ImGui::SetTooltip("%s", telemetryComment.c_str());
                }
                if (!line.comment.empty()) {
                    ImGui::SameLine();
                    ImGui::TextColored(kUiBlue, "  (Static: %s)", line.comment.c_str());
                }
            } else if (!line.comment.empty()) {
                ImGui::TextColored(kUiBlue, "%s", line.comment.c_str());
                if (ImGui::IsItemHovered()) {
                    ImGui::SetTooltip("%s", line.comment.c_str());
                }
            }
        }
        ImGui::EndTable();
    }
}


static json BuildProcessActivityJson(const ProcessActivitySnapshot& snapshot) {
    json root;
    root["tool"] = "InspecThor";
    root["export_type"] = "Process Activity";

    root["processes"] = json::array();
    for (const auto& row : snapshot.processes) {
        root["processes"].push_back({
            {"time", row.time},
            {"api", row.api},
            {"parent_pid", row.parentPid},
            {"parent_name", row.parentName},
            {"child_pid", row.childPid},
            {"child_name", row.childName},
            {"child_thread_id", row.childThreadId},
            {"executable", row.executable},
            {"command_line", row.commandLine},
            {"caller_function", row.callerFunction},
            {"caller_address", row.callerAddress}
        });
    }

    root["commands"] = json::array();
    for (const auto& row : snapshot.commands) {
        root["commands"].push_back({
            {"time", row.time},
            {"api", row.api},
            {"process_id", row.processId},
            {"process_name", row.processName},
            {"command", row.command},
            {"caller_function", row.callerFunction},
            {"caller_address", row.callerAddress}
        });
    }

    root["threads"] = json::array();
    for (const auto& row : snapshot.threads) {
        root["threads"].push_back({
            {"time", row.time},
            {"api", row.api},
            {"source_pid", row.processId},
            {"target_pid", row.targetPid},
            {"thread_id", row.threadId},
            {"start_address", row.startAddress},
            {"start_module", row.startModule},
            {"creator_function", row.creatorFunction},
            {"caller_address", row.callerAddress}
        });
    }

    root["process_handles"] = json::array();
    for (const auto& row : snapshot.handles) {
        root["process_handles"].push_back({
            {"time", row.time},
            {"source_pid", row.processId},
            {"target_pid", row.targetPid},
            {"handle", row.handle},
            {"type", row.type},
            {"name", row.name},
            {"access", row.access},
            {"decoded_access", row.decodedAccess},
            {"creator_function", row.creatorFunction},
            {"caller_address", row.callerAddress}
        });
    }

    auto addBehaviorRows = [&](const char* name, const std::vector<ProcessBehaviorRow>& rows) {
        root[name] = json::array();
        for (const auto& row : rows) root[name].push_back({
            {"time", row.time}, {"api", row.api}, {"source_pid", row.processId}, {"target_pid", row.targetPid},
            {"action", row.action}, {"details", row.details}, {"result", row.result},
            {"caller_function", row.callerFunction}, {"caller_address", row.callerAddress}, {"from_etw", row.fromEtw}
        });
    };
    addBehaviorRows("terminations", snapshot.terminations);
    addBehaviorRows("information_queries", snapshot.informationQueries);
    addBehaviorRows("token_access", snapshot.tokenAccess);
    addBehaviorRows("environment", snapshot.environment);
    addBehaviorRows("waiting_and_synchronization", snapshot.waits);
    addBehaviorRows("current_process_info", snapshot.currentProcessInfo);
    addBehaviorRows("process_discovery", snapshot.discovery);
    addBehaviorRows("callback_and_local_execution", snapshot.callbackExecutions);

    return root;
}

static std::string BuildProcessActivityMarkdown(const ProcessActivitySnapshot& snapshot) {
    std::ostringstream oss;
    oss << "# InspecThor Process Activity Export\n\n";
    oss << "- Process creation events: " << snapshot.processes.size() << "\n";
    oss << "- Commands: " << snapshot.commands.size() << "\n";
    oss << "- Threads: " << snapshot.threads.size() << "\n";
    oss << "- Process handles: " << snapshot.handles.size() << "\n";
    oss << "- Callback / local execution: " << snapshot.callbackExecutions.size() << "\n\n";

    oss << "## Process Creation\n\n";
    for (const auto& row : snapshot.processes) {
        oss << "- " << row.time << " " << row.api << " parent=\"" << row.parentName << "\" (" << row.parentPid << ")"
            << " child=\"" << row.childName << "\" (" << row.childPid << ") exe=\"" << row.executable
            << "\" command=\"" << row.commandLine << "\" caller=" << row.callerFunction << "\n";
    }

    oss << "\n## Command Execution\n\n";
    for (const auto& row : snapshot.commands) {
        oss << "- " << row.time << " pid=" << row.processId << " process=" << row.processName
            << " command=\"" << row.command << "\" caller=" << row.callerFunction << "\n";
    }

    oss << "\n## Thread Creation\n\n";
    for (const auto& row : snapshot.threads) {
        oss << "- " << row.time << " " << row.api << " target_pid=" << row.targetPid
            << " tid=" << row.threadId << " start=" << StaticHex(row.startAddress)
            << " module=" << row.startModule << " creator=" << row.creatorFunction << "\n";
    }

    oss << "\n## Process Handles\n\n";
    for (const auto& row : snapshot.handles) {
        oss << "- " << row.time << " source_pid=" << row.processId << " target_pid=" << row.targetPid
            << " handle=" << StaticHex(row.handle) << " type=" << row.type << " name=\"" << row.name
            << "\" access=" << row.access << " decoded_access=\"" << row.decodedAccess << "\""
            << " creator=" << row.creatorFunction << "\n";
    }

    auto appendBehaviorRows = [&](const char* title, const std::vector<ProcessBehaviorRow>& rows) {
        oss << "\n## " << title << "\n\n";
        for (const auto& row : rows) {
            oss << "- " << row.time << " " << row.action << " api=" << row.api
                << " source_pid=" << row.processId << " target_pid=" << row.targetPid
                << " details=\"" << row.details << "\" caller=" << row.callerFunction << "\n";
        }
    };
    appendBehaviorRows("Termination", snapshot.terminations);
    appendBehaviorRows("Information Queries", snapshot.informationQueries);
    appendBehaviorRows("Token Access", snapshot.tokenAccess);
    appendBehaviorRows("Environment", snapshot.environment);
    appendBehaviorRows("Waiting and Synchronization", snapshot.waits);
    appendBehaviorRows("Current Process Info", snapshot.currentProcessInfo);
    appendBehaviorRows("Process Discovery", snapshot.discovery);
    appendBehaviorRows("Callback and Local Execution", snapshot.callbackExecutions);

    return oss.str();
}

static bool ExportProcessActivitySnapshot(const ProcessActivitySnapshot& snapshot, const std::string& basename) {
    std::string jsonText = BuildProcessActivityJson(snapshot).dump(2);
    std::string markdownText = BuildProcessActivityMarkdown(snapshot);
    std::ostringstream html;
    html << "<!doctype html><html><head><meta charset=\"utf-8\"><title>InspecThor Process Activity</title>"
         << "<style>body{font-family:Consolas,monospace;background:#101114;color:#eee;padding:24px;}pre{background:#181a20;padding:14px;border:1px solid #333;overflow:auto;}h1,h2{color:#8b99e0;}</style>"
         << "</head><body><pre>" << EscapeHtml(markdownText) << "</pre></body></html>";

    bool ok = WriteTextFileUtf8(basename + ".json", jsonText);
    ok = WriteTextFileUtf8(basename + ".md", markdownText) && ok;
    ok = WriteTextFileUtf8(basename + ".html", html.str()) && ok;
    return ok;
}

