enum class ProcessGraphNodeKind {
    Process,
    Dll,
    Origin,
    Activity
};

struct ProcessGraphNode {
    std::string id;
    ProcessGraphNodeKind kind = ProcessGraphNodeKind::Process;
    std::string label;
    std::string subtitle;
    std::string command;
    std::string status;
    std::string category;
    std::string evidence;
    uint32_t pid = 0;
    uint64_t instanceStart = 0;
    int eventIndex = -1;
    uint64_t callerAddress = 0;
    bool fromEtw = false;
    uint32_t observations = 1;
    int ownerIndex = -1;
    int layer = 0;
    ImVec2 position = ImVec2(0.0f, 0.0f);
    ImVec2 size = ImVec2(300.0f, 96.0f);
};

struct ProcessGraphEdge {
    int from = -1;
    int to = -1;
    bool inferred = false;
    std::string evidence;
};

struct ProcessGraphModel {
    std::vector<ProcessGraphNode> nodes;
    std::vector<ProcessGraphEdge> edges;
    ImVec2 boundsMin = ImVec2(0.0f, 0.0f);
    ImVec2 boundsMax = ImVec2(0.0f, 0.0f);
};

static std::string CompactProcessGraphText(std::string value, size_t maxLength) {
    for (char& ch : value) {
        if (ch == '\r' || ch == '\n' || ch == '\t') ch = ' ';
    }
    while (value.find("  ") != std::string::npos) value.erase(value.find("  "), 1);
    if (value.empty()) return "-";
    if (value.size() <= maxLength) return value;
    if (maxLength <= 3) return value.substr(0, maxLength);
    return value.substr(0, maxLength - 3) + "...";
}

static ImVec2 ProcessGraphBezierPoint(const ImVec2& p0, const ImVec2& p1, const ImVec2& p2, const ImVec2& p3, float t) {
    const float u = 1.0f - t;
    const float uu = u * u;
    const float tt = t * t;
    return ImVec2(
        uu * u * p0.x + 3.0f * uu * t * p1.x + 3.0f * u * tt * p2.x + tt * t * p3.x,
        uu * u * p0.y + 3.0f * uu * t * p1.y + 3.0f * u * tt * p2.y + tt * t * p3.y
    );
}

static void DrawProcessGraphEdge(
    ImDrawList* drawList,
    const ImVec2& start,
    const ImVec2& end,
    ImU32 color,
    float thickness,
    bool inferred,
    float zoom
) {
    const float controlOffset = (std::max)(50.0f * zoom, (end.x - start.x) * 0.42f);
    const ImVec2 controlA(start.x + controlOffset, start.y);
    const ImVec2 controlB(end.x - controlOffset, end.y);
    if (inferred) {
        const int segments = 36;
        ImVec2 previous = start;
        for (int i = 1; i <= segments; ++i) {
            const ImVec2 current = ProcessGraphBezierPoint(start, controlA, controlB, end, (float)i / (float)segments);
            if (((i - 1) / 2) % 2 == 0) drawList->AddLine(previous, current, color, thickness);
            previous = current;
        }
    } else {
        drawList->AddBezierCubic(start, controlA, controlB, end, color, thickness, 24);
    }

    const ImVec2 beforeEnd = ProcessGraphBezierPoint(start, controlA, controlB, end, 0.96f);
    float dx = end.x - beforeEnd.x;
    float dy = end.y - beforeEnd.y;
    const float length = std::sqrt(dx * dx + dy * dy);
    if (length > 0.001f) {
        dx /= length;
        dy /= length;
    }
    const float arrowLength = 9.0f * zoom;
    const float arrowWidth = 5.0f * zoom;
    const ImVec2 base(end.x - dx * arrowLength, end.y - dy * arrowLength);
    const ImVec2 left(base.x - dy * arrowWidth, base.y + dx * arrowWidth);
    const ImVec2 right(base.x + dy * arrowWidth, base.y - dx * arrowWidth);
    drawList->AddTriangleFilled(end, left, right, color);
}

static ProcessGraphModel BuildProcessGraphModel(
    const ProcessActivitySnapshot& snapshot,
    const std::unordered_map<uint32_t, std::vector<std::string>>& userDlls,
    const std::vector<TelemetryEvent>& events
) {
    ProcessGraphModel model;
    std::vector<size_t> creationOrder(snapshot.processes.size());
    for (size_t i = 0; i < creationOrder.size(); ++i) creationOrder[i] = i;
    std::sort(creationOrder.begin(), creationOrder.end(), [&](size_t a, size_t b) {
        if (snapshot.processes[a].timestampMs != snapshot.processes[b].timestampMs)
            return snapshot.processes[a].timestampMs < snapshot.processes[b].timestampMs;
        return snapshot.processes[a].eventIndex < snapshot.processes[b].eventIndex;
    });

    std::vector<int> childNodeByRow(snapshot.processes.size(), -1);
    auto processId = [](uint32_t pid, uint64_t start, int eventIndex) {
        return "process:" + std::to_string(pid) + ":" + std::to_string(start) + ":" + std::to_string(eventIndex);
    };
    auto findMatchingInstance = [&](uint32_t pid, uint64_t timestamp, bool fromEtw, int eventIndex) {
        int best = -1;
        uint64_t bestDelta = UINT64_MAX;
        for (size_t i = 0; i < model.nodes.size(); ++i) {
            const auto& node = model.nodes[i];
            if (node.kind != ProcessGraphNodeKind::Process || node.pid != pid || node.instanceStart == 0) continue;
            const uint64_t delta = node.instanceStart > timestamp ? node.instanceStart - timestamp : timestamp - node.instanceStart;
            const bool duplicateEvidence = node.fromEtw != fromEtw || node.eventIndex == eventIndex || delta == 0;
            if (duplicateEvidence && delta <= 2000 && delta < bestDelta) {
                best = (int)i;
                bestDelta = delta;
            }
        }
        return best;
    };
    auto addProcessNode = [&](uint32_t pid, uint64_t start, int eventIndex, const std::string& label,
                              const std::string& command, bool fromEtw, uint64_t callerAddress) {
        ProcessGraphNode node;
        node.id = processId(pid, start, eventIndex);
        node.kind = ProcessGraphNodeKind::Process;
        node.pid = pid;
        node.instanceStart = start;
        node.eventIndex = eventIndex;
        node.callerAddress = callerAddress;
        node.fromEtw = fromEtw;
        node.label = label.empty() ? (pid ? "PID " + std::to_string(pid) : "Unknown process") : label;
        node.command = command;
        node.status = "OBSERVED";
        node.size = ImVec2(360.0f, 124.0f);
        model.nodes.push_back(std::move(node));
        return (int)model.nodes.size() - 1;
    };

    for (size_t rowIndex : creationOrder) {
        const auto& row = snapshot.processes[rowIndex];
        int nodeIndex = row.childPid ? findMatchingInstance(row.childPid, row.timestampMs, row.fromEtw, row.eventIndex) : -1;
        if (nodeIndex < 0) {
            nodeIndex = addProcessNode(row.childPid, row.timestampMs, row.eventIndex,
                row.childName, row.commandLine.empty() ? row.executable : row.commandLine,
                row.fromEtw, row.callerAddress);
        } else {
            auto& node = model.nodes[nodeIndex];
            if (!row.childName.empty()) node.label = row.childName;
            if (!row.commandLine.empty()) node.command = row.commandLine;
            else if (node.command.empty()) node.command = row.executable;
            if (node.eventIndex < 0 && row.eventIndex >= 0) {
                node.eventIndex = row.eventIndex;
                node.callerAddress = row.callerAddress;
                node.fromEtw = false;
            }
        }
        childNodeByRow[rowIndex] = nodeIndex;
    }

    auto findProcessAt = [&](uint32_t pid, uint64_t timestamp) {
        int best = -1;
        uint64_t bestStart = 0;
        for (size_t i = 0; i < model.nodes.size(); ++i) {
            const auto& node = model.nodes[i];
            if (node.kind != ProcessGraphNodeKind::Process || node.pid != pid) continue;
            if (node.instanceStart == 0 || node.instanceStart <= timestamp) {
                if (best < 0 || node.instanceStart >= bestStart) {
                    best = (int)i;
                    bestStart = node.instanceStart;
                }
            }
        }
        if (best >= 0) return best;
        for (size_t i = 0; i < model.nodes.size(); ++i) {
            if (model.nodes[i].kind == ProcessGraphNodeKind::Process && model.nodes[i].pid == pid) return (int)i;
        }
        return -1;
    };
    auto addEdge = [&](int from, int to, bool inferred, const std::string& evidence) {
        if (from < 0 || to < 0 || from == to) return;
        for (const auto& edge : model.edges) {
            if (edge.from == from && edge.to == to && edge.inferred == inferred) return;
        }
        ProcessGraphEdge edge;
        edge.from = from;
        edge.to = to;
        edge.inferred = inferred;
        edge.evidence = evidence;
        model.edges.push_back(std::move(edge));
    };

    for (size_t rowIndex : creationOrder) {
        const auto& row = snapshot.processes[rowIndex];
        const int child = childNodeByRow[rowIndex];
        if (child < 0 || !row.parentPid || row.parentPid == row.childPid) continue;
        int parent = findProcessAt(row.parentPid, row.timestampMs);
        if (parent < 0) {
            parent = addProcessNode(row.parentPid, 0, row.eventIndex, row.parentName, "", row.fromEtw, row.callerAddress);
        }
        addEdge(parent, child, false, row.api);
        model.nodes[child].evidence = row.api + " at " + row.time;
    }

    if (g_Target.pid) {
        int targetNode = findProcessAt(g_Target.pid, UINT64_MAX);
        if (targetNode < 0) {
            const std::wstring& rootPath = g_TargetProcessPath.empty() ? g_Target.path : g_TargetProcessPath;
            targetNode = addProcessNode(g_Target.pid, 0, -1,
                BaseNameFromPathOrCommand(WStringToString(rootPath)), g_TargetCommandLine, false, 0);
        } else {
            if (model.nodes[targetNode].command.empty()) model.nodes[targetNode].command = g_TargetCommandLine;
        }
    }

    std::unordered_map<uint32_t, std::vector<int>> instancesByPid;
    for (size_t i = 0; i < model.nodes.size(); ++i) {
        if (model.nodes[i].kind == ProcessGraphNodeKind::Process && model.nodes[i].pid)
            instancesByPid[model.nodes[i].pid].push_back((int)i);
    }
    for (auto& item : instancesByPid) {
        auto& indices = item.second;
        std::sort(indices.begin(), indices.end(), [&](int a, int b) {
            return model.nodes[a].instanceStart < model.nodes[b].instanceStart;
        });
        for (size_t pos = 0; pos < indices.size(); ++pos) {
            auto& node = model.nodes[indices[pos]];
            const uint64_t nextStart = pos + 1 < indices.size() ? model.nodes[indices[pos + 1]].instanceStart : UINT64_MAX;
            bool terminated = false;
            for (const auto& termination : snapshot.terminations) {
                if (termination.targetPid != node.pid) continue;
                if (termination.timestampMs >= node.instanceStart && termination.timestampMs < nextStart) {
                    terminated = true;
                    break;
                }
            }
            const bool latestInstance = pos + 1 == indices.size();
            if (terminated) node.status = "TERMINATED";
            else if (latestInstance && g_Target.active && node.pid == g_Target.pid) node.status = "RUNNING";
            else node.status = "OBSERVED";
        }
    }

    auto latestProcessForPid = [&](uint32_t pid) {
        int best = -1;
        uint64_t bestStart = 0;
        for (size_t i = 0; i < model.nodes.size(); ++i) {
            const auto& node = model.nodes[i];
            if (node.kind == ProcessGraphNodeKind::Process && node.pid == pid && (best < 0 || node.instanceStart >= bestStart)) {
                best = (int)i;
                bestStart = node.instanceStart;
            }
        }
        return best;
    };
    auto addOwnedNode = [&](int owner, ProcessGraphNodeKind kind, std::string typeKey,
                            std::string label, std::string subtitle, std::string evidence,
                            int eventIndex, uint64_t callerAddress, bool inferred) {
        if (owner < 0) return -1;
        const std::string id = (kind == ProcessGraphNodeKind::Dll ? "dll:" : "origin:") +
            model.nodes[owner].id + ":" + ToLowerCopy(typeKey);
        for (size_t i = 0; i < model.nodes.size(); ++i) if (model.nodes[i].id == id) return (int)i;
        ProcessGraphNode node;
        node.id = id;
        node.kind = kind;
        node.label = label;
        node.subtitle = subtitle;
        node.evidence = evidence;
        node.pid = model.nodes[owner].pid;
        node.instanceStart = model.nodes[owner].instanceStart;
        node.eventIndex = eventIndex;
        node.callerAddress = callerAddress;
        node.ownerIndex = owner;
        node.size = kind == ProcessGraphNodeKind::Dll ? ImVec2(205.0f, 62.0f) : ImVec2(190.0f, 64.0f);
        model.nodes.push_back(std::move(node));
        const int added = (int)model.nodes.size() - 1;
        addEdge(kind == ProcessGraphNodeKind::Dll ? owner : added,
            kind == ProcessGraphNodeKind::Dll ? added : owner, inferred, evidence);
        return added;
    };

    for (const auto& item : userDlls) {
        const int owner = latestProcessForPid(item.first);
        for (const auto& dll : item.second) {
            addOwnedNode(owner, ProcessGraphNodeKind::Dll, dll, dll, "USER DLL",
                "Observed in PID " + std::to_string(item.first), -1, 0, false);
        }
    }

    for (size_t i = 0; i < model.nodes.size(); ++i) {
        const auto& process = model.nodes[i];
        if (process.kind != ProcessGraphNodeKind::Process) continue;
        const std::string lowerName = ToLowerCopy(process.label);
        if (lowerName == "wscript.exe" || lowerName == "cscript.exe" || lowerName == "powershell.exe" ||
            lowerName == "pwsh.exe" || lowerName == "mshta.exe") {
            addOwnedNode((int)i, ProcessGraphNodeKind::Origin, "script", "Script Origin", process.label,
                "Inferred from script host process", process.eventIndex, process.callerAddress, true);
        }
    }

    for (const auto& row : snapshot.callbackExecutions) {
        const int owner = findProcessAt(row.processId, row.timestampMs);
        std::string type = "Callback";
        const std::string lower = ToLowerCopy(row.action + " " + row.api);
        if (lower.find("tls") != std::string::npos) type = "TLS Callback";
        else if (lower.find("fiber") != std::string::npos) type = "Fiber";
        else if (lower.find("exception") != std::string::npos || lower.find("vectored") != std::string::npos) type = "SEH / VEH";
        addOwnedNode(owner, ProcessGraphNodeKind::Origin, type, type, row.action,
            row.api + " at " + row.time, row.eventIndex, row.callerAddress, true);
    }

    for (size_t i = 0; i < events.size(); ++i) {
        const auto& event = events[i];
        if (!IsComActivityApi(event.apiName)) continue;
        const int owner = findProcessAt(event.processId, event.timestamp);
        const std::string lower = ToLowerCopy(event.apiName + " " + event.callerModule);
        const bool wmi = lower.find("wmi") != std::string::npos || lower.find("wbem") != std::string::npos || lower.find("cim") != std::string::npos;
        const std::string type = wmi ? "WMI" : "COM";
        addOwnedNode(owner, ProcessGraphNodeKind::Origin, type, type + " Origin", event.apiName,
            event.apiName + " at " + FormatTimestamp(event.timestamp), (int)i, event.callerAddress, true);
    }

    std::vector<int> parent(model.nodes.size(), -1);
    for (const auto& edge : model.edges) {
        if (edge.inferred || edge.from < 0 || edge.to < 0) continue;
        if (model.nodes[edge.from].kind == ProcessGraphNodeKind::Process && model.nodes[edge.to].kind == ProcessGraphNodeKind::Process)
            parent[edge.to] = edge.from;
    }
    std::vector<int> visit(model.nodes.size(), 0);
    std::function<int(int)> resolveLayer = [&](int index) -> int {
        if (index < 0 || index >= (int)model.nodes.size()) return 0;
        if (visit[index] == 2) return model.nodes[index].layer;
        if (visit[index] == 1) return 0;
        visit[index] = 1;
        model.nodes[index].layer = parent[index] >= 0 ? resolveLayer(parent[index]) + 1 : 0;
        visit[index] = 2;
        return model.nodes[index].layer;
    };
    for (size_t i = 0; i < model.nodes.size(); ++i) {
        if (model.nodes[i].kind == ProcessGraphNodeKind::Process) resolveLayer((int)i);
    }
    int minimumLayer = 0;
    for (auto& node : model.nodes) {
        if (node.kind == ProcessGraphNodeKind::Origin && node.ownerIndex >= 0) node.layer = model.nodes[node.ownerIndex].layer - 1;
        else if (node.kind == ProcessGraphNodeKind::Dll && node.ownerIndex >= 0) node.layer = model.nodes[node.ownerIndex].layer + 1;
        minimumLayer = (std::min)(minimumLayer, node.layer);
    }
    if (minimumLayer < 0) for (auto& node : model.nodes) node.layer -= minimumLayer;

    int maximumLayer = 0;
    for (const auto& node : model.nodes) maximumLayer = (std::max)(maximumLayer, node.layer);
    std::vector<std::vector<int>> byLayer((size_t)maximumLayer + 1);
    for (size_t i = 0; i < model.nodes.size(); ++i) byLayer[model.nodes[i].layer].push_back((int)i);
    for (auto& layer : byLayer) {
        std::sort(layer.begin(), layer.end(), [&](int a, int b) {
            const auto& left = model.nodes[a];
            const auto& right = model.nodes[b];
            if (left.ownerIndex != right.ownerIndex) return left.ownerIndex < right.ownerIndex;
            if (left.instanceStart != right.instanceStart) return left.instanceStart < right.instanceStart;
            if (left.pid != right.pid) return left.pid < right.pid;
            return left.label < right.label;
        });
        for (size_t order = 0; order < layer.size(); ++order) {
            auto& node = model.nodes[layer[order]];
            node.position = ImVec2((float)node.layer * 430.0f, (float)order * 154.0f);
        }
    }

    if (!model.nodes.empty()) {
        model.boundsMin = model.nodes.front().position;
        model.boundsMax = ImVec2(model.nodes.front().position.x + model.nodes.front().size.x,
            model.nodes.front().position.y + model.nodes.front().size.y);
        for (const auto& node : model.nodes) {
            model.boundsMin.x = (std::min)(model.boundsMin.x, node.position.x);
            model.boundsMin.y = (std::min)(model.boundsMin.y, node.position.y);
            model.boundsMax.x = (std::max)(model.boundsMax.x, node.position.x + node.size.x);
            model.boundsMax.y = (std::max)(model.boundsMax.y, node.position.y + node.size.y);
        }
    }
    return model;
}

static std::string FullActivityGraphCategory(const TelemetryEvent& event) {
    const ApiIntelInfo* intel = LookupApiIntel(event.apiName);
    std::string category = intel ? DisplayCategory(intel->category) : DisplayCategory(FallbackCategory(event.apiName));
    if (category != "Unmapped") return category;
    if (IsProcessInjectionApi(event.apiName)) return "Process Injection";
    if (IsDllActivityApi(event.apiName)) return "DLL Activity";
    if (IsServiceDriverApi(event.apiName)) return "Service Driver";
    if (IsIpcActivityApi(event.apiName)) return "IPC Synchronization";
    if (IsComActivityApi(event.apiName)) return "COM WMI";
    if (IsAntiAnalysisDirectApi(event.apiName)) return "Anti Analysis";
    if (IsCryptoApi(event.apiName)) return "Crypto";
    return "Other API";
}

static std::string FullActivityGraphTarget(const TelemetryEvent& event, const std::string& category) {
    auto firstText = [&](std::initializer_list<const char*> names) {
        for (const char* name : names) {
            std::string value = ParamDecodedTextOrEmpty(event, name);
            if (!value.empty() && value != "-") return value;
        }
        return std::string{};
    };
    const std::string lower = ToLowerCopy(category);
    std::string target;
    if (lower.find("network") != std::string::npos) {
        target = firstText({ "lpszUrl", "lpUrl", "pwszUrl", "lpszObjectName", "pwszObjectName",
            "lpszServerName", "pswzServerName", "hostname", "HostName", "name", "to", "from", "NodeName", "pNodeName", "pszName" });
    } else if (lower.find("registry") != std::string::npos) {
        target = firstText({ "KeyName", "ObjectName", "lpSubKey", "CompleteKeyPath", "ValueName", "lpValueName" });
    } else if (lower.find("file") != std::string::npos || lower.find("folder") != std::string::npos ||
        lower.find("loader") != std::string::npos || lower.find("dll") != std::string::npos) {
        target = firstText({ "lpLibFileName", "ModuleFileName", "lpFileName", "FileName", "ObjectName",
            "lpPathName", "PathName", "lpExistingFileName", "lpNewFileName" });
    } else if (lower.find("service") != std::string::npos || lower.find("driver") != std::string::npos) {
        target = firstText({ "lpServiceName", "lpDisplayName", "lpBinaryPathName", "DriverPath", "DeviceName", "lpFileName" });
    } else if (lower.find("ipc") != std::string::npos) {
        target = firstText({ "lpName", "ObjectName", "PipeName", "MappingName", "EventName", "MutexName" });
    } else if (lower.find("com") != std::string::npos || lower.find("wmi") != std::string::npos) {
        target = firstText({ "ClassId", "CLSID", "rclsid", "Namespace", "Query", "ObjectPath", "NetworkResource" });
    } else if (lower.find("crypto") != std::string::npos) {
        target = firstText({ "pszAlgId", "Algorithm", "AlgId", "pszProviderName", "CertificateName" });
    } else if (lower.find("process") != std::string::npos || lower.find("injection") != std::string::npos ||
        lower.find("command") != std::string::npos) {
        target = firstText({ "lpApplicationName", "lpCommandLine", "lpFile", "lpParameters", "ProcessName" });
        if (target.empty()) {
            const uint64_t pid = ParamValueOrZero(event, "dwProcessId");
            if (pid) target = "PID " + std::to_string(pid);
        }
    }
    if (target.empty() && lower.find("memory") != std::string::npos) {
        uint64_t address = ParamValueOrZero(event, "lpBaseAddress");
        if (!address) address = ParamValueOrZero(event, "BaseAddress");
        if (!address) address = ParamValueOrZero(event, "lpAddress");
        if (address) target = FormatHexValue(address);
    }
    return target.empty() ? event.apiName : target;
}

static void RelayoutFullActivityGraph(ProcessGraphModel& model) {
    int maximumLayer = 0;
    for (const auto& node : model.nodes) maximumLayer = (std::max)(maximumLayer, node.layer);
    std::vector<std::vector<int>> byLayer((size_t)maximumLayer + 1);
    for (size_t i = 0; i < model.nodes.size(); ++i) byLayer[model.nodes[i].layer].push_back((int)i);
    for (auto& layer : byLayer) {
        std::sort(layer.begin(), layer.end(), [&](int a, int b) {
            const auto& left = model.nodes[a];
            const auto& right = model.nodes[b];
            if (left.kind != right.kind) return (int)left.kind < (int)right.kind;
            if (left.ownerIndex != right.ownerIndex) return left.ownerIndex < right.ownerIndex;
            if (left.category != right.category) return left.category < right.category;
            if (left.instanceStart != right.instanceStart) return left.instanceStart < right.instanceStart;
            return left.label < right.label;
        });
        for (size_t order = 0; order < layer.size(); ++order) {
            model.nodes[layer[order]].position = ImVec2((float)model.nodes[layer[order]].layer * 430.0f, (float)order * 154.0f);
        }
    }
    if (model.nodes.empty()) return;
    model.boundsMin = model.nodes.front().position;
    model.boundsMax = ImVec2(model.nodes.front().position.x + model.nodes.front().size.x,
        model.nodes.front().position.y + model.nodes.front().size.y);
    for (const auto& node : model.nodes) {
        model.boundsMin.x = (std::min)(model.boundsMin.x, node.position.x);
        model.boundsMin.y = (std::min)(model.boundsMin.y, node.position.y);
        model.boundsMax.x = (std::max)(model.boundsMax.x, node.position.x + node.size.x);
        model.boundsMax.y = (std::max)(model.boundsMax.y, node.position.y + node.size.y);
    }
}

static ProcessGraphModel BuildFullActivityGraphModel(const std::vector<TelemetryEvent>& events) {
    std::vector<ObservedModule> modules = GetObservedModules(events);
    ProcessActivitySnapshot processSnapshot = BuildProcessActivitySnapshot(events, modules,
        IncludeEtwInCategorizedActivity() ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{});
    const std::unordered_map<uint32_t, std::vector<std::string>> noDllNodes;
    ProcessGraphModel model = BuildProcessGraphModel(processSnapshot, noDllNodes, events);

    // The main graph is an analyst-oriented behavior summary. Keep only the
    // process topology from PsGraph; callback, COM/WMI, DLL, and other origin
    // nodes remain available in their dedicated views.
    ProcessGraphModel processOnly;
    std::vector<int> remap(model.nodes.size(), -1);
    for (size_t i = 0; i < model.nodes.size(); ++i) {
        if (model.nodes[i].kind != ProcessGraphNodeKind::Process) continue;
        remap[i] = (int)processOnly.nodes.size();
        processOnly.nodes.push_back(model.nodes[i]);
    }
    for (const auto& edge : model.edges) {
        if (edge.from < 0 || edge.to < 0 || edge.from >= (int)remap.size() || edge.to >= (int)remap.size()) continue;
        if (remap[edge.from] < 0 || remap[edge.to] < 0) continue;
        ProcessGraphEdge retained = edge;
        retained.from = remap[edge.from];
        retained.to = remap[edge.to];
        processOnly.edges.push_back(std::move(retained));
    }
    model = std::move(processOnly);

    auto findOwner = [&](uint32_t pid, uint64_t timestamp) {
        int best = -1;
        uint64_t bestStart = 0;
        for (size_t i = 0; i < model.nodes.size(); ++i) {
            const auto& node = model.nodes[i];
            if (node.kind != ProcessGraphNodeKind::Process || node.pid != pid) continue;
            if (node.instanceStart == 0 || node.instanceStart <= timestamp) {
                if (best < 0 || node.instanceStart >= bestStart) {
                    best = (int)i;
                    bestStart = node.instanceStart;
                }
            }
        }
        return best;
    };
    auto addProcessAnchor = [&](const TelemetryEvent& event) {
        ProcessGraphNode node;
        node.id = "activity-process:" + std::to_string(event.processId);
        node.kind = ProcessGraphNodeKind::Process;
        node.pid = event.processId;
        node.label = BaseNameFromPathOrCommand(event.callerModule);
        if (node.label.empty() || node.label == "-") node.label = "PID " + std::to_string(event.processId);
        node.status = g_Target.active && event.processId == g_Target.pid ? "RUNNING" : "OBSERVED";
        node.size = ImVec2(360.0f, 124.0f);
        model.nodes.push_back(std::move(node));
        return (int)model.nodes.size() - 1;
    };

    std::unordered_map<std::string, int> activityByKey;
    for (size_t i = 0; i < model.nodes.size(); ++i) {
        if (model.nodes[i].kind == ProcessGraphNodeKind::Activity) activityByKey[model.nodes[i].id] = (int)i;
    }
    for (size_t eventIndex = 0; eventIndex < events.size(); ++eventIndex) {
        const auto& event = events[eventIndex];
        if (event.apiName.empty() || event.apiName.rfind("ETW ", 0) == 0 || IsProcessCreationApi(event.apiName)) continue;
        if (IsWinApiManuallyExcluded(event.apiName)) continue;
        if (!g_ShowBaselineApis && IsBaselineWinApi(event.apiName)) continue;
        int owner = findOwner(event.processId, event.timestamp);
        if (owner < 0) owner = addProcessAnchor(event);

        std::string category;
        std::string operation;
        if (IsFileApi(event.apiName)) {
            operation = FileOperationForApi(event.apiName);
            if (operation == "Read File" || operation == "Query Attributes" || operation == "Seek File" ||
                operation == "Flush File" || operation == "Close Handle" || operation.find("Mapping") != std::string::npos ||
                operation == "Map File View") continue;
            if (operation == "Write File" || operation == "Set Attributes" || operation == "Truncate/Extend File" ||
                operation == "Replace File") operation = "Modify";
            else if (operation == "Move/Rename File") operation = "Rename";
            else if (operation == "Delete File" || operation == "Remove Directory") operation = "Delete";
            else if (operation == "Create Directory") operation = "Create";
            else if (operation == "Open File") operation = "Open";
            else if (operation == "Create/Open File") operation = "Create / Open";
            else if (operation == "Copy File") operation = "Create";
            const bool folder = event.apiName.find("Directory") != std::string::npos ||
                (ParamValueOrZero(event, "dwFlagsAndAttributes") & 0x02000000ull) != 0 ||
                (ParamValueOrZero(event, "CreateOptions") & 0x1ull) != 0;
            category = folder ? "Folder Activity" : "File Activity";
        } else if (IsRegistryApi(event.apiName)) {
            operation = RegistryOperationForApi(event.apiName);
            if (operation == "Create Key") operation = "Create";
            else if (operation == "Open Key") operation = "Open";
            else if (operation == "Rename Key") operation = "Rename";
            else if (operation.find("Delete") != std::string::npos) operation = "Delete";
            else if (operation == "Set Value" || operation == "Set Key Security") operation = "Modify";
            else continue;
            category = "Registry Activity";
        } else if (IsNetworkApi(event.apiName)) {
            operation = NetworkActionForApi(event.apiName);
            if (operation == "Close" || operation == "Network") continue;
            category = "Network Connection";
        } else if (event.apiName == "WinExec" || ApiStartsWith(event.apiName, "ShellExecute")) {
            operation = "Execute";
            category = "Command Executed";
        } else {
            continue;
        }

        const std::string target = FullActivityGraphTarget(event, category);
        if (category == "Network Connection" && target == event.apiName) continue;
        const std::string key = model.nodes[owner].id + "|" + ToLowerCopy(category) + "|" + ToLowerCopy(target);
        auto found = activityByKey.find(key);
        if (found != activityByKey.end()) {
            auto& node = model.nodes[found->second];
            ++node.observations;
            node.eventIndex = (int)eventIndex;
            node.callerAddress = event.callerAddress;
            node.evidence = operation + " via " + event.apiName + " at " + FormatTimestamp(event.timestamp);
            continue;
        }

        ProcessGraphNode node;
        node.id = "activity:" + key;
        node.kind = ProcessGraphNodeKind::Activity;
        node.ownerIndex = owner;
        node.layer = model.nodes[owner].layer + 1;
        node.pid = event.processId;
        node.label = target;
        node.subtitle = operation + " | " + event.apiName;
        node.category = category;
        node.evidence = event.apiName + " at " + FormatTimestamp(event.timestamp);
        node.eventIndex = (int)eventIndex;
        node.callerAddress = event.callerAddress;
        node.size = ImVec2(330.0f, 108.0f);
        model.nodes.push_back(std::move(node));
        const int activityIndex = (int)model.nodes.size() - 1;
        activityByKey[key] = activityIndex;
        ProcessGraphEdge edge;
        edge.from = owner;
        edge.to = activityIndex;
        edge.evidence = event.apiName;
        model.edges.push_back(std::move(edge));
    }

    if (IncludeEtwInCategorizedActivity()) {
        auto addKernelActivity = [&](uint32_t pid, uint64_t timestamp, const std::string& category,
                                     const std::string& operation, const std::string& target,
                                     const std::string& evidence, int eventIndex) {
            if (target.empty() || target == "-" || target.find("Unknown ") == 0) return;
            int owner = findOwner(pid, timestamp);
            if (owner < 0) {
                TelemetryEvent anchor{};
                anchor.processId = pid;
                anchor.timestamp = timestamp;
                const AnalysisSession session = ProcessTreeManager::Instance().Snapshot();
                const auto process = std::find_if(session.processTreeNodes.begin(), session.processTreeNodes.end(),
                    [pid](const ProcessNode& node) { return node.pid == pid; });
                if (process != session.processTreeNodes.end()) anchor.callerModule = WStringToString(process->imagePath);
                owner = addProcessAnchor(anchor);
            }
            const std::string key = model.nodes[owner].id + "|" + ToLowerCopy(category) + "|" + ToLowerCopy(target);
            auto found = activityByKey.find(key);
            if (found != activityByKey.end()) {
                ++model.nodes[found->second].observations;
                model.nodes[found->second].evidence = evidence;
                return;
            }
            ProcessGraphNode node;
            node.id = "activity:" + key;
            node.kind = ProcessGraphNodeKind::Activity;
            node.ownerIndex = owner;
            node.layer = model.nodes[owner].layer + 1;
            node.pid = pid;
            node.label = target;
            node.subtitle = operation + " | Kernel observed";
            node.category = category;
            node.evidence = evidence;
            node.eventIndex = eventIndex;
            node.size = ImVec2(330.0f, 108.0f);
            model.nodes.push_back(std::move(node));
            const int activityIndex = static_cast<int>(model.nodes.size()) - 1;
            activityByKey[key] = activityIndex;
            ProcessGraphEdge edge;
            edge.from = owner;
            edge.to = activityIndex;
            edge.evidence = "ETW";
            model.edges.push_back(std::move(edge));
        };

        const auto kernelEvents = SnapshotEtwKernelEvents();
        const FileActivitySnapshot files = BuildFileActivitySnapshot({}, {}, kernelEvents);
        for (const auto& row : files.operations) {
            if (!row.fromEtw || row.operation == "Read File" || row.operation == "Close Handle" ||
                row.operation == "Flush File") continue;
            const std::string operation = row.operation == "Write File" ? "Modify" : row.operation;
            addKernelActivity(row.pid, row.timestampMs, row.directory ? "Folder Activity" : "File Activity",
                operation, row.path, row.api + " at " + row.time, row.eventIndex);
        }
        const RegistryActivitySnapshot registry = BuildRegistryActivitySnapshot({}, {}, kernelEvents);
        for (const auto& row : registry.operations) {
            if (!row.fromEtw) continue;
            const std::string lower = ToLowerCopy(row.operation);
            if (lower.find("create") == std::string::npos && lower.find("open") == std::string::npos &&
                lower.find("delete") == std::string::npos && lower.find("rename") == std::string::npos &&
                lower.find("set") == std::string::npos && lower.find("modify") == std::string::npos) continue;
            addKernelActivity(row.pid, row.timestampMs, "Registry Activity", row.operation,
                row.path + (row.valueName.empty() || row.valueName == "(Default)" ? "" : "\\" + row.valueName),
                row.api + " at " + row.time, row.eventIndex);
        }
    }

    // API interception can miss proprietary stacks or asynchronous system
    // workers. Add only high-value kernel connection endpoints as a fallback,
    // never the raw ETW event stream.
    bool usedNetworkFallback = false;
    NetworkActivitySnapshot network = BuildNetworkActivitySnapshotForUi(events, modules, &usedNetworkFallback);
    if (usedNetworkFallback) {
        for (const auto& connection : network.connections) {
            if (connection.sourceLayer.find("ETW") == std::string::npos) continue;
            std::string target = connection.domain != "-" ? connection.domain : connection.remoteIp;
            if (target.empty() || target == "-") continue;
            if (connection.remotePort != "-" && !connection.remotePort.empty()) target += ":" + connection.remotePort;
            int owner = findOwner(connection.pid, connection.timestampMs);
            if (owner < 0) {
                TelemetryEvent anchor{};
                anchor.processId = connection.pid;
                anchor.timestamp = connection.timestampMs;
                owner = addProcessAnchor(anchor);
            }
            const std::string category = "Network Connection";
            const std::string key = model.nodes[owner].id + "|network connection|" + ToLowerCopy(target);
            auto found = activityByKey.find(key);
            if (found != activityByKey.end()) {
                ++model.nodes[found->second].observations;
                continue;
            }
            ProcessGraphNode node;
            node.id = "activity:" + key;
            node.kind = ProcessGraphNodeKind::Activity;
            node.ownerIndex = owner;
            node.layer = model.nodes[owner].layer + 1;
            node.pid = connection.pid;
            node.label = target;
            node.subtitle = connection.action + " | Kernel fallback";
            node.category = category;
            node.evidence = "Kernel TCP/IP at " + connection.time;
            node.eventIndex = connection.eventIndex;
            node.size = ImVec2(330.0f, 108.0f);
            model.nodes.push_back(std::move(node));
            const int activityIndex = (int)model.nodes.size() - 1;
            activityByKey[key] = activityIndex;
            ProcessGraphEdge edge;
            edge.from = owner;
            edge.to = activityIndex;
            edge.evidence = "ETW TCP/IP";
            model.edges.push_back(std::move(edge));
        }
    }
    RelayoutFullActivityGraph(model);
    return model;
}

struct ProcessGraphCanvasState {
    ImVec2 pan = ImVec2(32.0f, 32.0f);
    float zoom = 1.0f;
    std::string selectedNodeId;
    std::string contextNodeId;
    std::string lastAnchor;
    bool backgroundGrabActive = false;
};

static ImVec4 ActivityGraphCategoryColor(const std::string& category) {
    const std::string lower = ToLowerCopy(category);
    if (lower.find("memory") != std::string::npos || lower.find("injection") != std::string::npos ||
        lower.find("anti") != std::string::npos || lower.find("driver") != std::string::npos) return kUiRed;
    if (lower.find("file") != std::string::npos || lower.find("folder") != std::string::npos ||
        lower.find("process") != std::string::npos || lower.find("command") != std::string::npos ||
        lower.find("service") != std::string::npos) return kUiGold;
    if (lower.find("registry") != std::string::npos || lower.find("ipc") != std::string::npos ||
        lower.find("loader") != std::string::npos || lower.find("dll") != std::string::npos) return kUiPurple;
    if (lower.find("network") != std::string::npos || lower.find("crypto") != std::string::npos ||
        lower.find("com") != std::string::npos || lower.find("wmi") != std::string::npos) return kUiBlue;
    return kUiGreen;
}

static void DrawProcessGraphCanvas(
    ProcessGraphModel model,
    ProcessGraphCanvasState& state,
    const char* canvasId
) {
    ImVec2& pan = state.pan;
    float& zoom = state.zoom;
    std::string& selectedNodeId = state.selectedNodeId;
    std::string& contextNodeId = state.contextNodeId;
    std::string& lastAnchor = state.lastAnchor;

    bool fitRequested = false;
    if (ImGui::Button("Fit Graph")) fitRequested = true;
    ImGui::SameLine();
    if (ImGui::Button("Reset View")) {
        zoom = 1.0f;
        pan = ImVec2(32.0f, 32.0f);
    }
    ImGui::SameLine();
    ImGui::TextColored(kUiTextMuted, "Drag empty space to pan  |  Wheel to zoom  |  Solid = observed  |  Dashed = inferred");

    const ProcessGraphNode* selectedNode = nullptr;
    for (const auto& node : model.nodes) if (node.id == selectedNodeId) { selectedNode = &node; break; }

    ImVec2 canvasSize = ImGui::GetContentRegionAvail();
    const float inspectorWidth = selectedNode ? (std::min)(430.0f, (std::max)(330.0f, canvasSize.x * 0.30f)) : 0.0f;
    if (selectedNode) canvasSize.x -= inspectorWidth + 8.0f;
    canvasSize.x = (std::max)(canvasSize.x, 80.0f);
    canvasSize.y = (std::max)(canvasSize.y, 80.0f);
    const ImVec2 canvasMin = ImGui::GetCursorScreenPos();
    const ImVec2 canvasMax(canvasMin.x + canvasSize.x, canvasMin.y + canvasSize.y);
    ImGui::InvisibleButton(canvasId, canvasSize,
        ImGuiButtonFlags_MouseButtonLeft | ImGuiButtonFlags_MouseButtonRight | ImGuiButtonFlags_MouseButtonMiddle);
    const bool canvasHovered = ImGui::IsItemHovered();

    std::string anchor;
    for (const auto& node : model.nodes) {
        if (node.kind == ProcessGraphNodeKind::Process) { anchor = node.id; break; }
    }
    if (lastAnchor != anchor) {
        fitRequested = true;
        lastAnchor = anchor;
    }

    auto fitGraph = [&]() {
        if (model.nodes.empty()) return;
        const float width = (std::max)(1.0f, model.boundsMax.x - model.boundsMin.x);
        const float height = (std::max)(1.0f, model.boundsMax.y - model.boundsMin.y);
        zoom = (std::min)((canvasSize.x - 60.0f) / width, (canvasSize.y - 60.0f) / height);
        zoom = (std::min)(1.5f, (std::max)(0.25f, zoom));
        pan.x = (canvasSize.x - width * zoom) * 0.5f - model.boundsMin.x * zoom;
        pan.y = (canvasSize.y - height * zoom) * 0.5f - model.boundsMin.y * zoom;
    };
    if (fitRequested) fitGraph();

    ImGuiIO& io = ImGui::GetIO();
    if (canvasHovered && io.MouseWheel != 0.0f) {
        const float oldZoom = zoom;
        zoom = (std::min)(2.0f, (std::max)(0.25f, zoom * (io.MouseWheel > 0.0f ? 1.12f : 0.89f)));
        const ImVec2 mouse(io.MousePos.x - canvasMin.x, io.MousePos.y - canvasMin.y);
        const ImVec2 world((mouse.x - pan.x) / oldZoom, (mouse.y - pan.y) / oldZoom);
        pan.x = mouse.x - world.x * zoom;
        pan.y = mouse.y - world.y * zoom;
    }
    if (canvasHovered && ImGui::IsMouseDragging(ImGuiMouseButton_Middle, 0.0f)) {
        pan.x += io.MouseDelta.x;
        pan.y += io.MouseDelta.y;
        ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
    }

    auto toScreen = [&](const ImVec2& point) {
        return ImVec2(canvasMin.x + pan.x + point.x * zoom, canvasMin.y + pan.y + point.y * zoom);
    };
    auto pointInside = [](const ImVec2& point, const ImVec2& minimum, const ImVec2& maximum) {
        return point.x >= minimum.x && point.y >= minimum.y && point.x <= maximum.x && point.y <= maximum.y;
    };

    int hoveredNode = -1;
    for (int i = (int)model.nodes.size() - 1; i >= 0; --i) {
        const ImVec2 minimum = toScreen(model.nodes[i].position);
        const ImVec2 maximum(minimum.x + model.nodes[i].size.x * zoom, minimum.y + model.nodes[i].size.y * zoom);
        if (pointInside(io.MousePos, minimum, maximum)) { hoveredNode = i; break; }
    }
    if (canvasHovered && ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        if (hoveredNode >= 0) {
            state.backgroundGrabActive = false;
            const auto& node = model.nodes[hoveredNode];
            selectedNodeId = node.id;
            if (node.eventIndex >= 0) {
                g_SelectedProcessActivityEventIndex = node.eventIndex;
                g_SelectedEventIndex = node.eventIndex;
            }
        } else {
            selectedNodeId.clear();
            state.backgroundGrabActive = true;
        }
    }
    if (state.backgroundGrabActive && ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
        if (ImGui::IsMouseDragging(ImGuiMouseButton_Left, 3.0f)) {
            pan.x += io.MouseDelta.x;
            pan.y += io.MouseDelta.y;
        }
    }
    if (ImGui::IsMouseReleased(ImGuiMouseButton_Left)) {
        state.backgroundGrabActive = false;
    }
    if (canvasHovered && hoveredNode >= 0 && ImGui::IsMouseClicked(ImGuiMouseButton_Right)) {
        contextNodeId = model.nodes[hoveredNode].id;
        selectedNodeId = contextNodeId;
        ImGui::OpenPopup("ProcessGraphNodeContext");
    }

    ImDrawList* drawList = ImGui::GetWindowDrawList();
    drawList->PushClipRect(canvasMin, canvasMax, true);
    drawList->AddRectFilled(canvasMin, canvasMax, ImGui::GetColorU32(kUiGraphCanvasBg));
    const float grid = 52.0f * zoom;
    if (grid >= 13.0f) {
        const ImU32 gridColor = ImGui::GetColorU32(kUiGraphGrid);
        float startX = std::fmod(pan.x, grid);
        float startY = std::fmod(pan.y, grid);
        if (startX < 0.0f) startX += grid;
        if (startY < 0.0f) startY += grid;
        for (float x = canvasMin.x + startX; x < canvasMax.x; x += grid) drawList->AddLine(ImVec2(x, canvasMin.y), ImVec2(x, canvasMax.y), gridColor);
        for (float y = canvasMin.y + startY; y < canvasMax.y; y += grid) drawList->AddLine(ImVec2(canvasMin.x, y), ImVec2(canvasMax.x, y), gridColor);
    }

    for (const auto& edge : model.edges) {
        if (edge.from < 0 || edge.to < 0 || edge.from >= (int)model.nodes.size() || edge.to >= (int)model.nodes.size()) continue;
        const auto& from = model.nodes[edge.from];
        const auto& to = model.nodes[edge.to];
        const ImVec2 fromPos = toScreen(from.position);
        const ImVec2 toPos = toScreen(to.position);
        const ImVec2 start(fromPos.x + from.size.x * zoom, fromPos.y + from.size.y * zoom * 0.5f);
        const ImVec2 end(toPos.x, toPos.y + to.size.y * zoom * 0.5f);
        const ImU32 edgeColor = ImGui::GetColorU32(edge.inferred ? kUiBlue : kUiTextMuted);
        DrawProcessGraphEdge(drawList, start, end, edgeColor, edge.inferred ? 1.4f : 1.8f, edge.inferred, zoom);
        if (edge.inferred && zoom >= 0.55f) {
            const ImVec2 middle = ProcessGraphBezierPoint(start,
                ImVec2(start.x + (end.x - start.x) * 0.42f, start.y),
                ImVec2(end.x - (end.x - start.x) * 0.42f, end.y), end, 0.5f);
            drawList->AddText(nullptr, ImGui::GetFontSize() * zoom * 0.78f, middle, edgeColor, "INFERRED");
        }
    }

    for (const auto& node : model.nodes) {
        const ImVec2 minimum = toScreen(node.position);
        const ImVec2 maximum(minimum.x + node.size.x * zoom, minimum.y + node.size.y * zoom);
        if (maximum.x < canvasMin.x || maximum.y < canvasMin.y || minimum.x > canvasMax.x || minimum.y > canvasMax.y) continue;
        ImVec4 accent = kUiBlue;
        if (node.kind == ProcessGraphNodeKind::Dll) accent = kUiPurple;
        else if (node.kind == ProcessGraphNodeKind::Activity) accent = ActivityGraphCategoryColor(node.category);
        else if (node.kind == ProcessGraphNodeKind::Process) {
            accent = node.status == "RUNNING" ? kUiGreen : (node.status == "TERMINATED" ? kUiRed : kUiGold);
        }
        const bool selected = selectedNodeId == node.id;
        const ImU32 accentColor = ImGui::GetColorU32(accent);
        drawList->AddRectFilled(minimum, maximum, ImGui::GetColorU32(kUiGraphNodeBg), 5.0f * zoom);
        drawList->AddRectFilled(minimum, ImVec2(minimum.x + 5.0f * zoom, maximum.y), accentColor, 5.0f * zoom);
        drawList->AddRect(minimum, maximum, selected ? ImGui::GetColorU32(kUiText) : accentColor,
            5.0f * zoom, (selected ? 3.0f : 1.4f) * zoom, 0);

        const float fontSize = ImGui::GetFontSize() * zoom;
        const ImVec2 textStart(minimum.x + 13.0f * zoom, minimum.y + 9.0f * zoom);
        const std::string categoryLine = node.kind == ProcessGraphNodeKind::Process ? "Process" :
            (node.kind == ProcessGraphNodeKind::Dll ? "DLL" :
            (node.kind == ProcessGraphNodeKind::Origin ?
                (node.category.empty() ? "Origin" : node.category) :
                (node.category.empty() ? "Activity" : node.category)));
        drawList->AddText(nullptr, fontSize * 0.72f, textStart, accentColor,
            CompactProcessGraphText(categoryLine, 44).c_str());
        drawList->AddText(nullptr, fontSize,
            ImVec2(textStart.x, textStart.y + 19.0f * zoom), ImGui::GetColorU32(kUiText),
            CompactProcessGraphText(node.label, 46).c_str());
        if (zoom >= 0.48f) {
            std::string secondLine;
            if (node.kind == ProcessGraphNodeKind::Process) {
                secondLine = "PID " + std::to_string(node.pid) + "  |  " + node.status;
            } else if (node.kind == ProcessGraphNodeKind::Activity) {
                secondLine = std::to_string(node.observations) + " event" +
                    (node.observations == 1 ? "" : "s") +
                    (node.subtitle.empty() ? "" : "  |  " + node.subtitle);
            } else {
                secondLine = node.subtitle;
            }
            drawList->AddText(nullptr, fontSize * 0.82f, ImVec2(textStart.x, textStart.y + 43.0f * zoom),
                accentColor, CompactProcessGraphText(secondLine, 56).c_str());
        }
        if (node.kind == ProcessGraphNodeKind::Process && zoom >= 0.70f) {
            const std::string commandPreview = CompactProcessGraphText(node.command, 180);
            drawList->AddText(nullptr, fontSize * 0.76f, ImVec2(textStart.x, textStart.y + 67.0f * zoom),
                ImGui::GetColorU32(kUiTextMuted), commandPreview.c_str(), nullptr, (node.size.x - 26.0f) * zoom);
        } else if (node.kind == ProcessGraphNodeKind::Origin && zoom >= 0.70f) {
            drawList->AddText(nullptr, fontSize * 0.72f, ImVec2(textStart.x, textStart.y + 67.0f * zoom),
                ImGui::GetColorU32(kUiBlue), "INFERRED");
        } else if (node.kind == ProcessGraphNodeKind::Activity && zoom >= 0.70f) {
            const std::string evidencePreview = CompactProcessGraphText(node.evidence, 150);
            drawList->AddText(nullptr, fontSize * 0.72f, ImVec2(textStart.x, textStart.y + 67.0f * zoom),
                ImGui::GetColorU32(kUiTextMuted), evidencePreview.c_str(), nullptr, (node.size.x - 26.0f) * zoom);
        }
    }
    drawList->PopClipRect();

    if (ImGui::BeginPopup("ProcessGraphNodeContext")) {
        const ProcessGraphNode* contextNode = nullptr;
        for (const auto& node : model.nodes) if (node.id == contextNodeId) { contextNode = &node; break; }
        if (contextNode) {
            ImGui::TextColored(kUiBlue, "%s", contextNode->label.c_str());
            ImGui::Separator();
            if (contextNode->pid && ImGui::MenuItem("Copy PID")) CopyToClipboard(std::to_string(contextNode->pid));
            if (!contextNode->command.empty() && ImGui::MenuItem("Copy Full Command")) CopyToClipboard(contextNode->command);
        }
        ImGui::EndPopup();
    }

    if (selectedNode) {
        ImGui::SetCursorScreenPos(ImVec2(canvasMax.x + 8.0f, canvasMin.y));
        ImGui::BeginChild("GraphNodeInspector", ImVec2(inspectorWidth, canvasSize.y), true,
            ImGuiWindowFlags_AlwaysVerticalScrollbar);
        const ImVec4 inspectorColor = selectedNode->kind == ProcessGraphNodeKind::Dll ? kUiPurple :
            (selectedNode->kind == ProcessGraphNodeKind::Activity ? ActivityGraphCategoryColor(selectedNode->category) :
             (selectedNode->kind == ProcessGraphNodeKind::Process ?
                (selectedNode->status == "RUNNING" ? kUiGreen : selectedNode->status == "TERMINATED" ? kUiRed : kUiGold) : kUiBlue));
        ImGui::TextColored(inspectorColor, "Event Details");
        ImGui::SameLine();
        ImGui::SetCursorPosX((std::max)(ImGui::GetCursorPosX(), ImGui::GetWindowContentRegionMax().x - 24.0f));
        if (ImGui::SmallButton("X##CloseGraphInspector")) selectedNodeId.clear();
        ImGui::Separator();
        ImGui::TextWrapped("%s", selectedNode->label.c_str());
        ImGui::Spacing();

        const char* nodeType = selectedNode->kind == ProcessGraphNodeKind::Process ? "Process" :
            selectedNode->kind == ProcessGraphNodeKind::Dll ? "DLL" :
            selectedNode->kind == ProcessGraphNodeKind::Origin ? "Origin / Evidence" : "Activity";
        ImGui::TextColored(kUiTextMuted, "Type");
        ImGui::TextWrapped("%s", nodeType);
        if (!selectedNode->category.empty()) {
            ImGui::TextColored(kUiTextMuted, "Category");
            ImGui::TextWrapped("%s", selectedNode->category.c_str());
        }
        if (selectedNode->pid) {
            ImGui::TextColored(kUiTextMuted, "Process");
            ImGui::Text("PID %u", selectedNode->pid);
        }
        if (!selectedNode->status.empty()) {
            ImGui::TextColored(kUiTextMuted, "Status");
            ImGui::TextColored(inspectorColor, "%s", selectedNode->status.c_str());
        }
        if (selectedNode->instanceStart) {
            ImGui::TextColored(kUiTextMuted, "Instance Start");
            ImGui::TextWrapped("%s", FormatTimestamp(selectedNode->instanceStart).c_str());
        }
        if (!selectedNode->subtitle.empty()) {
            ImGui::TextColored(kUiTextMuted, "Operation / Source");
            ImGui::TextWrapped("%s", selectedNode->subtitle.c_str());
        }
        if (!selectedNode->command.empty()) {
            ImGui::TextColored(kUiTextMuted, "Full Command");
            ImGui::TextWrapped("%s", selectedNode->command.c_str());
            if (ImGui::Button("Copy Command", ImVec2(-1.0f, 0.0f))) CopyToClipboard(selectedNode->command);
        }
        if (!selectedNode->evidence.empty()) {
            ImGui::TextColored(kUiTextMuted, "Evidence");
            ImGui::TextWrapped("%s", selectedNode->evidence.c_str());
        }
        ImGui::TextColored(kUiTextMuted, "Observations");
        ImGui::Text("%u", selectedNode->observations);
        if (selectedNode->kind == ProcessGraphNodeKind::Process)
            ImGui::TextWrapped("Telemetry source: %s", selectedNode->fromEtw ? "ETW" : "API / controller");
        ImGui::EndChild();
    }
}

static void DrawProcessGraph(
    const ProcessActivitySnapshot& snapshot,
    const std::unordered_map<uint32_t, std::vector<std::string>>& userDlls,
    const std::vector<TelemetryEvent>& events
) {
    static ProcessGraphCanvasState state;
    DrawProcessGraphCanvas(BuildProcessGraphModel(snapshot, userDlls, events), state, "ProcessGraphCanvas");
}

static void DrawProcessTreeNode(
    uint32_t pid,
    const std::string& label,
    const std::string& commandLine,
    uint64_t instanceStart,
    int instanceId,
    const std::vector<ProcessCreationRow>& rows,
    const std::vector<ProcessBehaviorRow>& terminations,
    const std::unordered_map<uint32_t, std::vector<std::string>>& userDlls,
    const std::string& prefix = "",
    bool isLast = true,
    bool isRoot = true
) {
    std::string displayLabel = label.empty() ? "Unknown process" : label;
    const ProcessBehaviorRow* termination = nullptr;
    for (const auto& row : terminations) {
        if (row.targetPid == pid && row.timestampMs >= instanceStart && (!termination || row.timestampMs < termination->timestampMs)) {
            termination = &row;
        }
    }
    bool isLiveRoot = pid == g_Target.pid && g_Target.active && !termination;
    const char* status = termination ? "TERMINATED" : (isLiveRoot ? "RUNNING" : "OBSERVED");
    ImVec4 statusColor = termination ? kUiRed : (isLiveRoot ? kUiGreen : kUiGold);
    // Explicit UTF-8 bytes avoid source-code page corruption in MSVC builds.
    std::string connector = isRoot ? "" : (isLast ? "\xE2\x94\x94\xE2\x94\x80 " : "\xE2\x94\x9C\xE2\x94\x80 ");
    std::string command = commandLine.empty() ? "Command unavailable" : commandLine;
    std::string line = prefix + connector + displayLabel + " (PID: " + std::to_string(pid) +
        ") (Command: " + command + ") (Status: " + status + ")";
    ImGui::PushID(instanceId);
    ImGui::Text("%s%s%s (PID: %d) (Command: %s) (Status: ", prefix.c_str(), connector.c_str(), displayLabel.c_str(), pid, command.c_str());
    ImGui::SameLine(0.0f, 0.0f);
    ImGui::TextColored(statusColor, "%s", status);
    ImGui::SameLine(0.0f, 0.0f);
    ImGui::Text(")");
    if (ImGui::BeginPopupContextItem("ProcessTreeContext")) {
        if (ImGui::MenuItem("Copy Full Command")) CopyToClipboard(commandLine);
        if (ImGui::MenuItem("Copy Tree Row")) CopyToClipboard(line);
        ImGui::EndPopup();
    }
    ImGui::PopID();

    std::vector<const ProcessCreationRow*> children;
    std::unordered_set<std::string> renderedChildren;
    for (const auto& row : rows) {
        std::string childInstance = std::to_string(row.childPid) + "|" + std::to_string(row.timestampMs);
        if (row.parentPid == pid && row.childPid != 0 && row.timestampMs >= instanceStart && renderedChildren.insert(childInstance).second)
            children.push_back(&row);
    }
    auto dllIt = userDlls.find(pid);
    size_t dllCount = dllIt == userDlls.end() ? 0 : dllIt->second.size();
    size_t totalChildren = children.size() + dllCount;
    std::string childPrefix = prefix + (isRoot ? "" : (isLast ? "   " : "\xE2\x94\x82  "));
    size_t childIndex = 0;
    for (const auto* row : children) {
        std::string childLabel = row->childName.empty()
            ? BaseNameFromPathOrCommand(row->executable.empty() ? row->commandLine : row->executable)
            : row->childName;
        DrawProcessTreeNode(row->childPid, childLabel, row->commandLine, row->timestampMs, row->eventIndex,
            rows, terminations, userDlls, childPrefix, ++childIndex == totalChildren, false);
    }
    if (dllIt != userDlls.end()) {
        for (size_t i = 0; i < dllIt->second.size(); ++i) {
            bool dllIsLast = ++childIndex == totalChildren;
            std::string dllConnector = dllIsLast ? "\xE2\x94\x94\xE2\x94\x80 " : "\xE2\x94\x9C\xE2\x94\x80 ";
            ImGui::PushID((int)(1000000 + i + pid));
            ImGui::TextColored(kUiPurple, "%s%s%s", childPrefix.c_str(), dllConnector.c_str(), dllIt->second[i].c_str());
            if (ImGui::BeginPopupContextItem("ProcessTreeDllContext")) {
                if (ImGui::MenuItem("Copy DLL Filename")) CopyToClipboard(dllIt->second[i]);
                ImGui::EndPopup();
            }
            ImGui::PopID();
        }
    }
}

static void DrawProcessBehaviorTable(const char* tableId, const std::vector<ProcessBehaviorRow>& rows) {
    if (rows.empty()) {
        return;
    }
    if (ImGui::BeginTable(tableId, 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders |
        ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Source PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Target PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Action", ImGuiTableColumnFlags_WidthFixed, 190.0f);
        ImGui::TableSetupColumn("Details", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Count", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            ImGui::PushID(row.eventIndex);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(row.time.c_str(), !row.fromEtw && g_SelectedProcessActivityEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns) && !row.fromEtw) {
                g_SelectedProcessActivityEventIndex = row.eventIndex;
                g_SelectedEventIndex = row.eventIndex;
            }
            if (ImGui::BeginPopupContextItem("ProcessBehaviorContext")) {
                if (ImGui::MenuItem("Copy Details")) CopyToClipboard(row.details);
                if (ImGui::MenuItem("Copy Row")) {
                    CopyToClipboard(row.time + " | " + row.action + " | " + row.details + " | " + row.api + " | " + row.callerFunction);
                }
                if (!row.fromEtw && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.processId);
            ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.targetPid ? std::to_string(row.targetPid).c_str() : "-");
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.action.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.details.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", row.result.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::Text("%u", row.observations);
            if (ImGui::IsItemHovered() && row.observations > 1) ImGui::SetTooltip("Last seen: %s", row.lastSeen.c_str());
            ImGui::TableSetColumnIndex(7);
            if (row.fromEtw) ImGui::TextColored(kUiBlue, "%s", row.api.c_str());
            else DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawProcessActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    const bool sandboxEtw = IsSandboxHostedSession();
    std::vector<EtwKernelEvent> etwSnapshot = IncludeEtwInCategorizedActivity()
        ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{};
    ProcessActivitySnapshot snapshot = BuildProcessActivitySnapshot(eventsSnapshot, modules, etwSnapshot);
    if (g_ProcessHideEtwFindings && !sandboxEtw) {
        snapshot.processes.erase(std::remove_if(snapshot.processes.begin(), snapshot.processes.end(), [](const ProcessCreationRow& row) {
            return row.api.rfind("ETW ", 0) == 0;
        }), snapshot.processes.end());
        snapshot.terminations.erase(std::remove_if(snapshot.terminations.begin(), snapshot.terminations.end(), [](const ProcessBehaviorRow& row) {
            return row.api.rfind("ETW ", 0) == 0;
        }), snapshot.terminations.end());
    }

    ImGui::BeginChild("ProcessActivityRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Process Activity", "Follow process creation, command execution, threads, handles, and the code responsible for each action.");

    size_t extendedEvents = snapshot.terminations.size() + snapshot.informationQueries.size() + snapshot.tokenAccess.size() +
        snapshot.environment.size() + snapshot.waits.size() + snapshot.currentProcessInfo.size() + snapshot.discovery.size() + snapshot.callbackExecutions.size();
    DrawEmptyAnalysisState(snapshot.processes.empty() && snapshot.commands.empty() && snapshot.threads.empty() &&
        snapshot.handles.empty() && extendedEvents == 0, "No process behavior captured. Start an analysis from Main or import a previous JSON database.");
    ImGui::Separator();

    std::unordered_map<uint32_t, std::vector<std::string>> userDlls;
    std::unordered_map<uint32_t, std::unordered_set<std::string>> seenUserDlls;
    auto rememberUserDll = [&](uint32_t pid, const std::string& moduleName, const std::string& path) {
        std::string display = path.empty() || path == "-" ? moduleName : path;
        std::string baseName = BaseNameFromPathOrCommand(display);
        if (pid == 0 || baseName.empty() || ToLowerCopy(baseName).find(".dll") == std::string::npos || IsAgentModule(baseName)) return;
        ObservedModule candidate; candidate.name = baseName; candidate.path = path;
        if (IsWindowsSystemModule(candidate)) return;
        std::string key = ToLowerCopy(display);
        if (seenUserDlls[pid].insert(key).second) userDlls[pid].push_back(baseName);
    };
    for (const auto& module : modules) rememberUserDll(g_Target.pid, module.name, module.path);
    for (const auto& ev : eventsSnapshot) {
        if (!IsDllLoadApi(ev.apiName)) continue;
        std::string path = ParamDecodedTextOrEmpty(ev, "lpLibFileName");
        if (path.empty()) path = ParamDecodedTextOrEmpty(ev, "ModuleFileName");
        if (path.empty()) path = ParamDecodedTextOrEmpty(ev, "lpFileName");
        rememberUserDll(ev.processId, BaseNameFromPathOrCommand(path), path);
    }

    ImGui::BeginChild("ProcessActivityWorkspace", ImVec2(0.0f, 0.0f), true);
    if (ImGui::BeginTabBar("ProcessActivityTabs")) {
        if (BeginFindingTabItem("PsTree", snapshot.processes.size())) {
            ImGui::SetWindowFontScale(1.16f);
            if (g_Target.pid != 0) {
                const std::wstring& rootPath = g_TargetProcessPath.empty() ? g_Target.path : g_TargetProcessPath;
                DrawProcessTreeNode(g_Target.pid, BaseNameFromPathOrCommand(WStringToString(rootPath)),
                    g_TargetCommandLine, 0, 0, snapshot.processes, snapshot.terminations, userDlls);
            } else if (snapshot.processes.empty()) {
            } else {
                std::unordered_set<uint32_t> childPids;
                std::unordered_set<uint32_t> renderedRoots;
                for (const auto& row : snapshot.processes) if (row.childPid) childPids.insert(row.childPid);
                for (const auto& row : snapshot.processes) {
                    if (childPids.find(row.parentPid) == childPids.end() && renderedRoots.insert(row.parentPid).second) {
                        DrawProcessTreeNode(row.parentPid, row.parentName, "", 0, row.eventIndex,
                            snapshot.processes, snapshot.terminations, userDlls);
                    }
                }
            }
            ImGui::SetWindowFontScale(1.0f);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("PsGraph", snapshot.processes.size())) {
            DrawProcessGraph(snapshot, userDlls, eventsSnapshot);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("PsList", snapshot.processes.size())) {
            if (ImGui::BeginTable("ProcessCreationTable", 7, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Parent Process", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Child Process", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Executable", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Command", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (const auto& row : snapshot.processes) {
                    ImGui::PushID(row.eventIndex);
                    ImGui::TableNextRow();
                    std::string rowText = "Time: " + row.time + "\nAPI: " + row.api +
                        "\nParent: " + (row.parentName.empty() ? "Unknown process" : row.parentName) + " (PID " + std::to_string(row.parentPid) + ")" +
                        "\nChild: " + (row.childName.empty() ? "Unknown process" : row.childName) +
                            (row.childPid ? " (PID " + std::to_string(row.childPid) + ")" : " (PID unavailable)") +
                        "\nExecutable: " + row.executable +
                        "\nCommand: " + row.commandLine +
                        "\nModule: " + ExtractModuleName(row.callerFunction);
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(row.time.c_str(), !row.fromEtw && g_SelectedProcessActivityEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns) && !row.fromEtw) {
                        g_SelectedProcessActivityEventIndex = row.eventIndex;
                        g_SelectedEventIndex = row.eventIndex;
                    }
                    if (ImGui::BeginPopupContextItem("ProcessCreationContext")) {
                        if (ImGui::MenuItem("Copy Row")) CopyToClipboard(rowText);
                        if (!row.fromEtw && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1);
                    ImGui::TextWrapped("%s (PID %u)", row.parentName.empty() ? "Unknown process" : row.parentName.c_str(), row.parentPid);
                    ImGui::TableSetColumnIndex(2);
                    if (row.childPid) {
                        ImGui::TextWrapped("%s (PID %u)", row.childName.empty() ? "Unknown process" : row.childName.c_str(), row.childPid);
                    } else {
                        ImGui::TextWrapped("%s (PID unavailable)", row.childName.empty() ? "Unknown process" : row.childName.c_str());
                    }
                    ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.executable.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.commandLine.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
                    ImGui::TableSetColumnIndex(6);
                    if (row.fromEtw) ImGui::TextColored(kUiBlue, "%s", row.api.c_str());
                    else DrawApiNameWithContext(row.api);
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Commands", snapshot.commands.size())) {
            if (ImGui::BeginTable("CommandExecutionTable", 5, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Command", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (const auto& row : snapshot.commands) {
                    ImGui::PushID(row.eventIndex);
                    ImGui::TableNextRow();
                    std::string rowText = row.time + "\nProcess: " + row.processName + "\nCommand: " + row.command + "\nModule: " + ExtractModuleName(row.callerFunction);
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(row.time.c_str(), g_SelectedProcessActivityEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedProcessActivityEventIndex = row.eventIndex;
                        g_SelectedEventIndex = row.eventIndex;
                    }
                    if (ImGui::BeginPopupContextItem("CommandExecutionContext")) {
                        if (ImGui::MenuItem("Copy Command")) CopyToClipboard(row.command);
                        if (ImGui::MenuItem("Copy Row")) CopyToClipboard(rowText);
                        if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.processName.c_str());
                    ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.command.c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
                    ImGui::TableSetColumnIndex(4); DrawApiNameWithContext(row.api);
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Threads", snapshot.threads.size())) {
            if (ImGui::BeginTable("ThreadCreationTable", 6, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Target PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("TID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Start Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (const auto& row : snapshot.threads) {
                    ImGui::PushID(row.eventIndex);
                    ImGui::TableNextRow();
                    std::string rowText = row.time + "\nAPI: " + row.api + "\nTarget PID: " + std::to_string(row.targetPid) +
                        "\nTID: " + std::to_string(row.threadId) + "\nStart: " + StaticHex(row.startAddress) +
                        "\nModule: " + ExtractModuleName(row.creatorFunction);
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(row.time.c_str(), g_SelectedProcessActivityEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedProcessActivityEventIndex = row.eventIndex;
                        g_SelectedEventIndex = row.eventIndex;
                    }
                    if (ImGui::BeginPopupContextItem("ThreadCreationContext")) {
                        if (ImGui::MenuItem("Copy Row")) CopyToClipboard(rowText);
                        if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.targetPid);
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%u", row.threadId);
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%s", StaticHex(row.startAddress).c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", ExtractModuleName(row.creatorFunction).c_str());
                    ImGui::TableSetColumnIndex(5); DrawApiNameWithContext(row.api);
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Handles", snapshot.handles.size())) {
            if (ImGui::BeginTable("ProcessHandlesTable", 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Source PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Target PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Type", ImGuiTableColumnFlags_WidthFixed, 90.0f);
                ImGui::TableSetupColumn("Name", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Access", ImGuiTableColumnFlags_WidthFixed, 100.0f);
                ImGui::TableSetupColumn("Decoded Access", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Handle", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (const auto& row : snapshot.handles) {
                    ImGui::PushID(row.eventIndex);
                    ImGui::TableNextRow();
                    std::string rowText = row.time + "\nSource PID: " + std::to_string(row.processId) +
                        "\nTarget PID: " + std::to_string(row.targetPid) + "\nType: " + row.type +
                        "\nName: " + row.name + "\nAccess: " + row.access +
                        "\nDecoded Access: " + row.decodedAccess +
                        "\nHandle: " + StaticHex(row.handle) + "\nModule: " + ExtractModuleName(row.creatorFunction);
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(row.time.c_str(), g_SelectedProcessActivityEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedProcessActivityEventIndex = row.eventIndex;
                        g_SelectedEventIndex = row.eventIndex;
                    }
                    if (ImGui::BeginPopupContextItem("ProcessHandleContext")) {
                        if (ImGui::MenuItem("Copy Row")) CopyToClipboard(rowText);
                        if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.processId);
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%u", row.targetPid);
                    ImGui::TableSetColumnIndex(3); ImGui::TextUnformatted(row.type.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.name.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::TextUnformatted(row.access.c_str());
                    ImGui::TableSetColumnIndex(6); ImGui::TextWrapped("%s", row.decodedAccess.c_str());
                    ImGui::TableSetColumnIndex(7); ImGui::Text("%s", StaticHex(row.handle).c_str());
                    ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(row.creatorFunction).c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Termination", snapshot.terminations.size())) {
            DrawProcessBehaviorTable("ProcessTerminationTable", snapshot.terminations);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Info Queries", snapshot.informationQueries.size())) {
            DrawProcessBehaviorTable("ProcessInformationQueryTable", snapshot.informationQueries);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Token", snapshot.tokenAccess.size())) {
            DrawProcessBehaviorTable("ProcessTokenAccessTable", snapshot.tokenAccess);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Environment", snapshot.environment.size())) {
            DrawProcessBehaviorTable("ProcessEnvironmentTable", snapshot.environment);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Wait / Sync", snapshot.waits.size())) {
            DrawProcessBehaviorTable("ProcessWaitingTable", snapshot.waits);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Process Info", snapshot.currentProcessInfo.size())) {
            DrawProcessBehaviorTable("CurrentProcessInfoTable", snapshot.currentProcessInfo);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Enumeration", snapshot.discovery.size())) {
            DrawProcessBehaviorTable("ProcessDiscoveryTable", snapshot.discovery);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Callback / Local", snapshot.callbackExecutions.size())) {
            ImGui::TextColored(kUiTextMuted,
                "Callback registration, activation, fiber transfers, alertable APC dispatch, SEH triggers, and inferred TLS callback execution.");
            ImGui::Separator();
            DrawProcessBehaviorTable("ProcessCallbackExecutionTable", snapshot.callbackExecutions);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();
    ImGui::EndChild();
}

static void DrawActivityTimelineTable(const std::vector<TelemetryEvent>& events) {
    const AnalysisSession session = ProcessTreeManager::Instance().Snapshot();
    struct Row { uint64_t time; uint32_t pid; std::string process; std::string activity; std::string evidence; };
    std::vector<Row> timeline;
    timeline.reserve(session.processTreeNodes.size() * 2 + events.size());
    for (const auto& node : session.processTreeNodes) {
        const std::string process = WStringToString(node.processName);
        timeline.push_back({ node.startTime, node.pid, process,
            node.relationship == "launcher" ? "Launcher started" : "Process started", WStringToString(node.commandLine) });
        if (node.exitTime) timeline.push_back({ node.exitTime, node.pid, process, "Process exited",
            "Exit code " + std::to_string(node.exitCode) });
    }
    for (const auto& event : events) {
        std::string detail = event.apiName;
        for (const auto& parameter : event.parameters) {
            if (!parameter.decoded.empty()) { detail += " | " + parameter.name + "=" + parameter.decoded.substr(0, 320); break; }
        }
        timeline.push_back({ event.timestamp, event.processId,
            event.processName.empty() ? BaseNameFromPathOrCommand(event.processPath) : event.processName,
            EventCategoryLabel(event), std::move(detail) });
    }
    if (IncludeEtwInCategorizedActivity()) {
        const auto kernelEvents = SnapshotEtwKernelEvents();
        for (const auto& event : kernelEvents) {
            if (event.category != "File" && event.category != "Registry" && event.category != "Network") continue;
            std::string process;
            const auto node = std::find_if(session.processTreeNodes.begin(), session.processTreeNodes.end(),
                [&event](const ProcessNode& item) { return item.pid == event.processId; });
            if (node != session.processTreeNodes.end()) process = WStringToString(node->processName);
            const std::string activity = event.category + " / " +
                (event.action.empty() ? event.opcode : event.action);
            std::string evidence = event.details;
            if (evidence.empty()) evidence = event.summary;
            if (evidence.empty()) evidence = event.provider + " / " + event.task;
            timeline.push_back({ event.timestamp, event.processId, process, activity, std::move(evidence) });
        }
    }
    std::stable_sort(timeline.begin(), timeline.end(), [](const Row& a, const Row& b) { return a.time < b.time; });
    DrawEmptyAnalysisState(timeline.empty(), "No session behavior has been captured yet.");
    if (ImGui::BeginTable("ActivityFullBehaviorTimeline", 5,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 105.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 75.0f);
        ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 180.0f);
        ImGui::TableSetupColumn("Activity", ImGuiTableColumnFlags_WidthFixed, 190.0f);
        ImGui::TableSetupColumn("Evidence");
        ImGui::TableHeadersRow();
        for (const auto& row : timeline) {
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0); ImGui::TextUnformatted(FormatTimestamp(row.time).c_str());
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(2); ImGui::TextUnformatted(row.process.empty() ? "-" : row.process.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextUnformatted(row.activity.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.evidence.c_str());
        }
        ImGui::EndTable();
    }
}

