static void DrawNetworkPayloadTable(const char* tableId, const std::vector<NetworkPayloadRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable(tableId, 8, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Direction", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Connection", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Source", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Bytes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Preview", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (size_t i = 0; i < rows.size(); ++i) {
            const auto& row = rows[i];
            if (g_HideExcluded && row.excluded) continue;
            if (!NetworkPayloadMatchesSearch(row, filter)) continue;
            ImGui::PushID((int)i);
            if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            bool selected = (g_SelectedNetworkPayloadIndex == (int)i);
            if (ImGui::Selectable(row.time.c_str(), selected, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedNetworkPayloadIndex = (int)i;
                g_SelectedNetworkEventIndex = row.eventIndex;
                g_SelectedEventIndex = row.eventIndex;
                g_HasSelectedNetworkPayload = true;
                g_SelectedNetworkPayloadData = row.payload;
                g_SelectedNetworkPayloadConnection = row.connection;
                g_SelectedNetworkPayloadDirection = row.direction;
                g_SelectedNetworkPayloadSource = row.sourceLayer;
                g_SelectedNetworkPayloadApi = row.api;
            }
            if (ImGui::BeginPopupContextItem("NetworkPayloadContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(NetworkPayloadRowText(row));
                if (ImGui::MenuItem("Copy Hex Bytes Only") && !row.payload.empty()) CopyToClipboard(HexRangeToHexOnly(row.payload, 0, row.payload.size()));
                if (ImGui::MenuItem("Copy ASCII Only") && !row.payload.empty()) CopyToClipboard(HexRangeToAsciiOnly(row.payload, 0, row.payload.size()));
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.direction.c_str());
            ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.connection.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::Text("%s", row.sourceLayer.c_str());
            ImGui::TableSetColumnIndex(4); DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(5); ImGui::Text("%zu", row.size);
            ImGui::TableSetColumnIndex(6); ImGui::TextWrapped("%s", row.httpPreview.empty() ? row.asciiPreview.c_str() : row.httpPreview.c_str());
            ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

