static void DrawNetworkActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    bool usedEtwFallback = false;
    NetworkActivitySnapshot snapshot = BuildNetworkActivitySnapshotForUi(eventsSnapshot, modules, &usedEtwFallback);
    std::string filter = g_NetworkSearchBuf;

    ImGui::BeginChild("NetworkActivityRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Network Activity", "Correlate API and ETW connections, DNS, URLs, reassembled streams, and plaintext captured at supported TLS boundaries.");

    DrawEmptyAnalysisState(snapshot.connections.empty() && snapshot.payloads.empty(), "No network behavior captured. Network APIs will appear here when the target communicates.");
    ImGui::Separator();

    ImGui::SetNextItemWidth(260.0f);
    ImGui::InputText("Search", g_NetworkSearchBuf, sizeof(g_NetworkSearchBuf));
    
    ImGui::SameLine();
    ImGui::Checkbox("Hide failed", &g_NetworkHideFailed);
    ImGui::SameLine();
    ImGui::TextColored((g_TraceConfig.flags & TraceConfigHookNetwork) ? kUiGreen : kUiTextMuted,
        "Hook Network: %s", (g_TraceConfig.flags & TraceConfigHookNetwork) ? "ON" : "OFF");
    if (usedEtwFallback) {
        ImGui::SameLine();
        ImGui::TextColored(kUiGold, "API endpoint telemetry unavailable; showing kernel network fallback");
    }
    ImGui::Separator();

    float networkAvailHeight = ImGui::GetContentRegionAvail().y;
    const float networkMinTop = 90.0f;
    const float networkMinBottom = 120.0f;
    const float networkSplitter = 4.0f;
    float networkMaxTop = networkAvailHeight - networkMinBottom - networkSplitter;
    if (networkMaxTop < networkMinTop) networkMaxTop = networkMinTop;
    g_NetworkActivityListHeight = (std::max)(networkMinTop, (std::min)(g_NetworkActivityListHeight, networkMaxTop));

    ImGui::BeginChild("NetworkActivityWorkspace", ImVec2(0.0f, g_NetworkActivityListHeight), true);
    if (ImGui::BeginTabBar("NetworkActivityTabs")) {
        if (BeginFindingTabItem("Connections", snapshot.connections.size())) {
            if (ImGui::BeginTable("NetworkConnectionsTable", 10, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Protocol", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Action", ImGuiTableColumnFlags_WidthFixed, 190.0f);
        ImGui::TableSetupColumn("Domain", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Remote IP", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Port", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Source", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : snapshot.connections) {
            if (g_HideExcluded && row.excluded) continue;
            if (g_NetworkHideFailed && !row.success) continue;
            if (!NetworkConnectionMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(row.time.c_str(), g_SelectedNetworkEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedNetworkEventIndex = row.eventIndex;
                if (row.eventIndex >= 0) g_SelectedEventIndex = row.eventIndex;
            }
            if (ImGui::BeginPopupContextItem("NetworkConnectionContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(NetworkConnectionRowText(row));
                if (ImGui::MenuItem("Copy Domain")) CopyToClipboard(row.domain);
                if (ImGui::MenuItem("Copy Remote IP")) CopyToClipboard(row.remoteIp);
                if (row.domain != "-" && ImGui::MenuItem("Lookup Domain in VirusTotal")) LookupNetworkIndicatorInVirusTotal("Domain", row.domain);
                if (row.remoteIp != "-" && ImGui::MenuItem("Lookup IP in VirusTotal")) LookupNetworkIndicatorInVirusTotal("IP Address", row.remoteIp);
                if (row.domain != "-" && ImGui::MenuItem("Exclude Domain")) g_NetworkExclusions.push_back("domain:" + row.domain);
                if (row.remoteIp != "-" && ImGui::MenuItem("Exclude IP")) g_NetworkExclusions.push_back("ip:" + row.remoteIp);
                if (row.remotePort != "-" && ImGui::MenuItem("Exclude Port")) g_NetworkExclusions.push_back("port:" + row.remotePort);
                if (row.pid && ImGui::MenuItem("Exclude PID")) g_NetworkExclusions.push_back("pid:" + std::to_string(row.pid));
                if (row.sourceApi != "ETW TCP/IP" && ImGui::MenuItem("Exclude API")) g_NetworkExclusions.push_back("api:" + row.sourceApi);
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.protocol.c_str());
            ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.action.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.domain.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.remoteIp.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::Text("%s", row.remotePort.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::TextColored(row.success ? kUiGreen : kUiRed, "%s", row.result.c_str());
            ImGui::TableSetColumnIndex(7); ImGui::Text("%s", row.sourceLayer.c_str());
            ImGui::TableSetColumnIndex(8); DrawApiNameWithContext(row.sourceApi);
            ImGui::TableSetColumnIndex(9); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Reassembled Streams", snapshot.streams.size())) {
            ImGui::TextColored(kUiTextMuted, "Buffers are grouped by connection, direction, and capture layer (maximum 1 MiB per stream).");
            DrawNetworkPayloadTable("NetworkStreamsTable", snapshot.streams, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("HTTP", snapshot.httpEvents.size())) {
            DrawNetworkPayloadTable("NetworkHttpTable", snapshot.httpEvents, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("URLs", snapshot.urls.size())) {
            DrawNetworkIndicatorTable("NetworkUrlsTable", snapshot.urls, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Domains", snapshot.domains.size())) {
            DrawNetworkIndicatorTable("NetworkDomainsTable", snapshot.domains, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("IP Addresses", snapshot.ips.size())) {
            DrawNetworkIndicatorTable("NetworkIpsTable", snapshot.ips, filter);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();

    VerticalSplitter("NetworkActivitySplit", g_NetworkActivityListHeight, networkMinTop, networkMaxTop, false);
    float networkViewerHeight = networkAvailHeight - g_NetworkActivityListHeight - networkSplitter;
    if (networkViewerHeight < networkMinBottom) networkViewerHeight = networkMinBottom;
    ImGui::BeginChild("NetworkContentViewer", ImVec2(0.0f, networkViewerHeight), true);
    ImGui::TextColored(kUiTextMuted, "Stream Content Viewer");
    ImGui::Separator();
    if (g_HasSelectedNetworkPayload) {
        ImGui::TextWrapped("Connection: %s", g_SelectedNetworkPayloadConnection.c_str());
        ImGui::Text("Direction: %s  |  Source: %s  |  API: %s  |  Bytes: %zu",
            g_SelectedNetworkPayloadDirection.c_str(), g_SelectedNetworkPayloadSource.c_str(),
            g_SelectedNetworkPayloadApi.c_str(), g_SelectedNetworkPayloadData.size());
        if (!g_SelectedNetworkPayloadData.empty()) {
            if (ImGui::Button("Copy Hex Bytes")) CopyToClipboard(HexRangeToHexOnly(
                g_SelectedNetworkPayloadData, 0, g_SelectedNetworkPayloadData.size()));
            ImGui::SameLine();
            if (ImGui::Button("Copy ASCII")) CopyToClipboard(HexRangeToAsciiOnly(
                g_SelectedNetworkPayloadData, 0, g_SelectedNetworkPayloadData.size()));
            ImGui::Separator();
            DrawHexDump(g_SelectedNetworkPayloadData);
        } else {
            ImGui::TextColored(kUiTextMuted, "The selected stream has no captured content.");
        }
    } else {
        ImGui::TextColored(kUiTextMuted, "Select a row in Reassembled Streams or HTTP to inspect its content.");
    }
    ImGui::EndChild();
    ImGui::EndChild();
}

static std::vector<uint8_t> RegistryViewerBytes(
    const std::string& type,
    const std::string& decoded,
    const std::vector<uint8_t>& captured
) {
    if (!captured.empty()) return captured;
    if (decoded.empty() || decoded == "-") return {};
    try {
        if (type == "REG_DWORD" || type == "REG_DWORD_BIG_ENDIAN") {
            uint32_t value = static_cast<uint32_t>(std::stoull(decoded, nullptr, 0));
            std::vector<uint8_t> bytes(sizeof(value));
            memcpy(bytes.data(), &value, sizeof(value));
            if (type == "REG_DWORD_BIG_ENDIAN") std::reverse(bytes.begin(), bytes.end());
            return bytes;
        }
        if (type == "REG_QWORD") {
            uint64_t value = std::stoull(decoded, nullptr, 0);
            std::vector<uint8_t> bytes(sizeof(value));
            memcpy(bytes.data(), &value, sizeof(value));
            return bytes;
        }
    } catch (...) {
    }
    if (type == "REG_SZ" || type == "REG_EXPAND_SZ" || type == "REG_MULTI_SZ") {
        std::wstring wide = StringToWString(decoded);
        std::vector<uint8_t> bytes((wide.size() + 1) * sizeof(wchar_t));
        memcpy(bytes.data(), wide.c_str(), bytes.size());
        return bytes;
    }
    if (type == "REG_BINARY") {
        std::vector<uint8_t> bytes;
        std::istringstream input(decoded);
        std::string token;
        while (input >> token) {
            try {
                size_t consumed = 0;
                unsigned long value = std::stoul(token, &consumed, 16);
                if (consumed == token.size() && value <= 0xFF) bytes.push_back(static_cast<uint8_t>(value));
            } catch (...) {
            }
        }
        if (!bytes.empty()) return bytes;
    }
    return std::vector<uint8_t>(decoded.begin(), decoded.end());
}

static void SelectRegistryData(
    const std::string& path,
    const std::string& valueName,
    const std::string& valueType,
    const std::string& decoded,
    const std::vector<uint8_t>& captured
) {
    g_HasSelectedRegistryData = true;
    g_SelectedRegistryPath = path;
    g_SelectedRegistryValueName = valueName;
    g_SelectedRegistryValueType = valueType;
    g_SelectedRegistryDecodedData = decoded;
    g_SelectedRegistryData = RegistryViewerBytes(valueType, decoded, captured);
    g_SelectedRegistryDataSource = captured.empty() ? "Decoded value representation" : "Captured registry buffer";
}

static void DrawRegistryOperationTable(const char* tableId, const std::vector<RegistryOperationRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable(tableId, 11, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Key Path", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Value", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Data", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("View", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Access", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (g_HideExcluded && row.excluded) continue;
            if (g_RegistryHideFailed && !row.success) continue;
            if (!RegistryRowMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            if (row.persistence) ImGui::TableNextRow(ImGuiTableRowFlags_None, 0.0f);
            else ImGui::TableNextRow();
            if (row.persistence) ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg0, ImGui::GetColorU32(ImVec4(0.35f, 0.25f, 0.05f, 0.40f)));
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(row.time.c_str(), g_SelectedRegistryEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedRegistryEventIndex = row.eventIndex;
                if (row.eventIndex >= 0) g_SelectedEventIndex = row.eventIndex;
                SelectRegistryData(row.path, row.valueName, row.valueType, row.valueData, row.rawData);
            }
            if (ImGui::BeginPopupContextItem("RegistryRowContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(RegistryRowText(row));
                if (ImGui::MenuItem("Copy Key Path")) CopyToClipboard(row.path);
                if (ImGui::MenuItem("Copy Value Data")) CopyToClipboard(row.valueData);
                if (ImGui::MenuItem("Exclude Path")) g_RegistryExclusions.push_back(row.path);
                if (row.valueName != "(Default)" && ImGui::MenuItem("Exclude Value Name")) g_RegistryExclusions.push_back("value:" + row.valueName);
                if (row.pid && ImGui::MenuItem("Exclude PID")) g_RegistryExclusions.push_back("pid:" + std::to_string(row.pid));
                if (!row.fromEtw && ImGui::MenuItem("Exclude API")) g_RegistryExclusions.push_back("api:" + row.api);
                if (ImGui::MenuItem("Exclude Operation")) g_RegistryExclusions.push_back("operation:" + row.operation);
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.operation.c_str());
            ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.path.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.valueName.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.valueType.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", row.valueData.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::TextColored(row.success ? kUiGreen : kUiRed, "%s", row.result.c_str());
            ImGui::TableSetColumnIndex(7); ImGui::Text("%s", row.registryView.c_str());
            ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", row.access.c_str());
            ImGui::TableSetColumnIndex(9);
            if (row.fromEtw) ImGui::TextColored(kUiBlue, "%s", row.api.c_str()); else DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(10); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawRegistryActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    std::vector<EtwKernelEvent> registryEtwEvents = (g_RegistryIncludeEtw || IsSandboxHostedSession())
        ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{};
    RegistryActivitySnapshot snapshot = BuildRegistryActivitySnapshot(eventsSnapshot, modules, registryEtwEvents);
    std::string filter = g_RegistrySearchBuf;

    ImGui::BeginChild("RegistryActivityRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Registry Activity", "Correlate Win32, native, and ETW registry activity; reconstruct observed state, decode values, and highlight persistence.");

    DrawEmptyAnalysisState(snapshot.operations.empty(), "No registry behavior captured. Registry access and persistence changes will appear here.");
    ImGui::Separator();

    ImGui::SetNextItemWidth(300.0f);
    ImGui::InputText("Search", g_RegistrySearchBuf, sizeof(g_RegistrySearchBuf));
    
    ImGui::SameLine();
    ImGui::Checkbox("Hide failed", &g_RegistryHideFailed);
    ImGui::Separator();

    float availHeight = ImGui::GetContentRegionAvail().y;
    const float splitterThickness = 4.0f;
    const float equalPanelHeight = (std::max)(80.0f, (availHeight - splitterThickness) * 0.5f);
    g_RegistryActivityListHeight = equalPanelHeight;

    ImGui::BeginChild("RegistryActivityWorkspace", ImVec2(0.0f, g_RegistryActivityListHeight), true);
    if (ImGui::BeginTabBar("RegistryActivityTabs")) {
        if (BeginFindingTabItem("Operations", snapshot.operations.size())) {
            DrawRegistryOperationTable("RegistryOperationsTable", snapshot.operations, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Registry Tree", snapshot.tree.size())) {
            for (const auto& kv : snapshot.tree) {
                if (ImGui::TreeNodeEx(kv.first.c_str(), ImGuiTreeNodeFlags_DefaultOpen)) {
                    for (size_t i = 0; i < kv.second.size(); ++i) {
                        ImGui::BulletText("%s", kv.second[i].c_str());
                    }
                    ImGui::TreePop();
                }
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Observed Final State", snapshot.finalState.size())) {
            ImGui::TextColored(kUiTextMuted, "Reconstructed from successful operations observed during this analysis; it is not a full system-registry snapshot.");
            if (ImGui::BeginTable("RegistryFinalStateTable", 7, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Key", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Value", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Data", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("State", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Last Updated", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Source", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.finalState.size(); ++i) {
                    const auto& state = snapshot.finalState[i];
                    if (!filter.empty() && !StringContainsInsensitive(state.key + " " + state.valueName + " " + state.data + " " + state.status, filter)) continue;
                    ImGui::PushID(static_cast<int>(i));
                    ImGui::TableNextRow();
                    if (state.persistence) ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg0, ImGui::GetColorU32(ImVec4(0.35f, 0.25f, 0.05f, 0.40f)));
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(state.key.c_str(), false, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedRegistryEventIndex = -1;
                        SelectRegistryData(state.key, state.valueName, state.type, state.data, state.rawData);
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::TextWrapped("%s", state.valueName.c_str());
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%s", state.type.c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", state.data.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextColored(state.status == "Deleted" ? kUiRed : kUiGreen, "%s", state.status.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::Text("%s", state.lastUpdated.c_str());
                    ImGui::TableSetColumnIndex(6); ImGui::Text("%s", state.sourceApi.c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Value History", snapshot.history.size())) {
            if (ImGui::BeginTable("RegistryHistoryTable", 4, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Key", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Value", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Changes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Latest Data", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.history.size(); ++i) {
                    const auto& history = snapshot.history[i];
                    if (!filter.empty() && !StringContainsInsensitive(history.key + " " + history.valueName, filter)) continue;
                    const RegistryOperationRow& latest = history.changes.back();
                    ImGui::PushID((int)i);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(history.key.c_str(), false, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedRegistryEventIndex = latest.eventIndex;
                        SelectRegistryData(latest.path, latest.valueName, latest.valueType, latest.valueData, latest.rawData);
                    }
                    if (ImGui::BeginPopupContextItem("RegistryHistoryContext")) {
                        std::ostringstream text;
                        text << history.key << "\\" << history.valueName << "\n";
                        for (const auto& change : history.changes) text << change.time << " | " << change.operation << " | " << change.valueData << "\n";
                        if (ImGui::MenuItem("Copy History")) CopyToClipboard(text.str());
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::TextWrapped("%s", history.valueName.c_str());
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%d", (int)history.changes.size());
                    ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", latest.valueData.c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Persistence", snapshot.persistence.size())) {
            DrawRegistryOperationTable("RegistryPersistenceTable", snapshot.persistence, filter);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();

    ImGui::Dummy(ImVec2(0.0f, splitterThickness));
    float detailsHeight = equalPanelHeight;
    ImGui::BeginChild("RegistryDataViewer", ImVec2(0.0f, detailsHeight), true);
    ImGui::TextColored(kUiTextMuted, "Data Viewer");
    ImGui::Separator();
    if (g_HasSelectedRegistryData) {
        ImGui::TextWrapped("Key: %s", g_SelectedRegistryPath.c_str());
        ImGui::Text("Value: %s  |  Type: %s  |  Bytes: %zu  |  Source: %s",
            g_SelectedRegistryValueName.c_str(), g_SelectedRegistryValueType.c_str(),
            g_SelectedRegistryData.size(), g_SelectedRegistryDataSource.c_str());
        ImGui::TextWrapped("Decoded: %s", g_SelectedRegistryDecodedData.c_str());
        if (!g_SelectedRegistryData.empty()) {
            if (ImGui::Button("Copy Hex Bytes")) CopyToClipboard(HexRangeToHexOnly(
                g_SelectedRegistryData, 0, g_SelectedRegistryData.size()));
            ImGui::SameLine();
            if (ImGui::Button("Copy ASCII")) CopyToClipboard(HexRangeToAsciiOnly(
                g_SelectedRegistryData, 0, g_SelectedRegistryData.size()));
            ImGui::Separator();
            DrawHexDump(g_SelectedRegistryData);
        } else {
            ImGui::TextColored(kUiTextMuted, "No registry value bytes were captured for this entry.");
        }
    } else {
        ImGui::TextColored(kUiTextMuted,
            "Select an entry in Operations, Observed Final State, Value History, or Persistence to inspect its bytes.");
    }
    ImGui::EndChild();
    ImGui::EndChild();
}

static void DrawFileOperationTable(const char* tableId, const std::vector<FileOperationRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable(tableId, 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Path", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Bytes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Detected", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (g_HideExcluded && row.excluded) continue;
            if (g_FileHideFailed && !row.success) continue;
            if (!FileRowMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(row.time.c_str(), g_SelectedFileEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedFileEventIndex = row.eventIndex;
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedFileInventoryIndex = -1;
                g_SelectedReconstructedFileIndex = -1;
                g_SelectedFileContent = row.content;
                g_SelectedFileContentPath = row.path;
                g_SelectedFileContentSource = "Captured " + row.operation;
                g_SelectedFileContentType = row.contentType;
            }
            if (ImGui::BeginPopupContextItem("FileOperationContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(FileRowText(row));
                if (ImGui::MenuItem("Copy Path")) CopyToClipboard(row.path);
                if (!row.secondaryPath.empty() && ImGui::MenuItem("Copy Target Path")) CopyToClipboard(row.secondaryPath);
                if (!row.content.empty() && ImGui::MenuItem("Copy Hex Bytes Only")) CopyToClipboard(HexRangeToHexOnly(row.content, 0, row.content.size()));
                if (!row.content.empty() && ImGui::MenuItem("Copy ASCII Only")) CopyToClipboard(HexRangeToAsciiOnly(row.content, 0, row.content.size()));
                if (ImGui::MenuItem("Add Path to Exclusions")) g_FileExclusions.push_back(row.path);
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.operation.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.path.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::Text("%zu", row.bytes);
            ImGui::TableSetColumnIndex(5); ImGui::Text("%s", row.contentType.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::TextColored(row.success ? (row.fromEtw ? kUiBlue : kUiGreen) : kUiRed, "%s", row.result.c_str());
            ImGui::TableSetColumnIndex(7); if (row.fromEtw) ImGui::TextColored(kUiBlue, "%s", row.api.c_str()); else DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static std::vector<uint8_t> ReadFileContentPreview(const std::string& path, size_t maximumBytes = 1024u * 1024u) {
    if (path.empty() || maximumBytes == 0) return {};
    std::wstring normalized = StringToWString(path);
    if (normalized.rfind(L"\\??\\", 0) == 0) normalized.erase(0, 4);
    std::ifstream stream(std::filesystem::path(normalized), std::ios::binary);
    if (!stream) return {};
    stream.seekg(0, std::ios::end);
    const std::streamoff length = stream.tellg();
    if (length <= 0) return {};
    const size_t bytes = (std::min)(maximumBytes, static_cast<size_t>(length));
    std::vector<uint8_t> content(bytes);
    stream.seekg(0, std::ios::beg);
    stream.read(reinterpret_cast<char*>(content.data()), static_cast<std::streamsize>(bytes));
    content.resize(static_cast<size_t>(stream.gcount()));
    return content;
}

static void DrawFileActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    std::vector<EtwKernelEvent> fileEtwEvents = (g_FileIncludeEtw || IsSandboxHostedSession())
        ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{};
    FileActivitySnapshot snapshot = BuildFileActivitySnapshot(eventsSnapshot, modules, fileEtwEvents);
    std::string filter = g_FileSearchBuf;

    ImGui::BeginChild("FileActivityRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("File Activity", "Track file and directory operations, inspect captured content, and reconstruct written files when data is available.");

    DrawEmptyAnalysisState(snapshot.operations.empty(), "No file behavior captured. File operations and recoverable write buffers will appear here.");
    ImGui::Separator();

    ImGui::SetNextItemWidth(300.0f);
    ImGui::InputText("Search", g_FileSearchBuf, sizeof(g_FileSearchBuf));
    
    ImGui::SameLine();
    ImGui::Checkbox("Hide failed", &g_FileHideFailed);
    ImGui::Separator();

    const float availHeight = ImGui::GetContentRegionAvail().y;
    const bool hasSelectedContent = !g_SelectedFileContentPath.empty();
    // Findings are the primary workspace. Keep enough rows visible even if a
    // previous splitter position was dragged almost to the top. Until an item
    // is selected, collapse the otherwise-empty viewer to its compact prompt.
    float minHeightTop = std::clamp(availHeight * 0.50f, 180.0f, 360.0f);
    float minHeightBottom = hasSelectedContent ? 160.0f : 68.0f;
    float splitterThickness = 4.0f;
    if (minHeightTop + minHeightBottom + splitterThickness > availHeight) {
        minHeightTop = (std::max)(80.0f, availHeight - minHeightBottom - splitterThickness);
    }
    float maxTopHeight = availHeight - minHeightBottom - splitterThickness;
    if (maxTopHeight < minHeightTop) maxTopHeight = minHeightTop;

    if (g_FileActivityListHeight > maxTopHeight) g_FileActivityListHeight = maxTopHeight;
    if (g_FileActivityListHeight < minHeightTop) g_FileActivityListHeight = minHeightTop;
    if (!hasSelectedContent) g_FileActivityListHeight = maxTopHeight;

    ImGui::BeginChild("FileActivityWorkspace", ImVec2(0.0f, g_FileActivityListHeight), true);
    if (ImGui::BeginTabBar("FileActivityTabs")) {
        if (BeginFindingTabItem("Operations", snapshot.operations.size())) {
            DrawFileOperationTable("FileOperationsTable", snapshot.operations, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Observed Objects", snapshot.inventory.size())) {
            if (ImGui::BeginTable("FileInventoryTable", 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Path", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Ext", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Detected", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Entropy", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("SHA256", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("State", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("First", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Last", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.inventory.size(); ++i) {
                    const auto& inv = snapshot.inventory[i];
                    if (g_HideExcluded && inv.excluded) continue;
                    if (!filter.empty() && !StringContainsInsensitive(inv.path + " " + inv.contentType, filter)) continue;
                    ImGui::PushID((int)i);
                    if (inv.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(inv.path.c_str(), g_SelectedFileInventoryIndex == (int)i, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedFileInventoryIndex = (int)i;
                        g_SelectedReconstructedFileIndex = -1;
                        g_SelectedFileEventIndex = -1;
                        g_SelectedFileContentPath = inv.path;
                        g_SelectedFileContentType = inv.contentType;
                        g_SelectedFileContentSource = "Observed file on disk (up to 1 MiB)";
                        g_SelectedFileContent.clear();
                        const std::string selectedPath = ToLowerCopy(inv.path);
                        for (const auto& recon : snapshot.reconstructed) {
                            if (ToLowerCopy(recon.path) == selectedPath && !recon.data.empty()) {
                                g_SelectedFileContent = recon.data;
                                g_SelectedFileContentSource = "Reconstructed writes";
                                break;
                            }
                        }
                        if (g_SelectedFileContent.empty()) {
                            for (auto operation = snapshot.operations.rbegin(); operation != snapshot.operations.rend(); ++operation) {
                                if (ToLowerCopy(operation->path) == selectedPath && !operation->content.empty()) {
                                    g_SelectedFileContent = operation->content;
                                    g_SelectedFileContentSource = "Captured " + operation->operation;
                                    break;
                                }
                            }
                        }
                        if (g_SelectedFileContent.empty() && !inv.deleted) {
                            g_SelectedFileContent = ReadFileContentPreview(inv.path);
                        }
                    }
                    if (ImGui::BeginPopupContextItem("FileInventoryContext")) {
                        if (ImGui::MenuItem("Copy Path")) CopyToClipboard(inv.path);
                        if (ImGui::MenuItem("Copy SHA256")) CopyToClipboard(inv.sha256);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%s", inv.extension.c_str());
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%zu", inv.size);
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%s", inv.contentType.empty() ? "-" : inv.contentType.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextColored(inv.entropy >= 7.2 ? kUiGold : kUiText, "%.2f", inv.entropy);
                    ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", inv.sha256.empty() ? "-" : inv.sha256.c_str());
                    ImGui::TableSetColumnIndex(6); ImGui::TextColored(inv.deleted ? kUiRed : kUiGreen, "%s", inv.deleted ? "Deleted" : (inv.failedCount ? "Observed*" : "Observed"));
                    ImGui::TableSetColumnIndex(7); ImGui::Text("%s", inv.firstSeen.c_str());
                    ImGui::TableSetColumnIndex(8); ImGui::Text("%s", inv.lastSeen.c_str());
                    if (inv.excluded && g_DimExcluded) ImGui::PopStyleColor();
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Reconstructed Files", snapshot.reconstructed.size())) {
            if (ImGui::BeginTable("ReconstructedFilesTable", 7, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Path", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Writes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Detected", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("SHA256", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Coverage", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Last", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.reconstructed.size(); ++i) {
                    const auto& recon = snapshot.reconstructed[i];
                    if (g_HideExcluded && recon.excluded) continue;
                    if (!filter.empty() && !StringContainsInsensitive(recon.path + " " + recon.contentType, filter)) continue;
                    ImGui::PushID((int)i);
                    if (recon.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(recon.path.c_str(), g_SelectedReconstructedFileIndex == (int)i, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedReconstructedFileIndex = (int)i;
                        g_SelectedFileInventoryIndex = -1;
                        g_SelectedFileEventIndex = -1;
                        g_SelectedFileContent = recon.data;
                        g_SelectedFileContentPath = recon.path;
                        g_SelectedFileContentSource = "Reconstructed writes";
                        g_SelectedFileContentType = recon.contentType;
                    }
                    if (ImGui::BeginPopupContextItem("ReconstructedFileContext")) {
                        if (ImGui::MenuItem("Copy Path")) CopyToClipboard(recon.path);
                        if (ImGui::MenuItem("Copy SHA256")) CopyToClipboard(recon.sha256);
                        if (ImGui::MenuItem("Copy Hex Bytes Only")) CopyToClipboard(HexRangeToHexOnly(recon.data, 0, recon.data.size()));
                        if (ImGui::MenuItem("Save Reconstructed File")) {
                            SaveBinaryFileWithDialog(recon.data, L"reconstructed_file.bin", L"reconstructed file");
                        }
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%zu", recon.data.size());
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%d", recon.writeCount);
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%s", recon.contentType.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", recon.sha256.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::TextColored(recon.complete ? kUiGreen : kUiGold, "%s", recon.complete ? "Complete" : "Partial");
                    ImGui::TableSetColumnIndex(6); ImGui::Text("%s", recon.lastSeen.c_str());
                    if (recon.excluded && g_DimExcluded) ImGui::PopStyleColor();
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Directory Activity", snapshot.directories.size())) {
            DrawFileOperationTable("DirectoryActivityTable", snapshot.directories, filter);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();

    VerticalSplitter("FileActivitySplit", g_FileActivityListHeight, minHeightTop, maxTopHeight, false);
    float detailsHeight = availHeight - g_FileActivityListHeight - splitterThickness;
    if (detailsHeight < minHeightBottom) detailsHeight = minHeightBottom;
    ImGui::BeginChild("FileContentViewer", ImVec2(0.0f, detailsHeight), true);
    ImGui::TextColored(kUiTextMuted, "Content Viewer");
    ImGui::Separator();
    if (!g_SelectedFileContentPath.empty()) {
        ImGui::TextWrapped("Path: %s", g_SelectedFileContentPath.c_str());
        ImGui::Text("Source: %s  |  Bytes: %zu  |  Detected: %s",
            g_SelectedFileContentSource.c_str(), g_SelectedFileContent.size(),
            g_SelectedFileContentType.empty() ? "-" : g_SelectedFileContentType.c_str());
        if (!g_SelectedFileContent.empty()) {
            if (ImGui::Button("Copy Hex Bytes Only")) CopyToClipboard(HexRangeToHexOnly(
                g_SelectedFileContent, 0, g_SelectedFileContent.size()));
            ImGui::SameLine();
            if (ImGui::Button("Copy ASCII Only")) CopyToClipboard(HexRangeToAsciiOnly(
                g_SelectedFileContent, 0, g_SelectedFileContent.size()));
            ImGui::Separator();
            DrawHexDump(g_SelectedFileContent);
        } else {
            ImGui::TextColored(kUiTextMuted,
                "No bytes were captured, reconstructed, or readable from disk for this object.");
        }
    } else {
        ImGui::TextColored(kUiTextMuted,
            "Select an operation, observed object, or reconstructed file to inspect its content.");
    }
    ImGui::EndChild();
    ImGui::EndChild();
}

static void DrawMemoryEventTable(const char* tableId, const std::vector<MemoryEventRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable(tableId, 10, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Category", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Target PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Details", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (row.heapActivity && !g_MemoryShowHeapActivity) continue;
            if (row.queryActivity && !g_MemoryShowQueryActivity) continue;
            if (g_HideExcluded && row.excluded) continue;
            if (!MemoryRowMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(row.time.c_str(), g_SelectedMemoryEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedMemoryEventIndex = row.eventIndex;
                g_SelectedEventIndex = row.eventIndex;
            }
            if (ImGui::BeginPopupContextItem("MemoryEventContext")) {
                std::ostringstream text;
                text << row.time << " | " << row.operation << " | Address: " << FormatHexValue(row.baseAddress) << " | Size: " << row.size << " | " << row.details;
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(text.str());
                if (ImGui::MenuItem("Copy Address")) CopyToClipboard(FormatHexValue(row.baseAddress));
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.category.c_str());
            ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.operation.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::Text("%u", row.targetPid);
            ImGui::TableSetColumnIndex(4); ImGui::Text("%s", FormatHexValue(row.baseAddress).c_str());
            ImGui::TableSetColumnIndex(5); ImGui::Text("%zu", row.size);
            ImGui::TableSetColumnIndex(6); ImGui::TextColored(row.success ? kUiGreen : kUiRed, "%s", row.result.c_str());
            ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", row.details.c_str());
            ImGui::TableSetColumnIndex(8); DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(9); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawMemoryActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    MemoryActivitySnapshot snapshot = BuildMemoryActivitySnapshotV2(eventsSnapshot, modules, g_Target.active ? g_Target.pid : 0);
    std::vector<RecoveredStringRow> recoveredStrings;
    {
        std::lock_guard<std::mutex> lock(g_RecoveredStringsMutex);
        recoveredStrings = g_RecoveredStrings;
    }
    std::string filter = g_MemorySearchBuf;
    size_t visibleEvents = 0;
    size_t visibleRegions = 0;
    for (const auto& row : snapshot.events) if ((!row.heapActivity || g_MemoryShowHeapActivity) && (!row.queryActivity || g_MemoryShowQueryActivity)) ++visibleEvents;
    for (const auto& region : snapshot.inventory) if (!region.heapRegion || g_MemoryShowHeapActivity) ++visibleRegions;

    ImGui::BeginChild("MemoryActivityRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Memory Activity", "Investigate allocations, protection changes, executable regions, captured writes, and shellcode or in-memory PE indicators.");

    DrawEmptyAnalysisState(snapshot.events.empty() && recoveredStrings.empty(), "No memory behavior captured. Allocations, protection changes, changed-page strings, and memory writes will appear here.");
    ImGui::Separator();

    ImGui::SetNextItemWidth(300.0f);
    ImGui::InputText("Search", g_MemorySearchBuf, sizeof(g_MemorySearchBuf));
    
    ImGui::SameLine();
    ImGui::Checkbox("Show heap activity", &g_MemoryShowHeapActivity);
    ImGui::SameLine();
    ImGui::Checkbox("Show memory queries", &g_MemoryShowQueryActivity);
    ImGui::Separator();

    float availHeight = ImGui::GetContentRegionAvail().y;
    const float minHeightTop = 140.0f;
    const float minHeightBottom = 120.0f;
    const float splitterThickness = 4.0f;
    float maxTopHeight = (std::max)(minHeightTop, availHeight - minHeightBottom - splitterThickness);
    g_MemoryActivityListHeight = (std::min)((std::max)(g_MemoryActivityListHeight, minHeightTop), maxTopHeight);
    ImGui::BeginChild("MemoryWorkspace", ImVec2(0.0f, g_MemoryActivityListHeight), true);
    if (ImGui::BeginTabBar("MemoryActivityTabs")) {

        if (BeginFindingTabItem("Memory Operations", visibleEvents)) {
            DrawMemoryEventTable("MemoryEventsTable", snapshot.events, filter);
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Observed Objects", visibleRegions)) {
            if (ImGui::BeginTable("MemoryInventoryTable", 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Base Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Allocation API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Initial Protect", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Current Protect", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Status", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.inventory.size(); ++i) {
                    const auto& reg = snapshot.inventory[i];
                    if (reg.heapRegion && !g_MemoryShowHeapActivity) continue;
                    if (g_HideExcluded && reg.excluded) continue;
                    ImGui::PushID((int)i);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0); ImGui::Text("%u", reg.pid);
                    ImGui::TableSetColumnIndex(1);
                    bool selected = (g_SelectedMemoryRegionIndex == (int)i);
                    if (ImGui::Selectable(FormatHexValue(reg.baseAddress).c_str(), selected, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedMemoryRegionIndex = (int)i;
                        CaptureMemoryRegionForViewer(reg);
                    }
                    if (ImGui::BeginPopupContextItem("MemoryInventoryContext")) {
                        if (ImGui::MenuItem("Copy Address")) CopyToClipboard(FormatHexValue(reg.baseAddress));
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%zu", reg.size);
                    ImGui::TableSetColumnIndex(3); DrawApiNameWithContext(reg.allocationApi);
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%s", reg.initialProtection.c_str());
                    ImGui::TableSetColumnIndex(5);
                    if (reg.isExecutable) ImGui::TextColored(kUiRed, "%s", reg.currentProtection.c_str());
                    else ImGui::Text("%s", reg.currentProtection.c_str());
                    ImGui::TableSetColumnIndex(6); ImGui::Text("%s", reg.type.c_str());
                    ImGui::TableSetColumnIndex(7); ImGui::TextColored(reg.status == "ACTIVE" ? kUiGreen : kUiRed, "%s", reg.status.c_str());
                    ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(reg.callerFunction).c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Region History", snapshot.history.size())) {
            const MemoryRegionRow* selectedRegion = nullptr;
            for (const auto& region : snapshot.inventory) {
                const uint32_t regionPid = region.targetPid ? region.targetPid : region.pid;
                if (region.baseAddress == g_SelectedMemoryDumpAddress &&
                    (!g_SelectedMemoryRegionPid || regionPid == g_SelectedMemoryRegionPid)) {
                    selectedRegion = &region;
                    break;
                }
            }
            if (selectedRegion) {
                ImGui::Text("Protection History for Region: %s", FormatHexValue(selectedRegion->baseAddress).c_str());
                ImGui::Separator();
                for (const auto& hist : snapshot.history) {
                    if (hist.baseAddress == selectedRegion->baseAddress) {
                        for (const auto& ev : hist.events) {
                            ImGui::BulletText("%s  |  %s  |  %s  |  Module: %s", ev.time.c_str(), ev.operation.c_str(), ev.details.c_str(), ExtractModuleName(ev.callerFunction).c_str());
                        }
                    }
                }
            } else {
                ImGui::TextColored(kUiTextMuted, "Select a region in Observed Objects to inspect its protection history.");
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Shellcode / PE Detection", snapshot.detections.size())) {
            if (ImGui::BeginTable("MemoryDetectionTable", 5, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Base Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Detection Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Details", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (const auto& det : snapshot.detections) {
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    ImGui::TextColored(kUiGold, "%s", FormatHexValue(det.baseAddress).c_str());
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%zu", det.size);
                    ImGui::TableSetColumnIndex(2); ImGui::TextColored(kUiGold, "%s", det.detectionType.c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", det.details.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", ExtractModuleName(det.callerFunction).c_str());
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Injection Sequences", snapshot.sequences.size())) {
            if (ImGui::BeginTable("MemorySequenceTable", 5, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Base Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Allocated Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Written Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Thread Started", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Protection", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.sequences.size(); ++i) {
                    const auto& seq = snapshot.sequences[i];
                    ImGui::PushID((int)i);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    bool selected = (g_SelectedMemorySequenceIndex == (int)i);
                    if (ImGui::Selectable(FormatHexValue(seq.baseAddress).c_str(), selected, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedMemorySequenceIndex = (int)i;
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%zu", seq.allocatedSize);
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%zu", seq.writtenSize);
                    ImGui::TableSetColumnIndex(3); ImGui::TextColored(seq.threadStarted ? kUiGreen : kUiTextMuted, seq.threadStarted ? "Yes" : "No");
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%s", seq.currentProtection.c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Recovered Runtime Strings", recoveredStrings.size())) {
            ImGui::TextColored(kUiTextMuted,
                "Runtime plaintext recovered from changed private or mapped memory pages.");
            bool executableOnly = g_RuntimeStringsExecutableOnly.load();
            if (ImGui::Checkbox("Executable regions only (RWX / -WX / R-X / --X)", &executableOnly)) {
                g_RuntimeStringsExecutableOnly.store(executableOnly);
            }
            ImGui::SameLine();
            ImGui::TextColored(kUiTextMuted, "Enable this only when ordinary RW memory is too noisy.");
            ImGui::Separator();
            if (recoveredStrings.empty()) {
                ImGui::TextColored(kUiTextMuted, g_Target.active
                    ? "Watching changed memory pages. Recovered strings will appear when matching memory changes."
                    : "Launch a target to begin runtime string recovery.");
            } else if (ImGui::BeginTable("RecoveredRuntimeStringsTable", 9,
                ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("First Seen", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Protect", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Region", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Encoding", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Classification", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Seen", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Recovered Value", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < recoveredStrings.size(); ++i) {
                    const auto& row = recoveredStrings[i];
                    if (executableOnly && row.protection.find('X') == std::string::npos) continue;
                    if (!filter.empty() && !StringContainsInsensitive(row.value + " " + row.encoding + " " +
                        row.classification + " " + row.protection + " " + row.regionType + " " + FormatHexValue(row.address), filter)) continue;
                    ImGui::PushID(static_cast<int>(i));
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0); ImGui::Selectable(row.firstSeen.c_str(), false, ImGuiSelectableFlags_SpanAllColumns);
                    if (ImGui::BeginPopupContextItem("RecoveredStringContext")) {
                        if (ImGui::MenuItem("Copy Recovered String")) CopyToClipboard(row.value);
                        if (ImGui::MenuItem("Copy Address")) CopyToClipboard(FormatHexValue(row.address));
                        if (ImGui::MenuItem("Copy Full Row")) CopyToClipboard(row.firstSeen + " | PID " +
                            std::to_string(row.pid) + " | " + FormatHexValue(row.address) + " | " +
                            row.protection + " | " + row.encoding + " | " + row.classification + " | " + row.value);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%s", FormatHexValue(row.address).c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::TextColored(row.protection.find('X') != std::string::npos ? kUiRed : kUiText, "%s", row.protection.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.regionType.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::Text("%s", row.encoding.c_str());
                    ImGui::TableSetColumnIndex(6);
                    ImGui::TextColored(row.classification.rfind("Decoded", 0) == 0 ? kUiGold : kUiText, "%s", row.classification.c_str());
                    ImGui::TableSetColumnIndex(7); ImGui::Text("%u", row.observations);
                    ImGui::TableSetColumnIndex(8); ImGui::TextUnformatted(row.value.c_str());
                    if (ImGui::IsItemHovered()) ImGui::SetTooltip("Last seen: %s", row.lastSeen.c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        ImGui::EndTabBar();
    }
    ImGui::EndChild();

    VerticalSplitter("MemoryActivitySplit", g_MemoryActivityListHeight, minHeightTop, maxTopHeight, false);
    float viewerHeight = availHeight - g_MemoryActivityListHeight - splitterThickness;
    if (viewerHeight < minHeightBottom) viewerHeight = minHeightBottom;
    ImGui::BeginChild("MemoryDumpViewer", ImVec2(0.0f, viewerHeight), true);
    ImGui::TextColored(kUiTextMuted, "Memory Dump Viewer");
    ImGui::Separator();
    const MemoryRegionRow* selectedRegion = nullptr;
    for (const auto& region : snapshot.inventory) {
        const uint32_t regionPid = region.targetPid ? region.targetPid : region.pid;
        if (region.baseAddress == g_SelectedMemoryDumpAddress &&
            (!g_SelectedMemoryRegionPid || regionPid == g_SelectedMemoryRegionPid)) {
            selectedRegion = &region;
            break;
        }
    }
    if (selectedRegion || g_SelectedMemoryDumpAddress) {
        ImGui::Text("PID: %u  |  Region Base: %s  |  Dump size: %zu bytes",
            g_SelectedMemoryRegionPid, FormatHexValue(g_SelectedMemoryDumpAddress).c_str(),
            g_SelectedMemoryDumpData.size());
        ImGui::TextColored(kUiTextMuted, "%s", g_SelectedMemoryDumpStatus.empty() ? "Select the region again to capture its bytes." : g_SelectedMemoryDumpStatus.c_str());
        if (!selectedRegion) ImGui::BeginDisabled();
        if (ImGui::Button("Refresh Live Read") && selectedRegion) CaptureMemoryRegionForViewer(*selectedRegion);
        if (!selectedRegion) ImGui::EndDisabled();
        if (!g_SelectedMemoryDumpData.empty()) {
            ImGui::SameLine();
            if (ImGui::Button("Copy Hex Bytes")) CopyToClipboard(HexRangeToHexOnly(g_SelectedMemoryDumpData, 0, g_SelectedMemoryDumpData.size()));
            ImGui::SameLine();
            if (ImGui::Button("Save Dump as File")) {
                std::wostringstream name;
                name << L"memory_0x" << std::hex << std::uppercase << g_SelectedMemoryDumpAddress << L".bin";
                SaveBinaryFileWithDialog(g_SelectedMemoryDumpData, name.str().c_str(), L"memory dump");
            }
        }
        ImGui::Separator();
        if (!g_SelectedMemoryDumpData.empty()) DrawHexDump(g_SelectedMemoryDumpData);
    } else {
        ImGui::TextColored(kUiTextMuted, "Select a region in Observed Objects to capture and inspect its bytes.");
    }
    ImGui::EndChild();
    ImGui::EndChild();
}

static void DrawDllEventTable(const char* tableId, const std::vector<DllEventRow>& rows, const std::string& filter, bool showAnalysis = false) {
    if (ImGui::BeginTable(tableId, showAnalysis ? 9 : 8, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Loaded DLL", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Target / Object", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("API / Source", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Status", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        if (showAnalysis) ImGui::TableSetupColumn("Analysis", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (g_HideExcluded && row.excluded) continue;
            if (!DllEventMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex >= 0 ? row.eventIndex : (int)row.moduleHandle);
            if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            bool selected = (g_SelectedDllEventIndex == row.eventIndex && row.eventIndex >= 0);
            if (ImGui::Selectable(row.time.c_str(), selected, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedDllEventIndex = row.eventIndex;
                if (row.eventIndex >= 0) {
                    g_SelectedEventIndex = row.eventIndex;
                    g_SelectedParamIndex = -1;
                }
            }
            if (ImGui::BeginPopupContextItem("DllEventContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(DllEventRowText(row));
                if (ImGui::MenuItem("Copy Module")) CopyToClipboard(row.moduleName);
                if (ImGui::MenuItem("Copy Target / Object")) CopyToClipboard(row.path.empty() ? row.requestedName : row.path);
                if (ImGui::MenuItem("Copy Handle")) CopyToClipboard(FormatHexValue(row.moduleHandle));
                if (!row.path.empty() && ImGui::MenuItem("Add Path To Exclusions")) g_DllExclusions.push_back(row.path);
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.operation.c_str());
            ImGui::TableSetColumnIndex(3);
            if (row.suspiciousLocation || row.reflectiveCandidate) ImGui::TextColored(kUiGold, "%s", row.moduleName.c_str());
            else ImGui::Text("%s", row.moduleName.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", (row.path.empty() ? row.requestedName : row.path).c_str());
            ImGui::TableSetColumnIndex(5); DrawApiNameWithContext(row.loadMethod);
            ImGui::TableSetColumnIndex(6);
            const bool succeeded = row.status == "SUCCESS" || row.status == "OBSERVED" || row.status == "KERNEL OBSERVED";
            ImGui::TextColored(succeeded ? kUiGreen : (row.status == "Detected" ? kUiGold : kUiRed), "%s", row.status.c_str());
            int moduleColumn = 7;
            if (showAnalysis) {
                ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", row.searchAnalysis.c_str());
                moduleColumn = 8;
            }
            ImGui::TableSetColumnIndex(moduleColumn); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawDllActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    DllActivitySnapshot snapshot = BuildDllActivitySnapshot(eventsSnapshot, modules,
        g_ShowEtwFindings ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{});
    std::string filter = g_DllSearchBuf;

    ImGui::BeginChild("DllActivityRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("DLL Activity", "Review module loads, dynamic export resolution, search-order risks, and reflective loading candidates.");

    DrawEmptyAnalysisState(snapshot.events.empty(), "No DLL behavior captured. Module loads and dynamic API resolution will appear here.");
    ImGui::Separator();

    ImGui::SetNextItemWidth(300.0f);
    ImGui::InputText("Search", g_DllSearchBuf, sizeof(g_DllSearchBuf));
    
    ImGui::Separator();

    ImGui::BeginChild("DllActivityWorkspace", ImVec2(0.0f, 0.0f), true);
    if (ImGui::BeginTabBar("DllActivityTabs")) {
        if (BeginFindingTabItem("Events", snapshot.events.size())) {
            DrawDllEventTable("DllEventsTable", snapshot.events, filter);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Observed Objects", snapshot.inventory.size())) {
            if (ImGui::BeginTable("DllInventoryTable", 11, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Target / Object", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Handle", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Method", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Loads", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Exports", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Signature", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("SHA256", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("First Seen", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("State", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < snapshot.inventory.size(); ++i) {
                    const auto& row = snapshot.inventory[i];
                    if (g_HideExcluded && row.excluded) continue;
                    if (!DllInventoryMatchesSearch(row, filter)) continue;
                    ImGui::PushID((int)i);
                    if (row.excluded && g_DimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0); ImGui::Text("%u", row.pid);
                    ImGui::TableSetColumnIndex(1);
                    if (ImGui::Selectable(row.moduleName.c_str(), g_SelectedDllModuleIndex == (int)i, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedDllModuleIndex = (int)i;
                    }
                    if (ImGui::BeginPopupContextItem("DllInventoryContext")) {
                        if (ImGui::MenuItem("Copy Module")) CopyToClipboard(row.moduleName);
                        if (ImGui::MenuItem("Copy Target / Object")) CopyToClipboard(row.path);
                        if (ImGui::MenuItem("Copy Handle")) CopyToClipboard(FormatHexValue(row.moduleHandle));
                        if (ImGui::MenuItem("Add Module To Exclusions")) g_DllExclusions.push_back(row.moduleName);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.path.c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%s", FormatHexValue(row.moduleHandle).c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.loadMethod.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::Text("%d", row.loadCount);
                    ImGui::TableSetColumnIndex(6); ImGui::Text("%d", row.exportResolutionCount);
                    ImGui::TableSetColumnIndex(7); ImGui::TextColored(row.signatureStatus == "Trusted signature" ? kUiGreen : kUiGold, "%s", row.signatureStatus.empty() ? "Unknown" : row.signatureStatus.c_str());
                    ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", row.sha256.empty() ? "-" : row.sha256.c_str());
                    ImGui::TableSetColumnIndex(9); ImGui::Text("%s", row.firstSeen.c_str());
                    ImGui::TableSetColumnIndex(10);
                    if (row.reflectiveCandidate) ImGui::TextColored(kUiGold, "Reflective");
                    else if (row.suspiciousLocation) ImGui::TextColored(kUiGold, "Suspicious");
                    else if (row.unloaded) ImGui::TextColored(kUiTextMuted, "Unloaded");
                    else ImGui::TextColored(kUiGreen, "Loaded");
                    if (row.excluded && g_DimExcluded) ImGui::PopStyleColor();
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Export Resolution", snapshot.exports.size())) {
            if (ImGui::BeginTable("DllExportTable", 8, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Target Module", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Export", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Status", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (const auto& row : snapshot.exports) {
                    if (!filter.empty() && !StringContainsInsensitive(row.moduleName + " " + row.exportName + " " + row.api + " " + row.callerFunction, filter)) continue;
                    ImGui::PushID(row.eventIndex);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(row.time.c_str(), g_SelectedDllEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                        g_SelectedDllEventIndex = row.eventIndex;
                        g_SelectedEventIndex = row.eventIndex;
                        g_SelectedParamIndex = -1;
                    }
                    if (ImGui::BeginPopupContextItem("DllExportContext")) {
                        if (ImGui::MenuItem("Copy Row")) CopyToClipboard(row.moduleName + "!" + row.exportName + " -> " + FormatHexValue(row.resolvedAddress));
                        if (ImGui::MenuItem("Copy Export")) CopyToClipboard(row.exportName);
                        if (ImGui::MenuItem("Copy Address")) CopyToClipboard(FormatHexValue(row.resolvedAddress));
                        if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.moduleName.c_str());
                    ImGui::TableSetColumnIndex(3); DrawApiNameWithContext(row.exportName);
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%s", FormatHexValue(row.resolvedAddress).c_str());
                    ImGui::TableSetColumnIndex(5); DrawApiNameWithContext(row.api);
                    ImGui::TableSetColumnIndex(6); ImGui::TextColored(row.status == "SUCCESS" ? kUiGreen : kUiRed, "%s", row.status.c_str());
                    ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Search Order Analysis", snapshot.searchOrder.size())) {
            DrawDllEventTable("DllSearchOrderTable", snapshot.searchOrder, filter, true);
            ImGui::EndTabItem();
        }

        if (BeginFindingTabItem("Reflective Load Candidates", snapshot.reflectiveCandidates.size())) {
            if (snapshot.reflectiveCandidates.empty()) {
            } else if (ImGui::BeginTable("DllReflectiveTable", 5, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Candidate", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Base Address", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Method", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("First Seen", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Target / Object", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (const auto& row : snapshot.reflectiveCandidates) {
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0); ImGui::TextColored(kUiGold, "%s", row.moduleName.c_str());
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%s", FormatHexValue(row.moduleHandle).c_str());
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.loadMethod.c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%s", row.firstSeen.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.path.c_str());
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }


        ImGui::EndTabBar();
    }
    ImGui::EndChild();
    ImGui::EndChild();
}

static void DrawServiceDriverEventTable(const char* tableId, const std::vector<ServiceDriverEventRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable(tableId, 10, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Category", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Name", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Path / Object", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Details", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Status", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!ServiceDriverEventMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(FormatTimestamp(row.timestamp).c_str(), g_SelectedEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedParamIndex = -1;
            }
            if (ImGui::BeginPopupContextItem("ServiceDriverEventContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(ServiceDriverRowText(row));
                if (ImGui::MenuItem("Copy Name")) CopyToClipboard(row.name);
                if (ImGui::MenuItem("Copy Path / Object")) CopyToClipboard(row.path);
                if (ImGui::MenuItem("Copy Handle")) CopyToClipboard(FormatHexValue(row.handle));
                if (row.ioctlCode && ImGui::MenuItem("Copy IOCTL")) CopyToClipboard(FormatHexValue(row.ioctlCode));
                if (row.eventIndex >= 0 && ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(2);
            ImVec4 color = row.byovdHint ? kUiRed : (row.persistence ? kUiGold : (row.category == "Driver" ? kUiBlue : kUiText));
            ImGui::TextColored(color, "%s", row.category.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::Text("%s", row.operation.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.name.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", row.path.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::TextWrapped("%s", row.details.c_str());
            ImGui::TableSetColumnIndex(7); DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(8);
            ImGui::TextColored(row.status == "SUCCESS" || row.status == "KERNEL OBSERVED" ? kUiGreen : kUiRed, "%s", row.status.c_str());
            ImGui::TableSetColumnIndex(9); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawServiceDriverInventoryTable(const std::vector<ServiceDriverInventoryRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable("ServiceDriverInventoryTable", 11, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Name", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Path", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Last Operation", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Count", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Persistence", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("BYOVD Hint", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Signature", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("SHA256", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Last Seen", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableHeadersRow();
        int id = 0;
        for (const auto& row : rows) {
            if (!ServiceDriverInventoryMatchesSearch(row, filter)) continue;
            ImGui::PushID(id++);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(1);
            if (ImGui::Selectable(row.type.c_str(), false, ImGuiSelectableFlags_SpanAllColumns)) {}
            if (ImGui::BeginPopupContextItem("ServiceDriverInventoryContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(row.type + " | " + row.name + " | " + row.path + " | " + row.lastOperation);
                if (ImGui::MenuItem("Copy Name")) CopyToClipboard(row.name);
                if (ImGui::MenuItem("Copy Path")) CopyToClipboard(row.path);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.name.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.path.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.lastOperation.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::Text("%d", row.count);
            ImGui::TableSetColumnIndex(6); ImGui::TextColored(row.persistence ? kUiGold : kUiTextMuted, "%s", row.persistence ? "Yes" : "-");
            ImGui::TableSetColumnIndex(7);
            if (row.byovdHint) {
                ImGui::TextColored(kUiRed, "Yes");
                if (ImGui::IsItemHovered()) {
                    std::string reason = "BYOVD Risk Flags:\n";
                    if (LooksByovdPath(row.path)) reason += "- Loaded from temporary or untrusted directory.\n";
                    if (!row.signatureStatus.empty() && row.signatureStatus != "Trusted signature") reason += "- Digital signature is untrusted or missing.\n";
                    if (IsKnownVulnerableDriver(row.name)) reason += "- Known vulnerable driver matching database.\n";
                    ImGui::SetTooltip("%s", reason.c_str());
                }
            } else {
                ImGui::TextColored(kUiTextMuted, "-");
            }
            ImGui::TableSetColumnIndex(8); ImGui::TextColored(row.signatureStatus == "Trusted signature" ? kUiGreen : kUiGold, "%s", row.signatureStatus.empty() ? "Unknown" : row.signatureStatus.c_str());
            ImGui::TableSetColumnIndex(9); ImGui::TextWrapped("%s", row.sha256.empty() ? "-" : row.sha256.c_str());
            ImGui::TableSetColumnIndex(10); ImGui::Text("%s", row.lastSeen.c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static float g_IoctlDetailsHeight = 250.0f;

static void DrawIoctlDecoderTable(const std::vector<ServiceDriverEventRow>& rows, const std::string& filter) {
    const ServiceDriverEventRow* selectedRow = nullptr;
    if (g_SelectedEventIndex >= 0) {
        for (const auto& row : rows) {
            if (row.eventIndex == g_SelectedEventIndex) {
                selectedRow = &row;
                break;
            }
        }
    }

    if (selectedRow) {
        float availHeight = ImGui::GetContentRegionAvail().y;
        float minHeightTable = 150.0f;
        float minHeightDetails = 150.0f;
        float splitterThickness = 4.0f;
        float maxDetailsHeight = availHeight - minHeightTable - splitterThickness;
        if (maxDetailsHeight < minHeightDetails) maxDetailsHeight = minHeightDetails;
        if (g_IoctlDetailsHeight > maxDetailsHeight) g_IoctlDetailsHeight = maxDetailsHeight;
        if (g_IoctlDetailsHeight < minHeightDetails) g_IoctlDetailsHeight = minHeightDetails;

        float tableHeight = availHeight - g_IoctlDetailsHeight - splitterThickness;
        if (tableHeight < minHeightTable) tableHeight = minHeightTable;

        ImGui::BeginChild("IoctlTablePanel", ImVec2(0.0f, tableHeight), false);
    }

    if (ImGui::BeginTable("IoctlDecoderTable", 10, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Device", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("IOCTL", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Device Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Access", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Method", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Function", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!ServiceDriverEventMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(FormatTimestamp(row.timestamp).c_str(), g_SelectedEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedParamIndex = -1;
            }
            if (ImGui::BeginPopupContextItem("IoctlContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(ServiceDriverRowText(row));
                if (ImGui::MenuItem("Copy IOCTL")) CopyToClipboard(FormatHexValue(row.ioctlCode));
                if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.path.empty() ? row.name.c_str() : row.path.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::Text("%s", FormatHexValue(row.ioctlCode).c_str());
            ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.ioctlDeviceType.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::Text("%s", row.ioctlAccess.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::Text("%s", row.ioctlMethod.c_str());
            ImGui::TableSetColumnIndex(7); ImGui::Text("%s", row.ioctlFunction.c_str());
            ImGui::TableSetColumnIndex(8); ImGui::TextColored(row.status == "SUCCESS" ? kUiGreen : kUiRed, "%s", row.status.c_str());
            ImGui::TableSetColumnIndex(9); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }

    if (selectedRow) {
        ImGui::EndChild();
        VerticalSplitter("IoctlDetailsSplit", g_IoctlDetailsHeight, 150.0f, ImGui::GetContentRegionAvail().y - 150.0f, true);
        ImGui::BeginChild("IoctlDetailsPanel", ImVec2(0.0f, g_IoctlDetailsHeight), true);
        
        ImGui::TextColored(kUiTextMuted, "IOCTL Decoder Details");
        ImGui::Separator();
        ImGui::Spacing();
        
        ImGui::Text("Device Path: "); ImGui::SameLine();
        ImGui::TextColored(kUiGold, "%s", selectedRow->path.empty() ? "(Unknown)" : selectedRow->path.c_str());
        
        ImGui::Text("Control Code: "); ImGui::SameLine();
        ImGui::TextColored(kUiGold, "%s", FormatHexValue(selectedRow->ioctlCode).c_str());
        
        ImGui::Text("Device Type: "); ImGui::SameLine();
        ImGui::TextColored(kUiBlue, "%s", selectedRow->ioctlDeviceType.c_str());
        
        ImGui::Text("Required Access: "); ImGui::SameLine();
        ImGui::TextColored(kUiBlue, "%s", selectedRow->ioctlAccess.c_str());
        
        ImGui::Text("Transfer Method: "); ImGui::SameLine();
        ImGui::TextColored(kUiBlue, "%s", selectedRow->ioctlMethod.c_str());
        
        ImGui::Text("Function Code: "); ImGui::SameLine();
        ImGui::TextColored(kUiBlue, "%s", selectedRow->ioctlFunction.c_str());

        ImGui::Text("Result: "); ImGui::SameLine();
        ImGui::TextColored(selectedRow->status == "SUCCESS" ? kUiGreen : kUiRed, "%s", selectedRow->status.c_str());
        
        ImGui::Text("Input Buffer Size: "); ImGui::SameLine();
        ImGui::Text("%llu bytes", (unsigned long long)selectedRow->inputSize);
        
        ImGui::Text("Output Buffer Size: "); ImGui::SameLine();
        ImGui::Text("%llu bytes", (unsigned long long)selectedRow->outputSize);
        
        ImGui::Separator();
        ImGui::Spacing();
        
        if (ImGui::BeginTabBar("IoctlPayloadTabs")) {
            if (ImGui::BeginTabItem("Input Payload")) {
                if (selectedRow->inputPayload.empty()) {
                    ImGui::TextColored(kUiTextMuted, "No input payload bytes were captured for this IOCTL.");
                } else {
                    DrawHexDump(selectedRow->inputPayload);
                }
                ImGui::EndTabItem();
            }
            if (ImGui::BeginTabItem("Output Payload")) {
                if (selectedRow->outputPayload.empty()) {
                    ImGui::TextColored(kUiTextMuted, "No output payload bytes were captured for this IOCTL.");
                } else {
                    DrawHexDump(selectedRow->outputPayload);
                }
                ImGui::EndTabItem();
            }
            ImGui::EndTabBar();
        }
        
        ImGui::EndChild();
    }
}

static void DrawServiceDriverActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    ServiceDriverSnapshot snapshot = BuildServiceDriverSnapshot(eventsSnapshot, modules,
        g_ShowEtwFindings ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{});
    std::string filter = g_ServiceDriverSearchBuf;

    ImGui::BeginChild("ServiceDriverRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Service & Driver", "Analyze service persistence, driver loading, device access, IOCTL traffic, and possible BYOVD behavior.");

    DrawEmptyAnalysisState(snapshot.events.empty(), "No service or driver behavior captured. SCM, driver, device, and IOCTL activity will appear here.");

    // ETW Blinding & Telemetry Tampering Warnings (Phase 5)
    bool etwRunning = IsEtwKernelTelemetryRunning();
    bool hasSCMDriverLoads = false;
    for (const auto& ev : snapshot.events) {
        if (ev.category == "Driver" && ev.api != "ETW Image Load") {
            hasSCMDriverLoads = true;
            break;
        }
    }
    bool hasEtwImageLoads = false;
    for (const auto& ev : snapshot.events) {
        if (ev.api == "ETW Image Load") {
            hasEtwImageLoads = true;
            break;
        }
    }
    bool potentialBlinding = etwRunning && hasSCMDriverLoads && !hasEtwImageLoads;

    if (!etwRunning) {
        ImGui::Spacing();
        ImGui::PushStyleColor(ImGuiCol_Text, kUiRed);
        ImGui::Text("WARNING: ETW Kernel Telemetry is not running. Driver image loads outside user-mode SCM hooks will NOT be captured.");
        ImGui::PopStyleColor();
    } else if (potentialBlinding) {
        ImGui::Spacing();
        ImGui::PushStyleColor(ImGuiCol_Text, kUiGold);
        ImGui::Text("WARNING: SCM driver load events detected but zero kernel ETW image load events were observed. The target process might have blinded or tampered with ETW telemetry.");
        ImGui::PopStyleColor();
    }

    ImGui::SetNextItemWidth(520.0f);
    ImGui::InputTextWithHint("##ServiceDriverSearch", "Filter service, driver, or IOCTL activity...", g_ServiceDriverSearchBuf, IM_ARRAYSIZE(g_ServiceDriverSearchBuf));
    ImGui::Separator();

    ImGui::BeginChild("ServiceDriverActivityWorkspace", ImVec2(0.0f, 0.0f), true);
    if (ImGui::BeginTabBar("ServiceDriverTabs")) {
        if (BeginFindingTabItem("Timeline", snapshot.events.size())) { DrawServiceDriverEventTable("ServiceDriverEventsTable", snapshot.events, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Service Events", snapshot.serviceEvents.size())) { DrawServiceDriverEventTable("ServiceEventsTable", snapshot.serviceEvents, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Driver Events", snapshot.driverEvents.size())) { DrawServiceDriverEventTable("DriverEventsTable", snapshot.driverEvents, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Observed Objects", snapshot.inventory.size())) { DrawServiceDriverInventoryTable(snapshot.inventory, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Persistence View", snapshot.persistence.size())) { DrawServiceDriverEventTable("ServicePersistenceTable", snapshot.persistence, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("BYOVD Visibility", snapshot.byovd.size())) { DrawServiceDriverEventTable("ByovdTable", snapshot.byovd, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Device Handles", snapshot.deviceHandles.size())) { DrawServiceDriverEventTable("DeviceHandlesTable", snapshot.deviceHandles, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("IOCTL Decoder", snapshot.ioctlEvents.size())) { DrawIoctlDecoderTable(snapshot.ioctlEvents, filter); ImGui::EndTabItem(); }
        ImGui::EndTabBar();
    }

    ImGui::EndChild();
    ImGui::EndChild();
}

enum class InjectionEventTableView {
    Timeline,
    RemoteMemory,
    RemoteExecution,
    SectionMapping
};

static void DrawProcessInjectionEventTable(
    const char* tableId,
    const std::vector<InjectionEventRow>& rows,
    const std::string& filter,
    InjectionEventTableView view
) {
    const int columns = view == InjectionEventTableView::Timeline ? 8 :
        (view == InjectionEventTableView::SectionMapping ? 10 : 9);
    if (ImGui::BeginTable(tableId, columns, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders |
        ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Target", ImGuiTableColumnFlags_WidthStretch);
        if (view == InjectionEventTableView::Timeline) {
            ImGui::TableSetupColumn("Technique", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 190.0f);
            ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Evidence", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        } else if (view == InjectionEventTableView::RemoteMemory) {
            ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 190.0f);
            ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Base", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Protection", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        } else if (view == InjectionEventTableView::RemoteExecution) {
            ImGui::TableSetupColumn("Thread ID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Technique", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 190.0f);
            ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Start / IP", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        } else {
            ImGui::TableSetupColumn("Operation", ImGuiTableColumnFlags_WidthFixed, 190.0f);
            ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Section", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Base", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Size", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Protection", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthFixed, 0.0f);
            ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        }
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!InjectionEventMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(FormatTimestamp(row.timestamp).c_str(), g_SelectedEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedParamIndex = -1;
            }
            if (ImGui::BeginPopupContextItem("InjectionEventContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(InjectionEventRowText(row));
                if (ImGui::MenuItem("Copy Target")) CopyToClipboard(row.targetProcess);
                if (row.baseAddress && ImGui::MenuItem("Copy Base Address")) CopyToClipboard(FormatHexValue(row.baseAddress));
                if (row.startAddress && ImGui::MenuItem("Copy Start Address")) CopyToClipboard(FormatHexValue(row.startAddress));
                if (!row.payload.empty() && ImGui::MenuItem("Copy Payload Hex")) CopyToClipboard(HexRangeToHexOnly(row.payload, 0, row.payload.size()));
                if (!row.payload.empty() && ImGui::MenuItem("Copy Payload ASCII")) CopyToClipboard(HexRangeToAsciiOnly(row.payload, 0, row.payload.size()));
                if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.targetProcess.c_str());
            const ImVec4 techColor = row.technique.find("Remote Thread") != std::string::npos ? kUiRed :
                (row.technique.find("APC") != std::string::npos ? kUiGold :
                (row.technique.find("Hollowing") != std::string::npos ? kUiRed :
                (row.technique.find("Hijacking") != std::string::npos ? kUiGold :
                (row.technique.find("Section") != std::string::npos ? kUiBlue :
                (row.technique.find("Bypass") != std::string::npos ? kUiRed : kUiText)))));
            const std::string base = row.baseAddress ? FormatHexValue(row.baseAddress) : "-";
            const std::string start = row.startAddress ? FormatHexValue(row.startAddress) : "-";
            const ImVec4 resultColor = row.status == "SUCCESS" ? kUiGreen : kUiRed;
            if (view == InjectionEventTableView::Timeline) {
                ImGui::TableSetColumnIndex(2); ImGui::TextColored(techColor, "%s", row.technique.c_str());
                ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.operation.c_str());
                ImGui::TableSetColumnIndex(4); DrawApiNameWithContext(row.api);
                ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", row.details.empty() ? "-" : row.details.c_str());
                ImGui::TableSetColumnIndex(6); ImGui::TextColored(resultColor, "%s", row.status.c_str());
                ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            } else if (view == InjectionEventTableView::RemoteMemory) {
                ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.operation.c_str());
                ImGui::TableSetColumnIndex(3); DrawApiNameWithContext(row.api);
                ImGui::TableSetColumnIndex(4); ImGui::Text("%s", base.c_str());
                ImGui::TableSetColumnIndex(5); ImGui::Text("%llu", (unsigned long long)row.size);
                ImGui::TableSetColumnIndex(6); ImGui::TextWrapped("%s", row.protection.empty() ? "-" : row.protection.c_str());
                ImGui::TableSetColumnIndex(7); ImGui::TextColored(resultColor, "%s", row.status.c_str());
                ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            } else if (view == InjectionEventTableView::RemoteExecution) {
                ImGui::TableSetColumnIndex(2); ImGui::Text("%s", row.targetTid ? std::to_string(row.targetTid).c_str() : "-");
                ImGui::TableSetColumnIndex(3); ImGui::TextColored(techColor, "%s", row.technique.c_str());
                ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.operation.c_str());
                ImGui::TableSetColumnIndex(5); DrawApiNameWithContext(row.api);
                ImGui::TableSetColumnIndex(6); ImGui::Text("%s", start.c_str());
                ImGui::TableSetColumnIndex(7); ImGui::TextColored(resultColor, "%s", row.status.c_str());
                ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            } else {
                ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.operation.c_str());
                ImGui::TableSetColumnIndex(3); DrawApiNameWithContext(row.api);
                ImGui::TableSetColumnIndex(4); ImGui::Text("%s", row.targetHandle ? FormatHexValue(row.targetHandle).c_str() : "-");
                ImGui::TableSetColumnIndex(5); ImGui::Text("%s", base.c_str());
                ImGui::TableSetColumnIndex(6); ImGui::Text("%llu", (unsigned long long)row.size);
                ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", row.protection.empty() ? "-" : row.protection.c_str());
                ImGui::TableSetColumnIndex(8); ImGui::TextColored(resultColor, "%s", row.status.c_str());
                ImGui::TableSetColumnIndex(9); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            }
            ImGui::PopID();
        }
        ImGui::EndTable();
    }

}

static void DrawInjectionChainTable(const std::vector<InjectionChainRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable("InjectionChainTable", 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
        ImGui::TableSetupColumn("Target", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Technique", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Steps", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Base", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Allocated", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Written", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Exec", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Last Seen", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!InjectionChainMatchesSearch(row, filter)) continue;
            ImGui::PushID((int)row.targetPid);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(row.targetProcess.c_str(), g_SelectedEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedParamIndex = -1;
            }
            if (ImGui::BeginPopupContextItem("InjectionChainContext")) {
                std::string text = row.targetProcess + " | " + row.technique + " | " + row.steps +
                    " | Base=" + FormatHexValue(row.baseAddress) + " | Exec=" + FormatHexValue(row.executionAddress);
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(text);
                if (row.baseAddress && ImGui::MenuItem("Copy Base Address")) CopyToClipboard(FormatHexValue(row.baseAddress));
                if (row.executionAddress && ImGui::MenuItem("Copy Execution Address")) CopyToClipboard(FormatHexValue(row.executionAddress));
                if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::TextColored(row.technique.find("Thread") != std::string::npos ? kUiRed : kUiGold, "%s", row.technique.c_str());
            ImGui::TableSetColumnIndex(2); ImGui::TextWrapped("%s", row.steps.c_str());
            std::string baseAddressText = row.baseAddress ? FormatHexValue(row.baseAddress) : "-";
            std::string executionAddressText = row.executionAddress ? FormatHexValue(row.executionAddress) : "-";
            ImGui::TableSetColumnIndex(3); ImGui::Text("%s", baseAddressText.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::Text("%llu", (unsigned long long)row.allocatedBytes);
            ImGui::TableSetColumnIndex(5); ImGui::Text("%llu", (unsigned long long)row.writtenBytes);
            ImGui::TableSetColumnIndex(6); ImGui::Text("%s", executionAddressText.c_str());
            ImGui::TableSetColumnIndex(7); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            ImGui::TableSetColumnIndex(8); ImGui::Text("%s", row.lastSeen.c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawInjectionPayloadTable(const std::vector<InjectionEventRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable("InjectionPayloadTable", 7, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable | ImGuiTableFlags_SizingFixedFit)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Target", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Base", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Bytes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Hex Preview", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("ASCII Preview", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!InjectionEventMatchesSearch(row, filter)) continue;
            size_t previewSize = std::min<size_t>(row.payload.size(), 64);
            ImGui::PushID(row.eventIndex);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(FormatTimestamp(row.timestamp).c_str(), g_SelectedEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedParamIndex = -1;
            }
            if (ImGui::BeginPopupContextItem("InjectionPayloadContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(InjectionEventRowText(row));
                if (ImGui::MenuItem("Copy Payload Hex")) CopyToClipboard(HexRangeToHexOnly(row.payload, 0, row.payload.size()));
                if (ImGui::MenuItem("Copy Payload ASCII")) CopyToClipboard(HexRangeToAsciiOnly(row.payload, 0, row.payload.size()));
                if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%s", row.targetProcess.c_str());
            ImGui::TableSetColumnIndex(2); DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(3); ImGui::Text("%s", FormatHexValue(row.baseAddress).c_str());
            ImGui::TableSetColumnIndex(4); ImGui::Text("%llu", (unsigned long long)row.payload.size());
            ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", HexRangeToHexOnly(row.payload, 0, previewSize).c_str());
            ImGui::TableSetColumnIndex(6); ImGui::TextWrapped("%s", HexRangeToAsciiOnly(row.payload, 0, previewSize).c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawProcessInjectionActivityView() {
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        eventsSnapshot = g_Events;
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    ProcessInjectionSnapshot snapshot = BuildProcessInjectionSnapshot(eventsSnapshot, modules,
        g_ShowEtwFindings ? SnapshotEtwKernelEvents() : std::vector<EtwKernelEvent>{});
    std::string filter = g_ProcessInjectionSearchBuf;

    ImGui::BeginChild("ProcessInjectionRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Process Injection Activity", "Connect remote memory operations with threads, APCs, section mapping, hijacking, and hollowing indicators.");

    DrawEmptyAnalysisState(snapshot.events.empty(), "No process-injection behavior captured. Remote memory and execution chains will appear here.");

    ImGui::SetNextItemWidth(560.0f);
    ImGui::InputTextWithHint("##ProcessInjectionSearch", "Filter injection events, targets, APIs, addresses, or callers...", g_ProcessInjectionSearchBuf, IM_ARRAYSIZE(g_ProcessInjectionSearchBuf));
    ImGui::Separator();

    ImGui::BeginChild("ProcessInjectionWorkspace", ImVec2(0.0f, 0.0f), true);
    if (ImGui::BeginTabBar("ProcessInjectionTabs")) {
        if (BeginFindingTabItem("Injection Timeline", snapshot.events.size())) { DrawProcessInjectionEventTable("ProcessInjectionEventsTable", snapshot.events, filter, InjectionEventTableView::Timeline); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Injection Chains", snapshot.chains.size())) { DrawInjectionChainTable(snapshot.chains, filter); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Remote Memory Operations", snapshot.remoteMemory.size())) { DrawProcessInjectionEventTable("InjectionRemoteMemoryTable", snapshot.remoteMemory, filter, InjectionEventTableView::RemoteMemory); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Remote Thread Activity", snapshot.remoteThreads.size())) { DrawProcessInjectionEventTable("InjectionRemoteThreadTable", snapshot.remoteThreads, filter, InjectionEventTableView::RemoteExecution); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("APC Activity", snapshot.apcEvents.size())) { DrawProcessInjectionEventTable("InjectionApcTable", snapshot.apcEvents, filter, InjectionEventTableView::RemoteExecution); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Thread Hijacking", snapshot.threadHijacking.size())) { DrawProcessInjectionEventTable("InjectionThreadHijackTable", snapshot.threadHijacking, filter, InjectionEventTableView::RemoteExecution); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Section Mapping", snapshot.sectionMapping.size())) { DrawProcessInjectionEventTable("InjectionSectionMapTable", snapshot.sectionMapping, filter, InjectionEventTableView::SectionMapping); ImGui::EndTabItem(); }
        if (BeginFindingTabItem("Payloads", snapshot.payloads.size())) { DrawInjectionPayloadTable(snapshot.payloads, filter); ImGui::EndTabItem(); }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();

    ImGui::EndChild();
}

static float g_AntiAnalysisDetailsWidth = 450.0f;

static void DrawAntiAnalysisEventTable(const char* tableId, const std::vector<AntiAnalysisRow>& rows, const std::string& filter) {
    const AntiAnalysisRow* selectedRow = nullptr;
    if (g_SelectedEventIndex >= 0) {
        for (const auto& row : rows) {
            if (row.eventIndex == g_SelectedEventIndex) {
                selectedRow = &row;
                break;
            }
        }
    }

    if (selectedRow) {
        float availWidth = ImGui::GetContentRegionAvail().x;
        float minWidthTable = 300.0f;
        float minWidthDetails = 250.0f;
        float splitterThickness = 4.0f;
        float maxDetailsWidth = availWidth - minWidthTable - splitterThickness;
        if (maxDetailsWidth < minWidthDetails) maxDetailsWidth = minWidthDetails;
        if (g_AntiAnalysisDetailsWidth > maxDetailsWidth) g_AntiAnalysisDetailsWidth = maxDetailsWidth;
        if (g_AntiAnalysisDetailsWidth < minWidthDetails) g_AntiAnalysisDetailsWidth = minWidthDetails;

        float tableWidth = availWidth - g_AntiAnalysisDetailsWidth - splitterThickness;
        if (tableWidth < minWidthTable) tableWidth = minWidthTable;

        ImGui::BeginChild((std::string(tableId) + "_Panel").c_str(), ImVec2(tableWidth, 0.0f), false);
    }

    if (ImGui::BeginTable(tableId, 9, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Family", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Technique", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Check", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Artifact", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("Result", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableSetupColumn("API", ImGuiTableColumnFlags_WidthFixed, 0.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!AntiAnalysisRowMatchesSearch(row, filter)) continue;
            ImGui::PushID(row.eventIndex);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            if (ImGui::Selectable(FormatTimestamp(row.timestamp).c_str(), g_SelectedEventIndex == row.eventIndex, ImGuiSelectableFlags_SpanAllColumns)) {
                g_SelectedEventIndex = row.eventIndex;
                g_SelectedParamIndex = -1;
            }
            if (ImGui::BeginPopupContextItem("AntiAnalysisEventContext")) {
                if (ImGui::MenuItem("Copy Row")) CopyToClipboard(AntiAnalysisRowText(row));
                if (ImGui::MenuItem("Copy Artifact")) CopyToClipboard(row.artifact);
                if (ImGui::MenuItem("Copy Result")) CopyToClipboard(row.result);
                if (ImGui::MenuItem("View in API Monitor")) FocusApiMonitorEvent(row.eventIndex, row.callerAddress);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%u", row.pid);
            ImGui::TableSetColumnIndex(2);
            ImVec4 familyColor = row.family == "Debugger Detection" ? kUiRed :
                (row.family == "VM Detection" ? kUiGold :
                (row.family == "Sandbox Detection" ? kUiGold :
                (row.family == "Analyst Tool Detection" ? kUiRed :
                (row.family == "Timing Check" ? kUiBlue : kUiText))));
            ImGui::TextColored(familyColor, "%s", row.family.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.technique.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.check.c_str());
            ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", row.artifact.c_str());
            ImGui::TableSetColumnIndex(6); ImGui::TextWrapped("%s", row.result.c_str());
            ImGui::TableSetColumnIndex(7); DrawApiNameWithContext(row.api);
            ImGui::TableSetColumnIndex(8); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            ImGui::PopID();
        }
        ImGui::EndTable();
    }

    if (selectedRow) {
        ImGui::EndChild();
        ImGui::SameLine();
        HorizontalSplitter((std::string(tableId) + "_Split").c_str(), g_AntiAnalysisDetailsWidth, 250.0f, ImGui::GetContentRegionAvail().x - 300.0f);
        ImGui::SameLine();
        ImGui::BeginChild((std::string(tableId) + "_Details").c_str(), ImVec2(g_AntiAnalysisDetailsWidth, 0.0f), true);

        ImGui::TextColored(kUiTextMuted, "Anti-Analysis Check Details");
        ImGui::Separator();
        ImGui::Spacing();

        if (selectedRow->technique == "Firmware Fingerprinting") {
            ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.2f, 0.12f, 0.02f, 1.0f));
            ImGui::PushStyleColor(ImGuiCol_Border, kUiGold);
            ImGui::BeginChild("AlertFirmware", ImVec2(0.0f, 90.0f), true);
            ImGui::TextColored(kUiGold, "WARNING: Firmware Query Detected");
            ImGui::TextWrapped("The application queried BIOS or ACPI tables using EnumSystemFirmwareTables or GetSystemFirmwareTable. This is a classic virtualization evasion technique used by malware to detect VMs.");
            ImGui::EndChild();
            ImGui::PopStyleColor(2);
            ImGui::Spacing();
        } else if (selectedRow->technique == "VEH Exception Handler Registration") {
            ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.25f, 0.05f, 0.05f, 1.0f));
            ImGui::PushStyleColor(ImGuiCol_Border, kUiRed);
            ImGui::BeginChild("AlertVeh", ImVec2(0.0f, 90.0f), true);
            ImGui::TextColored(kUiRed, "ALERT: Vectored Exception Handler Registered");
            ImGui::TextWrapped("Registering custom VEH exception handlers allows the program to intercept single steps, breakpoints, or hardware faults. This is frequently used to evade debuggers or custom monitoring tools.");
            ImGui::EndChild();
            ImGui::PopStyleColor(2);
            ImGui::Spacing();
        } else if (selectedRow->technique == "WMI Firmware Fingerprinting") {
            ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.2f, 0.12f, 0.02f, 1.0f));
            ImGui::PushStyleColor(ImGuiCol_Border, kUiGold);
            ImGui::BeginChild("AlertWmiFp", ImVec2(0.0f, 90.0f), true);
            ImGui::TextColored(kUiGold, "WARNING: WMI Firmware Profiling Detected");
            ImGui::TextWrapped("The application executed queries targeting Win32_BIOS, Win32_ComputerSystem, Win32_BaseBoard, or Win32_MotherboardDevice, which is frequently used to query motherboard serial numbers to evade virtualization.");
            ImGui::EndChild();
            ImGui::PopStyleColor(2);
            ImGui::Spacing();
        } else if (selectedRow->technique == "High-Precision Timing Probe") {
            ImGui::PushStyleColor(ImGuiCol_ChildBg, ImVec4(0.05f, 0.15f, 0.25f, 1.0f));
            ImGui::PushStyleColor(ImGuiCol_Border, kUiBlue);
            ImGui::BeginChild("AlertTiming", ImVec2(0.0f, 90.0f), true);
            ImGui::TextColored(kUiBlue, "NOTE: High-Precision Timing Probe");
            ImGui::TextWrapped("The application invoked high-precision system time APIs. Sub-millisecond timing delta probes are often used to identify CPU virtualization latency or timing loops.");
            ImGui::EndChild();
            ImGui::PopStyleColor(2);
            ImGui::Spacing();
        }

        ImGui::Text("Family: "); ImGui::SameLine();
        ImVec4 familyColor = selectedRow->family == "Debugger Detection" ? kUiRed :
            (selectedRow->family == "VM Detection" ? kUiGold :
            (selectedRow->family == "Sandbox Detection" ? kUiGold :
            (selectedRow->family == "Analyst Tool Detection" ? kUiRed :
            (selectedRow->family == "Timing Check" ? kUiBlue : kUiText))));
        ImGui::TextColored(familyColor, "%s", selectedRow->family.c_str());

        ImGui::Text("Technique: "); ImGui::SameLine();
        ImGui::TextColored(kUiGold, "%s", selectedRow->technique.c_str());

        ImGui::Text("API Called: "); ImGui::SameLine();
        ImGui::TextColored(kUiBlue, "%s", selectedRow->api.c_str());

        ImGui::Text("Check detail: "); ImGui::SameLine();
        ImGui::TextColored(kUiText, "%s", selectedRow->check.c_str());

        ImGui::Text("Result: "); ImGui::SameLine();
        ImGui::TextColored(kUiGreen, "%s", selectedRow->result.c_str());

        ImGui::Text("Target Artifact: "); ImGui::SameLine();
        ImGui::TextColored(kUiGold, "%s", selectedRow->artifact.c_str());

        ImGui::Text("Status: "); ImGui::SameLine();
        ImGui::TextColored(selectedRow->status == "SUCCESS" || selectedRow->status == "OBSERVED" ? kUiGreen : kUiRed, "%s", selectedRow->status.c_str());

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        ImGui::TextWrapped("Caller Function:\n%s", selectedRow->callerFunction.c_str());

        ImGui::EndChild();
    }
}

