static void CapturePowerShellSecurityContext(DWORD pid) {
    g_PowerShellCurrentUser = "-";
    g_PowerShellIntegrityLevel = "-";
    HANDLE process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    HANDLE token = nullptr;
    if (!process || !OpenProcessToken(process, TOKEN_QUERY, &token)) {
        if (process) CloseHandle(process);
        return;
    }
    DWORD bytes = 0;
    GetTokenInformation(token, TokenUser, nullptr, 0, &bytes);
    std::vector<BYTE> userBuffer(bytes);
    if (bytes && GetTokenInformation(token, TokenUser, userBuffer.data(), bytes, &bytes)) {
        auto user = reinterpret_cast<TOKEN_USER*>(userBuffer.data());
        wchar_t account[256] = {}, domain[256] = {};
        DWORD accountChars = _countof(account), domainChars = _countof(domain);
        SID_NAME_USE use{};
        if (LookupAccountSidW(nullptr, user->User.Sid, account, &accountChars, domain, &domainChars, &use)) {
            g_PowerShellCurrentUser = WStringToString(std::wstring(domain) + L"\\" + account);
        }
    }
    bytes = 0;
    GetTokenInformation(token, TokenIntegrityLevel, nullptr, 0, &bytes);
    std::vector<BYTE> integrityBuffer(bytes);
    if (bytes && GetTokenInformation(token, TokenIntegrityLevel, integrityBuffer.data(), bytes, &bytes)) {
        auto label = reinterpret_cast<TOKEN_MANDATORY_LABEL*>(integrityBuffer.data());
        DWORD rid = *GetSidSubAuthority(label->Label.Sid, *GetSidSubAuthorityCount(label->Label.Sid) - 1);
        if (rid >= SECURITY_MANDATORY_SYSTEM_RID) g_PowerShellIntegrityLevel = "System";
        else if (rid >= SECURITY_MANDATORY_HIGH_RID) g_PowerShellIntegrityLevel = "High";
        else if (rid >= SECURITY_MANDATORY_MEDIUM_RID) g_PowerShellIntegrityLevel = "Medium";
        else g_PowerShellIntegrityLevel = "Low";
    }
    CloseHandle(token);
    CloseHandle(process);
}

static std::string ReadPowerShellScriptText(const std::wstring& path) {
    std::ifstream input(std::filesystem::path(path), std::ios::binary);
    if (!input) return {};
    std::string bytes((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
    if (bytes.size() >= 2 && (unsigned char)bytes[0] == 0xFF && (unsigned char)bytes[1] == 0xFE) {
        std::wstring wide;
        for (size_t i = 2; i + 1 < bytes.size(); i += 2)
            wide.push_back((wchar_t)((unsigned char)bytes[i] | ((unsigned char)bytes[i + 1] << 8)));
        return WStringToString(wide);
    }
    if (bytes.size() >= 3 && (unsigned char)bytes[0] == 0xEF && (unsigned char)bytes[1] == 0xBB && (unsigned char)bytes[2] == 0xBF)
        bytes.erase(0, 3);
    return bytes;
}

static bool IsBatchProfile(const TargetProfile& profile) {
    return profile.executionMode == L"Launcher-based (Command Processor)";
}

static bool IsPowerShellProfile(const TargetProfile& profile) {
    return profile.executionMode == L"PowerShell Script Analysis";
}

static bool IsScriptHostProfile(const TargetProfile& profile) {
    return IsBatchProfile(profile) || IsPowerShellProfile(profile) ||
        profile.executionMode == L"Launcher-based (Windows Script Host)" ||
        profile.executionMode == L"Launcher-based (MSHTA)";
}

static std::string TrimBatchLine(std::string value) {
    const size_t first = value.find_first_not_of(" \t");
    if (first == std::string::npos) return {};
    const size_t last = value.find_last_not_of(" \t\r\n");
    return value.substr(first, last - first + 1);
}

static void ScanBatchCommands(const TargetProfile& profile) {
    SpecializedActivityStore::Instance().ResetBatch();
    const std::string script = ReadPowerShellScriptText(profile.originalPath);
    std::istringstream input(script);
    std::string physicalLine;
    std::string logicalLine;
    size_t logicalStart = 0;
    size_t lineNumber = 0;
    while (std::getline(input, physicalLine) && lineNumber < 100000) {
        ++lineNumber;
        if (!physicalLine.empty() && physicalLine.back() == '\r') physicalLine.pop_back();
        if (logicalLine.empty()) logicalStart = lineNumber;
        std::string part = physicalLine;
        size_t trailingCarets = 0;
        for (size_t i = part.size(); i > 0 && part[i - 1] == '^'; --i) ++trailingCarets;
        const bool continued = (trailingCarets % 2) != 0;
        if (continued) part.pop_back();
        if (!logicalLine.empty()) logicalLine.push_back(' ');
        logicalLine += part;
        if (continued) continue;

        const std::string command = TrimBatchLine(logicalLine);
        logicalLine.clear();
        if (command.empty()) continue;
        std::string classify = command;
        if (!classify.empty() && classify[0] == '@') classify = TrimBatchLine(classify.substr(1));
        const std::string lower = ToLowerCopy(classify);
        const bool comment = lower.rfind("rem ", 0) == 0 || lower == "rem" || lower.rfind("::", 0) == 0;
        SpecializedActivityStore::Instance().AddBatch({0, 0, "Line " + std::to_string(logicalStart), command,
            comment ? "Source comment" : "Source command (execution not confirmed)"});
    }
    if (!logicalLine.empty()) {
        const std::string command = TrimBatchLine(logicalLine);
        if (!command.empty()) SpecializedActivityStore::Instance().AddBatch(
            {0, 0, "Line " + std::to_string(logicalStart), command, "Incomplete continued source command"});
    }
    AddLog("[info] parsed " + std::to_string(SpecializedActivityStore::Instance().BatchSnapshot().size()) +
        " BAT/CMD source statements for command history.");
}

static void ScanGenericScriptLines(const TargetProfile& profile) {
    SpecializedActivityStore::Instance().ResetBatch();
    const std::string script = ReadPowerShellScriptText(profile.originalPath);
    std::istringstream input(script);
    std::string line;
    size_t lineNumber = 0;
    while (std::getline(input, line) && lineNumber < 100000) {
        ++lineNumber;
        if (!line.empty() && line.back() == '\r') line.pop_back();
        const std::string statement = TrimBatchLine(line);
        if (statement.empty()) continue;
        SpecializedActivityStore::Instance().AddBatch({0, 0, "Line " + std::to_string(lineNumber), statement,
            "Source statement (execution not confirmed)"});
    }
}

static std::string EscapePowerShellSingleQuoted(const std::wstring& value) {
    std::string utf8 = WStringToString(value);
    std::string escaped;
    escaped.reserve(utf8.size() + 8);
    for (char ch : utf8) { escaped.push_back(ch); if (ch == '\'') escaped.push_back('\''); }
    return escaped;
}

static bool WriteRuntimeTextFile(const std::filesystem::path& path, const std::string& content) {
    std::ofstream output(path, std::ios::binary | std::ios::trunc);
    if (!output) return false;
    output.write(content.data(), static_cast<std::streamsize>(content.size()));
    return output.good();
}

static std::filesystem::path ScriptTracePath(const std::filesystem::path& original, const wchar_t* extension) {
    const std::wstring suffix = L".inspecthor_" + std::to_wstring(GetCurrentProcessId()) + L"_" +
        std::to_wstring(GetTickCount64()) + extension;
    std::filesystem::path adjacent = original.parent_path() / (original.stem().wstring() + suffix);
    std::ofstream probe(adjacent, std::ios::binary | std::ios::trunc);
    if (probe) { probe.close(); std::error_code ignored; std::filesystem::remove(adjacent, ignored); return adjacent; }
    std::error_code error;
    std::filesystem::path fallback = std::filesystem::temp_directory_path(error) / L"Inspecthor";
    std::filesystem::create_directories(fallback, error);
    return fallback / (original.stem().wstring() + suffix);
}

static bool CreateInstrumentedBatchCopy(const TargetProfile& profile, std::wstring& tracedPath, std::string& error) {
    const std::string script = ReadPowerShellScriptText(profile.originalPath);
    if (script.empty()) { error = "BAT/CMD source could not be read for line tracing"; return false; }
    const std::filesystem::path outputPath = ScriptTracePath(profile.originalPath, L".cmd");
    std::istringstream input(script);
    std::ostringstream output;
    std::string line;
    size_t lineNumber = 0;
    bool continuation = false;
    while (std::getline(input, line)) {
        ++lineNumber;
        if (!line.empty() && line.back() == '\r') line.pop_back();
        const std::string trimmed = TrimBatchLine(line);
        std::string classify = trimmed;
        if (!classify.empty() && classify[0] == '@') classify = TrimBatchLine(classify.substr(1));
        const std::string lower = ToLowerCopy(classify);
        const bool structural = classify.empty() || classify[0] == ':' || lower.rfind("rem ", 0) == 0 || lower == "rem" ||
            classify == "(" || classify == ")" || lower.rfind(") else", 0) == 0 || lower == "else" || lower == "else (";
        if (!continuation && !structural) output << "@echo __INSPECTHOR_BATCH_LINE__:" << lineNumber << " 1>&2\r\n";
        output << line << "\r\n";
        size_t carets = 0;
        for (size_t i = line.size(); i > 0 && line[i - 1] == '^'; --i) ++carets;
        continuation = (carets % 2) != 0;
    }
    if (!WriteRuntimeTextFile(outputPath, output.str())) { error = "instrumented BAT/CMD copy could not be written"; return false; }
    tracedPath = outputPath.wstring();
    return true;
}

static bool CreatePowerShellTraceWrapper(const TargetProfile& profile, const std::wstring& userArguments,
    std::wstring& wrapperPath, std::string& error) {
    const std::filesystem::path outputPath = ScriptTracePath(profile.originalPath, L".ps1");
    std::ostringstream wrapper;
    wrapper << "$ErrorActionPreference='Continue'\r\nSet-PSDebug -Trace 1\r\ntry { & '"
            << EscapePowerShellSingleQuoted(profile.originalPath) << "'";
    if (!userArguments.empty()) wrapper << " " << WStringToString(userArguments);
    wrapper << "; $inspecthorExit=$LASTEXITCODE } finally { Set-PSDebug -Off }\r\n"
            << "if ($null -ne $inspecthorExit) { exit $inspecthorExit }\r\n";
    if (!WriteRuntimeTextFile(outputPath, wrapper.str())) { error = "PowerShell trace wrapper could not be written"; return false; }
    wrapperPath = outputPath.wstring();
    return true;
}

static void SetActiveScriptTrace(const std::wstring& path) {
    std::lock_guard<std::mutex> lock(g_ActiveScriptTraceMutex);
    g_ActiveScriptTracePath = path;
}

static void DeleteActiveScriptTrace() {
    std::wstring path;
    { std::lock_guard<std::mutex> lock(g_ActiveScriptTraceMutex); path.swap(g_ActiveScriptTracePath); }
    if (path.empty()) return;
    std::error_code error;
    std::filesystem::remove(path, error);
}

static bool HandleScriptTraceOutputLine(const std::string& line) {
    constexpr const char* batchMarker = "__INSPECTHOR_BATCH_LINE__:";
    const size_t marker = line.find(batchMarker);
    if (marker != std::string::npos) {
        size_t begin = marker + std::strlen(batchMarker), end = begin;
        while (end < line.size() && std::isdigit(static_cast<unsigned char>(line[end]))) ++end;
        if (end > begin) SpecializedActivityStore::Instance().MarkBatchExecuted(
            "Line " + line.substr(begin, end - begin), CurrentUnixTimeMilliseconds());
        return true;
    }
    if (g_PowerShellAnalysisActive.load()) {
        const size_t debug = line.find("DEBUG:");
        if (debug != std::string::npos) {
            size_t begin = debug + 6;
            while (begin < line.size() && std::isspace(static_cast<unsigned char>(line[begin]))) ++begin;
            size_t end = begin;
            while (end < line.size() && std::isdigit(static_cast<unsigned char>(line[end]))) ++end;
            if (end > begin && end < line.size() && line[end] == '+') {
                SpecializedActivityStore::Instance().MarkBatchExecuted(
                    "Line " + line.substr(begin, end - begin), CurrentUnixTimeMilliseconds());
            }
            AddConsoleOutput("[powershell-trace] " + line);
            return true;
        }
    }
    return false;
}

static void ScanPowerShellBehaviors(const TargetProfile& profile) {
    const std::string script = ReadPowerShellScriptText(profile.originalPath);
    const std::string lower = ToLowerCopy(script + "\n" + WStringToString(profile.launcherArguments));
    static const std::pair<const char*, const char*> patterns[] = {
        {"start-process", "Start-Process"}, {"invoke-expression", "Invoke-Expression"}, {"iex ", "Invoke-Expression alias"},
        {"invoke-webrequest", "Invoke-WebRequest"}, {"invoke-restmethod", "Invoke-RestMethod"},
        {"downloadstring", "DownloadString"}, {"downloadfile", "DownloadFile"},
        {"[reflection.assembly]::load", "Reflection loading"}, {"[system.reflection.assembly]::load", "Reflection loading"},
        {"add-type", "Add-Type"}, {"-comobject", "COM object creation"},
        {"get-wmiobject", "WMI usage"}, {"invoke-wmimethod", "WMI usage"}, {"get-ciminstance", "WMI/CIM usage"},
        {"new-pssession", "WinRM / remote session"}, {"invoke-command", "WinRM / remote command"}, {"wsman:", "WinRM"},
        {"register-scheduledtask", "Scheduled task creation"}, {"new-scheduledtask", "Scheduled task creation"},
        {"set-itemproperty", "Registry persistence or modification"}, {"new-itemproperty", "Registry persistence or modification"},
        {"amsi", "AMSI interaction"}, {"-encodedcommand", "EncodedCommand usage"}, {" -enc ", "EncodedCommand usage"},
        {"-noprofile", "NoProfile usage"}, {"-executionpolicy bypass", "ExecutionPolicy Bypass usage"}
    };
    std::unordered_set<std::string> seen;
    for (const auto& pattern : patterns) {
        if (lower.find(pattern.first) == std::string::npos || !seen.insert(pattern.second).second) continue;
        SpecializedActivityStore::Instance().AddPowerShell({ CurrentUnixTimeMilliseconds(), 0, pattern.second,
            std::string("Matched script token: ") + pattern.first, "Static script" }, false);
    }
}

static void BeginPowerShellAnalysis(const TargetProfile& profile) {
    g_ActivePowerShellProfile = profile;
    g_RootTargetFile = profile.originalPath;
    g_LauncherPid = 0;
    g_LauncherPath = profile.launcherPath;
    ScanPowerShellBehaviors(profile);
    AddLog("[info] PowerShell analysis armed: version=" + WStringToString(profile.powerShellVersion) +
        ", policy=" + WStringToString(profile.executionPolicy) + ".");
}

static const char* PowerShellNodeStatus(const ProcessNode& node) {
    if (node.pid == 0) return "SCRIPT";
    return node.exited ? "EXITED" : "RUNNING";
}

