static bool SelectDashboardFile(const std::wstring& path) {
    std::wstring extension = std::filesystem::path(path).extension().wstring();
    std::transform(extension.begin(), extension.end(), extension.begin(), [](wchar_t ch) { return (wchar_t)towlower(ch); });
    const std::string utf8 = WStringToString(path);
    if (extension == L".exe") {
        strcpy_s(g_DashboardExePath, utf8.c_str()); g_DashboardTargetType = 0; PrepareStaticAnalysisTarget(path); return true;
    }
    if (extension == L".dll") {
        strcpy_s(g_DashboardDllPath, utf8.c_str());
        g_DashboardTargetType = 1;
        g_DashboardTarget32 = Injector::IsFile32Bit(path);
        g_DashboardLastEnumeratedDllPath.clear();
        PrepareStaticAnalysisTarget(path);
        return true;
    }
    g_LastError = L"Unsupported target type. This build supports EXE targets and DLL injection only.";
    AddLog("[error] unsupported target type selected; only EXE and DLL are enabled in this module.");
    return false;
}

static bool ShouldInstrumentRootHost(const TargetProfile& profile) {
    (void)profile;
    return true;
}

static void StopPreviousSessionBeforeLaunch() {
    const AnalysisSession session = ProcessTreeManager::Instance().Snapshot();
    if (!session.active && !g_Target.active) return;
    ++g_RunTimerToken;
    DeleteActiveScriptTrace();
    StopRuntimeStringScanner();
    if (session.rootPid) TerminateProcessTree(session.rootPid);
    for (const auto& process : session.processTreeNodes) {
        if (!process.exited && process.pid && process.pid != session.rootPid) TerminateProcessTree(process.pid);
    }
    const DWORD previousPid = g_Target.pid;
    g_Target.active = false;
    if (previousPid) StopEtwForEndedTarget(previousPid);
    else StopEtwKernelTelemetry();
    ProcessTreeManager::Instance().StopSession(CurrentUnixTimeMilliseconds());
}

static void DrawLoadingSpinner(const char* label) {
    const float radius = 8.0f;
    const float thickness = 2.5f;
    const ImVec2 start = ImGui::GetCursorScreenPos();
    const ImVec2 center(start.x + radius, start.y + radius + 1.0f);
    const float rotation = static_cast<float>(ImGui::GetTime() * 4.5);
    ImDrawList* drawList = ImGui::GetWindowDrawList();
    drawList->PathClear();
    for (int i = 0; i <= 24; ++i) {
        const float angle = rotation + 0.35f + (4.9f * static_cast<float>(i) / 24.0f);
        drawList->PathLineTo(ImVec2(center.x + std::cos(angle) * radius, center.y + std::sin(angle) * radius));
    }
    drawList->PathStroke(ImGui::GetColorU32(kUiBlue), false, thickness);
    ImGui::Dummy(ImVec2(radius * 2.0f + 4.0f, radius * 2.0f + 3.0f));
    ImGui::SameLine();
    ImGui::TextColored(kUiBlue, "%s", label);
}

static void DrawDashboardView() {
    ConsumeCompletedStaticAnalysis();
    ImGui::BeginChild("DashboardRoot", ImVec2(0.0f, 0.0f), false);
    if (ImGui::BeginTabBar("MainWorkspaceTabs")) {
    if (ImGui::BeginTabItem("Target Setup")) {
    ImGui::BeginChild("SelectProgramPanel", ImVec2(0.0f, 0.0f), true);
    ImGui::TextColored(kUiBlue, "Select Program");
    ImGui::Separator();
    ImGui::Spacing();

    if (ImGui::RadioButton("Executable Target", &g_DashboardTargetType, 0) && g_DashboardExePath[0])
        PrepareStaticAnalysisTarget(StringToWString(g_DashboardExePath));
    ImGui::SameLine();
    if (ImGui::RadioButton("DLL Injection", &g_DashboardTargetType, 1) && g_DashboardDllPath[0])
        PrepareStaticAnalysisTarget(StringToWString(g_DashboardDllPath));
    ImGui::Spacing();

    ImGui::Text("Execution Duration:");
    ImGui::RadioButton("Runs until the program terminates itself.", &g_DashboardRunMode, 0);
    ImGui::RadioButton("Runs until the process is manually terminated.", &g_DashboardRunMode, 1);
    ImGui::RadioButton("Auto terminate after", &g_DashboardRunMode, 2);
    if (g_DashboardRunMode == 2) {
        ImGui::SameLine();
        ImGui::SetNextItemWidth(90.0f);
        ImGui::InputInt("seconds", &g_DashboardRunSeconds, 1, 10);
        if (g_DashboardRunSeconds < 1) g_DashboardRunSeconds = 1;
        if (g_DashboardRunSeconds > 86400) g_DashboardRunSeconds = 86400;
    }
    int configuredRunSeconds = (g_DashboardRunMode == 2) ? g_DashboardRunSeconds : 0;
    ImGui::Spacing();

    auto regularFile = [](const char* path) {
        std::error_code error;
        return path && path[0] && std::filesystem::is_regular_file(StringToWString(path), error);
    };
    bool hasTargetPath = g_DashboardTargetType == 0 ? regularFile(g_DashboardExePath) :
        (g_DashboardTargetType == 1 ? regularFile(g_DashboardDllPath) : false);
    const bool launchInProgress = g_LaunchingTarget.load();
    if (!hasTargetPath || launchInProgress) ImGui::BeginDisabled();
    if (PrimaryButton("Start Analysis", ImVec2(180.0f, 32.0f))) {
        StopPreviousSessionBeforeLaunch();
        g_PowerShellAnalysisActive.store(false);
        g_ScriptAnalysisActive.store(false);
        g_OfficeAnalysisActive.store(false);
        g_BatchAnalysisActive.store(false);
        g_ActivePowerShellProfile = {};
        g_ActiveOfficeProfile = {};
        g_ActiveBatchProfile = {};
        SpecializedActivityStore::Instance().ResetPowerShell();
        SpecializedActivityStore::Instance().ResetOffice();
        SpecializedActivityStore::Instance().ResetBatch();
        if (g_DashboardTargetType == 0) {
            TargetProfile profile;
            profile.originalPath = StringToWString(g_DashboardExePath); profile.detectedType = L"Executable";
            profile.launcherPath = profile.originalPath; profile.launcherArguments = StringToWString(g_DashboardExeArgs);
            profile.workingDirectory = std::filesystem::path(profile.originalPath).parent_path().wstring(); profile.executionMode = L"Direct executable";
            const auto session = ProcessTreeManager::Instance().BeginSession(profile.originalPath, "EXE", profile);
            AddLog("[info] analysis session created: " + session.sessionId + " target_type=EXE.");
            TriggerLaunch(StringToWString(g_DashboardExePath), StringToWString(g_DashboardExeArgs), configuredRunSeconds);
        } else if (g_DashboardTargetType == 1) {
            std::wstring mode = (g_DashboardDllMode == 0) ? L"dllmain" : L"rundll32";
            TargetProfile profile;
            profile.originalPath = StringToWString(g_DashboardDllPath); profile.detectedType = L"DLL";
            profile.executionMode = L"DLL Injection"; profile.workingDirectory = std::filesystem::path(profile.originalPath).parent_path().wstring();
            const auto session = ProcessTreeManager::Instance().BeginSession(profile.originalPath, "DLL", profile);
            AddLog("[info] analysis session created: " + session.sessionId + " target_type=DLL.");
            TriggerLaunchDll(StringToWString(g_DashboardDllPath), mode, g_DashboardExportName, g_DashboardTarget32, configuredRunSeconds);
        }
    }
    if (!hasTargetPath || launchInProgress) ImGui::EndDisabled();
    if (launchInProgress) {
        ImGui::SameLine();
        DrawLoadingSpinner("Starting target and waiting for the monitoring agent...");
    }
    ImGui::TextColored(kUiTextMuted, "Select a target below, then start the analysis from this always-visible action.");
    ImGui::Separator();
    ImGui::Spacing();

    if (g_DashboardTargetType == 0) {
        ImGui::Text("Executable Path:");
        ImGui::SetNextItemWidth(ImGui::GetContentRegionAvail().x - 105.0f);
        bool pathChanged = ImGui::InputText("##DashboardExePath", g_DashboardExePath, sizeof(g_DashboardExePath));
        ImGui::SameLine();
        if (PrimaryButton("Browse##DashboardExe", ImVec2(90.0f, 0.0f))) {
            wchar_t path[MAX_PATH] = L"";
            if (OpenFileDialog(g_hWnd, path, MAX_PATH, L"Executable Targets (*.exe)\0*.exe\0All Files (*.*)\0*.*\0")) {
                pathChanged = SelectDashboardFile(path) && g_DashboardTargetType == 0;
            }
        }
        if (pathChanged) {
            PrepareStaticAnalysisTarget(StringToWString(g_DashboardExePath));
        }

        ImGui::Text("Arguments:");
        ImGui::InputText("##DashboardExeArgs", g_DashboardExeArgs, sizeof(g_DashboardExeArgs));
    } else if (g_DashboardTargetType == 1) {
        ImGui::Text("DLL Path:");
        ImGui::SetNextItemWidth(ImGui::GetContentRegionAvail().x - 105.0f);
        bool dllPathChanged = ImGui::InputText("##DashboardDllPath", g_DashboardDllPath, sizeof(g_DashboardDllPath));
        ImGui::SameLine();
        if (PrimaryButton("Browse##DashboardDll", ImVec2(90.0f, 0.0f))) {
            wchar_t path[MAX_PATH] = L"";
            if (OpenFileDialog(g_hWnd, path, MAX_PATH, L"Dynamic Link Libraries (*.dll)\0*.dll\0All Files (*.*)\0*.*\0")) {
                dllPathChanged = SelectDashboardFile(path) && g_DashboardTargetType == 1;
            }
        }
        if (dllPathChanged) {
            g_DashboardLastEnumeratedDllPath.clear();
            const std::wstring dllPath = StringToWString(g_DashboardDllPath);
            std::error_code error;
            if (std::filesystem::is_regular_file(dllPath, error)) {
                g_DashboardTarget32 = Injector::IsFile32Bit(dllPath);
            }
            PrepareStaticAnalysisTarget(dllPath);
        }

        std::string currentDllPath(g_DashboardDllPath);
        if (!currentDllPath.empty() && currentDllPath != g_DashboardLastEnumeratedDllPath) {
            g_EnumExports = EnumerateDllExports(StringToWString(currentDllPath));
            g_EnumExportsDllPath = StringToWString(currentDllPath);
            g_DashboardLastEnumeratedDllPath = currentDllPath;
            g_DashboardExportName[0] = '\0';
            if (!g_EnumExports.empty() && !g_EnumExports[0].name.empty()) {
                strcpy_s(g_DashboardExportName, g_EnumExports[0].name.c_str());
            }
        }

        ImGui::Text("Execution Entry Mode:");
        ImGui::RadioButton("Inspecthor Loader (DllMain)", &g_DashboardDllMode, 0);
        ImGui::RadioButton("rundll32 Export", &g_DashboardDllMode, 1);
        if (g_DashboardDllMode == 1) {
            ImGui::Text("Export:");
            if (g_EnumExports.empty()) {
                ImGui::InputText("##DashboardExportName", g_DashboardExportName, sizeof(g_DashboardExportName));
            } else {
                const char* preview = g_DashboardExportName[0] ? g_DashboardExportName : "Select export";
                if (ImGui::BeginCombo("##DashboardExportCombo", preview)) {
                    for (const auto& exp : g_EnumExports) {
                        if (exp.name.empty()) continue;
                        bool selected = (exp.name == g_DashboardExportName);
                        if (ImGui::Selectable(exp.name.c_str(), selected)) {
                            strcpy_s(g_DashboardExportName, exp.name.c_str());
                        }
                    }
                    ImGui::EndCombo();
                }
            }
        }
        ImGui::Checkbox("32-bit (Wow64) Target", &g_DashboardTarget32);
    }

    ImGui::Spacing();
    bool hookNetwork = (g_TraceConfig.flags & TraceConfigHookNetwork) != 0;
    if (ImGui::Checkbox("Hook Network (Winsock, Schannel, OpenSSL plaintext)", &hookNetwork)) {
        if (hookNetwork) g_TraceConfig.flags |= TraceConfigHookNetwork;
        else g_TraceConfig.flags &= ~TraceConfigHookNetwork;
    }
    bool hookMemoryCopies = (g_TraceConfig.flags & TraceConfigHookMemoryCopies) != 0;
    if (ImGui::Checkbox("Hook bulk memory copies (RtlMoveMemory; noisy)", &hookMemoryCopies)) {
        if (hookMemoryCopies) g_TraceConfig.flags |= TraceConfigHookMemoryCopies;
        else g_TraceConfig.flags &= ~TraceConfigHookMemoryCopies;
    }
    ImGui::Text("Child Monitoring:");
    int childMode = static_cast<int>(g_ChildMonitoringMode);
    const char* childModes[] = { "Smart", "Aggressive", "Command-only" };
    ImGui::SetNextItemWidth(220.0f);
    if (ImGui::Combo("##DashboardChildMonitoringMode", &childMode, childModes, IM_ARRAYSIZE(childModes)))
        g_ChildMonitoringMode = static_cast<ChildMonitoringMode>(childMode);
    if (ImGui::IsItemHovered())
        ImGui::SetTooltip("Smart: inject high-value or suspicious descendants.\nAggressive: inject every eligible child in the session tree.\nCommand-only: record child commands and exits without injection.");
    ImGui::EndChild();
    ImGui::EndTabItem();
    }

    if ((g_DashboardTargetType == 0 || g_DashboardTargetType == 1) && ImGui::BeginTabItem("Static Analysis")) {
    ImGui::BeginChild("StaticAnalysisPanel", ImVec2(0.0f, 0.0f), true);
    ImGui::TextColored(kUiBlue, "Static Analysis Result");
    ImGui::Separator();
    ImGui::Spacing();

    const std::wstring selectedStaticPath = g_DashboardTargetType == 0
        ? StringToWString(g_DashboardExePath) : StringToWString(g_DashboardDllPath);
    const bool hasStaticTarget = !selectedStaticPath.empty() && FileExists(selectedStaticPath);
    if (g_StaticAnalysisRunning.load()) {
        DrawLoadingSpinner("Generating hashes, PE metadata, imports, strings, and resources...");
    } else {
        if (!hasStaticTarget) ImGui::BeginDisabled();
        const char* generateLabel = g_StaticAnalysis.valid ? "Regenerate Static Analysis" : "Generate Static Analysis";
        if (PrimaryButton(generateLabel, ImVec2(230.0f, 30.0f))) {
            StartStaticAnalysis(selectedStaticPath);
        }
        if (!hasStaticTarget) ImGui::EndDisabled();
        ImGui::SameLine();
        if (!hasStaticTarget) {
            ImGui::TextColored(kUiTextMuted, "Select a valid EXE or DLL first.");
        } else if (!g_StaticAnalysis.valid) {
            ImGui::TextColored(kUiTextMuted, "%s", g_StaticAnalysis.status.c_str());
        }
    }
    ImGui::Separator();
    ImGui::Spacing();

    auto drawAnalysisRow = [](const char* label, const std::string& value) {
        ImGui::TableNextRow();
        ImGui::TableSetColumnIndex(0);
        ImGui::TextColored(kUiTextMuted, "%s", label);
        ImGui::TableSetColumnIndex(1);
        ImGui::TextWrapped("%s", value.empty() ? "-" : value.c_str());
    };

    if (g_StaticAnalysis.valid && ImGui::BeginPopupContextWindow("StaticAnalysisContext", ImGuiPopupFlags_MouseButtonRight)) {
        if (ImGui::MenuItem("Copy All")) CopyToClipboard(BuildStaticAnalysisText());
        ImGui::EndPopup();
    }

    if (g_StaticAnalysis.valid && ImGui::BeginTabBar("StaticAnalysisTabs")) {
        if (ImGui::BeginTabItem("Summary")) {
            if (ImGui::BeginTable("StaticAnalysisSummaryTable", 2, ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Field", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Value", ImGuiTableColumnFlags_WidthStretch);
                drawAnalysisRow("File Type", g_StaticAnalysis.fileType);
                drawAnalysisRow("Architecture", g_StaticAnalysis.architecture);
                drawAnalysisRow("Subsystem", g_StaticAnalysis.subsystem);
                drawAnalysisRow("Entry Point", g_StaticAnalysis.entryPointRva);
                drawAnalysisRow("Compiled", g_StaticAnalysis.compileTime);
                drawAnalysisRow("Compiler", g_StaticAnalysis.compilerInfo);
                drawAnalysisRow("Imports", g_StaticAnalysis.importSummary);
                drawAnalysisRow("TLS Callbacks", std::to_string(g_StaticAnalysis.tlsCallbacks.size()));
                drawAnalysisRow("MD5", g_StaticAnalysis.md5);
                drawAnalysisRow("SHA1", g_StaticAnalysis.sha1);
                drawAnalysisRow("SHA256", g_StaticAnalysis.sha256);
                drawAnalysisRow("Path", g_StaticAnalysis.path);
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (ImGui::BeginTabItem("Imports")) {
            ImGui::Columns(2, "ImportsColumns", true);
            ImGui::TextColored(kUiTextMuted, "Imported DLLs");
            ImGui::BeginChild("ImportedDllsList", ImVec2(0.0f, 0.0f), true);
            if (g_SelectedImportDllIndex >= (int)g_StaticAnalysis.importedDlls.size()) {
                g_SelectedImportDllIndex = -1;
            }
            for (size_t i = 0; i < g_StaticAnalysis.importedDlls.size(); ++i) {
                const auto& dll = g_StaticAnalysis.importedDlls[i];
                bool selected = (g_SelectedImportDllIndex == (int)i);
                if (ImGui::Selectable(dll.c_str(), selected)) {
                    g_SelectedImportDllIndex = (int)i;
                }
            }
            ImGui::EndChild();
            ImGui::NextColumn();

            std::string selectedDll;
            if (g_SelectedImportDllIndex >= 0 && g_SelectedImportDllIndex < (int)g_StaticAnalysis.importedDlls.size()) {
                selectedDll = g_StaticAnalysis.importedDlls[g_SelectedImportDllIndex];
            }
            std::string selectedDllLower = ToLowerCopy(selectedDll);

            std::vector<std::string> visibleAllApis;
            if (!selectedDll.empty()) {
                auto it = g_StaticAnalysis.importsByDll.find(selectedDll);
                if (it != g_StaticAnalysis.importsByDll.end()) {
                    visibleAllApis = it->second;
                }
            } else {
                for (const auto& kv : g_StaticAnalysis.importsByDll) {
                    for (const auto& api : kv.second) {
                        visibleAllApis.push_back(kv.first + "!" + api);
                    }
                }
                std::sort(visibleAllApis.begin(), visibleAllApis.end());
            }

            std::vector<std::string> visibleProfiledApis;
            for (const auto& api : g_StaticAnalysis.suspiciousImports) {
                if (selectedDll.empty()) {
                    visibleProfiledApis.push_back(api);
                    continue;
                }
                std::string apiLower = ToLowerCopy(api);
                std::string prefix = selectedDllLower + "!";
                if (apiLower.rfind(prefix, 0) == 0) {
                    visibleProfiledApis.push_back(api);
                }
            }

            std::string detailTitle = selectedDll.empty()
                ? "Import Details"
                : "Import Details: " + selectedDll;
            ImGui::TextColored(kUiTextMuted, "%s", detailTitle.c_str());
            ImGui::TextWrapped("All APIs lists every imported function. Profiled APIs shows only imports matched by the malware-analysis profile; a match is notable, not proof of malicious behavior.");
            if (ImGui::BeginTabBar("ImportDetailTabs")) {
                if (ImGui::BeginTabItem(("All APIs (" + std::to_string(visibleAllApis.size()) + ")").c_str())) {
                    ImGui::BeginChild("AllImportsList", ImVec2(0.0f, 0.0f), true);
                    if (visibleAllApis.empty()) {
                    }
                    for (const auto& api : visibleAllApis) DrawApiNameWithContext(api, nullptr, true);
                    ImGui::EndChild();
                    ImGui::EndTabItem();
                }

                if (ImGui::BeginTabItem(("Profiled APIs (" + std::to_string(visibleProfiledApis.size()) + ")").c_str())) {
                    ImGui::BeginChild("SuspiciousImportsList", ImVec2(0.0f, 0.0f), true);
                    if (visibleProfiledApis.empty()) {
                    }
                    for (const auto& api : visibleProfiledApis) DrawApiNameWithContext(api, nullptr, true);
                    ImGui::EndChild();
                    ImGui::EndTabItem();
                }
                ImGui::EndTabBar();
            }
            ImGui::Columns(1);
            ImGui::EndTabItem();
        }

        if (ImGui::BeginTabItem("Sections")) {
            if (ImGui::BeginTable("SectionsTable", 6, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Name", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Raw", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Virtual", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Perm", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Entropy", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Flag", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (const auto& sec : g_StaticAnalysis.sections) {
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0); ImGui::Text("%s", sec.name.c_str());
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%u", sec.rawSize);
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%u", sec.virtualSize);
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%s", sec.permissions.c_str());
                    ImGui::TableSetColumnIndex(4); ImGui::Text("%.2f", sec.entropy);
                    ImGui::TableSetColumnIndex(5);
                    if (sec.rwx) ImGui::TextColored(kUiRed, "RWX section");
                    else if (sec.entropy >= 7.2) ImGui::TextColored(kUiGold, "High entropy");
                    else ImGui::Text("-");
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }

        if (ImGui::BeginTabItem("Strings")) {
            ImGui::Columns(2, "StringsColumns", true);
            ImGui::TextColored(kUiTextMuted, "ASCII Strings");
            ImGui::SetNextItemWidth(-1.0f);
            ImGui::InputTextWithHint("##StaticAsciiFilter", "Filter ASCII strings...", g_StaticAsciiFilter, sizeof(g_StaticAsciiFilter));
            std::string allFilteredAscii;
            for (const auto& s : g_StaticAnalysis.asciiStrings) if (StringContainsInsensitive(s, g_StaticAsciiFilter)) {
                if (!allFilteredAscii.empty()) allFilteredAscii += "\n";
                allFilteredAscii += s;
            }
            if (ImGui::Button("Copy All Filtered##Ascii")) CopyToClipboard(allFilteredAscii);
            ImGui::BeginChild("AsciiStringsList", ImVec2(0.0f, 0.0f), true);
            for (size_t i = 0; i < g_StaticAnalysis.asciiStrings.size(); ++i) {
                const auto& s = g_StaticAnalysis.asciiStrings[i];
                if (!StringContainsInsensitive(s, g_StaticAsciiFilter)) continue;
                ImGui::PushID((int)i);
                ImGui::Selectable(s.c_str(), false);
                if (ImGui::BeginPopupContextItem("AsciiStringContext")) {
                    if (ImGui::MenuItem("Copy String")) CopyToClipboard(s);
                    ImGui::EndPopup();
                }
                ImGui::PopID();
            }
            ImGui::EndChild();
            ImGui::NextColumn();
            ImGui::TextColored(kUiTextMuted, "Unicode Strings");
            ImGui::SetNextItemWidth(-1.0f);
            ImGui::InputTextWithHint("##StaticUnicodeFilter", "Filter Unicode strings...", g_StaticUnicodeFilter, sizeof(g_StaticUnicodeFilter));
            std::string allFilteredUnicode;
            for (const auto& s : g_StaticAnalysis.unicodeStrings) if (StringContainsInsensitive(s, g_StaticUnicodeFilter)) {
                if (!allFilteredUnicode.empty()) allFilteredUnicode += "\n";
                allFilteredUnicode += s;
            }
            if (ImGui::Button("Copy All Filtered##Unicode")) CopyToClipboard(allFilteredUnicode);
            ImGui::BeginChild("UnicodeStringsList", ImVec2(0.0f, 0.0f), true);
            for (size_t i = 0; i < g_StaticAnalysis.unicodeStrings.size(); ++i) {
                const auto& s = g_StaticAnalysis.unicodeStrings[i];
                if (!StringContainsInsensitive(s, g_StaticUnicodeFilter)) continue;
                ImGui::PushID((int)i);
                ImGui::Selectable(s.c_str(), false);
                if (ImGui::BeginPopupContextItem("UnicodeStringContext")) {
                    if (ImGui::MenuItem("Copy String")) CopyToClipboard(s);
                    ImGui::EndPopup();
                }
                ImGui::PopID();
            }
            ImGui::EndChild();
            ImGui::Columns(1);
            ImGui::EndTabItem();
        }

        if (ImGui::BeginTabItem("Resources")) {
            if (g_SelectedStaticResourceIndex >= (int)g_StaticAnalysis.resources.size()) g_SelectedStaticResourceIndex = -1;
            if (g_SelectedStaticResourceIndex < 0) ImGui::BeginDisabled();
            if (ImGui::Button("Dump Selected Resource")) {
                const auto& selected = g_StaticAnalysis.resources[g_SelectedStaticResourceIndex];
                std::wstring defaultName = L"resource_" + std::to_wstring(g_SelectedStaticResourceIndex) + L".bin";
                SaveBinaryFileWithDialog(selected.data, defaultName.c_str(), L"resource");
            }
            if (g_SelectedStaticResourceIndex < 0) ImGui::EndDisabled();
            ImGui::SameLine();
            ImGui::TextColored(kUiTextMuted, "Select a resource row, then dump its original bytes.");
            if (ImGui::BeginTable("ResourcesTable", 6, ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_SizingFixedFit)) {
                ImGui::TableSetupColumn("Type", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Name", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Lang", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("Bytes", ImGuiTableColumnFlags_WidthFixed, 0.0f);
                ImGui::TableSetupColumn("ASCII Preview", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn("Hex Preview", ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();
                for (size_t i = 0; i < g_StaticAnalysis.resources.size(); ++i) {
                    const auto& res = g_StaticAnalysis.resources[i];
                    ImGui::PushID((int)i);
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    if (ImGui::Selectable(res.type.c_str(), g_SelectedStaticResourceIndex == (int)i, ImGuiSelectableFlags_SpanAllColumns))
                        g_SelectedStaticResourceIndex = (int)i;
                    if (ImGui::BeginPopupContextItem("StaticResourceContext")) {
                        if (ImGui::MenuItem("Dump Resource")) {
                            std::wstring defaultName = L"resource_" + std::to_wstring(i) + L".bin";
                            SaveBinaryFileWithDialog(res.data, defaultName.c_str(), L"resource");
                        }
                        ImGui::EndPopup();
                    }
                    ImGui::TableSetColumnIndex(1); ImGui::Text("%s", res.name.c_str());
                    ImGui::TableSetColumnIndex(2); ImGui::Text("%s", res.language.c_str());
                    ImGui::TableSetColumnIndex(3); ImGui::Text("%u", res.size);
                    ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", res.asciiPreview.c_str());
                    ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", res.hexPreview.c_str());
                    ImGui::PopID();
                }
                ImGui::EndTable();
            }
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }

    ImGui::EndChild();
    ImGui::EndTabItem();
    }

    if (ImGui::BeginTabItem("Process Info")) {
    DrawProcessInfoPanel(ImGui::GetContentRegionAvail().y);
    ImGui::EndTabItem();
    }

    if (ImGui::BeginTabItem("Output")) {
    float logHeight = ImGui::GetContentRegionAvail().y;
    ImGui::Columns(2, "DashboardOutputColumns", true);
    DrawLogQueuePanel(logHeight);
    ImGui::NextColumn();
    DrawConsoleOutputPanel(logHeight);
    ImGui::Columns(1);
    ImGui::EndTabItem();
    }

    ImGui::EndTabBar();
    }

    ImGui::EndChild();
}

static bool ExportHtmlReport() {
    wchar_t path[MAX_PATH] = {};
    if (!SaveFileDialog(g_hWnd, path, MAX_PATH,
        L"Inspecthor HTML Report (*.html)\0*.html\0All Files (*.*)\0*.*\0\0", L"html", L"inspecthor_report.html")) return false;
    std::vector<TelemetryEvent> events;
    { std::lock_guard<std::mutex> lock(g_EventsMutex); events = g_Events; }
    std::unordered_map<std::string, size_t> categories;
    size_t findingCount = 0;
    for (const auto& event : events) {
        if (event.apiName.rfind("ETW ", 0) == 0 || event.dllName == "ETW" || IsWinApiManuallyExcluded(event.apiName)) continue;
        ++categories[EventCategoryLabel(event)]; ++findingCount;
    }
    std::vector<std::pair<std::string, size_t>> sorted(categories.begin(), categories.end());
    std::sort(sorted.begin(), sorted.end(), [](const auto& a, const auto& b) { return a.second > b.second; });
    std::ostringstream html;
    html << "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
         << "<title>Inspecthor Analysis Report</title><style>"
         << ":root{color-scheme:dark;--bg:#0d1117;--panel:#161b22;--line:#30363d;--text:#e6edf3;--muted:#8b949e;--blue:#8b9bea;--red:#ff6b6b}"
         << "*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Segoe UI,Arial,sans-serif}"
         << "main{max-width:1500px;margin:auto;padding:28px}h1,h2{font-weight:600}h1{margin-bottom:4px}.muted{color:var(--muted)}"
         << ".grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:14px}"
         << ".count{font-size:28px;color:var(--blue)}table{width:100%;border-collapse:collapse;background:var(--panel)}th,td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}"
         << "th{position:sticky;top:0;background:#21262d;color:var(--blue)}code{white-space:pre-wrap;word-break:break-word;color:#d2a8ff}.table-wrap{overflow:auto;max-height:70vh;border:1px solid var(--line);border-radius:8px}"
         << "</style></head><body><main><h1>Inspecthor Analysis Report</h1><div class='muted'>User-mode findings report. Raw ETW kernel rows are excluded to reduce noise.</div>";
    html << "<h2>Target</h2><div class='grid'>"
         << "<div class='card'><b>File</b><br><code>" << EscapeHtml(WidePathToUtf8(g_Target.path)) << "</code></div>"
         << "<div class='card'><b>PID</b><br>" << g_Target.pid << "</div>"
         << "<div class='card'><b>Execution</b><br>" << EscapeHtml(g_Target.launchMode) << "</div>"
         << "<div class='card'><b>SHA-256</b><br><code>" << EscapeHtml(g_StaticAnalysis.sha256) << "</code></div></div>";
    html << "<h2>Finding overview</h2><div class='grid'><div class='card'><div class='count'>" << findingCount << "</div>captured user-mode events</div>";
    for (const auto& item : sorted) html << "<div class='card'><div class='count'>" << item.second << "</div>" << EscapeHtml(item.first) << "</div>";
    html << "</div>";
    if (!g_ActivePowerShellProfile.originalPath.empty()) {
        html << "<h2>PowerShell Analysis</h2><div class='grid'>"
             << "<div class='card'><b>Script</b><br><code>" << EscapeHtml(WStringToString(g_ActivePowerShellProfile.originalPath)) << "</code></div>"
             << "<div class='card'><b>Execution Host</b><br><code>" << EscapeHtml(WStringToString(g_ActivePowerShellProfile.launcherPath)) << "</code></div>"
             << "<div class='card'><b>Version</b><br>" << EscapeHtml(WStringToString(g_ActivePowerShellProfile.powerShellVersion)) << "</div>"
             << "<div class='card'><b>Policy</b><br>" << EscapeHtml(WStringToString(g_ActivePowerShellProfile.executionPolicy)) << "</div></div>";
        html << "<div class='table-wrap'><table><thead><tr><th>Time</th><th>PID</th><th>Behavior</th><th>Evidence</th><th>Source</th></tr></thead><tbody>";
        for (const auto& behavior : SpecializedActivityStore::Instance().PowerShellSnapshot()) html << "<tr><td>" << EscapeHtml(FormatTimestamp(behavior.timestamp))
            << "</td><td>" << behavior.pid << "</td><td>" << EscapeHtml(behavior.behavior) << "</td><td><code>"
            << EscapeHtml(behavior.evidence) << "</code></td><td>" << EscapeHtml(behavior.source) << "</td></tr>";
        html << "</tbody></table></div>";
        html << "<h2>PowerShell Execution Chain</h2><div class='table-wrap'><table><thead><tr><th>PID</th><th>Parent PID</th><th>Process</th><th>Command</th><th>Instrumentation</th><th>Exit</th></tr></thead><tbody>";
        {
            for (const auto& node : ProcessTreeManager::Instance().ProcessSnapshot()) html << "<tr><td>" << node.pid << "</td><td>" << node.parentPid
                << "</td><td><code>" << EscapeHtml(WStringToString(node.imagePath)) << "</code></td><td><code>"
                << EscapeHtml(WStringToString(node.commandLine)) << "</code></td><td>" << EscapeHtml(node.decision)
                << "</td><td>" << (node.exited ? std::to_string(node.exitCode) : "Running") << "</td></tr>";
        }
        html << "</tbody></table></div>";
    }
    html << "<h2>Evidence</h2><div class='table-wrap'><table><thead><tr><th>Time</th><th>Category</th><th>API</th><th>PID / TID</th><th>Caller</th><th>Result</th><th>Captured details</th></tr></thead><tbody>";
    for (const auto& event : events) {
        if (event.apiName.rfind("ETW ", 0) == 0 || event.dllName == "ETW" || IsWinApiManuallyExcluded(event.apiName)) continue;
        std::ostringstream details;
        for (const auto& parameter : event.parameters) {
            if (!parameter.decoded.empty()) details << parameter.name << "=" << parameter.decoded << "\n";
        }
        std::ostringstream result; result << "0x" << std::hex << std::uppercase << event.returnValue;
        html << "<tr><td>" << EscapeHtml(FormatTimestamp(event.timestamp)) << "</td><td>" << EscapeHtml(EventCategoryLabel(event))
             << "</td><td><code>" << EscapeHtml(event.apiName) << "</code></td><td>" << event.processId << " / " << event.threadId
             << "</td><td><code>" << EscapeHtml(event.callerModule) << "</code></td><td><code>" << result.str()
             << "</code></td><td><code>" << EscapeHtml(details.str()) << "</code></td></tr>";
    }
    html << "</tbody></table></div><h2>Interpretation notes</h2><div class='card'>"
         << "This report records observed behavior, not a final verdict. Empty sections can mean no matching event was captured, an API was unsupported, or execution did not reach that behavior. Correlate high-value events by PID, time, caller, and parameters."
         << "</div></main></body></html>";
    if (!WriteTextFileUtf8(WidePathToUtf8(path), html.str())) { AddLog("[error] failed to write HTML report."); return false; }
    AddLog("[info] exported HTML report to " + WidePathToUtf8(path) + ".");
    ShowSaveSuccessMessage(std::filesystem::path(path), L"HTML report");
    return true;
}

static bool ExportAnalysisDatabase() {
    json root;
    root["format"] = "Inspecthor Analysis Database";
    root["version"] = 6;
    root["exported_at"] = static_cast<uint64_t>(time(nullptr));
    root["target"] = {
        {"path", WStringToString(g_Target.path)},
        {"process_path", WStringToString(g_TargetProcessPath)},
        {"command_line", g_TargetCommandLine},
        {"pid", g_Target.pid},
        {"active", g_Target.active},
        {"architecture", g_Target.is32Bit ? "x86" : "x64"},
        {"launch_mode", g_Target.launchMode}
    };
    root["events"] = json::array();
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        for (const auto& event : g_Events) {
            root["events"].push_back(json::parse(event.ToJson()));
        }
    }
    root["recovered_runtime_strings"] = json::array();
    {
        std::lock_guard<std::mutex> lock(g_RecoveredStringsMutex);
        for (const auto& row : g_RecoveredStrings) {
            root["recovered_runtime_strings"].push_back({
                {"pid", row.pid}, {"address", row.address}, {"value", row.value},
                {"encoding", row.encoding}, {"classification", row.classification},
                {"protection", row.protection}, {"region_type", row.regionType},
                {"first_seen", row.firstSeen}, {"last_seen", row.lastSeen},
                {"observations", row.observations}
            });
        }
    }
    root["etw_kernel_events"] = json::array();
    for (const auto& event : SnapshotEtwKernelEvents()) {
        json properties = json::array();
        for (const auto& property : event.properties) properties.push_back({ {"name", property.name}, {"value", property.value} });
        root["etw_kernel_events"].push_back({
            {"timestamp", event.timestamp}, {"process_id", event.processId}, {"thread_id", event.threadId},
            {"provider", event.provider}, {"task", event.task}, {"opcode", event.opcode},
            {"category", event.category}, {"action", event.action}, {"details", event.details},
            {"summary", event.summary}, {"event_id", event.eventId}, {"properties", std::move(properties)}
        });
    }
    root["hook_statuses"] = json::array();
    {
        std::lock_guard<std::mutex> lock(g_HookStatusMutex);
        for (const auto& status : g_HookStatuses) {
            root["hook_statuses"].push_back({
                {"api", status.apiName}, {"dll", status.dllName}, {"status", status.status}, {"reason", status.reason}
            });
        }
    }
    {
        std::lock_guard<std::mutex> lock(g_LogsMutex);
        root["log_queue"] = g_Logs;
    }
    {
        std::lock_guard<std::mutex> lock(g_ConsoleMutex);
        root["console_output"] = g_ConsoleOutput;
    }
    root["controller_process_terminations"] = json::array();
    {
        std::lock_guard<std::mutex> lock(g_ProcessLifecycleMutex);
        for (const auto& row : g_ControllerProcessTerminations) {
            if (row.details == "Target process exited or disconnected from its telemetry pipe") continue;
            root["controller_process_terminations"].push_back({
                {"timestamp", row.timestampMs}, {"time", row.time}, {"pid", row.targetPid},
                {"action", row.action}, {"details", row.details}, {"result", row.result}
            });
        }
    }
    root["observed_process_paths"] = json::object();
    for (const auto& entry : ProcessTreeManager::Instance().ObservedProcessPaths())
        root["observed_process_paths"][std::to_string(entry.first)] = entry.second;
    {
        auto rowToJson = [](const ProcessWatcherRecord& row) {
            return json{
                {"timestamp", row.timestamp}, {"end_timestamp", row.endTimestamp}, {"pid", row.pid},
                {"parent_pid", row.parentPid}, {"process_name", row.processName}, {"file_path", row.filePath},
                {"command_line", row.commandLine}, {"status", row.status}, {"intercepted", row.intercepted}
            };
        };
        std::lock_guard<std::mutex> watcherLock(g_ProcessWatcherMutex);
        root["process_watcher"] = {
            {"running", g_ProcessWatcherRunning.load()},
            {"live", json::array()}, {"created", json::array()},
            {"terminated", json::array()}, {"commands", json::array()}
        };
        for (const auto& pair : g_ProcessWatcherLive) root["process_watcher"]["live"].push_back(rowToJson(pair.second));
        for (const auto& row : g_ProcessWatcherCreated) root["process_watcher"]["created"].push_back(rowToJson(row));
        for (const auto& row : g_ProcessWatcherTerminated) root["process_watcher"]["terminated"].push_back(rowToJson(row));
        for (const auto& row : g_ProcessWatcherCommands) root["process_watcher"]["commands"].push_back(rowToJson(row));
    }
    {
        auto rowToJson = [](const FolderFileWatcherRecord& row) {
            return json{
                {"timestamp", row.timestamp}, {"action", row.action}, {"object_type", row.objectType},
                {"path", row.path}, {"old_path", row.oldPath}, {"size", row.size},
                {"note", row.note}
            };
        };
        std::lock_guard<std::mutex> folderLock(g_FolderFileWatcherMutex);
        root["folder_file_watcher"] = {
            {"running", g_FolderFileWatcherRunning.load()},
            {"exclude_enabled", g_FolderFileWatcherExcludeEnabled},
            {"exclude_contains", g_FolderFileWatcherExcludeBuf},
            {"created", json::array()}, {"modified", json::array()}, {"renamed", json::array()},
            {"moved", json::array()}, {"copied", json::array()}, {"deleted", json::array()}
        };
        for (const auto& row : g_FolderFileWatcherCreated) root["folder_file_watcher"]["created"].push_back(rowToJson(row));
        for (const auto& row : g_FolderFileWatcherModified) root["folder_file_watcher"]["modified"].push_back(rowToJson(row));
        for (const auto& row : g_FolderFileWatcherRenamed) root["folder_file_watcher"]["renamed"].push_back(rowToJson(row));
        for (const auto& row : g_FolderFileWatcherMoved) root["folder_file_watcher"]["moved"].push_back(rowToJson(row));
        for (const auto& row : g_FolderFileWatcherCopied) root["folder_file_watcher"]["copied"].push_back(rowToJson(row));
        for (const auto& row : g_FolderFileWatcherDeleted) root["folder_file_watcher"]["deleted"].push_back(rowToJson(row));
    }
    {
        auto rowToJson = [](const NetWatcherConnection& row) {
            return json{
                {"timestamp", row.timestamp}, {"protocol", row.protocol}, {"local_address", row.localAddress},
                {"local_port", row.localPort}, {"remote_address", row.remoteAddress}, {"remote_port", row.remotePort},
                {"state", row.state}, {"pid", row.pid}, {"process_name", row.processName},
                {"file_path", row.filePath}, {"command_line", row.commandLine}, {"excluded", row.excluded}
            };
        };
        std::lock_guard<std::mutex> netLock(g_NetWatcherMutex);
        root["net_watcher"] = {
            {"running", g_NetWatcherRunning.load()},
            {"hide_excluded", g_NetWatcherHideExcluded},
            {"dim_excluded", g_NetWatcherDimExcluded},
            {"active", json::array()},
            {"events", json::array()}
        };
        for (const auto& pair : g_NetWatcherActive) root["net_watcher"]["active"].push_back(rowToJson(pair.second));
        for (const auto& row : g_NetWatcherEvents) root["net_watcher"]["events"].push_back(rowToJson(row));
    }
    const AnalysisSession sessionSnapshot = ProcessTreeManager::Instance().Snapshot();
    root["analysis_session"] = {
        {"session_id", sessionSnapshot.sessionId}, {"original_target", WStringToString(sessionSnapshot.originalTargetPath)},
        {"target_type", sessionSnapshot.targetType}, {"root_pid", sessionSnapshot.rootPid},
        {"launcher_pid", sessionSnapshot.launcherPid}, {"primary_pid", sessionSnapshot.primaryPid},
        {"start_time", sessionSnapshot.startTime}, {"end_time", sessionSnapshot.endTime},
        {"active", sessionSnapshot.active}, {"processes", json::array()}
    };
    for (const auto& node : sessionSnapshot.processTreeNodes) root["analysis_session"]["processes"].push_back({
        {"pid", node.pid}, {"parent_pid", node.parentPid}, {"image_path", WStringToString(node.imagePath)},
        {"process_name", WStringToString(node.processName)}, {"command_line", WStringToString(node.commandLine)},
        {"start_time", node.startTime}, {"exit_time", node.exitTime}, {"relationship", node.relationship},
        {"instrumentation_status", node.instrumentationStatus}, {"decision", node.decision}, {"reason", node.reason},
        {"monitored", node.monitored}, {"exited", node.exited}, {"exit_code", node.exitCode}
    });
    root["powershell_analysis"] = {
        {"active", g_PowerShellAnalysisActive.load()},
        {"target_file", WStringToString(g_ActivePowerShellProfile.originalPath)},
        {"detected_type", WStringToString(g_ActivePowerShellProfile.detectedType)},
        {"execution_host", WStringToString(g_ActivePowerShellProfile.launcherPath)},
        {"arguments", WStringToString(g_ActivePowerShellProfile.launcherArguments)},
        {"working_directory", WStringToString(g_ActivePowerShellProfile.workingDirectory)},
        {"execution_mode", WStringToString(g_ActivePowerShellProfile.executionMode)},
        {"powershell_version", WStringToString(g_ActivePowerShellProfile.powerShellVersion)},
        {"execution_policy", WStringToString(g_ActivePowerShellProfile.executionPolicy)},
        {"current_user", g_PowerShellCurrentUser}, {"integrity_level", g_PowerShellIntegrityLevel},
        {"processes", json::array()}, {"behaviors", json::array()}
    };
    {
        const auto powerShellProcesses = g_ActivePowerShellProfile.originalPath.empty()
            ? std::vector<ProcessNode>{} : ProcessTreeManager::Instance().ProcessSnapshot();
        for (const auto& node : powerShellProcesses) root["powershell_analysis"]["processes"].push_back({
            {"pid", node.pid}, {"parent_pid", node.parentPid}, {"image_path", WStringToString(node.imagePath)},
            {"command_line", WStringToString(node.commandLine)}, {"timestamp", node.timestamp},
            {"decision", node.decision}, {"reason", node.reason}, {"is_launcher", node.isLauncher},
            {"is_root_target", node.isRootTarget}, {"monitored", node.monitored}, {"exited", node.exited},
            {"exit_code", node.exitCode}
        });
    }
    {
        for (const auto& behavior : SpecializedActivityStore::Instance().PowerShellSnapshot()) root["powershell_analysis"]["behaviors"].push_back({
            {"timestamp", behavior.timestamp}, {"pid", behavior.pid}, {"behavior", behavior.behavior},
            {"evidence", behavior.evidence}, {"source", behavior.source}
        });
    }
    root["office_analysis"] = {
        {"target_file", WStringToString(g_ActiveOfficeProfile.originalPath)},
        {"detected_type", WStringToString(g_ActiveOfficeProfile.detectedType)},
        {"office_host", WStringToString(g_ActiveOfficeProfile.officeHost)},
        {"resolved_host", WStringToString(g_ActiveOfficeProfile.launcherPath)},
        {"arguments", WStringToString(g_ActiveOfficeProfile.launcherArguments)},
        {"working_directory", WStringToString(g_ActiveOfficeProfile.workingDirectory)}, {"behaviors", json::array()}
    };
    { for (const auto& behavior : SpecializedActivityStore::Instance().OfficeSnapshot())
        root["office_analysis"]["behaviors"].push_back({ {"timestamp", behavior.timestamp}, {"pid", behavior.pid},
            {"behavior", behavior.behavior}, {"evidence", behavior.evidence}, {"source", behavior.source} }); }
    root["script_analysis"] = {
        {"active", g_ScriptAnalysisActive.load()},
        {"target_file", WStringToString(g_ActiveBatchProfile.originalPath)},
        {"detected_type", WStringToString(g_ActiveBatchProfile.detectedType)},
        {"launcher", WStringToString(g_ActiveBatchProfile.launcherPath)},
        {"arguments", WStringToString(g_ActiveBatchProfile.launcherArguments)},
        {"execution_mode", WStringToString(g_ActiveBatchProfile.executionMode)},
        {"trace_executed_lines", g_TraceExecutedScriptLines},
        {"commands", json::array()}
    };
    { for (const auto& command : SpecializedActivityStore::Instance().BatchSnapshot())
        root["script_analysis"]["commands"].push_back({ {"line", command.behavior}, {"command", command.evidence},
            {"source", command.source}, {"observations", command.observations}, {"first_seen", command.firstSeen}, {"last_seen", command.lastSeen} }); }
    root["static_analysis"] = {
        {"valid", g_StaticAnalysis.valid}, {"path", g_StaticAnalysis.path}, {"md5", g_StaticAnalysis.md5},
        {"sha1", g_StaticAnalysis.sha1}, {"sha256", g_StaticAnalysis.sha256}, {"file_type", g_StaticAnalysis.fileType},
        {"architecture", g_StaticAnalysis.architecture}, {"subsystem", g_StaticAnalysis.subsystem},
        {"entry_point_rva", g_StaticAnalysis.entryPointRva}, {"compile_time", g_StaticAnalysis.compileTime},
        {"compiler_info", g_StaticAnalysis.compilerInfo}, {"import_summary", g_StaticAnalysis.importSummary},
        {"status", g_StaticAnalysis.status}, {"imported_dlls", g_StaticAnalysis.importedDlls},
        {"imports_by_dll", g_StaticAnalysis.importsByDll}, {"suspicious_imports", g_StaticAnalysis.suspiciousImports},
        {"tls_callbacks", g_StaticAnalysis.tlsCallbacks},
        {"ascii_strings", g_StaticAnalysis.asciiStrings}, {"unicode_strings", g_StaticAnalysis.unicodeStrings}
    };
    root["static_analysis"]["sections"] = json::array();
    for (const auto& section : g_StaticAnalysis.sections) {
        root["static_analysis"]["sections"].push_back({
            {"name", section.name}, {"raw_size", section.rawSize}, {"virtual_size", section.virtualSize},
            {"permissions", section.permissions}, {"entropy", section.entropy}, {"rwx", section.rwx}
        });
    }
    root["static_analysis"]["resources"] = json::array();
    for (const auto& resource : g_StaticAnalysis.resources) {
        root["static_analysis"]["resources"].push_back({
            {"type", resource.type}, {"name", resource.name}, {"language", resource.language},
            {"size", resource.size}, {"ascii_preview", resource.asciiPreview}, {"hex_preview", resource.hexPreview},
            {"data", resource.data}
        });
    }
    root["ui_capture_settings"] = {
        {"capturing_active", g_CapturingActive},
        {"hook_network", (g_TraceConfig.flags & TraceConfigHookNetwork) != 0},
        {"hook_memory_copies", (g_TraceConfig.flags & TraceConfigHookMemoryCopies) != 0},
        {"hook_heap", (g_TraceConfig.flags & TraceConfigHookHeap) != 0},
        {"hook_advanced_native", (g_TraceConfig.flags & TraceConfigHookAdvancedNative) != 0},
        {"network_include_etw", g_NetworkIncludeEtw},
        {"network_hide_failed", g_NetworkHideFailed},
        {"registry_include_etw", g_RegistryIncludeEtw},
        {"registry_hide_failed", g_RegistryHideFailed},
        {"file_include_etw", g_FileIncludeEtw},
        {"file_hide_failed", g_FileHideFailed},
        {"memory_show_heap_activity", g_MemoryShowHeapActivity},
        {"memory_show_query_activity", g_MemoryShowQueryActivity},
        {"runtime_strings_executable_only", g_RuntimeStringsExecutableOnly.load()},
        {"process_hide_etw_findings", g_ProcessHideEtwFindings},
        {"show_etw_findings", g_ShowEtwFindings},
        {"show_baseline_apis", g_ShowBaselineApis}
    };
    root["exclusions"] = {
        {"winapi", g_WinApiExclusions},
        {"network", g_NetworkExclusions},
        {"registry", g_RegistryExclusions},
        {"files", g_FileExclusions},
        {"memory", g_MemoryExclusions},
        {"dlls", g_DllExclusions},
        {"ipc", g_IpcExclusions}
    };

    wchar_t path[MAX_PATH] = {};
    if (!SaveFileDialog(g_hWnd, path, MAX_PATH,
        L"Inspecthor JSON Database (*.json)\0*.json\0All Files (*.*)\0*.*\0\0",
        L"json", L"inspecthor_analysis.json")) {
        return false;
    }
    std::ofstream output(std::filesystem::path(path), std::ios::binary);
    if (!output.is_open()) {
        AddLog("[error] failed to export analysis database.");
        return false;
    }
    output << root.dump(2);
    output.close();
    AddLog("[info] exported complete analysis database to " + WidePathToUtf8(path) + ".");
    ShowSaveSuccessMessage(std::filesystem::path(path), L"analysis database");
    return true;
}

static bool ImportAnalysisDatabase() {
    if (g_Target.active) {
        AddLog("[warn] stop the active target before importing a previous analysis.");
        return false;
    }

    wchar_t path[MAX_PATH] = L"";
    if (!OpenFileDialog(g_hWnd, path, MAX_PATH, L"Inspecthor JSON Database (*.json)\0*.json\0All Files (*.*)\0*.*\0")) {
        return false;
    }

    try {
        std::ifstream input(std::filesystem::path(path), std::ios::binary);
        if (!input.is_open()) {
            AddLog("[error] could not open the selected analysis database.");
            return false;
        }

        json root;
        input >> root;
        const json* eventRows = nullptr;
        if (root.is_array()) {
            eventRows = &root;
        } else if (root.is_object() && root.contains("events") && root["events"].is_array()) {
            eventRows = &root["events"];
        }
        if (!eventRows) {
            AddLog("[error] selected JSON does not contain an Inspecthor event database.");
            return false;
        }

        std::vector<TelemetryEvent> importedEvents;
        importedEvents.reserve(eventRows->size());
        for (const auto& item : *eventRows) {
            if (!item.is_object()) continue;
            TelemetryEvent event = ParseTelemetryFromJson(item.dump());
            if (!event.apiName.empty()) importedEvents.push_back(std::move(event));
        }
        if (importedEvents.empty() && !eventRows->empty()) {
            AddLog("[error] no valid telemetry events were found in the selected database.");
            return false;
        }

        if (root.is_object() && root.contains("exclusions") && root["exclusions"].is_object()) {
            const auto& exclusions = root["exclusions"];
            if (exclusions.contains("winapi")) g_WinApiExclusions = exclusions["winapi"].get<std::vector<std::string>>();
            if (exclusions.contains("network")) g_NetworkExclusions = exclusions["network"].get<std::vector<std::string>>();
            if (exclusions.contains("registry")) g_RegistryExclusions = exclusions["registry"].get<std::vector<std::string>>();
            if (exclusions.contains("files")) g_FileExclusions = exclusions["files"].get<std::vector<std::string>>();
            if (exclusions.contains("memory")) g_MemoryExclusions = exclusions["memory"].get<std::vector<std::string>>();
            if (exclusions.contains("dlls")) g_DllExclusions = exclusions["dlls"].get<std::vector<std::string>>();
            if (exclusions.contains("ipc")) g_IpcExclusions = exclusions["ipc"].get<std::vector<std::string>>();
        }

        std::vector<RecoveredStringRow> importedStrings;
        if (root.is_object() && root.contains("recovered_runtime_strings") && root["recovered_runtime_strings"].is_array()) {
            for (const auto& item : root["recovered_runtime_strings"]) {
                if (!item.is_object()) continue;
                RecoveredStringRow row;
                row.pid = item.value("pid", 0u);
                row.address = item.value("address", 0ull);
                row.value = item.value("value", "");
                row.encoding = item.value("encoding", "Unknown");
                row.classification = item.value("classification", "Runtime text");
                row.protection = item.value("protection", "?");
                row.regionType = item.value("region_type", "Other");
                row.firstSeen = item.value("first_seen", "-");
                row.lastSeen = item.value("last_seen", row.firstSeen);
                row.observations = item.value("observations", 1u);
                if (!row.value.empty()) importedStrings.push_back(std::move(row));
            }
        }

        std::vector<EtwKernelEvent> importedEtwEvents;
        if (root.is_object() && root.contains("etw_kernel_events") && root["etw_kernel_events"].is_array()) {
            for (const auto& item : root["etw_kernel_events"]) {
                if (!item.is_object()) continue;
                EtwKernelEvent event;
                event.timestamp = item.value("timestamp", 0ull);
                event.processId = item.value("process_id", 0u);
                event.threadId = item.value("thread_id", 0u);
                event.provider = item.value("provider", "");
                event.task = item.value("task", "");
                event.opcode = item.value("opcode", "");
                event.category = item.value("category", "");
                event.action = item.value("action", "");
                event.details = item.value("details", "");
                event.summary = item.value("summary", "");
                event.eventId = static_cast<uint16_t>(item.value("event_id", 0u));
                if (item.contains("properties") && item["properties"].is_array()) {
                    for (const auto& property : item["properties"]) {
                        if (property.is_object()) event.properties.push_back({
                            property.value("name", ""), property.value("value", "")
                        });
                    }
                }
                importedEtwEvents.push_back(std::move(event));
            }
        }

        if (root.is_object() && root.contains("target") && root["target"].is_object()) {
            const auto& target = root["target"];
            g_Target.path = StringToWString(target.value("path", ""));
            g_TargetProcessPath = StringToWString(target.value("process_path", target.value("path", "")));
            g_TargetCommandLine = target.value("command_line", "");
            g_Target.pid = target.value("pid", 0u);
            g_Target.active = false;
            g_Target.is32Bit = target.value("architecture", "x64") == "x86";
            g_Target.launchMode = target.value("launch_mode", "Imported analysis");
            g_ProcessRunState.store(g_Target.pid ? ProcessRunState::Terminated : ProcessRunState::NotRunning);
            UpdateProcessInfoSnapshot();
        }

        if (root.is_object() && root.contains("powershell_analysis") && root["powershell_analysis"].is_object()) {
            const auto& ps = root["powershell_analysis"];
            g_PowerShellAnalysisActive.store(false);
            g_ActivePowerShellProfile = {};
            g_ActivePowerShellProfile.originalPath = StringToWString(ps.value("target_file", ""));
            g_ActivePowerShellProfile.detectedType = StringToWString(ps.value("detected_type", "PowerShell Script (.ps1)"));
            g_ActivePowerShellProfile.launcherPath = StringToWString(ps.value("execution_host", ""));
            g_ActivePowerShellProfile.launcherArguments = StringToWString(ps.value("arguments", ""));
            g_ActivePowerShellProfile.workingDirectory = StringToWString(ps.value("working_directory", ""));
            g_ActivePowerShellProfile.executionMode = StringToWString(ps.value("execution_mode", "PowerShell Script Analysis"));
            g_ActivePowerShellProfile.powerShellVersion = StringToWString(ps.value("powershell_version", ""));
            g_ActivePowerShellProfile.executionPolicy = StringToWString(ps.value("execution_policy", ""));
            g_PowerShellCurrentUser = ps.value("current_user", "-");
            g_PowerShellIntegrityLevel = ps.value("integrity_level", "-");
            {
                AnalysisSession importedSession;
                importedSession.sessionId = "imported-" + std::to_string(CurrentUnixTimeMilliseconds());
                importedSession.originalTargetPath = g_ActivePowerShellProfile.originalPath;
                importedSession.targetType = "PowerShell";
                importedSession.targetProfile = g_ActivePowerShellProfile;
                if (ps.contains("processes") && ps["processes"].is_array()) for (const auto& item : ps["processes"]) {
                    ProcessNode node;
                    node.pid = item.value("pid", 0u); node.parentPid = item.value("parent_pid", 0u);
                    node.imagePath = StringToWString(item.value("image_path", ""));
                    node.commandLine = StringToWString(item.value("command_line", ""));
                    node.timestamp = item.value("timestamp", 0ull); node.decision = item.value("decision", "");
                    node.reason = item.value("reason", ""); node.isLauncher = item.value("is_launcher", false);
                    node.isRootTarget = item.value("is_root_target", false); node.monitored = item.value("monitored", false);
                    node.exited = item.value("exited", true); node.exitCode = item.value("exit_code", 0ul);
                    node.processName = std::filesystem::path(node.imagePath).filename().wstring();
                    node.startTime = node.timestamp;
                    node.instrumentationStatus = node.monitored ? "injected" : (node.exited ? "exited" : "command-only");
                    node.relationship = node.isLauncher ? "launcher" : (node.isRootTarget ? "root" : "monitored-child");
                    if (node.isLauncher || node.isRootTarget) importedSession.rootPid = node.pid;
                    if (node.monitored) importedSession.monitoredPids.insert(node.pid);
                    importedSession.processTreeNodes.push_back(std::move(node));
                }
                ProcessTreeManager::Instance().Restore(importedSession);
            }
            {
                std::vector<SpecializedBehaviorRecord> importedBehaviors;
                if (ps.contains("behaviors") && ps["behaviors"].is_array()) for (const auto& item : ps["behaviors"]) {
                    importedBehaviors.push_back({ item.value("timestamp", 0ull), item.value("pid", 0u),
                        item.value("behavior", ""), item.value("evidence", ""), item.value("source", "") });
                }
                SpecializedActivityStore::Instance().RestorePowerShell(std::move(importedBehaviors));
            }
        } else {
            g_PowerShellAnalysisActive.store(false);
            g_ActivePowerShellProfile = {};
            ProcessTreeManager::Instance().Reset();
            SpecializedActivityStore::Instance().ResetPowerShell();
        }

        if (root.is_object() && root.contains("process_watcher") && root["process_watcher"].is_object()) {
            auto parseWatcherRow = [](const json& item) {
                ProcessWatcherRecord row;
                row.timestamp = item.value("timestamp", 0ull);
                row.endTimestamp = item.value("end_timestamp", 0ull);
                row.pid = item.value("pid", 0u);
                row.parentPid = item.value("parent_pid", 0u);
                row.processName = item.value("process_name", "");
                row.filePath = item.value("file_path", "");
                row.commandLine = item.value("command_line", "");
                row.status = item.value("status", "");
                row.intercepted = item.value("intercepted", false);
                return row;
            };
            const auto& watcher = root["process_watcher"];
            std::lock_guard<std::mutex> watcherLock(g_ProcessWatcherMutex);
            g_ProcessWatcherCreated.clear();
            g_ProcessWatcherTerminated.clear();
            g_ProcessWatcherCommands.clear();
            if (watcher.contains("created") && watcher["created"].is_array())
                for (const auto& item : watcher["created"]) g_ProcessWatcherCreated.push_back(parseWatcherRow(item));
            if (watcher.contains("terminated") && watcher["terminated"].is_array())
                for (const auto& item : watcher["terminated"]) g_ProcessWatcherTerminated.push_back(parseWatcherRow(item));
            if (watcher.contains("commands") && watcher["commands"].is_array())
                for (const auto& item : watcher["commands"]) g_ProcessWatcherCommands.push_back(parseWatcherRow(item));
        }

        if (root.is_object() && root.contains("folder_file_watcher") && root["folder_file_watcher"].is_object()) {
            auto parseFolderRow = [](const json& item) {
                FolderFileWatcherRecord row;
                row.timestamp = item.value("timestamp", 0ull);
                row.action = item.value("action", "");
                row.objectType = item.value("object_type", "");
                row.path = item.value("path", "");
                row.oldPath = item.value("old_path", "");
                row.size = item.value("size", 0ull);
                row.note = item.value("note", "");
                return row;
            };
            const auto& watcher = root["folder_file_watcher"];
            std::lock_guard<std::mutex> folderLock(g_FolderFileWatcherMutex);
            g_FolderFileWatcherCreated.clear();
            g_FolderFileWatcherModified.clear();
            g_FolderFileWatcherRenamed.clear();
            g_FolderFileWatcherMoved.clear();
            g_FolderFileWatcherCopied.clear();
            g_FolderFileWatcherDeleted.clear();
            g_FolderFileWatcherExcludeEnabled = watcher.value("exclude_enabled", true);
            std::string excludeContains = watcher.value("exclude_contains", std::string("imgui.ini"));
            strncpy_s(g_FolderFileWatcherExcludeBuf, excludeContains.c_str(), _TRUNCATE);
            if (watcher.contains("created") && watcher["created"].is_array())
                for (const auto& item : watcher["created"]) g_FolderFileWatcherCreated.push_back(parseFolderRow(item));
            if (watcher.contains("modified") && watcher["modified"].is_array())
                for (const auto& item : watcher["modified"]) g_FolderFileWatcherModified.push_back(parseFolderRow(item));
            if (watcher.contains("renamed") && watcher["renamed"].is_array())
                for (const auto& item : watcher["renamed"]) g_FolderFileWatcherRenamed.push_back(parseFolderRow(item));
            if (watcher.contains("moved") && watcher["moved"].is_array())
                for (const auto& item : watcher["moved"]) g_FolderFileWatcherMoved.push_back(parseFolderRow(item));
            if (watcher.contains("copied") && watcher["copied"].is_array())
                for (const auto& item : watcher["copied"]) g_FolderFileWatcherCopied.push_back(parseFolderRow(item));
            if (watcher.contains("deleted") && watcher["deleted"].is_array())
                for (const auto& item : watcher["deleted"]) g_FolderFileWatcherDeleted.push_back(parseFolderRow(item));
        }

        if (root.is_object() && root.contains("net_watcher") && root["net_watcher"].is_object()) {
            auto parseNetRow = [](const json& item) {
                NetWatcherConnection row;
                row.timestamp = item.value("timestamp", 0ull);
                row.protocol = item.value("protocol", "");
                row.localAddress = item.value("local_address", "");
                row.localPort = item.value("local_port", "");
                row.remoteAddress = item.value("remote_address", "");
                row.remotePort = item.value("remote_port", "");
                row.state = item.value("state", "");
                row.pid = item.value("pid", 0u);
                row.processName = item.value("process_name", "");
                row.filePath = item.value("file_path", "");
                row.commandLine = item.value("command_line", "");
                row.excluded = item.value("excluded", false);
                return row;
            };
            const auto& watcher = root["net_watcher"];
            std::lock_guard<std::mutex> netLock(g_NetWatcherMutex);
            g_NetWatcherActive.clear();
            g_NetWatcherEvents.clear();
            g_NetWatcherHideExcluded = watcher.value("hide_excluded", true);
            g_NetWatcherDimExcluded = watcher.value("dim_excluded", true);
            if (watcher.contains("active") && watcher["active"].is_array()) {
                for (const auto& item : watcher["active"]) {
                    NetWatcherConnection row = parseNetRow(item);
                    g_NetWatcherActive[NetWatcherKey(row)] = std::move(row);
                }
            }
            if (watcher.contains("events") && watcher["events"].is_array())
                for (const auto& item : watcher["events"]) g_NetWatcherEvents.push_back(parseNetRow(item));
        }

        if (root.is_object() && root.contains("analysis_session") && root["analysis_session"].is_object()) {
            const auto& data = root["analysis_session"];
            AnalysisSession imported;
            imported.sessionId = data.value("session_id", "imported-" + std::to_string(CurrentUnixTimeMilliseconds()));
            imported.originalTargetPath = StringToWString(data.value("original_target", ""));
            imported.targetType = data.value("target_type", "Imported"); imported.rootPid = data.value("root_pid", 0u);
            imported.launcherPid = data.value("launcher_pid", 0u); imported.primaryPid = data.value("primary_pid", 0u);
            imported.startTime = data.value("start_time", 0ull); imported.endTime = data.value("end_time", 0ull); imported.active = false;
            if (data.contains("processes") && data["processes"].is_array()) for (const auto& item : data["processes"]) {
                ProcessNode node;
                node.pid = item.value("pid", 0u); node.parentPid = item.value("parent_pid", 0u);
                node.imagePath = StringToWString(item.value("image_path", "")); node.processName = StringToWString(item.value("process_name", ""));
                node.commandLine = StringToWString(item.value("command_line", "")); node.startTime = node.timestamp = item.value("start_time", 0ull);
                node.exitTime = item.value("exit_time", 0ull); node.relationship = item.value("relationship", "");
                node.instrumentationStatus = item.value("instrumentation_status", ""); node.decision = item.value("decision", "");
                node.reason = item.value("reason", ""); node.monitored = item.value("monitored", false); node.exited = item.value("exited", true);
                node.exitCode = item.value("exit_code", 0ul); node.isLauncher = node.relationship == "launcher"; node.isRootTarget = node.relationship == "root";
                if (node.instrumentationStatus == "injected" || node.instrumentationStatus == "pending") imported.monitoredPids.insert(node.pid);
                else if (node.instrumentationStatus == "command-only") imported.commandOnlyPids.insert(node.pid);
                else if (node.instrumentationStatus == "skipped") imported.skippedPids.insert(node.pid);
                if (node.exited) imported.exitedPids.insert(node.pid);
                imported.processTreeNodes.push_back(std::move(node));
            }
            ProcessTreeManager::Instance().Restore(imported);
        }

        g_OfficeAnalysisActive.store(false); g_ActiveOfficeProfile = {};
        SpecializedActivityStore::Instance().ResetOffice();
        if (root.is_object() && root.contains("office_analysis") && root["office_analysis"].is_object()) {
            const auto& office = root["office_analysis"];
            g_ActiveOfficeProfile.originalPath = StringToWString(office.value("target_file", ""));
            g_ActiveOfficeProfile.detectedType = StringToWString(office.value("detected_type", ""));
            g_ActiveOfficeProfile.officeHost = StringToWString(office.value("office_host", ""));
            g_ActiveOfficeProfile.launcherPath = StringToWString(office.value("resolved_host", ""));
            g_ActiveOfficeProfile.launcherArguments = StringToWString(office.value("arguments", ""));
            g_ActiveOfficeProfile.workingDirectory = StringToWString(office.value("working_directory", ""));
            g_ActiveOfficeProfile.executionMode = L"Office Document Analysis"; g_ActiveOfficeProfile.isOffice = !g_ActiveOfficeProfile.originalPath.empty();
            std::vector<SpecializedBehaviorRecord> importedOfficeBehaviors;
            if (office.contains("behaviors") && office["behaviors"].is_array()) for (const auto& item : office["behaviors"])
                importedOfficeBehaviors.push_back({ item.value("timestamp", 0ull), item.value("pid", 0u), item.value("behavior", ""), item.value("evidence", ""), item.value("source", "") });
            SpecializedActivityStore::Instance().RestoreOffice(std::move(importedOfficeBehaviors));
        }

        g_BatchAnalysisActive.store(false); g_ScriptAnalysisActive.store(false); g_ActiveBatchProfile = {};
        SpecializedActivityStore::Instance().ResetBatch();
        const json* importedScript = nullptr;
        if (root.is_object() && root.contains("script_analysis") && root["script_analysis"].is_object()) importedScript = &root["script_analysis"];
        else if (root.is_object() && root.contains("batch_analysis") && root["batch_analysis"].is_object()) importedScript = &root["batch_analysis"];
        if (importedScript) {
            const auto& batch = *importedScript;
            g_ActiveBatchProfile.originalPath = StringToWString(batch.value("target_file", ""));
            g_ActiveBatchProfile.detectedType = StringToWString(batch.value("detected_type", "BAT / CMD"));
            g_ActiveBatchProfile.launcherPath = StringToWString(batch.value("launcher", ""));
            g_ActiveBatchProfile.launcherArguments = StringToWString(batch.value("arguments", ""));
            g_ActiveBatchProfile.executionMode = StringToWString(batch.value("execution_mode", "Launcher-based (Command Processor)"));
            g_ActiveBatchProfile.isLauncherBased = true;
            g_TraceExecutedScriptLines = batch.value("trace_executed_lines", true);
            std::vector<SpecializedBehaviorRecord> importedCommands;
            if (batch.contains("commands") && batch["commands"].is_array()) for (const auto& item : batch["commands"]) {
                SpecializedBehaviorRecord command{0, 0, item.value("line", ""), item.value("command", ""), item.value("source", "")};
                command.observations = item.value("observations", 0u); command.firstSeen = item.value("first_seen", 0ull); command.lastSeen = item.value("last_seen", 0ull);
                importedCommands.push_back(std::move(command));
            }
            SpecializedActivityStore::Instance().RestoreBatch(std::move(importedCommands));
            g_ScriptAnalysisActive.store(batch.value("active", false));
            g_BatchAnalysisActive.store(IsBatchProfile(g_ActiveBatchProfile));
            g_ActivePowerShellProfile = g_ActiveBatchProfile;
        }

        if (root.is_object() && root.contains("static_analysis") && root["static_analysis"].is_object()) {
            const auto& data = root["static_analysis"];
            ++g_StaticAnalysisRequestToken;
            g_StaticAnalysis = {};
            g_StaticAnalysis.valid = data.value("valid", false);
            g_StaticAnalysis.path = data.value("path", "");
            g_StaticAnalysis.md5 = data.value("md5", "");
            g_StaticAnalysis.sha1 = data.value("sha1", "");
            g_StaticAnalysis.sha256 = data.value("sha256", "");
            g_StaticAnalysis.fileType = data.value("file_type", "");
            g_StaticAnalysis.architecture = data.value("architecture", "");
            g_StaticAnalysis.subsystem = data.value("subsystem", "");
            g_StaticAnalysis.entryPointRva = data.value("entry_point_rva", "");
            g_StaticAnalysis.compileTime = data.value("compile_time", "");
            g_StaticAnalysis.compilerInfo = data.value("compiler_info", "");
            g_StaticAnalysis.importSummary = data.value("import_summary", "");
            g_StaticAnalysis.status = data.value("status", "");
            if (data.contains("imported_dlls")) g_StaticAnalysis.importedDlls = data["imported_dlls"].get<std::vector<std::string>>();
            if (data.contains("imports_by_dll")) g_StaticAnalysis.importsByDll = data["imports_by_dll"].get<std::unordered_map<std::string, std::vector<std::string>>>();
            if (data.contains("suspicious_imports")) g_StaticAnalysis.suspiciousImports = data["suspicious_imports"].get<std::vector<std::string>>();
            if (data.contains("tls_callbacks")) g_StaticAnalysis.tlsCallbacks = data["tls_callbacks"].get<std::vector<std::string>>();
            if (data.contains("ascii_strings")) g_StaticAnalysis.asciiStrings = data["ascii_strings"].get<std::vector<std::string>>();
            if (data.contains("unicode_strings")) g_StaticAnalysis.unicodeStrings = data["unicode_strings"].get<std::vector<std::string>>();
            if (data.contains("sections") && data["sections"].is_array()) {
                for (const auto& item : data["sections"]) {
                    StaticAnalysisInfo::SectionRow row;
                    row.name = item.value("name", ""); row.rawSize = item.value("raw_size", 0u);
                    row.virtualSize = item.value("virtual_size", 0u); row.permissions = item.value("permissions", "");
                    row.entropy = item.value("entropy", 0.0); row.rwx = item.value("rwx", false);
                    g_StaticAnalysis.sections.push_back(std::move(row));
                }
            }
            if (data.contains("resources") && data["resources"].is_array()) {
                for (const auto& item : data["resources"]) {
                    StaticAnalysisInfo::ResourceRow row;
                    row.type = item.value("type", ""); row.name = item.value("name", "");
                    row.language = item.value("language", ""); row.size = item.value("size", 0u);
                    row.asciiPreview = item.value("ascii_preview", ""); row.hexPreview = item.value("hex_preview", "");
                    if (item.contains("data") && item["data"].is_array()) row.data = item["data"].get<std::vector<uint8_t>>();
                    g_StaticAnalysis.resources.push_back(std::move(row));
                }
            }
        }

        {
            std::lock_guard<std::mutex> lock(g_EventsMutex);
            g_Events = std::move(importedEvents);
        }
        {
            std::lock_guard<std::mutex> lock(g_DisasmCacheMutex);
            g_DisasmCache.clear();
        }
        {
            std::lock_guard<std::mutex> lock(g_ResolvedFuncStartsMutex);
            g_ResolvedFuncStarts.clear();
        }
        {
            std::lock_guard<std::mutex> lock(g_SymbolCacheMutex);
            g_CallerSymbolCache.clear();
        }
        {
            std::lock_guard<std::mutex> lock(g_ModuleContextMutex);
            g_ObservedModuleCache.clear();
        }
        {
            std::lock_guard<std::mutex> lock(g_HookStatusMutex);
            g_HookStatuses.clear();
            if (root.is_object() && root.contains("hook_statuses") && root["hook_statuses"].is_array()) {
                for (const auto& item : root["hook_statuses"]) {
                    HookStatusRow row;
                    row.apiName = item.value("api", "");
                    row.dllName = item.value("dll", "");
                    row.status = item.value("status", "");
                    row.reason = item.value("reason", "");
                    g_HookStatuses.push_back(std::move(row));
                }
            }
        }
        if (root.is_object() && root.contains("log_queue") && root["log_queue"].is_array()) {
            std::lock_guard<std::mutex> lock(g_LogsMutex);
            g_Logs = root["log_queue"].get<std::vector<std::string>>();
        }
        if (root.is_object() && root.contains("console_output") && root["console_output"].is_array()) {
            std::lock_guard<std::mutex> lock(g_ConsoleMutex);
            g_ConsoleOutput = root["console_output"].get<std::vector<std::string>>();
        }
        {
            std::lock_guard<std::mutex> lock(g_RecoveredStringsMutex);
            g_RecoveredStrings = std::move(importedStrings);
            g_RecoveredStringIndex.clear();
            for (size_t i = 0; i < g_RecoveredStrings.size(); ++i) {
                const auto& row = g_RecoveredStrings[i];
                std::string key = std::to_string(row.pid) + "|" + std::to_string(row.address) + "|" + row.encoding + "|" + row.value;
                g_RecoveredStringIndex[key] = i;
            }
        }
        {
            std::lock_guard<std::mutex> lock(g_ProcessLifecycleMutex);
            g_ControllerProcessTerminations.clear();
            if (root.is_object() && root.contains("controller_process_terminations") && root["controller_process_terminations"].is_array()) {
                for (const auto& item : root["controller_process_terminations"]) {
                    ProcessBehaviorRow row;
                    row.timestampMs = item.value("timestamp", 0ull);
                    row.time = item.value("time", "");
                    row.lastSeen = row.time;
                    row.targetPid = item.value("pid", 0u);
                    row.processId = row.targetPid;
                    row.action = item.value("action", "Process Terminated");
                    row.details = item.value("details", "");
                    if (row.details == "Target process exited or disconnected from its telemetry pipe") continue;
                    row.result = item.value("result", "");
                    row.api = "Controller Lifecycle";
                    row.callerFunction = "Inspecthor";
                    row.fromEtw = true;
                    g_ControllerProcessTerminations.push_back(std::move(row));
                }
            }
        }
        if (root.is_object() && root.contains("ui_capture_settings") && root["ui_capture_settings"].is_object()) {
            const auto& settings = root["ui_capture_settings"];
            if (settings.value("hook_network", true)) g_TraceConfig.flags |= TraceConfigHookNetwork;
            else g_TraceConfig.flags &= ~TraceConfigHookNetwork;
            if (settings.value("hook_memory_copies", false)) g_TraceConfig.flags |= TraceConfigHookMemoryCopies;
            else g_TraceConfig.flags &= ~TraceConfigHookMemoryCopies;
            // Never restore known-unsafe hook tiers from an imported database.
            g_TraceConfig.flags &= ~(TraceConfigHookHeap | TraceConfigHookAdvancedNative);
            g_ShowEtwFindings = settings.value("show_etw_findings", settings.value("network_include_etw", false));
            g_NetworkIncludeEtw = g_ShowEtwFindings;
            g_NetworkHideFailed = settings.value("network_hide_failed", false);
            g_RegistryIncludeEtw = g_ShowEtwFindings;
            g_RegistryHideFailed = settings.value("registry_hide_failed", false);
            g_FileIncludeEtw = g_ShowEtwFindings;
            g_FileHideFailed = settings.value("file_hide_failed", false);
            g_MemoryShowHeapActivity = settings.value("memory_show_heap_activity", false);
            g_MemoryShowQueryActivity = settings.value("memory_show_query_activity", false);
            g_RuntimeStringsExecutableOnly.store(settings.value("runtime_strings_executable_only", false));
            g_ProcessHideEtwFindings = !g_ShowEtwFindings;
            g_ShowBaselineApis = settings.value("show_baseline_apis", false);
        }
        ReplaceEtwKernelEvents(std::move(importedEtwEvents));
        g_SelectedEventIndex = -1;
        g_SelectedParamIndex = -1;
        g_SelectedHexDumpRow = -1;
        g_HexRangeAnchor = -1;
        g_HexRangeFocus = -1;
        g_SelectedEtwEventIndex = -1;
        g_SelectedMemoryRegionIndex = -1;
        g_SelectedMemoryRegionPid = 0;
        g_SelectedMemoryDumpData.clear();
        g_SelectedMemoryDumpAddress = 0;
        g_SelectedMemoryDumpStatus.clear();
        {
            std::lock_guard<std::mutex> dumpLock(g_MemoryDumpCacheMutex);
            g_MemoryDumpCache.clear();
        }

        size_t importedCount = 0;
        {
            std::lock_guard<std::mutex> lock(g_EventsMutex);
            importedCount = g_Events.size();
        }
        AddLog("[info] imported previous analysis database: " + std::to_string(importedCount) +
            " telemetry events and " + std::to_string(g_RecoveredStrings.size()) + " recovered runtime strings.");
        return true;
    } catch (const std::exception& ex) {
        AddLog(std::string("[error] failed to import analysis database: ") + ex.what());
        return false;
    }
}

static bool ProcessWatcherTextMatches(const ProcessWatcherRecord& row, const std::string& filterLower) {
    if (filterLower.empty()) return true;
    std::string haystack = ToLowerCopy(row.processName + " " + std::to_string(row.pid) + " " +
        std::to_string(row.parentPid) + " " + row.filePath + " " + row.commandLine + " " +
        row.status);
    return haystack.find(filterLower) != std::string::npos;
}

static void DrawProcessWatcherFlatRows(const char* tableId, const std::vector<ProcessWatcherRecord>& rows, const std::string& filterLower, bool showEndTime) {
    if (ImGui::BeginTable(tableId, showEndTime ? 7 : 6,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 86.0f);
        if (showEndTime) ImGui::TableSetupColumn("Ended", ImGuiTableColumnFlags_WidthFixed, 86.0f);
        ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 170.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 78.0f);
        ImGui::TableSetupColumn("Parent", ImGuiTableColumnFlags_WidthFixed, 78.0f);
        ImGui::TableSetupColumn("File Path", ImGuiTableColumnFlags_WidthStretch, 0.35f);
        ImGui::TableSetupColumn("Command Line", ImGuiTableColumnFlags_WidthStretch, 0.45f);
        ImGui::TableHeadersRow();
        for (auto it = rows.rbegin(); it != rows.rend(); ++it) {
            const ProcessWatcherRecord& row = *it;
            if (!ProcessWatcherTextMatches(row, filterLower)) continue;
            ImGui::TableNextRow();
            int col = 0;
            ImGui::TableSetColumnIndex(col++); ImGui::TextUnformatted(FormatTimestamp(row.timestamp).c_str());
            if (showEndTime) { ImGui::TableSetColumnIndex(col++); ImGui::TextUnformatted(FormatTimestamp(row.endTimestamp).c_str()); }
            ImGui::TableSetColumnIndex(col++); ImGui::TextUnformatted(row.processName.c_str());
            ImGui::TableSetColumnIndex(col++); ImGui::Text("%lu", row.pid);
            ImGui::TableSetColumnIndex(col++); ImGui::Text("%lu", row.parentPid);
            ImGui::TableSetColumnIndex(col++); ImGui::TextWrapped("%s", row.filePath.c_str());
            ImGui::TableSetColumnIndex(col++); ImGui::TextWrapped("%s", row.commandLine.c_str());
        }
        ImGui::EndTable();
    }
}

static void DrawProcessWatcherRunningTree(const std::vector<ProcessWatcherRecord>& rows, const std::string& filterLower) {
    std::unordered_map<DWORD, ProcessWatcherRecord> byPid;
    std::unordered_map<DWORD, std::vector<DWORD>> children;
    for (const auto& row : rows) {
        byPid[row.pid] = row;
        children[row.parentPid].push_back(row.pid);
    }
    for (auto& item : children) {
        std::sort(item.second.begin(), item.second.end(), [&](DWORD a, DWORD b) {
            return ToLowerCopy(byPid[a].processName) < ToLowerCopy(byPid[b].processName);
        });
    }

    auto visibleSubtree = [&](auto&& self, DWORD pid) -> bool {
        auto it = byPid.find(pid);
        if (it == byPid.end()) return false;
        if (ProcessWatcherTextMatches(it->second, filterLower)) return true;
        auto childIt = children.find(pid);
        if (childIt == children.end()) return false;
        for (DWORD child : childIt->second) if (self(self, child)) return true;
        return false;
    };

    if (ImGui::BeginTable("ProcessWatcherRunningTree", 5,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 280.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 78.0f);
        ImGui::TableSetupColumn("Parent", ImGuiTableColumnFlags_WidthFixed, 78.0f);
        ImGui::TableSetupColumn("File Path", ImGuiTableColumnFlags_WidthStretch, 0.40f);
        ImGui::TableSetupColumn("Command Line", ImGuiTableColumnFlags_WidthStretch, 0.55f);
        ImGui::TableHeadersRow();
        std::unordered_set<DWORD> visited;
        auto drawNode = [&](auto&& self, DWORD pid) -> void {
            if (!visited.insert(pid).second) return;
            auto it = byPid.find(pid);
            if (it == byPid.end() || !visibleSubtree(visibleSubtree, pid)) return;
            const ProcessWatcherRecord& row = it->second;
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGuiTreeNodeFlags flags = ImGuiTreeNodeFlags_SpanFullWidth;
            if (children[pid].empty()) flags |= ImGuiTreeNodeFlags_Leaf | ImGuiTreeNodeFlags_NoTreePushOnOpen;
            if (row.intercepted) ImGui::PushStyleColor(ImGuiCol_Text, kUiGold);
            const std::string baseName = ToLowerCopy(ProcessWatcherBaseName(row.processName));
            if (baseName == "explorer.exe" || baseName == "services.exe") ImGui::SetNextItemOpen(true, ImGuiCond_Once);
            const bool open = ImGui::TreeNodeEx((void*)(uintptr_t)pid, flags, "%s", row.processName.c_str());
            if (row.intercepted) ImGui::PopStyleColor();
            ImGui::TableSetColumnIndex(1); ImGui::Text("%lu", row.pid);
            ImGui::TableSetColumnIndex(2); ImGui::Text("%lu", row.parentPid);
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.filePath.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.commandLine.c_str());
            if (open && !(flags & ImGuiTreeNodeFlags_NoTreePushOnOpen)) {
                for (DWORD child : children[pid]) self(self, child);
                ImGui::TreePop();
            }
        };
        std::vector<DWORD> roots;
        for (const auto& row : rows) if (!row.parentPid || byPid.find(row.parentPid) == byPid.end()) roots.push_back(row.pid);
        std::sort(roots.begin(), roots.end(), [&](DWORD a, DWORD b) {
            return ToLowerCopy(byPid[a].processName) < ToLowerCopy(byPid[b].processName);
        });
        for (DWORD root : roots) drawNode(drawNode, root);
        ImGui::EndTable();
    }
}

static void DrawProcessWatcherView() {
    std::vector<ProcessWatcherRecord> liveRows, createdRows, terminatedRows, commandRows;
    {
        std::lock_guard<std::mutex> lock(g_ProcessWatcherMutex);
        for (const auto& pair : g_ProcessWatcherLive) liveRows.push_back(pair.second);
        createdRows = g_ProcessWatcherCreated;
        terminatedRows = g_ProcessWatcherTerminated;
        commandRows = g_ProcessWatcherCommands;
    }
    std::sort(liveRows.begin(), liveRows.end(), [](const auto& a, const auto& b) {
        if (a.parentPid != b.parentPid) return a.parentPid < b.parentPid;
        return ToLowerCopy(a.processName) < ToLowerCopy(b.processName);
    });

    ImGui::BeginChild("ProcessWatcherRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Process Monitor", "");
    ImGui::TextColored(g_ProcessWatcherRunning.load() ? kUiGreen : kUiRed, "%s",
        g_ProcessWatcherRunning.load() ? "Monitoring: ON" : "Monitoring: OFF");
    ImGui::SameLine();
    ImGui::TextColored(kUiTextMuted, "| Running: %zu | Created: %zu | Commands: %zu | Terminated: %zu",
        liveRows.size(), createdRows.size(), commandRows.size(), terminatedRows.size());
    ImGui::SameLine();
    const float clearButtonX = ImGui::GetWindowContentRegionMax().x - 88.0f;
    if (ImGui::GetCursorPosX() < clearButtonX) ImGui::SetCursorPosX(clearButtonX);
    DrawControlButtonPalette();
    if (ImGui::Button("Clear", ImVec2(82.0f, 26.0f))) {
        std::lock_guard<std::mutex> lock(g_ProcessWatcherMutex);
        g_ProcessWatcherCommands.clear();
        g_ProcessWatcherTerminated.clear();
        g_ProcessWatcherCreated.clear();
        commandRows.clear();
        terminatedRows.clear();
        createdRows.clear();
    }
    ImGui::PopStyleColor(4);
    ImGui::Spacing();
    ImGui::SetNextItemWidth(360.0f);
    ImGui::InputTextWithHint("##ProcessWatcherSearch", "Filter process, PID, path, command...", g_ProcessWatcherSearchBuf, sizeof(g_ProcessWatcherSearchBuf));
    const std::string filterLower = ToLowerCopy(g_ProcessWatcherSearchBuf);
    ImGui::Spacing();

    if (ImGui::BeginTabBar("ProcessWatcherTabs")) {
        if (ImGui::BeginTabItem("Running Processes")) {
            DrawProcessWatcherRunningTree(liveRows, filterLower);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Created Processes", createdRows.size())) {
            DrawProcessWatcherFlatRows("ProcessWatcherCreated", createdRows, filterLower, false);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Command Executions", commandRows.size())) {
            DrawProcessWatcherFlatRows("ProcessWatcherCommands", commandRows, filterLower, false);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Terminated Processes", terminatedRows.size())) {
            DrawProcessWatcherFlatRows("ProcessWatcherTerminated", terminatedRows, filterLower, true);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();
}

static bool FolderFileWatcherTextMatches(const FolderFileWatcherRecord& row, const std::string& filterLower) {
    if (filterLower.empty()) return true;
    std::string haystack = ToLowerCopy(row.action + " " + row.objectType + " " + row.path + " " +
        row.oldPath + " " + row.note);
    return haystack.find(filterLower) != std::string::npos;
}

static bool FolderFileWatcherIsExcluded(const FolderFileWatcherRecord& row) {
    if (!g_FolderFileWatcherExcludeEnabled) return false;
    std::string patterns = g_FolderFileWatcherExcludeBuf;
    std::replace(patterns.begin(), patterns.end(), ';', ',');
    std::stringstream ss(patterns);
    std::string pattern;
    const std::string haystack = row.path + " " + row.oldPath + " " + row.note;
    while (std::getline(ss, pattern, ',')) {
        pattern.erase(pattern.begin(), std::find_if(pattern.begin(), pattern.end(), [](unsigned char ch) { return !std::isspace(ch); }));
        pattern.erase(std::find_if(pattern.rbegin(), pattern.rend(), [](unsigned char ch) { return !std::isspace(ch); }).base(), pattern.end());
        if (!pattern.empty() && StringContainsInsensitive(haystack, pattern)) return true;
    }
    return false;
}

