static void DrawFolderFileWatcherView() {
    std::vector<FolderFileWatcherRecord> createdRows, modifiedRows, renamedRows, movedRows, copiedRows, deletedRows;
    {
        std::lock_guard<std::mutex> lock(g_FolderFileWatcherMutex);
        createdRows = g_FolderFileWatcherCreated;
        modifiedRows = g_FolderFileWatcherModified;
        renamedRows = g_FolderFileWatcherRenamed;
        movedRows = g_FolderFileWatcherMoved;
        copiedRows = g_FolderFileWatcherCopied;
        deletedRows = g_FolderFileWatcherDeleted;
    }
    const size_t visibleCreated = CountVisibleFolderFileWatcherRows(createdRows);
    const size_t visibleModified = CountVisibleFolderFileWatcherRows(modifiedRows);
    const size_t visibleRenamed = CountVisibleFolderFileWatcherRows(renamedRows);
    const size_t visibleMoved = CountVisibleFolderFileWatcherRows(movedRows);
    const size_t visibleCopied = CountVisibleFolderFileWatcherRows(copiedRows);
    const size_t visibleDeleted = CountVisibleFolderFileWatcherRows(deletedRows);
    const size_t totalEvents = visibleCreated + visibleModified + visibleRenamed + visibleMoved + visibleCopied + visibleDeleted;

    ImGui::BeginChild("FolderFileWatcherRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("File Monitor", "");
    ImGui::TextColored(g_FolderFileWatcherRunning.load() ? kUiGreen : kUiRed, "%s",
        g_FolderFileWatcherRunning.load() ? "Monitoring: ON" : "Monitoring: OFF");
    ImGui::SameLine();
    ImGui::TextColored(kUiTextMuted, "| Events: %zu | Exclude: %s",
        totalEvents, g_FolderFileWatcherExcludeEnabled ? g_FolderFileWatcherExcludeBuf : "OFF");
    ImGui::Spacing();

    ImGui::Checkbox("Exclude matching findings", &g_FolderFileWatcherExcludeEnabled);
    ImGui::SameLine();
    ImGui::SetNextItemWidth(320.0f);
    ImGui::InputTextWithHint("##FolderFileWatcherExclude", "Comma-separated path text, e.g. imgui.ini", g_FolderFileWatcherExcludeBuf, sizeof(g_FolderFileWatcherExcludeBuf));
    ImGui::SameLine();
    DrawControlButtonPalette();
    if (ImGui::Button("Clear", ImVec2(82.0f, 26.0f))) {
        std::lock_guard<std::mutex> lock(g_FolderFileWatcherMutex);
        g_FolderFileWatcherCreated.clear();
        g_FolderFileWatcherModified.clear();
        g_FolderFileWatcherRenamed.clear();
        g_FolderFileWatcherMoved.clear();
        g_FolderFileWatcherCopied.clear();
        g_FolderFileWatcherDeleted.clear();
        createdRows.clear(); modifiedRows.clear(); renamedRows.clear(); movedRows.clear();
        copiedRows.clear(); deletedRows.clear();
    }
    ImGui::PopStyleColor(4);

    ImGui::SetNextItemWidth(420.0f);
    ImGui::InputTextWithHint("##FolderFileWatcherSearch", "Filter action, type, path, note...", g_FolderFileWatcherSearchBuf, sizeof(g_FolderFileWatcherSearchBuf));
    const std::string filterLower = ToLowerCopy(g_FolderFileWatcherSearchBuf);
    ImGui::Spacing();
    ImGui::TextColored(kUiTextMuted, "Best-effort user-mode watcher. Process attribution requires ETW correlation or a filesystem driver.");
    ImGui::Spacing();

    if (ImGui::BeginTabBar("FolderFileWatcherTabs")) {
        if (BeginFindingTabItem("Created Files/Folders", visibleCreated)) {
            DrawFolderFileWatcherRows("FolderFileWatcherCreated", createdRows, filterLower, false, true);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Modified Files", visibleModified)) {
            DrawFolderFileWatcherRows("FolderFileWatcherModified", modifiedRows, filterLower, false, true);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Renamed Files/Folders", visibleRenamed)) {
            DrawFolderFileWatcherRows("FolderFileWatcherRenamed", renamedRows, filterLower, true, true);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Moved Files/Folders", visibleMoved)) {
            DrawFolderFileWatcherRows("FolderFileWatcherMoved", movedRows, filterLower, true, true);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Copied Files", visibleCopied)) {
            DrawFolderFileWatcherRows("FolderFileWatcherCopied", copiedRows, filterLower, false, true);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Deleted Files/Folders", visibleDeleted)) {
            DrawFolderFileWatcherRows("FolderFileWatcherDeleted", deletedRows, filterLower, false, true);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();
}

static bool NetWatcherMatchesSearch(const NetWatcherConnection& row, const std::string& filter) {
    if (filter.empty()) return true;
    return StringContainsInsensitive(row.protocol + " " + row.localAddress + " " + row.localPort + " " +
        row.remoteAddress + " " + row.remotePort + " " + row.state + " " + std::to_string(row.pid) + " " +
        row.processName + " " + row.filePath + " " + row.commandLine, filter);
}

static size_t CountVisibleNetWatcherRows(const std::vector<NetWatcherConnection>& rows) {
    return static_cast<size_t>(std::count_if(rows.begin(), rows.end(), [](const NetWatcherConnection& row) {
        return !(g_NetWatcherHideExcluded && row.excluded);
    }));
}

static size_t CountVisibleNetWatcherIndicators(const std::vector<NetworkIndicatorRow>& rows) {
    return static_cast<size_t>(std::count_if(rows.begin(), rows.end(), [](const NetworkIndicatorRow& row) {
        return !(g_NetWatcherHideExcluded && row.excluded);
    }));
}

static void AddNetWatcherIndicatorManual(std::unordered_map<std::string, NetworkIndicatorRow>& map,
    const std::string& value,
    const std::string& type,
    const std::string& time,
    const std::string& source,
    const std::string& caller) {
    std::string clean = TrimNetworkValue(value);
    if (clean.empty() || clean == "-") return;
    std::string key = ToLowerCopy(type + ":" + clean);
    auto& row = map[key];
    if (row.count == 0) {
        row.value = clean;
        row.type = type;
        row.firstSeen = time.empty() ? "-" : time;
        row.sourceApi = source;
        row.callerFunction = caller;
        row.excluded = NetworkMatchesExclusion(clean) ||
            (type == "URL" && NetworkMatchesExclusion(ExtractHostFromUrl(clean)));
    }
    row.lastSeen = time.empty() ? row.firstSeen : time;
    row.count++;
}

static void MergeNetWatcherPassiveIndicators(NetworkActivitySnapshot& snapshot) {
    std::unordered_map<std::string, NetworkIndicatorRow> domainMap;
    std::unordered_map<std::string, NetworkIndicatorRow> urlMap;
    for (const auto& row : snapshot.domains) domainMap[ToLowerCopy(row.type + ":" + row.value)] = row;
    for (const auto& row : snapshot.urls) urlMap[ToLowerCopy(row.type + ":" + row.value)] = row;

    {
        std::lock_guard<std::mutex> lock(g_NetWatcherMutex);
        for (const auto& pair : g_NetWatcherDnsDomains) {
            domainMap[pair.first] = pair.second;
        }
    }

    std::vector<SysmonEventRow> sysmonRows;
    {
        std::lock_guard<std::mutex> lock(g_SysmonMutex);
        sysmonRows = g_SysmonEvents;
    }
    for (const auto& row : sysmonRows) {
        auto field = [&](const char* name) {
            auto it = row.fields.find(name);
            return it == row.fields.end() ? std::string{} : it->second;
        };
        if (row.eventId == 22) {
            AddNetWatcherIndicatorManual(domainMap, row.queryName, "Domain", row.time, "Sysmon DNS", BaseNameFromPathOrCommand(row.image));
        }
        if (row.eventId == 3) {
            AddNetWatcherIndicatorManual(domainMap, field("DestinationHostname"), "Domain", row.time, "Sysmon Network", BaseNameFromPathOrCommand(row.image));
        }
        for (const auto& url : ExtractUrlsFromText(row.commandLine)) {
            AddNetWatcherIndicatorManual(urlMap, url, "URL", row.time, "Sysmon CommandLine", BaseNameFromPathOrCommand(row.image));
            AddNetWatcherIndicatorManual(domainMap, ExtractHostFromUrl(url), "Domain", row.time, "Sysmon CommandLine", BaseNameFromPathOrCommand(row.image));
        }
    }

    std::vector<ProcessWatcherRecord> processRows;
    {
        std::lock_guard<std::mutex> lock(g_ProcessWatcherMutex);
        for (const auto& pair : g_ProcessWatcherLive) processRows.push_back(pair.second);
        processRows.insert(processRows.end(), g_ProcessWatcherCreated.begin(), g_ProcessWatcherCreated.end());
        processRows.insert(processRows.end(), g_ProcessWatcherCommands.begin(), g_ProcessWatcherCommands.end());
    }
    for (const auto& row : processRows) {
        for (const auto& url : ExtractUrlsFromText(row.commandLine)) {
            const std::string time = FormatTimestamp(row.timestamp);
            const std::string caller = row.processName.empty() ? ProcessWatcherBaseName(row.filePath) : row.processName;
            AddNetWatcherIndicatorManual(urlMap, url, "URL", time, "Process CommandLine", caller);
            AddNetWatcherIndicatorManual(domainMap, ExtractHostFromUrl(url), "Domain", time, "Process CommandLine", caller);
        }
    }

    snapshot.domains.clear();
    snapshot.urls.clear();
    for (auto& pair : domainMap) snapshot.domains.push_back(std::move(pair.second));
    for (auto& pair : urlMap) snapshot.urls.push_back(std::move(pair.second));
    std::sort(snapshot.domains.begin(), snapshot.domains.end(), [](const NetworkIndicatorRow& a, const NetworkIndicatorRow& b) {
        return a.lastSeen > b.lastSeen;
    });
    std::sort(snapshot.urls.begin(), snapshot.urls.end(), [](const NetworkIndicatorRow& a, const NetworkIndicatorRow& b) {
        return a.lastSeen > b.lastSeen;
    });
}

static std::vector<NetWatcherConnection> NetWatcherActiveRowsSnapshot() {
    std::vector<NetWatcherConnection> rows;
    std::lock_guard<std::mutex> lock(g_NetWatcherMutex);
    rows.reserve(g_NetWatcherActive.size());
    for (const auto& pair : g_NetWatcherActive) rows.push_back(pair.second);
    return rows;
}

