static void DrawNetWatcherIpTable(const std::vector<NetWatcherConnection>& rows, const std::string& filter) {
    struct IpRow { std::string ip; size_t count = 0; std::string firstSeen; std::string lastSeen; std::string processes; bool excluded = false; };
    std::unordered_map<std::string, IpRow> map;
    for (const auto& row : rows) {
        if (g_NetWatcherHideExcluded && row.excluded) continue;
        if (row.remoteAddress.empty() || row.remoteAddress == "-" || row.remoteAddress == "0.0.0.0" || row.remoteAddress == "::") continue;
        auto& item = map[row.remoteAddress];
        if (item.count == 0) {
            item.ip = row.remoteAddress;
            item.firstSeen = FormatTimestamp(row.timestamp);
            item.excluded = NetworkMatchesExclusion(row.remoteAddress);
        }
        item.lastSeen = FormatTimestamp(row.timestamp);
        item.count++;
        if (item.processes.find(row.processName) == std::string::npos) {
            if (!item.processes.empty()) item.processes += ", ";
            item.processes += row.processName;
        }
    }
    std::vector<IpRow> ipRows;
    for (auto& pair : map) ipRows.push_back(std::move(pair.second));
    std::sort(ipRows.begin(), ipRows.end(), [](const IpRow& a, const IpRow& b) { return a.count > b.count; });
    if (ImGui::BeginTable("NetWatcherIpIndicators", 5,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("IP Address", ImGuiTableColumnFlags_WidthFixed, 180.0f);
        ImGui::TableSetupColumn("Count", ImGuiTableColumnFlags_WidthFixed, 80.0f);
        ImGui::TableSetupColumn("First Seen", ImGuiTableColumnFlags_WidthFixed, 95.0f);
        ImGui::TableSetupColumn("Last Seen", ImGuiTableColumnFlags_WidthFixed, 95.0f);
        ImGui::TableSetupColumn("Processes", ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableHeadersRow();
        for (const auto& row : ipRows) {
            if (!filter.empty() && !StringContainsInsensitive(row.ip + " " + row.processes, filter)) continue;
            if (row.excluded && g_NetWatcherHideExcluded) continue;
            if (row.excluded && g_NetWatcherDimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0); ImGui::TextUnformatted(row.ip.c_str());
            if (ImGui::BeginPopupContextItem("NetWatcherIpContext")) {
                if (ImGui::MenuItem("Copy IP")) CopyToClipboard(row.ip);
                if (ImGui::MenuItem("Lookup IP in VT")) LookupNetworkIndicatorInVirusTotal("IP Address", row.ip);
                if (ImGui::MenuItem("Exclude IP")) g_NetworkExclusions.push_back("ip:" + row.ip);
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%zu", row.count);
            ImGui::TableSetColumnIndex(2); ImGui::TextUnformatted(row.firstSeen.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextUnformatted(row.lastSeen.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.processes.c_str());
            if (row.excluded && g_NetWatcherDimExcluded) ImGui::PopStyleColor();
        }
        ImGui::EndTable();
    }
}

static void DrawNetWatcherIndicatorTable(const char* tableId, const std::vector<NetworkIndicatorRow>& rows, const std::string& filter) {
    if (ImGui::BeginTable(tableId, 6,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("Value", ImGuiTableColumnFlags_WidthStretch, 0.45f);
        ImGui::TableSetupColumn("Count", ImGuiTableColumnFlags_WidthFixed, 70.0f);
        ImGui::TableSetupColumn("First Seen", ImGuiTableColumnFlags_WidthFixed, 95.0f);
        ImGui::TableSetupColumn("Last Seen", ImGuiTableColumnFlags_WidthFixed, 95.0f);
        ImGui::TableSetupColumn("Source API", ImGuiTableColumnFlags_WidthFixed, 160.0f);
        ImGui::TableSetupColumn("Module", ImGuiTableColumnFlags_WidthStretch, 0.30f);
        ImGui::TableHeadersRow();
        for (size_t i = 0; i < rows.size(); ++i) {
            const auto& row = rows[i];
            if (g_NetWatcherHideExcluded && row.excluded) continue;
            if (!NetworkIndicatorMatchesSearch(row, filter)) continue;
            ImGui::PushID((int)i);
            if (row.excluded && g_NetWatcherDimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGui::Selectable(row.value.c_str(), false, ImGuiSelectableFlags_SpanAllColumns);
            if (ImGui::BeginPopupContextItem("NetWatcherIndicatorContext")) {
                if (ImGui::MenuItem("Copy Value")) CopyToClipboard(row.value);
                if ((row.type == "IP Address" || row.type == "Domain") && ImGui::MenuItem("Lookup in VirusTotal"))
                    LookupNetworkIndicatorInVirusTotal(row.type, row.value);
                if (row.type == "URL" && ImGui::MenuItem("Open URL")) ShellExecuteW(nullptr, L"open", StringToWString(row.value).c_str(), nullptr, nullptr, SW_SHOWNORMAL);
                if (ImGui::MenuItem("Add to Network Exclusions")) {
                    if (row.type == "Domain") g_NetworkExclusions.push_back("domain:" + row.value);
                    else if (row.type == "IP Address") g_NetworkExclusions.push_back("ip:" + row.value);
                    else g_NetworkExclusions.push_back(row.value);
                }
                ImGui::EndPopup();
            }
            ImGui::TableSetColumnIndex(1); ImGui::Text("%d", row.count);
            ImGui::TableSetColumnIndex(2); ImGui::TextUnformatted(row.firstSeen.c_str());
            ImGui::TableSetColumnIndex(3); ImGui::TextUnformatted(row.lastSeen.c_str());
            ImGui::TableSetColumnIndex(4); DrawApiNameWithContext(row.sourceApi);
            ImGui::TableSetColumnIndex(5); ImGui::TextWrapped("%s", ExtractModuleName(row.callerFunction).c_str());
            if (row.excluded && g_NetWatcherDimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static void DrawNetWatcherProcessTable(const std::vector<NetWatcherConnection>& rows, const std::string& filter) {
    struct ProcRow { DWORD pid = 0; std::string process; std::string path; size_t count = 0; std::string endpoints; };
    std::unordered_map<DWORD, ProcRow> map;
    for (const auto& row : rows) {
        if (g_NetWatcherHideExcluded && row.excluded) continue;
        auto& item = map[row.pid];
        if (item.count == 0) { item.pid = row.pid; item.process = row.processName; item.path = row.filePath; }
        item.count++;
        const std::string endpoint = row.remoteAddress == "-" ? row.localAddress + ":" + row.localPort : row.remoteAddress + ":" + row.remotePort;
        if (item.endpoints.find(endpoint) == std::string::npos) {
            if (!item.endpoints.empty()) item.endpoints += ", ";
            item.endpoints += endpoint;
        }
    }
    std::vector<ProcRow> procRows;
    for (auto& pair : map) procRows.push_back(std::move(pair.second));
    std::sort(procRows.begin(), procRows.end(), [](const ProcRow& a, const ProcRow& b) { return a.count > b.count; });
    if (ImGui::BeginTable("NetWatcherProcesses", 5,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 76.0f);
        ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 170.0f);
        ImGui::TableSetupColumn("Connections", ImGuiTableColumnFlags_WidthFixed, 100.0f);
        ImGui::TableSetupColumn("Endpoints", ImGuiTableColumnFlags_WidthStretch, 0.45f);
        ImGui::TableSetupColumn("Path", ImGuiTableColumnFlags_WidthStretch, 0.55f);
        ImGui::TableHeadersRow();
        for (const auto& row : procRows) {
            if (!filter.empty() && !StringContainsInsensitive(row.process + " " + row.path + " " + row.endpoints + " " + std::to_string(row.pid), filter)) continue;
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0); ImGui::Text("%lu", row.pid);
            ImGui::TableSetColumnIndex(1); ImGui::TextUnformatted(row.process.c_str());
            ImGui::TableSetColumnIndex(2); ImGui::Text("%zu", row.count);
            ImGui::TableSetColumnIndex(3); ImGui::TextWrapped("%s", row.endpoints.c_str());
            ImGui::TableSetColumnIndex(4); ImGui::TextWrapped("%s", row.path.c_str());
        }
        ImGui::EndTable();
    }
}

static void DrawNetWatcherView() {
    if (g_SysmonAutoRefresh && (g_SysmonLastRefreshMs.load() == 0 || CurrentUnixTimeMilliseconds() - g_SysmonLastRefreshMs.load() > 10000))
        StartSysmonRefreshAsync();
    std::vector<NetWatcherConnection> activeRows, eventRows;
    std::vector<TelemetryEvent> eventsSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_NetWatcherMutex);
        activeRows.reserve(g_NetWatcherActive.size());
        for (const auto& pair : g_NetWatcherActive) activeRows.push_back(pair.second);
        eventRows = g_NetWatcherEvents;
    }
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        if (g_NetWatcherTelemetryBaseline < g_Events.size())
            eventsSnapshot.assign(g_Events.begin() + static_cast<std::ptrdiff_t>(g_NetWatcherTelemetryBaseline), g_Events.end());
    }
    std::vector<ObservedModule> modules = GetObservedModules(eventsSnapshot);
    NetworkActivitySnapshot networkSnapshot = BuildNetworkActivitySnapshotForUi(eventsSnapshot, modules);
    MergeNetWatcherPassiveIndicators(networkSnapshot);
    std::sort(activeRows.begin(), activeRows.end(), [](const auto& a, const auto& b) {
        if (a.pid != b.pid) return a.pid < b.pid;
        return a.remoteAddress < b.remoteAddress;
    });

    ImGui::BeginChild("NetWatcherRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Network Monitor", "");
    ImGui::TextColored(g_NetWatcherRunning.load() ? kUiGreen : kUiRed, "%s",
        g_NetWatcherRunning.load() ? "Monitoring: ON" : "Monitoring: OFF");
    ImGui::SameLine();
    ImGui::TextColored(kUiTextMuted, "| Active: %zu | Events: %zu | Domains: %zu | URLs: %zu",
        CountVisibleNetWatcherRows(activeRows), CountVisibleNetWatcherRows(eventRows),
        CountVisibleNetWatcherIndicators(networkSnapshot.domains), CountVisibleNetWatcherIndicators(networkSnapshot.urls));
    ImGui::SameLine();
    DrawControlButtonPalette();
    if (ImGui::Button("Clear", ImVec2(82.0f, 26.0f))) {
        std::lock_guard<std::mutex> lock(g_NetWatcherMutex);
        g_NetWatcherEvents.clear();
        g_NetWatcherActive.clear();
        g_NetWatcherDnsDomains.clear();
        activeRows.clear();
        eventRows.clear();
        {
            std::lock_guard<std::mutex> eventsLock(g_EventsMutex);
            g_NetWatcherTelemetryBaseline = g_Events.size();
        }
        networkSnapshot = {};
    }
    ImGui::PopStyleColor(4);
    ImGui::Spacing();

    ImGui::SetNextItemWidth(360.0f);
    ImGui::InputTextWithHint("##NetWatcherSearch", "Filter process, PID, IP, port, state, path...", g_NetWatcherSearchBuf, sizeof(g_NetWatcherSearchBuf));
    ImGui::SameLine();
    ImGui::Checkbox("Hide excluded", &g_NetWatcherHideExcluded);
    ImGui::SameLine();
    ImGui::Checkbox("Dim excluded", &g_NetWatcherDimExcluded);
    const std::string filterLower = ToLowerCopy(g_NetWatcherSearchBuf);
    ImGui::Spacing();
    ImGui::TextColored(kUiTextMuted, "Uses TCP/UDP tables for IP endpoints and DNS cache/Sysmon/API telemetry for domains. URLs come from process command lines or captured HTTP/API payloads.");
    ImGui::Spacing();

    if (ImGui::BeginTabBar("NetWatcherTabs")) {
        if (BeginFindingTabItem("Active Connections", CountVisibleNetWatcherRows(activeRows))) {
            DrawNetWatcherConnectionTable("NetWatcherActiveConnections", activeRows, filterLower);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Connection Events", CountVisibleNetWatcherRows(eventRows))) {
            DrawNetWatcherConnectionTable("NetWatcherConnectionEvents", eventRows, filterLower);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("IP Addresses", CountVisibleNetWatcherRows(eventRows))) {
            DrawNetWatcherIpTable(eventRows, filterLower);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Domains", CountVisibleNetWatcherIndicators(networkSnapshot.domains))) {
            DrawNetWatcherIndicatorTable("NetWatcherDomains", networkSnapshot.domains, filterLower);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("URLs", CountVisibleNetWatcherIndicators(networkSnapshot.urls))) {
            DrawNetWatcherIndicatorTable("NetWatcherUrls", networkSnapshot.urls, filterLower);
            ImGui::EndTabItem();
        }
        if (BeginFindingTabItem("Processes", CountVisibleNetWatcherRows(activeRows))) {
            DrawNetWatcherProcessTable(activeRows, filterLower);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();
}

static bool IsInjectWatcherApi(const std::string& api) {
    return api == "WriteProcessMemory" || api == "NtWriteVirtualMemory" || api == "ZwWriteVirtualMemory" ||
        api == "NtMapViewOfSection" || api == "MapViewOfFile" || api == "MapViewOfFileEx" ||
        api == "RtlDecompressBuffer";
}

static std::string InjectWatcherOperation(const std::string& api) {
    if (api == "WriteProcessMemory" || api == "NtWriteVirtualMemory" || api == "ZwWriteVirtualMemory") return "Remote Memory Write";
    if (api == "NtMapViewOfSection") return "Section Mapping";
    if (api == "MapViewOfFile" || api == "MapViewOfFileEx") return "Mapped View";
    if (api == "RtlDecompressBuffer") return "Runtime Decompression";
    return "Injection / Memory Modification";
}

static bool InjectWatcherSucceeded(const TelemetryEvent& ev) {
    if (ev.apiName.rfind("Nt", 0) == 0 || ev.apiName.rfind("Zw", 0) == 0 || ev.apiName == "RtlDecompressBuffer")
        return static_cast<int32_t>(ev.returnValue) >= 0;
    return ev.returnValue != 0 && ev.returnValue != UINT64_MAX;
}

static const ParameterCapture* InjectWatcherBufferParam(const TelemetryEvent& ev, std::string& kind) {
    if (ev.apiName == "WriteProcessMemory" || ev.apiName == "NtWriteVirtualMemory" || ev.apiName == "ZwWriteVirtualMemory") {
        kind = "Write Buffer";
        return FindParam(ev, "lpBuffer");
    }
    if (ev.apiName == "MapViewOfFile" || ev.apiName == "MapViewOfFileEx") {
        kind = "Mapped Bytes";
        return FindParam(ev, "MappedBytes");
    }
    if (ev.apiName == "RtlDecompressBuffer") {
        kind = "Uncompressed Buffer";
        const ParameterCapture* output = FindParam(ev, "UncompressedBuffer");
        if (output && !output->memory.empty()) return output;
        kind = "Compressed Buffer";
        return FindParam(ev, "CompressedBuffer");
    }
    kind.clear();
    return nullptr;
}

static std::vector<InjectWatcherRow> BuildInjectWatcherRows(const std::vector<TelemetryEvent>& events) {
    std::vector<InjectWatcherRow> rows;
    rows.reserve(events.size());
    for (size_t i = 0; i < events.size(); ++i) {
        const TelemetryEvent& ev = events[i];
        if (!IsInjectWatcherApi(ev.apiName)) continue;
        InjectWatcherRow row;
        row.eventIndex = static_cast<int>(i);
        row.timestamp = ev.timestamp;
        row.sourcePid = ev.processId;
        row.targetPid = static_cast<DWORD>(ParamValueOrZero(ev, "dwProcessId"));
        if (!row.targetPid) row.targetPid = ev.processId;
        row.sourceProcess = ev.processName.empty() ? BaseNameFromPathOrCommand(ev.processPath) : ev.processName;
        row.operation = InjectWatcherOperation(ev.apiName);
        row.api = ev.apiName;
        row.result = InjectWatcherSucceeded(ev) ? "SUCCESS" : ("FAILED (" + FormatHexValue(ev.returnValue) + ")");
        row.callerFunction = ev.callerModule.empty() ? FormatHexValue(ev.callerAddress) : ev.callerModule;
        if (ev.apiName == "NtMapViewOfSection") {
            row.address = ParamValueOrZero(ev, "BaseAddress");
            row.requestedSize = static_cast<size_t>(ParamValueOrZero(ev, "ViewSize"));
        } else if (ev.apiName == "MapViewOfFile" || ev.apiName == "MapViewOfFileEx") {
            row.address = ev.returnValue;
            row.requestedSize = static_cast<size_t>(ParamValueOrZero(ev, "dwNumberOfBytesToMap"));
        } else if (ev.apiName == "RtlDecompressBuffer") {
            row.address = ParamValueOrZero(ev, "UncompressedBuffer");
            row.requestedSize = static_cast<size_t>(ParamValueOrZero(ev, "UncompressedSize"));
        } else {
            row.address = ParamValueOrZero(ev, "lpBaseAddress");
            row.requestedSize = static_cast<size_t>(ParamValueOrZero(ev, "nSize"));
        }
        std::string kind;
        const ParameterCapture* buffer = InjectWatcherBufferParam(ev, kind);
        row.bufferKind = kind;
        if (buffer) row.buffer = buffer->memory;
        row.capturedSize = row.buffer.size();
        rows.push_back(std::move(row));
    }
    return rows;
}

static bool InjectWatcherRowMatches(const InjectWatcherRow& row, const std::string& filter) {
    if (filter.empty()) return true;
    return StringContainsInsensitive(row.operation + " " + row.api + " " + row.sourceProcess + " " +
        row.result + " " + row.callerFunction + " " + FormatHexValue(row.address) + " " +
        std::to_string(row.sourcePid) + " " + std::to_string(row.targetPid), filter);
}

