static std::string XmlDecode(std::string value) {
    auto replaceAll = [](std::string& text, const std::string& from, const std::string& to) {
        size_t pos = 0;
        while ((pos = text.find(from, pos)) != std::string::npos) {
            text.replace(pos, from.size(), to);
            pos += to.size();
        }
    };
    replaceAll(value, "&lt;", "<");
    replaceAll(value, "&gt;", ">");
    replaceAll(value, "&quot;", "\"");
    replaceAll(value, "&apos;", "'");
    replaceAll(value, "&amp;", "&");
    return value;
}

static std::string XmlTagValue(const std::string& xml, const std::string& tag) {
    const std::string open = "<" + tag + ">";
    const std::string close = "</" + tag + ">";
    size_t start = xml.find(open);
    if (start == std::string::npos) return "";
    start += open.size();
    size_t end = xml.find(close, start);
    if (end == std::string::npos) return "";
    return XmlDecode(xml.substr(start, end - start));
}

static std::string XmlAttributeValue(const std::string& xml, const std::string& marker, const std::string& attribute) {
    size_t start = xml.find(marker);
    if (start == std::string::npos) return "";
    size_t attr = xml.find(attribute + "='", start);
    size_t quoteLen = 2;
    if (attr == std::string::npos) {
        attr = xml.find(attribute + "=\"", start);
        quoteLen = 2;
    }
    if (attr == std::string::npos) return "";
    attr += attribute.size() + quoteLen;
    const char quote = xml[attr - 1];
    size_t end = xml.find(quote, attr);
    if (end == std::string::npos) return "";
    return XmlDecode(xml.substr(attr, end - attr));
}

static std::string SysmonCleanTime(std::string value) {
    if (value.empty()) return "-";
    std::replace(value.begin(), value.end(), 'T', ' ');
    size_t dot = value.find('.');
    if (dot != std::string::npos) value.erase(dot);
    if (!value.empty() && value.back() == 'Z') value.pop_back();
    if (value.size() >= 19) return value.substr(0, 19);
    return value;
}

static std::string SysmonField(const SysmonEventRow& row, const std::string& key) {
    auto it = row.fields.find(key);
    return it == row.fields.end() ? "" : it->second;
}

