    case 1: case 5: case 8: case 9: case 10: case 25: return "Process";
    case 2: case 11: case 15: case 23: case 26: case 27: case 28: case 29: case 30: return "File";
    case 12: case 13: case 14: return "Registry";
    case 3: case 22: return "Network";
