    ImGui::SameLine();
    if (ImGui::Button("Open##SysmonConfigUrl", ImVec2(90.0f, 0.0f)))
        ShellExecuteW(nullptr, L"open", StringToWString(g_SysmonConfigUrl).c_str(), nullptr, nullptr, SW_SHOWNORMAL);

    ImGui::Text("Local Sysmon Folder");
    ImGui::SetNextItemWidth((std::max)(420.0f, ImGui::GetContentRegionAvail().x - 110.0f));
