static void DrawSysmonRowsTable(const char* tableId,
    const std::vector<SysmonEventRow>& rows,
    const std::string& category,
    const std::string& filter,
    const SysmonProcessChoice* choice) {
    if (ImGui::BeginTable(tableId, 9,
        ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
        ImGui::TableSetupScrollFreeze(0, 1);
        ImGui::TableSetupColumn("Time", ImGuiTableColumnFlags_WidthFixed, 150.0f);
        ImGui::TableSetupColumn("ID", ImGuiTableColumnFlags_WidthFixed, 44.0f);
        ImGui::TableSetupColumn("Category", ImGuiTableColumnFlags_WidthFixed, 92.0f);
        ImGui::TableSetupColumn("Event", ImGuiTableColumnFlags_WidthFixed, 190.0f);
        ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 220.0f);
        ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 70.0f);
        ImGui::TableSetupColumn("Object / Destination", ImGuiTableColumnFlags_WidthStretch, 0.45f);
        ImGui::TableSetupColumn("Command / Details", ImGuiTableColumnFlags_WidthStretch, 0.55f);
        ImGui::TableSetupColumn("User", ImGuiTableColumnFlags_WidthFixed, 150.0f);
        ImGui::TableHeadersRow();
        for (const auto& row : rows) {
            if (!SysmonEventVisibleForChoice(row, category, filter, choice)) continue;
            const bool excluded = SysmonEventExcluded(row);
            ImGui::PushID(static_cast<int>(row.recordId));
            if (excluded && g_SysmonDimExcluded) ImGui::PushStyleColor(ImGuiCol_Text, kUiTextMuted);
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0); ImGui::PushID(0); DrawCopyableSysmonCell(row.time); ImGui::PopID();
            ImGui::TableSetColumnIndex(1); ImGui::PushID(1); DrawCopyableSysmonCell(std::to_string(row.eventId)); ImGui::PopID();
            ImGui::TableSetColumnIndex(2); ImGui::PushID(2); DrawCopyableSysmonCell(row.category); ImGui::PopID();
            ImGui::TableSetColumnIndex(3); ImGui::PushID(3); DrawCopyableSysmonCell(row.eventName, true); ImGui::PopID();
            ImGui::TableSetColumnIndex(4); ImGui::PushID(4); DrawCopyableSysmonCell(BaseNameFromPathOrCommand(row.image), true); ImGui::PopID();
            ImGui::TableSetColumnIndex(5); ImGui::PushID(5); DrawCopyableSysmonCell(row.processId.empty() ? "-" : row.processId); ImGui::PopID();
            ImGui::TableSetColumnIndex(6);
            std::string object = row.targetObject;
            if (row.category == "Network") object = row.eventId == 22 ? row.queryName : (row.destinationIp + ":" + row.destinationPort);
            if (object.empty()) object = SysmonField(row, "ImageLoaded");
            if (object.empty()) object = SysmonField(row, "PipeName");
            ImGui::PushID(6); DrawCopyableSysmonCell(object.empty() ? "-" : object, true); ImGui::PopID();
            ImGui::TableSetColumnIndex(7); ImGui::PushID(7); DrawCopyableSysmonCell(SysmonImportantData(row), true); ImGui::PopID();
            ImGui::TableSetColumnIndex(8); ImGui::PushID(8); DrawCopyableSysmonCell(row.user, true); ImGui::PopID();
            if (ImGui::BeginPopupContextItem("SysmonEventContext")) {
                if (ImGui::MenuItem("Copy important data")) CopyToClipboard(SysmonImportantData(row));
                if (ImGui::MenuItem("Copy command line")) CopyToClipboard(row.commandLine);
                if (ImGui::MenuItem("Copy process GUID")) CopyToClipboard(row.processGuid);
                ImGui::EndPopup();
            }
            if (excluded && g_SysmonDimExcluded) ImGui::PopStyleColor();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
}

static ImVec4 SysmonGraphCategoryColor(const std::string& category) {
    if (category == "Process") return kUiGreen;
    if (category == "File") return kUiGold;
    if (category == "Registry") return kUiRed;
    if (category == "Network") return kUiBlue;
    if (category == "Image") return kUiPurple;
    if (category == "Pipe" || category == "WMI") return ImVec4(0.24f, 0.64f, 0.78f, 1.0f);
    if (category == "Driver" || category == "Service") return ImVec4(0.78f, 0.44f, 0.22f, 1.0f);
    return kUiTextMuted;
}

static std::string SysmonGraphEventValue(const SysmonEventRow& row) {
    if (row.category == "Network") {
        if (row.eventId == 22) return row.queryName.empty() ? SysmonImportantData(row) : row.queryName;
        std::string endpoint = row.destinationIp;
        if (!row.destinationPort.empty()) endpoint += ":" + row.destinationPort;
        return endpoint.empty() ? SysmonImportantData(row) : endpoint;
    }
    if (row.category == "Image") {
        std::string imageLoaded = SysmonField(row, "ImageLoaded");
        return imageLoaded.empty() ? SysmonImportantData(row) : imageLoaded;
    }
    if (row.category == "Pipe") {
        std::string pipe = SysmonField(row, "PipeName");
        return pipe.empty() ? SysmonImportantData(row) : pipe;
    }
    if (!row.targetObject.empty()) return row.targetObject;
    if (!row.details.empty()) return row.details;
    return SysmonImportantData(row);
}

static void DrawSysmonGraph(const std::vector<SysmonEventRow>& rows,
    const std::string& filter,
    const SysmonProcessChoice* selected) {
    if (!selected) {
        ImGui::TextColored(kUiTextMuted, "Select a Sysmon process above to render its focused event graph.");
        return;
    }

    std::vector<const SysmonEventRow*> processEvents;
    for (const auto& row : rows) {
        if (!SysmonEventMatchesProcessChoice(row, *selected)) continue;
        if (!SysmonEventVisible(row, "", filter)) continue;
        processEvents.push_back(&row);
    }
    std::sort(processEvents.begin(), processEvents.end(), [](const SysmonEventRow* a, const SysmonEventRow* b) {
        if (a->time != b->time) return a->time < b->time;
        return a->recordId < b->recordId;
    });

    ImGui::TextColored(kUiTextMuted, "Showing %zu visible Sysmon events for the selected process. Search/exclusion controls above also affect this graph.", processEvents.size());
    if (processEvents.empty()) {
        ImGui::TextColored(kUiGold, "No visible events for this process. Clear the search or disable Hide excluded if needed.");
    }

    ImVec2 canvasPos = ImGui::GetCursorScreenPos();
    ImVec2 avail = ImGui::GetContentRegionAvail();
    const float processW = 300.0f, processH = 96.0f, eventW = 360.0f, eventH = 86.0f, yGap = 18.0f;
    ImVec2 canvasSize((std::max)(avail.x, processW + eventW + 160.0f),
        (std::max)(avail.y, 80.0f + (float)(std::max<size_t>(1, processEvents.size())) * (eventH + yGap)));
    ImGui::InvisibleButton("SysmonGraphCanvas", canvasSize);
    ImDrawList* draw = ImGui::GetWindowDrawList();
    draw->AddRectFilled(canvasPos, ImVec2(canvasPos.x + canvasSize.x, canvasPos.y + canvasSize.y), ImGui::GetColorU32(kUiGraphCanvasBg));
    draw->PushClipRect(canvasPos, ImVec2(canvasPos.x + canvasSize.x, canvasPos.y + canvasSize.y), true);

    ImVec2 processPos(canvasPos.x + 24.0f, canvasPos.y + 34.0f);
    draw->AddRectFilled(processPos, ImVec2(processPos.x + processW, processPos.y + processH), ImGui::GetColorU32(kUiGraphNodeBg), 8.0f);
    draw->AddRect(processPos, ImVec2(processPos.x + processW, processPos.y + processH), ImGui::GetColorU32(kUiGreen), 8.0f, 0, 2.0f);
    draw->AddText(ImVec2(processPos.x + 14.0f, processPos.y + 12.0f), ImGui::GetColorU32(kUiGreen), "PROCESS");
    draw->AddText(ImVec2(processPos.x + 14.0f, processPos.y + 34.0f), ImGui::GetColorU32(kUiText), BaseNameFromPathOrCommand(selected->image).c_str());
    std::string pidLine = "PID " + (selected->pid.empty() ? "-" : selected->pid) + " | " + std::to_string(processEvents.size()) + " events";
    draw->AddText(ImVec2(processPos.x + 14.0f, processPos.y + 58.0f), ImGui::GetColorU32(kUiTextMuted), pidLine.c_str());
    if (!selected->commandLine.empty()) {
        std::string command = selected->commandLine.substr(0, 80);
        if (selected->commandLine.size() > 80) command += "...";
        draw->AddText(ImVec2(processPos.x + 14.0f, processPos.y + 78.0f), ImGui::GetColorU32(kUiTextMuted), command.c_str());
    }

    const float eventX = processPos.x + processW + 96.0f;
    for (size_t i = 0; i < processEvents.size(); ++i) {
        const SysmonEventRow& row = *processEvents[i];
        ImVec2 p(eventX, canvasPos.y + 24.0f + i * (eventH + yGap));
        ImVec4 accent = SysmonGraphCategoryColor(row.category);
        ImU32 accentColor = ImGui::GetColorU32(accent);
        ImVec2 edgeStart(processPos.x + processW, processPos.y + processH * 0.5f);
        ImVec2 edgeEnd(p.x, p.y + eventH * 0.5f);
        draw->AddBezierCubic(edgeStart, ImVec2(edgeStart.x + 56.0f, edgeStart.y),
            ImVec2(edgeEnd.x - 56.0f, edgeEnd.y), edgeEnd, ImGui::GetColorU32(kUiTextMuted), 1.5f);
        draw->AddTriangleFilled(ImVec2(edgeEnd.x - 8, edgeEnd.y - 5), ImVec2(edgeEnd.x - 8, edgeEnd.y + 5), edgeEnd, ImGui::GetColorU32(kUiTextMuted));

        draw->AddRectFilled(p, ImVec2(p.x + eventW, p.y + eventH), ImGui::GetColorU32(kUiGraphNodeBg), 8.0f);
        draw->AddRect(p, ImVec2(p.x + eventW, p.y + eventH), accentColor, 8.0f, 0, 2.0f);
        draw->AddText(ImVec2(p.x + 12.0f, p.y + 9.0f), accentColor, row.category.c_str());
        std::string eventLine = row.eventName + " | ID " + std::to_string(row.eventId);
        draw->AddText(ImVec2(p.x + 12.0f, p.y + 29.0f), ImGui::GetColorU32(kUiText), eventLine.c_str());
        std::string value = SysmonGraphEventValue(row);
        if (value.size() > 76) value = value.substr(0, 73) + "...";
        draw->AddText(ImVec2(p.x + 12.0f, p.y + 51.0f), ImGui::GetColorU32(kUiTextMuted), value.c_str());
        draw->AddText(ImVec2(p.x + 12.0f, p.y + 69.0f), ImGui::GetColorU32(kUiTextMuted), row.time.c_str());
    }
    draw->PopClipRect();
}

static void DrawSysmonEventsView() {
    if (g_SysmonLastRefreshMs.load() == 0 || (g_SysmonAutoRefresh && CurrentUnixTimeMilliseconds() - g_SysmonLastRefreshMs.load() > 5000))
        StartSysmonRefreshAsync();
    std::vector<SysmonEventRow> rows;
    std::vector<SysmonProcessChoice> choices;
    std::string status;
    SnapshotSysmonState(rows, choices, status);
    if (!choices.empty()) {
        if (g_SysmonSelectedProcessIndex < 0) g_SysmonSelectedProcessIndex = 0;
        if (g_SysmonSelectedProcessIndex >= (int)choices.size()) g_SysmonSelectedProcessIndex = 0;
    }
    const SysmonProcessChoice* selectedChoice = choices.empty() ? nullptr : &choices[g_SysmonSelectedProcessIndex];
    const SysmonProcessChoice* tableChoice = g_SysmonMonitorAllProcesses ? nullptr : selectedChoice;

    ImGui::BeginChild("SysmonEventsRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Sysmon Events", "");
    if (PrimaryButton("Refresh", ImVec2(90.0f, 26.0f))) StartSysmonRefreshAsync();
    ImGui::SameLine();
    ImGui::SetNextItemWidth(320.0f);
    ImGui::InputTextWithHint("##SysmonSearch", "Filter Sysmon events...", g_SysmonSearchBuf, sizeof(g_SysmonSearchBuf));
    std::string filter = ToLowerCopy(g_SysmonSearchBuf);
    ImGui::SameLine();
    ImGui::Checkbox("Hide excluded", &g_SysmonHideExcluded);
    ImGui::SameLine();
    ImGui::Checkbox("Dim excluded", &g_SysmonDimExcluded);
    ImGui::SetNextItemWidth((std::max)(360.0f, ImGui::GetContentRegionAvail().x));
    ImGui::InputTextWithHint("##SysmonExclude", "Exclude contains keywords, comma-separated", g_SysmonExcludeBuf, sizeof(g_SysmonExcludeBuf));
    if (g_SysmonMonitorAllProcesses) {
        ImGui::TextColored(kUiTextMuted, "Scope: Monitor all processes | %s", status.c_str());
    } else if (selectedChoice) {
        ImGui::TextColored(kUiTextMuted, "Scope: PID %s | %s | %s",
            selectedChoice->pid.empty() ? "-" : selectedChoice->pid.c_str(),
            BaseNameFromPathOrCommand(selectedChoice->image).c_str(),
            status.c_str());
    } else {
        ImGui::TextColored(kUiTextMuted, "Scope: Select a process in Process Focus | %s", status.c_str());
    }
    ImGui::Spacing();

    const std::string countCacheKey =
        filter + "|" + g_SysmonExcludeBuf + "|" +
        (g_SysmonHideExcluded ? "hide" : "show") + "|" +
        (g_SysmonMonitorAllProcesses ? "all" : (selectedChoice ? selectedChoice->key : "none")) + "|" +
        std::to_string(rows.size()) + "|" + std::to_string(g_SysmonLastRefreshMs.load());
    std::unordered_map<std::string, size_t> counts;
    bool cacheHit = false;
    {
        std::lock_guard<std::mutex> lock(g_SysmonMutex);
        cacheHit = (g_SysmonCachedFilterKey == countCacheKey);
        if (cacheHit) counts = g_SysmonCachedCounts;
    }
    const char* categories[] = { "Process", "File", "Registry", "Network", "Image", "Pipe", "Service", "Driver", "WMI", "Clipboard", "Configuration" };
    if (!cacheHit) {
        counts[""] = CountVisibleSysmonEvents(rows, "", filter, tableChoice);
        for (const char* category : categories) {
            counts[category] = CountVisibleSysmonEvents(rows, category, filter, tableChoice);
        }
        std::lock_guard<std::mutex> lock(g_SysmonMutex);
        g_SysmonCachedFilterKey = countCacheKey;
        g_SysmonCachedCounts = counts;
    }
    const size_t visibleAll = counts[""];
    ImGui::TextColored(kUiTextMuted, "Visible: %zu | Hidden by exclusions/search: %zu | Right-click any cell to copy its value.",
        visibleAll, rows.size() > visibleAll ? rows.size() - visibleAll : 0);
    ImGui::Spacing();
    if (ImGui::BeginTabBar("SysmonEventTabs")) {
        if (ImGui::BeginTabItem("Process Focus")) {
            if (ImGui::Checkbox("Monitor all processes", &g_SysmonMonitorAllProcesses)) {
                g_SysmonCachedFilterKey.clear();
            }
            ImGui::SameLine();
            ImGui::TextColored(kUiTextMuted, "Choose one PID for focused Sysmon triage, or monitor all for the old global view.");
            ImGui::Spacing();
            if (choices.empty()) {
                ImGui::TextColored(kUiGold, "No Sysmon process IDs loaded yet. Click Refresh after Sysmon is installed and producing events.");
            } else {
                if (ImGui::BeginTable("SysmonProcessPickerTable", 7,
                    ImGuiTableFlags_RowBg | ImGuiTableFlags_BordersInnerV | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable)) {
                    ImGui::TableSetupScrollFreeze(0, 1);
                    ImGui::TableSetupColumn("PID", ImGuiTableColumnFlags_WidthFixed, 70.0f);
                    ImGui::TableSetupColumn("Process", ImGuiTableColumnFlags_WidthFixed, 190.0f);
                    ImGui::TableSetupColumn("Full Path", ImGuiTableColumnFlags_WidthStretch, 0.32f);
                    ImGui::TableSetupColumn("First Seen", ImGuiTableColumnFlags_WidthFixed, 145.0f);
                    ImGui::TableSetupColumn("Last Seen", ImGuiTableColumnFlags_WidthFixed, 145.0f);
                    ImGui::TableSetupColumn("Events", ImGuiTableColumnFlags_WidthFixed, 70.0f);
                    ImGui::TableSetupColumn("Command / MD5", ImGuiTableColumnFlags_WidthStretch, 0.42f);
                    ImGui::TableHeadersRow();
                    for (int i = 0; i < (int)choices.size(); ++i) {
                        const auto& choice = choices[i];
                        ImGui::PushID(i);
                        ImGui::TableNextRow();
                        const bool selected = i == g_SysmonSelectedProcessIndex;
                        ImGui::TableSetColumnIndex(0);
                        if (ImGui::Selectable((choice.pid.empty() ? "-" : choice.pid).c_str(), false,
                            ImGuiSelectableFlags_SpanAllColumns | ImGuiSelectableFlags_AllowOverlap)) {
                            g_SysmonSelectedProcessIndex = i;
                            selectedChoice = &choices[g_SysmonSelectedProcessIndex];
                            tableChoice = g_SysmonMonitorAllProcesses ? nullptr : selectedChoice;
                            g_SysmonCachedFilterKey.clear();
                        }
                        ImGui::TableSetColumnIndex(1); DrawCopyableSysmonCell(BaseNameFromPathOrCommand(choice.image), true);
                        ImGui::TableSetColumnIndex(2); DrawCopyableSysmonCell(choice.image.empty() ? "-" : choice.image, true);
                        ImGui::TableSetColumnIndex(3); DrawCopyableSysmonCell(choice.firstSeen.empty() ? "-" : choice.firstSeen);
                        ImGui::TableSetColumnIndex(4); DrawCopyableSysmonCell(choice.lastSeen.empty() ? "-" : choice.lastSeen);
                        ImGui::TableSetColumnIndex(5); DrawCopyableSysmonCell(std::to_string(choice.eventCount));
                        ImGui::TableSetColumnIndex(6);
                        std::string details = choice.commandLine.empty() ? "" : choice.commandLine;
                        if (!choice.hashes.empty()) {
                            if (!details.empty()) details += " | ";
                            details += choice.hashes;
                        }
                        DrawCopyableSysmonCell(details.empty() ? "-" : details, true);
                        if (selected) {
                            const ImU32 selectedColor = ImGui::GetColorU32(ImVec4(kUiBlue.x, kUiBlue.y, kUiBlue.z, 0.38f));
                            ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg0, selectedColor);
                            ImGui::TableSetBgColor(ImGuiTableBgTarget_RowBg1, selectedColor);
                        }
                        ImGui::PopID();
                    }
                    ImGui::EndTable();
                }
                if (selectedChoice) {
                    ImGui::TextColored(kUiTextMuted, "Focused PID: %s | Path: %s",
                        selectedChoice->pid.empty() ? "-" : selectedChoice->pid.c_str(),
                        selectedChoice->image.empty() ? "-" : selectedChoice->image.c_str());
                    if (!selectedChoice->commandLine.empty()) ImGui::TextWrapped("Command: %s", selectedChoice->commandLine.c_str());
                    if (!selectedChoice->hashes.empty()) ImGui::TextWrapped("MD5: %s", selectedChoice->hashes.c_str());
                }
            }
            ImGui::EndTabItem();
        }
        for (const char* category : categories) {
            size_t count = counts[category];
            if (BeginFindingTabItem(category, count)) {
                DrawSysmonRowsTable((std::string("Sysmon") + category).c_str(), rows, category, filter, tableChoice);
                ImGui::EndTabItem();
            }
        }
        if (ImGui::BeginTabItem("Graph")) {
            DrawSysmonGraph(rows, filter, selectedChoice);
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }
    ImGui::EndChild();
}

