static void DrawControlsView() {
    ImGui::BeginChild("ControlsRoot", ImVec2(0.0f, 0.0f), false);
    DrawViewHeader("Controls", "");
    ImGui::BeginChild("ControlsContent", ImVec2(0.0f, 0.0f), true);

    const float buttonWidth = 260.0f;
    ImGui::TextColored(kUiBlue, "Session");
    ImGui::Separator();
    DrawControlButtonPalette();
    if (ImGui::Button("Clear Logs", ImVec2(buttonWidth, 30))) {
        std::lock_guard<std::mutex> lock(g_LogsMutex);
        g_Logs.clear();
        g_Logs.push_back("[info] logs cleared.");
        g_SelectedLogIndex = -1;
    }
    ImGui::PopStyleColor(4);

    ImGui::SameLine();
    if (!g_CapturingActive) {
        ImGui::PushStyleColor(ImGuiCol_Button, kUiGold);
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(0.80f, 0.63f, 0.20f, 1.00f));
        ImGui::PushStyleColor(ImGuiCol_ButtonActive, ImVec4(0.72f, 0.57f, 0.16f, 1.00f));
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.047f, 0.051f, 0.055f, 1.0f));
    } else {
        DrawControlButtonPalette();
    }
    if (ImGui::Button(g_CapturingActive ? "Pause Capture" : "Resume Capture", ImVec2(buttonWidth, 30))) {
        g_CapturingActive = !g_CapturingActive;
        AddLog(g_CapturingActive ? "Capturing active." : "Capturing paused.");
    }
    ImGui::PopStyleColor(4);

    if (g_Target.active) {
        ImGui::Spacing();
        ImGui::PushStyleColor(ImGuiCol_Button, kUiRed);
        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(0.80f, 0.29f, 0.29f, 1.0f));
        ImGui::PushStyleColor(ImGuiCol_ButtonActive, ImVec4(0.62f, 0.22f, 0.22f, 1.0f));
        ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.047f, 0.051f, 0.055f, 1.00f));
        if (ImGui::Button("Terminate Tree", ImVec2(buttonWidth, 30))) {
            ++g_RunTimerToken;
            DWORD pid = g_Target.pid;
            TerminateProcessTree(g_Target.pid);
            AddTargetLifecycleOutput(pid, "terminated by analyst");
            RecordControllerProcessTermination(pid, "Terminated by analyst");
            g_Target.active = false;
            g_ProcessRunState.store(ProcessRunState::Terminated);
            StopRuntimeStringScanner();
            StopEtwForEndedTarget(pid);
            AddLog("[info] target process tree terminated.");
        }
        ImGui::PopStyleColor(4);
    }

    ImGui::Spacing();
    ImGui::Spacing();
    ImGui::TextColored(kUiBlue, "Export / Import");
    ImGui::Separator();
    DrawControlButtonPalette();
    if (ImGui::Button("Export JSON", ImVec2(buttonWidth, 30))) ExportAnalysisDatabase();
    ImGui::SameLine();
    if (ImGui::Button("Import JSON", ImVec2(buttonWidth, 30))) ImportAnalysisDatabase();
    ImGui::PopStyleColor(4);

    ImGui::Spacing();
    ImGui::Spacing();
    ImGui::TextColored(kUiBlue, "AI");
    ImGui::Separator();
    DrawControlButtonPalette();
    if (ImGui::Button("AI Settings", ImVec2(buttonWidth, 30))) g_SelectedNavIndex = 18;
    ImGui::PopStyleColor(4);

    ImGui::Spacing();
    ImGui::Spacing();
    ImGui::TextColored(kUiBlue, "View Options");
    ImGui::Separator();
    ImGui::Text("Theme");
    const char* themeNames[] = { "White", "Dark" };
    ImGui::SetNextItemWidth(260.0f);
    if (ImGui::Combo("##ThemeSelector", &g_SelectedTheme, themeNames, IM_ARRAYSIZE(themeNames))) {
        ApplySelectedTheme();
        ImGui::GetStyle().ScaleAllSizes(1.08f);
        AddLog(g_SelectedTheme == 0 ? "[info] UI theme changed to White." : "[info] UI theme changed to Dark.");
    }
    ImGui::Spacing();
    if (ImGui::Checkbox("Show ETW findings", &g_ShowEtwFindings)) {
        g_ProcessHideEtwFindings = !g_ShowEtwFindings;
        g_NetworkIncludeEtw = g_ShowEtwFindings;
        g_RegistryIncludeEtw = g_ShowEtwFindings;
        g_FileIncludeEtw = g_ShowEtwFindings;
        AddLog(g_ShowEtwFindings ? "[info] ETW findings shown in activity tabs." : "[info] ETW findings hidden from activity tabs.");
    }
    if (ImGui::IsItemHovered()) ImGui::SetTooltip("ETW collection continues; this controls ETW-derived rows in activity tabs.");
    ImGui::Spacing();
    ImGui::Checkbox("Hide excluded", &g_HideExcluded);
    if (ImGui::IsItemHovered()) ImGui::SetTooltip("Hide low-signal events matching exclusions workspace-wide.");
    ImGui::Spacing();
    ImGui::Checkbox("Dim excluded", &g_DimExcluded);
    if (ImGui::IsItemHovered()) ImGui::SetTooltip("Dim low-signal events matching exclusions instead of hiding them.");
    g_VerboseLogging = true;

    ImGui::EndChild();
    ImGui::EndChild();
}

