static bool IsProcessActivityFindingApi(const std::string& api) {
    return IsProcessCreationApi(api) || IsThreadCreationApi(api) || api == "OpenProcess" || api == "NtOpenProcess" ||
        api == "TerminateProcess" || api == "ExitProcess" || api == "NtTerminateProcess" ||
        api == "QueryFullProcessImageNameW" || api == "QueryFullProcessImageNameA" || api == "GetProcessId" ||
        api == "GetProcessInformation" || api == "NtQueryInformationProcess" || api == "OpenProcessToken" ||
        api == "GetTokenInformation" || api == "AdjustTokenPrivileges" || api == "DuplicateToken" ||
        api == "DuplicateTokenEx" || api == "NtOpenProcessToken" || api.find("EnvironmentVariable") != std::string::npos ||
        api.find("EnvironmentStrings") != std::string::npos || api.find("ExpandEnvironment") != std::string::npos ||
        api.find("WaitFor") == 0 || api.find("NtWaitFor") == 0 || api.find("GetCurrentProcess") == 0 ||
        api.find("GetCommandLine") == 0 || api.find("GetCurrentDirectory") == 0 || api.find("GetModuleFileName") == 0 ||
        api == "CreateToolhelp32Snapshot" || api == "Process32FirstW" || api == "Process32NextW" ||
        api == "NtQuerySystemInformation" || IsCallbackExecutionApi(api);
}

static bool IsMemoryActivityFindingApi(const std::string& api) {
    bool heap = ApiStartsWith(api, "Heap") || api == "RtlAllocateHeap" || api == "RtlFreeHeap";
    bool query = api == "VirtualQuery" || api == "VirtualQueryEx" || api == "NtQueryVirtualMemory";
    if (heap && !g_MemoryShowHeapActivity) return false;
    if (query && !g_MemoryShowQueryActivity) return false;
    return ApiStartsWith(api, "Shellcode") || api.find("VirtualAlloc") != std::string::npos || api.find("VirtualProtect") != std::string::npos ||
        api.find("VirtualFree") != std::string::npos || api == "NtAllocateVirtualMemory" || api == "NtProtectVirtualMemory" ||
        api == "NtFreeVirtualMemory" || api == "WriteProcessMemory" || api == "NtWriteVirtualMemory" || api == "RtlMoveMemory" || api == "memcpy" ||
        api == "ReadProcessMemory" || api == "NtReadVirtualMemory" || api.find("MapViewOfFile") != std::string::npos ||
        api == "NtMapViewOfSection" || api == "UnmapViewOfFile" || api == "NtUnmapViewOfSection" ||
        ApiStartsWith(api, "CreateFileMapping") || ApiStartsWith(api, "OpenFileMapping") || api == "NtCreateSection" ||
        api == "NtOpenSection" || api == "LocalAlloc" || api == "LocalFree" || api == "GlobalAlloc" || api == "GlobalFree" || heap || query;
}

static std::unordered_map<int, size_t> BuildActivityFindingCounts() {
    static std::unordered_map<int, size_t> cachedCounts;
    static auto lastRefresh = std::chrono::steady_clock::time_point{};
    static bool hasCachedCounts = false;
    auto now = std::chrono::steady_clock::now();
    if (hasCachedCounts && now - lastRefresh < std::chrono::milliseconds(500)) return cachedCounts;
    std::vector<TelemetryEvent> events;
    {
        std::lock_guard<std::mutex> lock(g_EventsMutex);
        events = g_Events;
    }
    std::unordered_map<int, size_t> counts;
    for (const auto& event : events) if (IsWinApiMonitorVisible(event.apiName)) ++counts[1];
    std::vector<EtwKernelEvent> etwEvents = SnapshotEtwKernelEvents();
    const bool sandboxEtw = IsSandboxHostedSession();
    counts[2] = etwEvents.size();
    if (!g_ProcessHideEtwFindings || sandboxEtw) {
        for (const auto& event : etwEvents) if (event.category == "Process") ++counts[4];
    }
    for (const auto& event : events) {
        const std::string& api = event.apiName;
        if (IsProcessActivityFindingApi(api)) ++counts[4];
        if (IsMemoryActivityFindingApi(api)) ++counts[8];
        if (IsDllActivityApi(api)) ++counts[9];
        if (IsServiceDriverApi(api)) ++counts[11];
        if (IsComActivityApi(api)) ++counts[12];
        if (IsAntiAnalysisDirectApi(api)) ++counts[14];
        if (IsCryptoApi(api)) ++counts[15];
    }
    // Process Injection intentionally ignores ordinary process creation and
    // only emits suspended-process or remote-operation findings. Use the same
    // snapshot as the view so its sidebar badge cannot disagree with the UI.
    std::vector<ObservedModule> modules = GetObservedModules(events);
    counts[5] = BuildNetworkActivitySnapshotForUi(events, modules).connections.size();
    counts[6] = BuildRegistryActivitySnapshot(events, modules,
        (g_RegistryIncludeEtw || sandboxEtw) ? etwEvents : std::vector<EtwKernelEvent>{}).operations.size();
    counts[7] = BuildFileActivitySnapshot(events, modules,
        (g_FileIncludeEtw || sandboxEtw) ? etwEvents : std::vector<EtwKernelEvent>{}).operations.size();
    counts[10] = BuildIpcActivitySnapshot(events, modules).events.size();
    counts[13] = BuildProcessInjectionSnapshot(events, modules, etwEvents).events.size();
    {
        std::lock_guard<std::mutex> lock(g_ProcessWatcherMutex);
        counts[20] = g_ProcessWatcherCreated.size();
    }
    {
        std::lock_guard<std::mutex> lock(g_FolderFileWatcherMutex);
        counts[21] = CountVisibleFolderFileWatcherRows(g_FolderFileWatcherCreated) +
            CountVisibleFolderFileWatcherRows(g_FolderFileWatcherModified) +
            CountVisibleFolderFileWatcherRows(g_FolderFileWatcherRenamed) +
            CountVisibleFolderFileWatcherRows(g_FolderFileWatcherMoved) +
            CountVisibleFolderFileWatcherRows(g_FolderFileWatcherCopied) +
            CountVisibleFolderFileWatcherRows(g_FolderFileWatcherDeleted);
    }
    {
        std::vector<NetWatcherConnection> netEvents;
        {
            std::lock_guard<std::mutex> lock(g_NetWatcherMutex);
            netEvents = g_NetWatcherEvents;
        }
        std::vector<TelemetryEvent> netTelemetry;
        if (g_NetWatcherTelemetryBaseline < events.size())
            netTelemetry.assign(events.begin() + static_cast<std::ptrdiff_t>(g_NetWatcherTelemetryBaseline), events.end());
        NetworkActivitySnapshot netSnapshot = BuildNetworkActivitySnapshotForUi(netTelemetry, GetObservedModules(netTelemetry));
        MergeNetWatcherPassiveIndicators(netSnapshot);
        counts[22] = CountVisibleNetWatcherRows(netEvents) +
            CountVisibleNetWatcherIndicators(netSnapshot.domains) +
            CountVisibleNetWatcherIndicators(netSnapshot.urls);
    }
    counts[23] = BuildInjectWatcherRows(events).size();
    {
        std::vector<TelemetryEvent> registryWatcherEvents;
        if (g_RegistryWatcherTelemetryBaseline < events.size())
            registryWatcherEvents.assign(events.begin() + static_cast<std::ptrdiff_t>(g_RegistryWatcherTelemetryBaseline), events.end());
        RegistryActivitySnapshot registryWatcherSnapshot = BuildRegistryWatcherSnapshotFromSources(registryWatcherEvents);
        counts[24] = FilterRegistryWatcherRows(registryWatcherSnapshot, "All").size();
    }
    {
        std::lock_guard<std::mutex> lock(g_SysmonMutex);
        counts[26] = g_SysmonEvents.size();
    }
    {
        std::lock_guard<std::mutex> lock(g_RecoveredStringsMutex);
        counts[8] += g_RecoveredStrings.size();
    }
    {
        std::lock_guard<std::mutex> lock(g_ProcessLifecycleMutex);
        counts[4] += std::count_if(g_ControllerProcessTerminations.begin(), g_ControllerProcessTerminations.end(),
            [](const ProcessBehaviorRow& row) {
                return row.details != "Target process exited or disconnected from its telemetry pipe";
            });
    }
    cachedCounts = counts;
    lastRefresh = now;
    hasCachedCounts = true;
    return cachedCounts;
}

static bool AiEventMatchesView(const TelemetryEvent& event, int viewId) {
    const std::string& api = event.apiName;
    switch (viewId) {
    case 1: return IsWinApiMonitorVisible(api);
    case 4: return IsProcessActivityFindingApi(api);
    case 5: return IsNetworkApi(api);
    case 6: return IsRegistryApi(api);
    case 7: return IsFileApi(api);
    case 8: return IsMemoryActivityFindingApi(api);
    case 9: return IsDllActivityApi(api);
    case 10: return IsIpcActivityApi(api);
    case 11: return IsServiceDriverApi(api);
    case 12: return IsComActivityApi(api);
    case 13: return IsProcessInjectionApi(api);
    case 14: return IsAntiAnalysisDirectApi(api);
    case 15: return IsCryptoApi(api);
    default: return true;
    }
}

static std::string BuildAiFindingsContext(int viewId) {
    std::vector<TelemetryEvent> events;
    { std::lock_guard<std::mutex> lock(g_EventsMutex); events = g_Events; }
    std::ostringstream out;
    out << "Target: " << WidePathToUtf8(g_Target.path) << "\nPID: " << g_Target.pid
        << "\nLaunch mode: " << g_Target.launchMode << "\nScope: " << (viewId < 0 ? "All findings" : std::to_string(viewId)) << "\n";
    size_t included = 0;
    for (const auto& event : events) {
        if (event.apiName.rfind("ETW ", 0) == 0 || event.dllName == "ETW") continue;
        if (IsWinApiManuallyExcluded(event.apiName)) continue;
        if (viewId >= 0 && !AiEventMatchesView(event, viewId)) continue;
        out << "\n[" << FormatTimestamp(event.timestamp) << "] category=" << EventCategoryLabel(event)
            << " api=" << event.apiName << " pid=" << event.processId << " tid=" << event.threadId
            << " result=0x" << std::hex << event.returnValue << std::dec;
        if (!event.callerModule.empty()) out << " caller=" << event.callerModule;
        for (const auto& parameter : event.parameters) {
            if (!parameter.decoded.empty()) out << " " << parameter.name << "=" << parameter.decoded.substr(0, 300);
        }
        if (++included >= 800 || out.tellp() > 100000) { out << "\n[Context truncated after " << included << " events]"; break; }
    }
    if (included == 0) out << "\nNo matching non-ETW findings were captured.";
    return out.str();
}

static AiConfig CurrentAiConfig() {
    AiConfig config;
    config.provider = g_AiProvider == 1 ? AiProvider::Anthropic : AiProvider::OpenAICompatible;
    config.endpoint = g_AiEndpoint;
    config.apiKey = g_AiApiKey;
    config.model = g_AiModel;
    return config;
}

static void StartAiRequest(int viewId, const std::string& question) {
    if (g_AiRequestActive.exchange(true)) return;
    g_AiLastScope = viewId;
    g_AiLastQuestion = question.empty() ? "Summarize the findings and identify the most important behaviors." : question;
    g_AiPopupRequested = true;
    { std::lock_guard<std::mutex> lock(g_AiResultMutex); g_AiResult.clear(); g_AiError.clear(); }
    const AiConfig config = CurrentAiConfig();
    const std::string context = BuildAiFindingsContext(viewId);
    const std::string prompt = g_AiLastQuestion + "\n\nInspecthor evidence:\n" + context;
    std::thread([config, prompt]() {
        std::string response, error;
        RequestAiCompletion(config,
            "You are a malware-analysis assistant. Use only the supplied evidence. Distinguish observations from inferences, prioritize analyst actions, and never claim that absent telemetry proves benign behavior. Provide your output as plain text without any markdown formatting (do not use **, *, #, markdown tables, or lists).",
            prompt, response, error);
        { std::lock_guard<std::mutex> lock(g_AiResultMutex); g_AiResult = std::move(response); g_AiError = std::move(error); }
        g_AiRequestActive.store(false);
    }).detach();
}

static void ShowOrStartAiRequest(int viewId, const std::string& question) {
    bool hasResult = false;
    {
        std::lock_guard<std::mutex> lock(g_AiResultMutex);
        hasResult = !g_AiResult.empty();
    }
    std::string normQuestion = question.empty() ? "Summarize the findings and identify the most important behaviors." : question;
    if (hasResult && viewId == g_AiLastScope && g_AiLastQuestion == normQuestion) {
        g_AiPopupRequested = true;
    } else {
        StartAiRequest(viewId, question);
    }
}

