// Memory-Mapped PE Headers PE Safe parser logic
static bool ParsePEHeaderSafe(LPVOID baseAddr, PIMAGE_EXPORT_DIRECTORY& outExportDir, PIMAGE_NT_HEADERS& outNtHeaders) {
    __try {
        PIMAGE_DOS_HEADER dosHeader = (PIMAGE_DOS_HEADER)baseAddr;
        if (dosHeader->e_magic == IMAGE_DOS_SIGNATURE) {
            PIMAGE_NT_HEADERS ntHeaders = (PIMAGE_NT_HEADERS)((BYTE*)baseAddr + dosHeader->e_lfanew);
            if (ntHeaders->Signature == IMAGE_NT_SIGNATURE) {
                outNtHeaders = ntHeaders;
                IMAGE_DATA_DIRECTORY exportDirEntry = ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];
                if (exportDirEntry.Size > 0) {
                    PIMAGE_SECTION_HEADER section = IMAGE_FIRST_SECTION(ntHeaders);
                    for (int i = 0; i < ntHeaders->FileHeader.NumberOfSections; i++, section++) {
                        if (exportDirEntry.VirtualAddress >= section->VirtualAddress && 
                            exportDirEntry.VirtualAddress < section->VirtualAddress + section->Misc.VirtualSize) {
                            DWORD offset = exportDirEntry.VirtualAddress - section->VirtualAddress + section->PointerToRawData;
                            outExportDir = (PIMAGE_EXPORT_DIRECTORY)((BYTE*)baseAddr + offset);
                            return true;
                        }
                    }
                }
            }
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
    return false;
}

static bool SafeCopyString(char* dest, const char* src, size_t maxLen) {
    __try {
        size_t i = 0;
        while (src[i] != '\0' && i < maxLen - 1) {
            dest[i] = src[i];
            i++;
        }
        dest[i] = '\0';
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

static std::vector<ExportInfo> EnumerateDllExports(const std::wstring& filePath) {
    std::vector<ExportInfo> exports;
    HANDLE hFile = CreateFileW(filePath.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, 0, nullptr);
    if (hFile == INVALID_HANDLE_VALUE) return exports;

    HANDLE hMapping = CreateFileMappingW(hFile, nullptr, PAGE_READONLY, 0, 0, nullptr);
    if (!hMapping) { CloseHandle(hFile); return exports; }

    LPVOID baseAddr = MapViewOfFile(hMapping, FILE_MAP_READ, 0, 0, 0);
    if (!baseAddr) { CloseHandle(hMapping); CloseHandle(hFile); return exports; }

    PIMAGE_EXPORT_DIRECTORY exportsDir = nullptr;
    PIMAGE_NT_HEADERS ntHeaders = nullptr;

    if (ParsePEHeaderSafe(baseAddr, exportsDir, ntHeaders)) {
        auto RvaToPtr = [&](DWORD rva) -> BYTE* {
            PIMAGE_SECTION_HEADER section = IMAGE_FIRST_SECTION(ntHeaders);
            for (int i = 0; i < ntHeaders->FileHeader.NumberOfSections; i++, section++) {
                if (rva >= section->VirtualAddress && rva < section->VirtualAddress + section->Misc.VirtualSize) {
                    DWORD offset = rva - section->VirtualAddress + section->PointerToRawData;
                    return (BYTE*)baseAddr + offset;
                }
            }
            return nullptr;
        };

        DWORD* names = (DWORD*)RvaToPtr(exportsDir->AddressOfNames);
        WORD* ordinals = (WORD*)RvaToPtr(exportsDir->AddressOfNameOrdinals);
        DWORD* functions = (DWORD*)RvaToPtr(exportsDir->AddressOfFunctions);

        if (names && ordinals && functions) {
            for (DWORD i = 0; i < exportsDir->NumberOfNames; i++) {
                char* namePtr = (char*)RvaToPtr(names[i]);
                WORD ordIndex = ordinals[i];
                DWORD funcRva = functions[ordIndex];
                
                char localName[256] = {};
                ExportInfo info;
                if (namePtr && SafeCopyString(localName, namePtr, sizeof(localName))) {
                    info.name = localName;
                } else {
                    info.name = "";
                }
                info.ordinal = exportsDir->Base + ordIndex;
                info.address = funcRva;
                exports.push_back(info);
            }
        }
    }

    UnmapViewOfFile(baseAddr);
    CloseHandle(hMapping);
    CloseHandle(hFile);
    return exports;
}

// Telemetry Deserializer from JSON string
static TelemetryEvent ParseTelemetryFromJson(const std::string& jsonStr) {
    TelemetryEvent ev = {};
    try {
        auto j = json::parse(jsonStr);
        if (!j.contains("event")) {
            ev.timestamp = j.value("timestamp", 0ULL);
            ev.processId = j.value("processId", 0UL);
            ev.threadId = j.value("threadId", 0UL);
            ev.apiName = j.value("apiName", "");
            ev.dllName = j.value("dllName", "");
            ev.callerAddress = j.value("callerAddress", 0ULL);
            ev.callerModule = j.value("callerModule", "");
            ev.callerModuleBase = j.value("callerModuleBase", 0ULL);
            ev.returnValue = j.value("returnValue", 0ULL);
            ev.sessionId = j.value("sessionId", "");
            ev.processRelationship = j.value("processRelationship", "");
            ev.processName = j.value("processName", "");
            ev.processPath = j.value("processPath", "");
            ev.monitoredProcess = j.value("monitoredProcess", false);
            
            if (j.contains("parameters") && j["parameters"].is_array()) {
                for (const auto& jp : j["parameters"]) {
                    ParameterCapture p;
                    p.name = jp.value("name", "");
                    p.type = jp.value("type", "");
                    p.value = jp.value("value", 0ULL);
                    p.decoded = jp.value("decoded", "");
                    if (jp.contains("memory") && jp["memory"].is_array()) {
                        for (const auto& jb : jp["memory"]) {
                            p.memory.push_back(jb.get<uint8_t>());
                        }
                    }
                    ev.parameters.push_back(p);
                }
            }
            if (j.contains("callStack") && j["callStack"].is_array()) {
                for (const auto& jcs : j["callStack"]) {
                    ev.callStack.push_back(jcs.get<uint64_t>());
                }
            }
        }
    } catch (...) {
        // ignore malformed trace rows gracefully
    }
    return ev;
}

// Direct3D Device Management Setup
static bool CreateDeviceD3D(HWND hWnd) {
    DXGI_SWAP_CHAIN_DESC sd;
    ZeroMemory(&sd, sizeof(sd));
    sd.BufferCount = 2;
    sd.BufferDesc.Width = 0;
    sd.BufferDesc.Height = 0;
    sd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    sd.BufferDesc.RefreshRate.Numerator = 60;
    sd.BufferDesc.RefreshRate.Denominator = 1;
    sd.Flags = DXGI_SWAP_CHAIN_FLAG_ALLOW_MODE_SWITCH;
    sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    sd.OutputWindow = hWnd;
    sd.SampleDesc.Count = 1;
    sd.SampleDesc.Quality = 0;
    sd.Windowed = TRUE;
    sd.SwapEffect = DXGI_SWAP_EFFECT_DISCARD;

    UINT createDeviceFlags = 0;
    D3D_FEATURE_LEVEL featureLevel;
    const D3D_FEATURE_LEVEL featureLevelArray[2] = { D3D_FEATURE_LEVEL_11_0, D3D_FEATURE_LEVEL_10_0 };
    
    HRESULT res = D3D11CreateDeviceAndSwapChain(nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr, createDeviceFlags, featureLevelArray, 2, D3D11_SDK_VERSION, &sd, &g_pSwapChain, &g_pd3dDevice, &featureLevel, &g_pd3dDeviceContext);
    if (res == DXGI_ERROR_UNSUPPORTED)
        res = D3D11CreateDeviceAndSwapChain(nullptr, D3D_DRIVER_TYPE_WARP, nullptr, createDeviceFlags, featureLevelArray, 2, D3D11_SDK_VERSION, &sd, &g_pSwapChain, &g_pd3dDevice, &featureLevel, &g_pd3dDeviceContext);
    if (res != S_OK)
        return false;

    CreateRenderTarget();
    return true;
}

static void CleanupDeviceD3D() {
    CleanupRenderTarget();
    if (g_pSwapChain) { g_pSwapChain->Release(); g_pSwapChain = nullptr; }
    if (g_pd3dDeviceContext) { g_pd3dDeviceContext->Release(); g_pd3dDeviceContext = nullptr; }
    if (g_pd3dDevice) { g_pd3dDevice->Release(); g_pd3dDevice = nullptr; }
}

static void CreateRenderTarget() {
    ID3D11Texture2D* pBackBuffer = nullptr;
    g_pSwapChain->GetBuffer(0, IID_PPV_ARGS(&pBackBuffer));
    g_pd3dDevice->CreateRenderTargetView(pBackBuffer, nullptr, &g_mainRenderTargetView);
    pBackBuffer->Release();
}

static void CleanupRenderTarget() {
    if (g_mainRenderTargetView) { g_mainRenderTargetView->Release(); g_mainRenderTargetView = nullptr; }
}

